class EMRThreadingHTTPServer(ThreadingHTTPServer):
    """Ignore routine client disconnects while preserving unexpected tracebacks."""

    def handle_error(self, request, client_address):
        error = sys.exc_info()[1]
        if isinstance(
            error,
            (ConnectionResetError, ConnectionAbortedError, BrokenPipeError),
        ):
            return
        # Some Windows socket failures may arrive as the base OSError class.
        if isinstance(error, OSError) and getattr(error, "winerror", None) in (10053, 10054):
            return
        super().handle_error(request, client_address)


def application_install_dir():
    """Return the folder containing the running .exe or this source file."""
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__))


