def ensure_ai_configuration_schema(db):
    """Store non-secret AI preferences in SQLite.

    The API key deliberately lives outside hospital.db so routine clinical
    database backups do not copy the credential to every backup file.
    """
    db.execute("""CREATE TABLE IF NOT EXISTS ai_configuration (
        config_id INTEGER PRIMARY KEY CHECK(config_id=1),
        text_model TEXT NOT NULL DEFAULT 'gpt-5.6-terra',
        transcription_model TEXT NOT NULL DEFAULT 'gpt-4o-mini-transcribe',
        voice_enabled INTEGER NOT NULL DEFAULT 1,
        updated_by TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    db.execute("""INSERT OR IGNORE INTO ai_configuration(
        config_id,text_model,transcription_model,voice_enabled
    ) VALUES(1,?,?,1)""", (
        DEFAULT_OPENAI_REVIEW_MODEL,
        DEFAULT_OPENAI_TRANSCRIPTION_MODEL,
    ))


def read_ai_configuration(db):
    ensure_ai_configuration_schema(db)
    row = db.execute("""SELECT text_model,transcription_model,voice_enabled,
                               updated_by,updated_dt
                        FROM ai_configuration WHERE config_id=1""").fetchone()
    values = dict(row) if row else {}
    text_model = str(values.get("text_model", "") or "").strip()
    transcription_model = str(
        values.get("transcription_model", "") or ""
    ).strip()
    if text_model not in OPENAI_TEXT_MODELS:
        text_model = DEFAULT_OPENAI_REVIEW_MODEL
    if transcription_model not in OPENAI_TRANSCRIPTION_MODELS:
        transcription_model = DEFAULT_OPENAI_TRANSCRIPTION_MODEL
    return {
        "text_model": text_model,
        "transcription_model": transcription_model,
        "voice_enabled": 1 if int(values.get("voice_enabled", 1) or 0) else 0,
        "updated_by": str(values.get("updated_by", "") or ""),
        "updated_dt": str(values.get("updated_dt", "") or ""),
    }


def openai_secret_path(database_path):
    return Path(str(database_path)).expanduser().resolve().parent / OPENAI_SECRET_FILENAME


def read_saved_openai_api_key(database_path):
    path = openai_secret_path(database_path)
    try:
        return path.read_text(encoding="utf-8").strip()
    except (FileNotFoundError, OSError, UnicodeError):
        return ""


def resolve_openai_api_key(database_path):
    """Environment configuration takes precedence over the Admin-saved key."""
    environment_key = str(os.environ.get("OPENAI_API_KEY", "") or "").strip()
    if environment_key:
        return environment_key, "environment"
    saved_key = read_saved_openai_api_key(database_path)
    return saved_key, ("saved" if saved_key else "")


def masked_openai_api_key(api_key):
    value = str(api_key or "").strip()
    if not value:
        return ""
    suffix = value[-4:] if len(value) >= 4 else ""
    return "••••••••" + suffix


def save_openai_api_key(database_path, api_key):
    value = str(api_key or "").strip()
    if len(value) < 20 or any(character.isspace() for character in value):
        raise ValueError("The API key is invalid. Paste the complete key without spaces.")
    path = openai_secret_path(database_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(
        ".%s.%s.tmp" % (path.name.lstrip("."), secrets.token_hex(8))
    )
    descriptor = os.open(
        str(temporary), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600
    )
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            handle.write(value + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(str(temporary), str(path))
        try:
            os.chmod(str(path), 0o600)
        except OSError:
            pass
    finally:
        try:
            if temporary.exists():
                temporary.unlink()
        except OSError:
            pass
    return path


def delete_saved_openai_api_key(database_path):
    path = openai_secret_path(database_path)
    try:
        path.unlink()
        return True
    except FileNotFoundError:
        return False


def openai_api_url(path):
    base = str(
        os.environ.get("OPENAI_API_BASE", "https://api.openai.com/v1") or ""
    ).strip().rstrip("/")
    return base + "/" + str(path or "").lstrip("/")


def _openai_error_message(exc, fallback):
    try:
        payload = json.loads(exc.read().decode("utf-8", errors="replace"))
        message = str(payload.get("error", {}).get("message", "") or "").strip()
    except Exception:
        message = ""
    return message or "%s (HTTP %s)." % (fallback, getattr(exc, "code", "?"))


def test_openai_api_key(api_key, text_model):
    """Verify both authentication and access to the configured text model."""
    model = str(text_model or DEFAULT_OPENAI_REVIEW_MODEL).strip()
    request = Request(
        openai_api_url("models/%s" % quote(model, safe="")),
        headers={"Authorization": "Bearer " + str(api_key or "").strip()},
        method="GET",
    )
    try:
        with urlopen(request, timeout=20) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        raise RuntimeError(_openai_error_message(exc, "OpenAI connection test failed"))
    except URLError as exc:
        raise RuntimeError(
            "Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc)
        )
    if str(payload.get("id", "") or "").strip() != model:
        raise RuntimeError("OpenAI returned an unexpected model response.")
    return model


def request_openai_transcription(
    api_key, audio_bytes, filename, content_type, language_code,
    model=DEFAULT_OPENAI_TRANSCRIPTION_MODEL,
):
    """Transcribe one short browser recording without retaining the audio."""
    language_code = "vi" if str(language_code or "").lower() == "vi" else "en"
    model = str(model or DEFAULT_OPENAI_TRANSCRIPTION_MODEL).strip()
    if model not in OPENAI_TRANSCRIPTION_MODELS:
        model = DEFAULT_OPENAI_TRANSCRIPTION_MODEL
    audio_bytes = bytes(audio_bytes or b"")
    if not audio_bytes:
        raise ValueError("The audio recording is empty.")
    if len(audio_bytes) > 6 * 1024 * 1024:
        raise ValueError("The recording is too large. Record no more than 60 seconds.")
    safe_filename = re.sub(
        r"[^A-Za-z0-9_.-]+", "_", str(filename or "vitals.webm")
    ).strip("._") or "vitals.webm"
    safe_content_type = str(content_type or "audio/webm").split(";", 1)[0].strip()
    if safe_content_type not in {
        "audio/webm", "audio/ogg", "audio/wav", "audio/x-wav",
        "audio/mpeg", "audio/mp4", "video/webm",
    }:
        raise ValueError("This browser audio format is not supported.")
    boundary = "----EIUEMR%s" % secrets.token_hex(16)
    prompt = (
        "A nurse is dictating vital signs only. Preserve every measurement "
        "as digits and preserve the original language. Expected terms include "
        "pulse, blood pressure, temperature, respiratory rate, SpO2, pain "
        "score, capillary blood glucose, height, weight and AVPU."
        if language_code == "en" else
        "Điều dưỡng đang đọc dấu sinh hiệu. Giữ mọi số đo ở dạng chữ số và "
        "giữ nguyên tiếng Việt. Các thuật ngữ có thể gồm mạch, huyết áp, "
        "nhiệt độ, nhịp thở, SpO2, điểm đau, đường huyết mao mạch, chiều cao, "
        "cân nặng và AVPU."
    )

    def field(name, value):
        return (
            "--%s\r\nContent-Disposition: form-data; name=\"%s\"\r\n\r\n%s\r\n"
            % (boundary, name, value)
        ).encode("utf-8")

    body = b"".join((
        field("model", model),
        field("language", language_code),
        field("prompt", prompt),
        (
            "--%s\r\nContent-Disposition: form-data; name=\"file\"; "
            "filename=\"%s\"\r\nContent-Type: %s\r\n\r\n"
            % (boundary, safe_filename, safe_content_type)
        ).encode("utf-8"),
        audio_bytes,
        ("\r\n--%s--\r\n" % boundary).encode("ascii"),
    ))
    request = Request(
        openai_api_url("audio/transcriptions"),
        data=body,
        headers={
            "Authorization": "Bearer " + str(api_key or "").strip(),
            "Content-Type": "multipart/form-data; boundary=%s" % boundary,
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=90) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        raise RuntimeError(_openai_error_message(exc, "Speech recognition failed"))
    except URLError as exc:
        raise RuntimeError(
            "Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc)
        )
    except (ValueError, OSError) as exc:
        raise RuntimeError("Invalid speech recognition response: %s" % exc)
    transcript = " ".join(str(payload.get("text", "") or "").split()).strip()
    if not transcript:
        raise RuntimeError("Speech recognition returned no text.")
    return transcript


def extract_vitals_from_transcript(transcript):
    """Extract explicitly dictated measurements; never infer missing values."""
    text_value = unicodedata.normalize("NFKC", str(transcript or ""))
    normalized = text_value.casefold().replace(",", ".")
    values = {}
    rejected = []

    def capture(key, patterns, minimum, maximum):
        for pattern in patterns:
            match = re.search(pattern, normalized, flags=re.IGNORECASE)
            if not match:
                continue
            try:
                number = float(match.group(1))
            except (TypeError, ValueError):
                continue
            if minimum <= number <= maximum:
                values[key] = (
                    str(int(number)) if number.is_integer()
                    else ("%.2f" % number).rstrip("0").rstrip(".")
                )
            else:
                rejected.append(key)
            return

    bp_match = re.search(
        r"(?:huy[eế]t\s*[aá]p|blood\s*pressure|\bbp\b)\s*(?:l[aà]\s*)?"
        r"(\d{2,3})\s*(?:/|tr[eê]n|over)\s*(\d{2,3})",
        normalized, flags=re.IGNORECASE,
    )
    if bp_match:
        systolic, diastolic = int(bp_match.group(1)), int(bp_match.group(2))
        if 40 <= systolic <= 300 and 20 <= diastolic <= 200:
            values["bp_sys"], values["bp_dia"] = str(systolic), str(diastolic)
        else:
            rejected.extend(["bp_sys", "bp_dia"])
    capture("pulse", (
        r"(?:m[aạ]ch|pulse|heart\s*rate)\s*(?:l[aà]\s*)?(\d{1,3}(?:\.\d+)?)",
    ), 20, 300)
    capture("temp", (
        r"(?:nhi[eệ]t\s*(?:đ[oộ]|do)|temperature|\btemp\b)\s*(?:l[aà]\s*)?(\d{2}(?:\.\d+)?)",
    ), 25, 45)
    capture("rr", (
        r"(?:nh[iị]p\s*th[oở]|respiratory\s*rate|respirations?|\brr\b)\s*(?:l[aà]\s*)?(\d{1,2}(?:\.\d+)?)",
    ), 3, 90)
    capture("spo2", (
        r"(?:spo\s*2|saturation|đ[oộ]\s*b[aã]o\s*h[oò]a)\s*(?:l[aà]\s*)?(\d{1,3}(?:\.\d+)?)",
    ), 1, 100)
    capture("pain_score", (
        r"(?:đi[eể]m\s*đau|pain(?:\s*score)?)\s*(?:l[aà]\s*)?(\d{1,2}(?:\.\d+)?)",
    ), 0, 10)
    capture("bg", (
        r"(?:đ[uư][oờ]ng\s*huy[eế]t(?:\s*mao\s*m[aạ]ch)?|blood\s*glucose|glucose|\bbg\b)\s*(?:l[aà]\s*)?(\d{1,3}(?:\.\d+)?)",
    ), 0.1, 60)
    capture("height", (
        r"(?:chi[eề]u\s*cao|height)\s*(?:l[aà]\s*)?(\d{2,3}(?:\.\d+)?)",
    ), 30, 250)
    capture("weight", (
        r"(?:c[aâ]n\s*n[aặ]ng|weight)\s*(?:l[aà]\s*)?(\d{1,3}(?:\.\d+)?)",
    ), 0.5, 500)
    avpu_patterns = (
        ("U", r"(?:\bavpu\s*u\b|\bunresponsive\b|kh[oô]ng\s*đ[aá]p\s*[uứ]ng)"),
        ("P", r"(?:\bavpu\s*p\b|\bpain response\b|đ[aá]p\s*[uứ]ng\s*đau)"),
        ("V", r"(?:\bavpu\s*v\b|\bvoice response\b|đ[aá]p\s*[uứ]ng\s*l[oờ]i)"),
        ("A", r"(?:\bavpu\s*a\b|\balert\b|t[iỉ]nh\s*t[aá]o)"),
    )
    if "avpu" in normalized or "tỉnh táo" in normalized or "đáp ứng" in normalized:
        for code, pattern in avpu_patterns:
            if re.search(pattern, normalized, flags=re.IGNORECASE):
                values["avpu"] = code
                break
    return values, sorted(set(rejected))

# The vital signs the Nursing Process tab documents. They are never typed
# there: a nurse picks one Nursing Care Time observation that was already
# recorded, and these values (plus its date/time) are copied across.
PROCESS_VITAL_KEYS = (
    "pulse", "bp_sys", "bp_dia", "temp", "rr", "spo2", "pain_score", "bg",
)


def _normalized_vital_key(raw_key):
    key = str(raw_key or "").strip().lower()
    for prefix in ("process_vital_", "triage_"):
        if key.startswith(prefix):
            key = key[len(prefix):]
    return {
        "glucose": "bg", "blood_glucose": "bg",
        "capillary_glucose": "bg", "systolic": "bp_sys",
        "diastolic": "bp_dia", "temperature": "temp",
        "respiratory_rate": "rr", "pain": "pain_score",
    }.get(key, key)


