VITAL_THRESHOLD_SPEC_BY_KEY = {
    item[0]: {
        "key": item[0], "label_en": item[1], "label_vi": item[2],
        "unit": item[3], "hard_min": item[4], "hard_max": item[5],
        "bold_min": item[6], "bold_max": item[7],
        "alert_min": item[8], "alert_max": item[9],
    }
    for item in VITAL_THRESHOLD_SPECS
}


def default_vital_thresholds(kind="bold"):
    prefix = "alert" if str(kind) == "alert" else "bold"
    return {
        key: {
            "min": float(spec[prefix + "_min"]),
            "max": float(spec[prefix + "_max"]),
        }
        for key, spec in VITAL_THRESHOLD_SPEC_BY_KEY.items()
    }


def validated_vital_thresholds(raw_value, kind="bold"):
    """Return a complete, bounded min/max map for per-user vital settings."""
    defaults = default_vital_thresholds(kind)
    if isinstance(raw_value, str):
        try:
            raw_value = json.loads(raw_value) if raw_value.strip() else {}
        except (TypeError, ValueError, json.JSONDecodeError):
            raw_value = {}
    source = raw_value if isinstance(raw_value, dict) else {}
    result = {}
    for key, spec in VITAL_THRESHOLD_SPEC_BY_KEY.items():
        item = source.get(key, {})
        item = item if isinstance(item, dict) else {}
        try:
            lower = float(item.get("min", defaults[key]["min"]))
            upper = float(item.get("max", defaults[key]["max"]))
        except (TypeError, ValueError):
            lower = defaults[key]["min"]
            upper = defaults[key]["max"]
        if not math.isfinite(lower) or not math.isfinite(upper):
            lower = defaults[key]["min"]
            upper = defaults[key]["max"]
        lower = max(float(spec["hard_min"]), min(float(spec["hard_max"]), lower))
        upper = max(float(spec["hard_min"]), min(float(spec["hard_max"]), upper))
        if lower > upper:
            lower = defaults[key]["min"]
            upper = defaults[key]["max"]
        result[key] = {"min": lower, "max": upper}
    return result


def vital_value_is_abnormal(raw_key, raw_value, vitals=None, thresholds=None):
    """Flag values outside configured (or default) observation ranges.

    These visual flags are prompts for review, not diagnoses. Defaults remain
    available until the signed-in account saves its own thresholds.
    """
    key = _normalized_vital_key(raw_key)
    source = vitals if isinstance(vitals, dict) else {}
    if key == "bp":
        text = str(raw_value or "").strip()
        if "/" in text:
            systolic, _, diastolic = text.partition("/")
            return (
                vital_value_is_abnormal(
                    "bp_sys", systolic, source, thresholds
                )
                or vital_value_is_abnormal(
                    "bp_dia", diastolic, source, thresholds
                )
            )
        return False
    if key == "avpu":
        code = str(raw_value or "").strip().upper()[:1]
        return bool(code and code != "A")
    number = _mews_number(raw_value)
    if number is None:
        return False
    ranges = validated_vital_thresholds(thresholds, "bold")
    selected = ranges.get(key)
    if not selected:
        return False
    lower, upper = selected["min"], selected["max"]
    return number < lower or number > upper


def vital_threshold_violations(vitals, thresholds):
    """List recorded numeric observations outside configured alert limits."""
    source = vitals if isinstance(vitals, dict) else {}
    normalized = _process_vitals_from_record(source)
    for extra_key in ("map", "gcs"):
        normalized[extra_key] = source.get(extra_key, "")
    ranges = validated_vital_thresholds(thresholds, "alert")
    result = []
    for key, limits in ranges.items():
        number = _mews_number(normalized.get(key, ""))
        if number is None:
            continue
        if number < limits["min"] or number > limits["max"]:
            result.append({
                "key": key,
                "value": number,
                "min": limits["min"],
                "max": limits["max"],
            })
    return result


def _vital_summary_parts(vitals, thresholds=None):
    source = vitals if isinstance(vitals, dict) else {}

    def value(key):
        return " ".join(str(source.get(key, "") or "").split())

    blood_pressure = value("bp") or "/".join(
        part for part in (value("bp_sys"), value("bp_dia")) if part
    )
    bp_abnormal = (
        vital_value_is_abnormal("bp", blood_pressure, source, thresholds)
        or vital_value_is_abnormal(
            "bp_sys", value("bp_sys"), source, thresholds
        )
        or vital_value_is_abnormal(
            "bp_dia", value("bp_dia"), source, thresholds
        )
    )
    return [
        ("pulse", "M", value("pulse"), "l/p",
         vital_value_is_abnormal("pulse", value("pulse"), source, thresholds)),
        ("bp", "HA", blood_pressure, "mmHg", bp_abnormal),
        ("temp", "T", value("temp"), "C",
         vital_value_is_abnormal("temp", value("temp"), source, thresholds)),
        ("rr", "NT", value("rr"), "l/p",
         vital_value_is_abnormal("rr", value("rr"), source, thresholds)),
        ("spo2", "SpO2", value("spo2"), "%",
         vital_value_is_abnormal("spo2", value("spo2"), source, thresholds)),
        ("pain_score", "Đau", value("pain_score"), "/10",
         vital_value_is_abnormal(
            "pain_score", value("pain_score"), source, thresholds
         )),
        ("bg", "ĐH", value("bg") or value("glucose"), "mmol/L",
         vital_value_is_abnormal(
            "bg", value("bg") or value("glucose"), source, thresholds
         )),
        ("avpu", "AVPU", value("avpu"), "",
         vital_value_is_abnormal("avpu", value("avpu"), source)),
    ]


def _vital_summary_html(vitals, thresholds=None):
    parts = []
    for _key, label, text_value, unit, abnormal in _vital_summary_parts(
        vitals, thresholds
    ):
        if not text_value:
            continue
        content = "%s %s %s" % (label, text_value, unit)
        escaped = html.escape(content)
        if abnormal:
            escaped = (
                '<strong class="vital-abnormal-value" '
                'title="Outside configured bold range">%s</strong>'
                % escaped
            )
        parts.append(escaped)
    return " · ".join(parts)


def _vital_summary_pdf_markup(vitals, thresholds=None, bold_color="#991b1b"):
    bold_color = str(bold_color or "#991b1b")
    if not re.match(r"^#[0-9a-fA-F]{6}$", bold_color):
        bold_color = "#991b1b"
    parts = []
    for _key, label, text_value, unit, abnormal in _vital_summary_parts(
        vitals, thresholds
    ):
        if not text_value:
            continue
        escaped = html.escape("%s %s %s" % (label, text_value, unit))
        parts.append(
            '<font color="%s"><b>%s</b></font>' % (
                bold_color, escaped
            ) if abnormal else escaped
        )
    return " · ".join(parts) or "-"


def _process_vitals_from_record(raw_vitals):
    """Pull the eight Nursing Process vital signs out of a stored Nursing
    Care vitals dict, splitting the combined "120/80" blood pressure back
    into its systolic/diastolic parts when they were not stored apart."""
    source = raw_vitals if isinstance(raw_vitals, dict) else {}
    picked = {
        key: " ".join(str(source.get(key, "") or "").split())
        for key in PROCESS_VITAL_KEYS
    }
    if not picked["bp_sys"] and not picked["bp_dia"]:
        combined = str(source.get("bp", "") or "").strip()
        if "/" in combined:
            systolic, _, diastolic = combined.partition("/")
            picked["bp_sys"] = systolic.strip()
            picked["bp_dia"] = diastolic.strip()
    if not picked["bg"]:
        picked["bg"] = " ".join(str(source.get("glucose", "") or "").split())
    return picked



def _fluid_number(text_value):
    """Đọc một số mL từ ô nhập. Chấp nhận dấu phẩy thập phân; rỗng = 0."""
    text_value = str(text_value or "").replace(",", ".").strip()
    if not text_value:
        return 0.0
    try:
        number = float(text_value)
    except (TypeError, ValueError):
        return 0.0
    if number != number or number in (float("inf"), float("-inf")):
        return 0.0
    return number


def _fluid_source_options(summary_text):
    """Rút danh sách gợi ý ngắn gọn từ phần tóm tắt y lệnh đang hoạt động.

    Ô "Dịch truyền" lấy gợi ý từ y lệnh THUỐC, ô "Ăn uống" lấy từ y lệnh DINH
    DƯỠNG, nên điều dưỡng chỉ chọn đúng thứ bác sĩ đã ra y lệnh rồi điền thể
    tích, thay vì gõ lại tên. Vẫn cho gõ tay tự do (datalist, không phải
    select) để ghi được thứ ngoài y lệnh, ví dụ nước lọc người nhà mang vào.
    """
    options = []
    for raw_line in str(summary_text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith("Order ["):
            close = line.find("] ")
            if close > 0:
                line = line[close + 2:]
        if line.endswith(")"):
            opened = line.rfind(" (")
            if opened > 0:
                line = line[:opened]
        parts = [
            part.strip() for part in line.split("|")
            if part.strip() and not part.strip().lower().startswith("schedule")
        ]
        label = " - ".join(parts[:4]).strip()
        if label and label not in options:
            options.append(label)
    return options


FLUID_CHART_HOURS = 24
FLUID_CHART_FIELDS = (
    "hour", "iv", "iv_ml", "oral", "oral_ml", "urine_ml", "other_out_ml",
    # Cột cuối không còn là "cân bằng giờ" (máy tự tính, không cần ô riêng)
    # mà là ghi chú bất thường: tính chất dịch, màu sắc, mùi, phản ứng...
    "note",
)


def _fluid_totals_value(vitals, key):
    """Một ô tổng kết đã lưu; trả "" khi bản ghi cũ chưa có bảng theo giờ."""
    totals = vitals.get("fluid_totals") if isinstance(vitals, dict) else None
    if not isinstance(totals, dict):
        return ""
    return str(totals.get(key, "") or "")


def _fluid_clock_minutes(value):
    """Đổi "HH:MM" thành số phút trong ngày; trả None nếu ô giờ để trống."""
    parts = str(value or "").strip().split(":")
    if len(parts) < 2:
        return None
    try:
        hour, minute = int(parts[0]), int(parts[1])
    except (TypeError, ValueError):
        return None
    if not (0 <= hour <= 23 and 0 <= minute <= 59):
        return None
    return hour * 60 + minute


def fluid_elapsed_minutes(rows):
    """Số phút đã trôi qua của từng dòng, tính từ dòng theo dõi đầu tiên.

    Giờ ghi trong bảng là giờ trong ngày, nên khi sang ngày mới (22:00 -> 01:00)
    hiệu số được cộng thêm 24 giờ thay vì thành số âm. Dòng không ghi giờ được
    coi là cách dòng trước 1 tiếng.
    """
    elapsed, previous, started, result = 0, None, False, []
    for item in rows:
        current = _fluid_clock_minutes(
            item.get("hour") if isinstance(item, dict) else ""
        )
        if not started:
            started = True
        elif previous is None or current is None:
            elapsed += 60
        else:
            elapsed += (current - previous) % 1440
        if current is not None:
            previous = current
        result.append(elapsed)
    return result


# ---------------------------------------------------------------------------
# Mất nước không nhận biết qua da và hơi thở (insensible water loss)
#
# Nguồn:
#   (1) Hall JE. Guyton & Hall Textbook of Medical Physiology. 15th ed.
#       Elsevier; 2024 - người trưởng thành mất khoảng 600-800 mL/ngày,
#       chủ yếu qua da và phổi.
#   (2) Marino PL. The ICU Book. 5th ed. Wolters Kluwer; 2023 - thực hành
#       hồi sức ước tính insensible loss khoảng 0,5 mL/kg/giờ, tăng khi
#       sốt, tăng thông khí và bỏng.
#
# Máy tự tính theo cân nặng và số giờ thực sự đã theo dõi, rồi cộng thêm
# cho sốt. Điều dưỡng vẫn ghi đè bằng tay được (bỏng, thở máy không làm ẩm,
# nằm giường sưởi...) - ô nhập tay luôn thắng số máy tính.
# ---------------------------------------------------------------------------
FLUID_INSENSIBLE_ML_PER_KG_HOUR = 0.5
# Mỗi 1°C thân nhiệt trên 37°C làm tăng insensible loss khoảng 10-12,5%.
FLUID_INSENSIBLE_FEVER_PERCENT = 12.5
FLUID_INSENSIBLE_FEVER_BASE_C = 37.0
# Cân nặng dự phòng khi phiếu chưa ghi cân nặng: dùng mức 600-800 mL/ngày
# của Guyton & Hall quy về 0,5 mL/kg/giờ, tương ứng một người lớn ~58 kg.
FLUID_INSENSIBLE_FALLBACK_KG = 58.0


def _fluid_insensible_ml_per_hour(weight_kg, temp_c=None):
    """mL mất qua da và hơi thở trong MỘT giờ, đã hiệu chỉnh theo sốt."""
    weight = _fluid_number(weight_kg)
    if weight <= 0:
        weight = FLUID_INSENSIBLE_FALLBACK_KG
    rate = weight * FLUID_INSENSIBLE_ML_PER_KG_HOUR
    temperature = _fluid_number(temp_c)
    # Chỉ hiệu chỉnh khi thân nhiệt đọc được và thực sự là số đo người
    # (bỏ qua ô gõ nhầm như 3.7 hay 370).
    if 30.0 <= temperature <= 45.0 and temperature > FLUID_INSENSIBLE_FEVER_BASE_C:
        degrees_over = temperature - FLUID_INSENSIBLE_FEVER_BASE_C
        rate *= 1.0 + (FLUID_INSENSIBLE_FEVER_PERCENT / 100.0) * degrees_over
    return rate


def fluid_insensible_loss(weight_kg, temp_c=None, minutes=0):
    """Tổng mất nước qua da và hơi thở trong ``minutes`` phút theo dõi."""
    try:
        span = float(minutes or 0)
    except (TypeError, ValueError):
        span = 0.0
    if span <= 0:
        return 0.0
    return _fluid_insensible_ml_per_hour(weight_kg, temp_c) * (span / 60.0)


def fluid_insensible_summary(weight_kg, temp_c=None):
    """Câu giải thích ngắn hiện dưới ô Mất nước qua da và hơi thở."""
    weight = _fluid_number(weight_kg)
    used_weight = weight if weight > 0 else FLUID_INSENSIBLE_FALLBACK_KG
    parts = [
        "%.1f mL/kg/giờ x %.1f kg" % (
            FLUID_INSENSIBLE_ML_PER_KG_HOUR, used_weight,
        )
    ]
    if weight <= 0:
        parts[-1] += " (chưa ghi cân nặng - dùng mức người lớn chuẩn)"
    temperature = _fluid_number(temp_c)
    if 30.0 <= temperature <= 45.0 and temperature > FLUID_INSENSIBLE_FEVER_BASE_C:
        parts.append(
            "+%.1f%%/°C sốt (%.1f°C)" % (
                FLUID_INSENSIBLE_FEVER_PERCENT, temperature,
            )
        )
    parts.append("= %.0f mL/giờ" % _fluid_insensible_ml_per_hour(
        weight_kg, temp_c,
    ))
    return " ; ".join(parts)


def collect_fluid_chart(form_data, weight_kg="", temp_c=""):
    """Đọc bảng theo dõi dịch theo giờ từ biểu mẫu và tự tính mọi tổng số.

    Trả về (danh sách dòng có dữ liệu, dict tổng kết). Cân bằng 12 giờ tính
    trên 12 dòng đầu, cân bằng 24 giờ tính trên cả bảng. Mọi con số đều được
    tính lại ở máy chủ, không tin giá trị do trình duyệt gửi lên.

    Dịch ra gồm cả MẤT NƯỚC QUA DA VÀ HƠI THỞ (insensible loss): máy tự tính
    0,5 mL/kg/giờ theo cân nặng và thời gian đã theo dõi, cộng thêm cho sốt;
    điều dưỡng ghi đè bằng tay được qua ô fluid_insensible_12h /
    fluid_insensible_24h. Bỏ khoản này thì cân bằng dịch luôn dương giả.
    """
    rows = []
    for index in range(FLUID_CHART_HOURS):
        row = {
            key: str(
                form_data.get("fluid_%s_%d" % (key, index), "") or ""
            ).strip()
            for key in FLUID_CHART_FIELDS
        }
        if not any(
            row[key] for key in FLUID_CHART_FIELDS if key != "hour"
        ):
            continue
        for key in ("iv_ml", "oral_ml", "urine_ml", "other_out_ml"):
            if row[key] and _fluid_number(row[key]) < 0:
                raise ValueError(
                    "Thể tích dịch ở giờ thứ %d không được là số âm."
                    % (index + 1)
                )
        row["index"] = index
        row["in_ml"] = "%.1f" % (
            _fluid_number(row["iv_ml"]) + _fluid_number(row["oral_ml"])
        )
        row["out_ml"] = "%.1f" % (
            _fluid_number(row["urine_ml"])
            + _fluid_number(row["other_out_ml"])
        )
        row["balance_ml"] = "%.1f" % (
            _fluid_number(row["in_ml"]) - _fluid_number(row["out_ml"])
        )
        rows.append(row)

    def total(selected, key):
        return sum(_fluid_number(item[key]) for item in selected)

    # Mốc tổng kết tính theo GIỜ ĐÃ GHI, không theo số thứ tự dòng: điều dưỡng
    # có thể bỏ trống vài giờ không theo dõi, và bảng chỉ lưu những dòng thực
    # sự có số liệu.
    for item, minutes in zip(rows, fluid_elapsed_minutes(rows)):
        item["elapsed_min"] = minutes
    first_half = [item for item in rows if item["elapsed_min"] < 720]
    within_day = [item for item in rows if item["elapsed_min"] < 1440]
    totals = {"rows_beyond_24h": len(rows) - len(within_day)}
    # Số giờ thực sự đã theo dõi của từng mốc tổng kết. Dòng đầu tiên tính
    # là 0 phút, nên khoảng theo dõi là phút của dòng cuối cùng trong mốc;
    # bảng chỉ có một dòng thì coi như tròn 1 giờ để vẫn có số liệu.
    def elapsed_span(selected):
        if not selected:
            return 0.0
        span = float(selected[-1]["elapsed_min"] - selected[0]["elapsed_min"])
        return span if span > 0 else 60.0

    for label, selected, cap in (
        ("12h", first_half, 720.0), ("24h", within_day, 1440.0),
    ):
        volume_in = total(selected, "iv_ml") + total(selected, "oral_ml")
        measured_out = (
            total(selected, "urine_ml") + total(selected, "other_out_ml")
        )
        span = min(elapsed_span(selected), cap)
        auto_insensible = fluid_insensible_loss(weight_kg, temp_c, span)
        manual_insensible = str(
            form_data.get("fluid_insensible_" + label, "") or ""
        ).strip()
        if manual_insensible:
            if _fluid_number(manual_insensible) < 0:
                raise ValueError(
                    "Mất nước qua da và hơi thở không được là số âm."
                )
            insensible = _fluid_number(manual_insensible)
            totals["insensible_source_" + label] = "manual"
        else:
            insensible = auto_insensible
            totals["insensible_source_" + label] = "auto"
        volume_out = measured_out + insensible
        totals["hours_" + label] = "%.1f" % (span / 60.0)
        totals["insensible_" + label] = "%.1f" % insensible
        totals["insensible_auto_" + label] = "%.1f" % auto_insensible
        totals["measured_out_" + label] = "%.1f" % measured_out
        totals["in_" + label] = "%.1f" % volume_in
        totals["out_" + label] = "%.1f" % volume_out
        totals["balance_" + label] = "%.1f" % (volume_in - volume_out)
    totals["iv_24h"] = "%.1f" % total(within_day, "iv_ml")
    totals["oral_24h"] = "%.1f" % total(within_day, "oral_ml")
    totals["urine_24h"] = "%.1f" % total(within_day, "urine_ml")
    # "Dịch ra khác" gộp luôn phần mất qua da và hơi thở, vì bốn ô tổng cũ
    # (input_total_ml / urine_ml / output_total_ml / balance_ml) mà Desktop,
    # PDF và các báo cáo đang đọc chỉ có ba khoang. Không gộp thì cân bằng
    # ở những nơi đó lệch đúng bằng lượng insensible loss.
    totals["other_out_24h"] = "%.1f" % (
        total(within_day, "other_out_ml") + _fluid_number(
            totals.get("insensible_24h", "0")
        )
    )
    totals["other_out_measured_24h"] = "%.1f" % total(
        within_day, "other_out_ml"
    )
    totals["insensible_note"] = fluid_insensible_summary(weight_kg, temp_c)
    return rows, totals



# ---------------------------------------------------------------------------
# Hai thang lượng giá nguy cơ trong Nursing Assessment
#
# JHFRAT - Johns Hopkins Fall Risk Assessment Tool (nguy cơ té ngã)
#   Bảy nhóm yếu tố, tổng tối đa 35 điểm.
#   Phân loại: dưới 6 = nguy cơ THẤP, 6-13 = TRUNG BÌNH, trên 13 = CAO.
#   Hai tình huống xác định thẳng mức nguy cơ, bỏ qua tính điểm:
#     - Đã ngã trong lần nằm viện này  -> nguy cơ CAO
#     - Liệt hoàn toàn / bất động hoàn toàn -> nguy cơ THẤP
#
#   LƯU Ý BẢN QUYỀN: JHFRAT là công cụ có bản quyền của Johns Hopkins
#   Medicine và được cấp phép theo từng cơ sở. Trước khi dùng cho chăm sóc
#   người bệnh thật (ngoài mục đích giảng dạy), cơ sở cần có giấy phép hợp lệ.
#
# Braden Scale (nguy cơ loét tì đè)
#   Sáu tiểu mục; năm mục 1-4 điểm, riêng Ma sát & Trượt 1-3 điểm.
#   Tổng 6-23; ĐIỂM CÀNG THẤP thì nguy cơ CÀNG CAO.
#   Phân loại: >=19 không nguy cơ, 15-18 nhẹ, 13-14 trung bình,
#              10-12 cao, <=9 rất cao.
#   Braden Scale là tài sản trí tuệ của Barbara Braden và Nancy Bergstrom.
# ---------------------------------------------------------------------------

