UI_TRANSLATIONS.update(UI_TRANSLATIONS_ADDED)

UNTRANSLATED_UI_STRINGS = set()

_I18N_SKIP_BLOCKS = re.compile(
    r"<(script|style|textarea)\b[^>]*>.*?</\1>", re.S | re.I
)
_I18N_TEXT_NODE = re.compile(r">([^<>]+)<")
_I18N_ATTRIBUTE = re.compile(
    r'\b(placeholder|title|aria-label|alt)="([^"]*)"'
)


def normalize_app_language(value):
    """Mã ngôn ngữ hợp lệ; mọi giá trị lạ đều về mặc định (Tiếng Anh)."""
    code = str(value or "").strip().lower()[:2]
    return code if code in dict(APP_LANGUAGES) else DEFAULT_APP_LANGUAGE


def load_external_translations():
    """Nạp thêm translations.json cạnh ứng dụng (nếu có) và đè lên danh mục."""
    path = os.path.join(application_install_dir(), "translations.json")
    if not os.path.exists(path):
        return 0
    try:
        with open(path, "r", encoding="utf-8") as handle:
            rows = json.load(handle)
    except Exception:
        return 0
    added = 0
    if isinstance(rows, dict):
        rows = [
            [key, value.get("en", ""), value.get("vi", "")]
            for key, value in rows.items() if isinstance(value, dict)
        ]
    for row in rows or []:
        if not isinstance(row, (list, tuple)) or len(row) < 3:
            continue
        source = " ".join(str(row[0] or "").split())
        if not source:
            continue
        UI_TRANSLATIONS[source] = (str(row[1] or ""), str(row[2] or ""))
        added += 1
    return added


_I18N_COUNT_SUFFIX = re.compile(r"^(.*?)\s*\((\d+)\)$")
# Nhan ket thuc bang mot con so tran, vi du "Evaluation for diagnosis 1".
_I18N_TRAILING_NUMBER = re.compile(r"^(.*?[^\d\s])\s+(\d+)$")
_I18N_LABEL_VALUE = re.compile(r"^([^:]{2,}?)\s*:\s*(.+)$")
# Lua chon dang "1 - Hoan toan han che": dich phan nhan, giu nguyen so diem.
_I18N_NUMBER_PREFIX = re.compile(r"^(\d+)\s*-\s*(.+)$")


def _lookup_ui_entry(key, language):
    entry = UI_TRANSLATIONS.get(key)
    if not entry:
        return None
    index = 1 if normalize_app_language(language) == "vi" else 0
    return entry[index] or entry[0] or key


def translate_ui_text(value, language=DEFAULT_APP_LANGUAGE):
    """Dịch một chuỗi hiển thị. Không tìm thấy thì trả nguyên văn.

    Ngoài việc tra khớp nguyên chuỗi, còn xử lý hai dạng nhãn có kèm phần
    động - rất phổ biến trong giao diện này:
      * "Chưa thực hiện (3)"  -> dịch phần nhãn, giữ nguyên con số
      * "Chẩn đoán: Viêm phổi" -> dịch phần nhãn, giữ nguyên nội dung
    Nhờ vậy một mục danh mục phục vụ được mọi giá trị, và nội dung lâm sàng
    do điều dưỡng nhập không bao giờ bị đụng tới.
    """
    raw = str(value if value is not None else "")
    key = " ".join(raw.split())
    if not key:
        return raw
    # Giữ nguyên khoảng trắng đầu/cuối của chuỗi gốc để bố cục không xô lệch.
    lead = raw[:len(raw) - len(raw.lstrip())]
    trail = raw[len(raw.rstrip()):]

    translated = _lookup_ui_entry(key, language)
    if translated is not None:
        return lead + translated + trail

    match = _I18N_COUNT_SUFFIX.match(key)
    if match:
        head = _lookup_ui_entry(match.group(1).strip(), language)
        if head is not None:
            return "%s%s (%s)%s" % (lead, head, match.group(2), trail)

    match = _I18N_TRAILING_NUMBER.match(key)
    if match:
        head = _lookup_ui_entry(match.group(1).strip(), language)
        if head is not None:
            return "%s%s %s%s" % (lead, head, match.group(2), trail)

    match = _I18N_NUMBER_PREFIX.match(key)
    if match:
        tail = _lookup_ui_entry(match.group(2).strip(), language)
        if tail is not None:
            return "%s%s - %s%s" % (lead, match.group(1), tail, trail)

    match = _I18N_LABEL_VALUE.match(key)
    if match:
        head = _lookup_ui_entry(match.group(1).strip(), language)
        if head is not None:
            return "%s%s: %s%s" % (lead, head, match.group(2), trail)

    UNTRANSLATED_UI_STRINGS.add(key)
    return raw


def translate_ui_html(markup, language=DEFAULT_APP_LANGUAGE):
    """Dịch một trang HTML đã dựng xong.

    Chỉ đụng vào phần chữ người dùng đọc: đoạn văn bản giữa các thẻ và bốn
    thuộc tính hiển thị. Bỏ qua hoàn toàn <script>, <style> và <textarea> - đó
    là mã lệnh và dữ liệu người dùng đã nhập, dịch vào là hỏng.
    """
    markup = str(markup or "")
    if normalize_app_language(language) == DEFAULT_APP_LANGUAGE and not any(
        entry[0] for entry in UI_TRANSLATIONS.values()
    ):
        return markup
    protected = []

    def stash(match):
        protected.append(match.group(0))
        return "\x00I18N%d\x00" % (len(protected) - 1)

    guarded = _I18N_SKIP_BLOCKS.sub(stash, markup)

    def text_node(match):
        original = match.group(1)
        if "\x00I18N" in original:
            return match.group(0)
        plain = html.unescape(original)
        if not plain.strip():
            return match.group(0)
        translated = translate_ui_text(plain, language)
        if translated == plain:
            return match.group(0)
        return ">" + html.escape(translated, quote=False) + "<"

    def attribute(match):
        name, original = match.group(1), match.group(2)
        plain = html.unescape(original)
        if not plain.strip():
            return match.group(0)
        translated = translate_ui_text(plain, language)
        if translated == plain:
            return match.group(0)
        return '%s="%s"' % (name, html.escape(translated, quote=True))

    guarded = _I18N_TEXT_NODE.sub(text_node, guarded)
    guarded = _I18N_ATTRIBUTE.sub(attribute, guarded)
    for index, block in enumerate(protected):
        guarded = guarded.replace("\x00I18N%d\x00" % index, block)
    return guarded


def read_app_language(connection):
    """Ngôn ngữ mặc định của cả hệ thống, lưu trong ui_label_settings."""
    try:
        row = connection.execute(
            "SELECT setting_value FROM ui_label_settings WHERE setting_key=?",
            (APP_LANGUAGE_SETTING_KEY,),
        ).fetchone()
    except sqlite3.Error:
        return DEFAULT_APP_LANGUAGE
    return normalize_app_language(row[0] if row else "")


def write_app_language(connection, language):
    """Ghi ngôn ngữ mặc định của hệ thống."""
    language = normalize_app_language(language)
    try:
        with connection:
            connection.execute(
                """INSERT INTO ui_label_settings(
                       setting_key,setting_value,updated_by,updated_dt
                   ) VALUES(?,?,?,?)
                   ON CONFLICT(setting_key) DO UPDATE SET
                       setting_value=excluded.setting_value,
                       updated_dt=excluded.updated_dt""",
                (APP_LANGUAGE_SETTING_KEY, language, "",
                 datetime.now().strftime("%Y-%m-%d %H:%M:00")),
            )
    except sqlite3.Error:
        return False
    return True


def normalize_wristband_label_layout(value=None):
    """Return safe, printable dimensions for the administrator label preset."""
    raw = value if isinstance(value, dict) else {}
    ranges = {
        "width_mm": (35.0, 160.0),
        "height_mm": (20.0, 100.0),
        "font_pt": (6.0, 24.0),
        "name_font_pt": (6.0, 30.0),
        "barcode_height_mm": (6.0, 60.0),
    }
    normalized = {}
    for key, default in DEFAULT_WRISTBAND_LABEL_LAYOUT.items():
        try:
            candidate = float(raw.get(key, default))
        except (TypeError, ValueError):
            candidate = default
        lower, upper = ranges[key]
        normalized[key] = max(lower, min(candidate, upper))
    # Do not permit an unreadable barcode that is taller than the label.
    normalized["barcode_height_mm"] = min(
        normalized["barcode_height_mm"],
        max(6.0, normalized["height_mm"] - 10.0),
    )
    return normalized


def read_wristband_label_layout(connection):
    try:
        row = connection.execute(
            "SELECT setting_value FROM ui_label_settings WHERE setting_key=?",
            (WRISTBAND_LAYOUT_SETTING_KEY,),
        ).fetchone()
        value = json.loads(row[0]) if row and row[0] else {}
    except (sqlite3.Error, TypeError, ValueError, json.JSONDecodeError):
        value = {}
    return normalize_wristband_label_layout(value)


def write_wristband_label_layout(connection, value, updated_by=""):
    layout = normalize_wristband_label_layout(value)
    try:
        with connection:
            connection.execute(
                """INSERT INTO ui_label_settings(
                       setting_key,setting_value,updated_by,updated_dt
                   ) VALUES(?,?,?,?)
                   ON CONFLICT(setting_key) DO UPDATE SET
                       setting_value=excluded.setting_value,
                       updated_by=excluded.updated_by,
                       updated_dt=excluded.updated_dt""",
                (
                    WRISTBAND_LAYOUT_SETTING_KEY,
                    json.dumps(layout, separators=(",", ":")),
                    str(updated_by or ""),
                    datetime.now().strftime("%Y-%m-%d %H:%M:00"),
                ),
            )
    except sqlite3.Error:
        return False
    return True


def patient_id_qr_svg(value, aria_label="Patient ID QR code"):
    """Build a self-contained SVG QR code for the unique patient ID."""
    try:
        from reportlab.graphics.barcode.qr import QrCodeWidget
        from reportlab.graphics.shapes import Drawing
        from reportlab.graphics import renderSVG
        widget = QrCodeWidget(str(value or ""))
        left, bottom, right, top = widget.getBounds()
        drawing = Drawing(right - left, top - bottom)
        drawing.add(widget)
        raw_svg = renderSVG.drawToString(drawing)
        svg_start = raw_svg.find("<svg")
        if svg_start < 0:
            return ""
        raw_svg = raw_svg[svg_start:]
        return raw_svg.replace(
            "<svg ",
            '<svg class="wristband-qr" role="img" aria-label="%s" '
            % html.escape(str(aria_label or ""), quote=True),
            1,
        )
    except Exception:
        return ""


def export_untranslated_strings(path=None):
    """Ghi ra danh sách chuỗi hiển thị chưa có bản dịch, để bổ sung dần.

    Kết quả là một tệp JSON đúng định dạng ``translations.json``: chỉ cần điền
    hai cột bản dịch rồi đặt cạnh ứng dụng.
    """
    path = path or os.path.join(
        application_install_dir(), "untranslated.json"
    )
    rows = [[item, "", ""] for item in sorted(UNTRANSLATED_UI_STRINGS)]
    try:
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(rows, handle, ensure_ascii=False, indent=1)
    except OSError:
        return ""
    return path


def ui_translation_coverage():
    """(số mục đã dịch, số chuỗi gặp mà chưa có bản dịch)."""
    return len(UI_TRANSLATIONS), len(UNTRANSLATED_UI_STRINGS)


def translate_widget_tree(widget, language=DEFAULT_APP_LANGUAGE):
    """Dịch toàn bộ chữ hiển thị của một cây widget Qt (bản Desktop).

    Bản gốc của mỗi ô chữ được nhớ lại ở lần dịch đầu tiên, nên đổi qua đổi
    lại giữa hai ngôn ngữ không bao giờ làm sai lệch chuỗi gốc.
    """
    if widget is None:
        return 0
    count = 0
    getters = (
        ("text", "setText"),
        ("placeholderText", "setPlaceholderText"),
        ("windowTitle", "setWindowTitle"),
        ("toolTip", "setToolTip"),
        ("title", "setTitle"),
    )
    stack = [widget]
    seen = set()
    while stack:
        node = stack.pop()
        if node is None or id(node) in seen:
            continue
        seen.add(id(node))
        for getter, setter in getters:
            try:
                read = getattr(node, getter, None)
                write = getattr(node, setter, None)
                if not callable(read) or not callable(write):
                    continue
                store = "_i18n_source_" + getter
                original = getattr(node, store, None)
                if original is None:
                    original = str(read() or "")
                    if not original.strip():
                        continue
                    setattr(node, store, original)
                translated = translate_ui_text(original, language)
                if translated != str(read() or ""):
                    write(translated)
                    count += 1
            except Exception:
                continue
        # Nhãn tab và tiêu đề cột của bảng.
        try:
            if hasattr(node, "count") and hasattr(node, "setTabText"):
                for index in range(int(node.count())):
                    store = "_i18n_tab_%d" % index
                    original = getattr(node, store, None)
                    if original is None:
                        original = str(node.tabText(index) or "")
                        setattr(node, store, original)
                    node.setTabText(index, translate_ui_text(original, language))
                    count += 1
        except Exception:
            pass
        try:
            for child in node.children():
                stack.append(child)
        except Exception:
            pass
    return count



