def fall_risk_band(score, direct_level=""):
    """Bậc nguy cơ té ngã dùng để tra can thiệp."""
    if direct_level == "high":
        return "high"
    if direct_level == "low":
        return "low"
    if score > 13:
        return "high"
    if score >= 6:
        return "mid"
    return "low"


def pressure_risk_band(total):
    """Bậc nguy cơ loét tì đè dùng để tra can thiệp."""
    if total is None:
        return ""
    if total >= 19:
        return "none"
    if total >= 15:
        return "mild"
    if total >= 13:
        return "mid"
    if total >= 10:
        return "high"
    return "veryhigh"


def risk_interventions(table, band, language=DEFAULT_APP_LANGUAGE):
    """Các dòng can thiệp CỘNG DỒN cho một bậc nguy cơ."""
    if not band:
        return []
    index = 1 if normalize_app_language(language) == "vi" else 0
    lines = []
    for key, items in table:
        lines.extend(item[index] for item in items)
        if key == band:
            break
    return lines


def _vital_summary_line(vitals):
    """One compact, readable line of vital signs for pickers and tables."""
    return " · ".join(
        "%s %s %s" % (label, text_value, unit)
        for _key, label, text_value, unit, _abnormal
        in _vital_summary_parts(vitals) if text_value
    )
