def _follow_up_text_lines(value):
    """Một mục trên một dòng, bỏ dòng trống và khoảng trắng thừa."""
    if isinstance(value, (list, tuple)):
        raw_lines = []
        for item in value:
            raw_lines.extend(str(item or "").splitlines())
    else:
        raw_lines = str(value or "").splitlines()
    lines = []
    seen = set()
    for raw_line in raw_lines:
        text = " ".join(str(raw_line or "").split()).strip()
        if not text:
            continue
        folded = text.casefold()
        if folded in seen:
            continue
        seen.add(folded)
        lines.append(text)
    return lines


def _follow_up_block_text(value):
    """Giữ nguyên nhiều dòng của một ô can thiệp, chỉ bỏ dòng trống."""
    if isinstance(value, (list, tuple)):
        raw_lines = []
        for item in value:
            raw_lines.extend(str(item or "").splitlines())
    else:
        raw_lines = str(value or "").splitlines()
    return "\n".join(
        line.rstrip() for line in raw_lines if str(line or "").strip()
    ).strip()


def normalize_follow_up_care(raw):
    """Chuẩn hóa khối "theo dõi tiếp theo" của một mốc sinh hiệu.

    Trả về::

        {
            "problems": ["..."],          # Vấn đề của người bệnh
            "nursing_care": "...",        # NIC 1
            "procedure": "...",           # NIC 2
            "medication": "...",          # NIC 3
            "laboratory": "...",          # NIC 4
            "nutrition": "...",           # NIC 5
        }
    """
    source = raw if isinstance(raw, dict) else {}
    normalized = {"problems": _follow_up_text_lines(source.get("problems", []))}
    for key in FOLLOW_UP_CARE_STORED_KEYS:
        normalized[key] = _follow_up_block_text(source.get(key, ""))
    return normalized


def follow_up_care_is_empty(value):
    normalized = normalize_follow_up_care(value)
    return not normalized["problems"] and not any(
        normalized[key] for key in FOLLOW_UP_CARE_STORED_KEYS
    )


def follow_up_care_interventions(value):
    """Đổi khối theo dõi tiếp theo thành các dòng ct_list (NIC) chuẩn."""
    normalized = normalize_follow_up_care(value)
    entries = []
    for key in FOLLOW_UP_CARE_STORED_KEYS:
        detail = normalized[key]
        if not detail:
            continue
        kind = FOLLOW_UP_CARE_INTERVENTION_KINDS[key]
        entries.append({
            "loai": kind, "chi_tiet": detail,
            "type": kind, "details": detail,
        })
    return entries


def latest_recorded_care_level(connection, patient_id, limit=30):
    """Care Level mới nhất được ghi trong hồ sơ điều dưỡng của người bệnh.

    Danh sách người bệnh (cả Web và Desktop) hiển thị giá trị này thay cho
    cột Bed/Care cũ: nó luôn là phân cấp chăm sóc mà điều dưỡng ghi gần đây
    nhất, kể cả khi mốc theo dõi mới nhất chưa nhập lại.
    """
    patient_id = str(patient_id or "").strip()
    if not connection or not patient_id:
        return ""
    try:
        rows = connection.execute(
            """SELECT snapshot FROM nursing_care WHERE patient_id=?
               ORDER BY datetime(care_dt) DESC, care_id DESC LIMIT ?""",
            (patient_id, int(limit)),
        ).fetchall()
    except sqlite3.Error:
        return ""
    for row in rows:
        raw = row[0] if not isinstance(row, dict) else row.get("snapshot")
        try:
            snapshot = json.loads(raw) if isinstance(raw, str) and raw else {}
        except (TypeError, ValueError):
            snapshot = {}
        if not isinstance(snapshot, dict):
            continue
        extras = snapshot.get("extras", {})
        if not isinstance(extras, dict):
            continue
        level = str(extras.get("care_level", "") or "").strip()
        if level:
            return level
    return ""


def care_record_owner_code(connection, care_id):
    """nurse_code của tài khoản đã ghi bản ghi nursing_care này.

    Dùng để tính mốc ghi nhận đầu tiên THEO TỪNG TÀI KHOẢN: khi mở lại một
    bản ghi cũ phải so nó với mốc đầu tiên của chính người đã ghi nó, chứ
    không phải của người đang đăng nhập.
    """
    try:
        care_id = int(care_id or 0)
    except (TypeError, ValueError):
        return ""
    if not connection or not care_id:
        return ""
    try:
        row = connection.execute(
            "SELECT nurse_code FROM nursing_care WHERE care_id=?",
            (care_id,),
        ).fetchone()
    except sqlite3.Error:
        return ""
    if not row:
        return ""
    try:
        value = row[0]
    except (TypeError, IndexError, KeyError):
        value = ""
    return str(value or "").strip()


def first_care_record_id(connection, patient_id, exam_attempt_id=None,
                         nurse_code=""):
    """care_id của mốc ghi nhận ĐẦU TIÊN (care_dt sớm nhất) của người bệnh.

    Mốc đầu tiên được tính RIÊNG CHO TỪNG TÀI KHOẢN ghi hồ sơ (nurse_code):
    mỗi sinh viên, cũng như giảng viên, đều có mốc ghi nhận đầu tiên của
    riêng mình trên cùng một người bệnh. Trước đây hàm này tính chung cho cả
    người bệnh nên ai lưu bản ghi sớm nhất (thường là giảng viên) mới nhập
    được Nursing Process / Nursing Plan, còn mọi tài khoản vào sau đều bị
    khóa chỉ-xem.

    Bỏ trống nurse_code để giữ hành vi cũ (tính trên toàn bộ hồ sơ người
    bệnh), ví dụ khi cần biết mốc mở hồ sơ của cả ca bệnh.

    Trả về 0 khi tài khoản đó chưa có mốc theo dõi nào, nghĩa là mốc sắp
    nhập chính là mốc đầu tiên.
    """
    patient_id = str(patient_id or "").strip()
    if not connection or not patient_id:
        return 0
    sql = """SELECT care_id FROM nursing_care WHERE patient_id=?"""
    arguments = [patient_id]
    if exam_attempt_id:
        sql += " AND exam_attempt_id=?"
        arguments.append(exam_attempt_id)
    nurse_code = str(nurse_code or "").strip()
    if nurse_code:
        sql += " AND lower(trim(COALESCE(nurse_code,'')))=?"
        arguments.append(nurse_code.lower())
    sql += " ORDER BY datetime(care_dt),care_id LIMIT 1"
    try:
        row = connection.execute(sql, arguments).fetchone()
    except sqlite3.Error:
        return 0
    if not row:
        return 0
    try:
        return int(row[0])
    except (TypeError, ValueError, IndexError):
        return 0


def is_first_care_timepoint(connection, patient_id, care_id,
                            exam_attempt_id=None, nurse_code=""):
    """True khi bản ghi đang mở là mốc ghi nhận đầu tiên CỦA TÀI KHOẢN ĐÓ.

    Một bản ghi hoàn toàn mới (care_id rỗng/0) chỉ là mốc đầu tiên khi tài
    khoản đang ghi chưa lưu mốc theo dõi nào cho người bệnh này.

    Khi gọi với một care_id đã lưu mà không truyền nurse_code, chủ sở hữu
    được suy ra từ chính bản ghi đó, để lúc mở lại hồ sơ cho kết quả giống
    hệt lúc tạo mới.
    """
    nurse_code = str(nurse_code or "").strip()
    if not nurse_code and care_id:
        nurse_code = care_record_owner_code(connection, care_id)
    first_id = first_care_record_id(
        connection, patient_id, exam_attempt_id, nurse_code
    )
    if not first_id:
        return True
    try:
        care_id = int(care_id or 0)
    except (TypeError, ValueError):
        care_id = 0
    return bool(care_id) and care_id == first_id


