def seed_default_quick_catalogs(conn, actor="system_default"):
    """Insert the shared starter catalog (DEFAULT_QUICK_CATALOG_SEED --
    NANDA patient problems, nursing diagnoses, NOC goals, NIC
    interventions) into quick_catalog_items, one category at a time and
    only when that category is still completely empty, so an
    administrator's own customization (including deleting every starter
    item) is never overwritten. ``conn`` must be a sqlite3.Connection with
    the ``quick_catalog_items`` table already created. Called from both
    the Desktop DatabaseManager and the Web server startup so the shared
    catalog is seeded the same way no matter which side starts first --
    the two must never drift apart into separate copies of this list."""
    now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for category_key, default_items in DEFAULT_QUICK_CATALOG_SEED.items():
        existing = conn.execute(
            "SELECT COUNT(*) FROM quick_catalog_items WHERE category_key=?",
            (category_key,),
        ).fetchone()
        if existing and int(existing[0] or 0) > 0:
            continue
        for sort_order, item_text in enumerate(default_items):
            try:
                conn.execute(
                    """INSERT INTO quick_catalog_items
                    (category_key,item_text,sort_order,active,created_by,
                     created_dt,updated_dt)
                    VALUES(?,?,?,1,?,?,?)""",
                    (
                        category_key, item_text, sort_order, actor,
                        now_text, now_text,
                    ),
                )
            except sqlite3.IntegrityError:
                continue


def topup_default_quick_catalogs(conn, actor="system_default"):
    """Add any starter item from DEFAULT_QUICK_CATALOG_SEED that is not yet
    present in an existing, already-populated category.

    seed_default_quick_catalogs() above only fills a category the very
    first time it is completely empty, so a database created before some
    headings (2 - Nursing diagnosis/cause, 3 - Goals, 5 - Evaluations,
    etc.) were added to DEFAULT_QUICK_CATALOG_SEED can be left stuck with
    only its original items (e.g. only the respiratory patient problems
    and interventions) forever, even after the code is updated with the
    full list -- because those categories already have rows and are no
    longer "empty". This function is safe to call on every startup: it
    only INSERTs an (category_key, item_text) pair that is missing, never
    touches, reorders, or deletes any row an administrator already has
    (including custom items or items they removed on purpose), so it
    simply lets an older database catch up with newer starter content."""
    now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for category_key, default_items in DEFAULT_QUICK_CATALOG_SEED.items():
        existing_rows = conn.execute(
            "SELECT item_text, COALESCE(MAX(sort_order), -1) "
            "FROM quick_catalog_items WHERE category_key=?",
            (category_key,),
        ).fetchall()
        if not existing_rows:
            # Fully empty: seed_default_quick_catalogs() already handles
            # (or will handle) this category from scratch.
            continue
        existing_texts = {
            str(row[0] or "").strip().casefold() for row in existing_rows
        }
        next_sort_order = int(existing_rows[0][1] or -1) + 1
        for item_text in default_items:
            if str(item_text or "").strip().casefold() in existing_texts:
                continue
            try:
                conn.execute(
                    """INSERT INTO quick_catalog_items
                    (category_key,item_text,sort_order,active,created_by,
                     created_dt,updated_dt)
                    VALUES(?,?,?,1,?,?,?)""",
                    (
                        category_key, item_text, next_sort_order, actor,
                        now_text, now_text,
                    ),
                )
                next_sort_order += 1
            except sqlite3.IntegrityError:
                continue


# ---------------------------------------------------------------------------
# Procedure Implementation (Heading 4 nursing techniques)
# ---------------------------------------------------------------------------
# Only the formal nursing TECHNIQUES from the "nursing_procedure" catalog are
# stored here - one row per performed procedure, with the clock time it was
# carried out, a follow-up note and the nurse who performed it. Everything else
# in Heading 4 stays free text in the Nursing Care box.
#
# Desktop, Mobile Web and the PDF exports all go through the four helpers
# below against the same hospital.db table, which is what makes the two-way
# sync exact: whichever client saves last, both read the identical rows.

NURSING_PROCEDURE_COLUMNS = (
    "procedure_name", "performed_time", "follow_up_note", "nurse_name",
)


def ensure_nursing_procedure_schema(connection):
    """Create nursing_procedure_records (and its indexes) if missing.

    Safe to call repeatedly; called from both the desktop DatabaseManager and
    the web server bootstrap so either app can create the table first."""
    connection.execute("""CREATE TABLE IF NOT EXISTS nursing_procedure_records (
        procedure_id INTEGER PRIMARY KEY AUTOINCREMENT,
        patient_id TEXT NOT NULL,
        care_id INTEGER,
        procedure_name TEXT NOT NULL,
        performed_time TEXT DEFAULT '',
        follow_up_note TEXT DEFAULT '',
        nurse_code TEXT DEFAULT '',
        nurse_name TEXT DEFAULT '',
        entered_by_username TEXT DEFAULT '',
        source TEXT DEFAULT '',
        sort_order INTEGER DEFAULT 0,
        created_dt TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS
        idx_nursing_procedure_care
        ON nursing_procedure_records(care_id,sort_order,procedure_id)""")
    connection.execute("""CREATE INDEX IF NOT EXISTS
        idx_nursing_procedure_patient
        ON nursing_procedure_records(patient_id,procedure_id)""")


def normalize_procedure_time(raw_value=""):
    """Accept 8:5, 08:05, 0805, 08h05, 08:05:00 -> "08:05" (or "")."""
    text = " ".join(str(raw_value or "").split())
    if not text:
        return ""
    digits = re.sub(r"[^0-9]", "", text)
    if len(digits) in (3, 4):
        hour, minute = int(digits[:-2] or 0), int(digits[-2:])
    else:
        parts = re.split(r"[^0-9]+", text)
        parts = [p for p in parts if p != ""]
        if not parts:
            return ""
        try:
            hour = int(parts[0])
            minute = int(parts[1]) if len(parts) > 1 else 0
        except ValueError:
            return ""
    if not (0 <= hour <= 23) or not (0 <= minute <= 59):
        return ""
    return "%02d:%02d" % (hour, minute)


def normalize_nursing_procedure_rows(raw_rows):
    """Coerce anything row-shaped (dicts from a form, JSON, sqlite rows, or
    plain "name" strings) into the canonical dict list, dropping rows with no
    procedure name so an empty trailing input never creates a record."""
    rows = []
    for raw in list(raw_rows or []):
        if isinstance(raw, str):
            raw = {"procedure_name": raw}
        elif not isinstance(raw, dict):
            try:
                raw = dict(raw)
            except (TypeError, ValueError):
                continue
        name = " ".join(str(raw.get("procedure_name", "") or "").split())
        if not name:
            continue
        rows.append({
            "procedure_name": name[:400],
            "performed_time": normalize_procedure_time(
                raw.get("performed_time", "")
            ),
            "follow_up_note": str(
                raw.get("follow_up_note", "") or ""
            ).strip()[:2000],
            "nurse_code": str(raw.get("nurse_code", "") or "").strip()[:60],
            "nurse_name": str(raw.get("nurse_name", "") or "").strip()[:200],
        })
    return rows


def load_nursing_procedures(connection, care_id=None, patient_id=""):
    """Read the procedure rows for one nursing-care record (or, when care_id
    is None, every row of one patient, newest care record first)."""
    try:
        ensure_nursing_procedure_schema(connection)
    except sqlite3.Error:
        return []
    if care_id:
        cursor = connection.execute(
            """SELECT procedure_id,patient_id,care_id,procedure_name,
                      performed_time,follow_up_note,nurse_code,nurse_name,
                      source,sort_order,created_dt,updated_dt
               FROM nursing_procedure_records WHERE care_id=?
               ORDER BY sort_order,procedure_id""",
            (int(care_id),),
        )
    else:
        cursor = connection.execute(
            """SELECT procedure_id,patient_id,care_id,procedure_name,
                      performed_time,follow_up_note,nurse_code,nurse_name,
                      source,sort_order,created_dt,updated_dt
               FROM nursing_procedure_records WHERE patient_id=?
               ORDER BY care_id DESC,sort_order,procedure_id""",
            (str(patient_id or ""),),
        )
    keys = (
        "procedure_id", "patient_id", "care_id", "procedure_name",
        "performed_time", "follow_up_note", "nurse_code", "nurse_name",
        "source", "sort_order", "created_dt", "updated_dt",
    )
    return [dict(zip(keys, tuple(row))) for row in cursor.fetchall()]


def replace_nursing_procedures(connection, patient_id, care_id, rows,
                               source="", entered_by_username=""):
    """Replace every procedure row of one care record in a single step.

    Returns the number of rows written. The caller owns the transaction so
    this composes with the rest of a care save."""
    care_id = int(care_id or 0)
    if not care_id:
        return 0
    ensure_nursing_procedure_schema(connection)
    now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    previous = {
        str(row[0] or "").casefold(): {
            "created_dt": str(row[1] or ""),
            "performed_time": str(row[2] or ""),
            "follow_up_note": str(row[3] or ""),
            "nurse_code": str(row[4] or ""),
            "nurse_name": str(row[5] or ""),
            "updated_dt": str(row[6] or ""),
        }
        for row in connection.execute(
            """SELECT procedure_name,created_dt,performed_time,
                      follow_up_note,nurse_code,nurse_name,updated_dt
               FROM nursing_procedure_records WHERE care_id=?""",
            (care_id,),
        ).fetchall()
    }
    connection.execute(
        "DELETE FROM nursing_procedure_records WHERE care_id=?", (care_id,)
    )
    clean_rows = normalize_nursing_procedure_rows(rows)
    for position, row in enumerate(clean_rows):
        saved = previous.get(row["procedure_name"].casefold(), {})
        # The Nursing Plan form intentionally submits only procedure names.
        # Preserve execution details already confirmed on the patient page
        # when that care plan is edited later.
        performed_time = row["performed_time"] or saved.get(
            "performed_time", ""
        )
        follow_up_note = row["follow_up_note"] or saved.get(
            "follow_up_note", ""
        )
        nurse_code = row["nurse_code"] or saved.get("nurse_code", "")
        nurse_name = row["nurse_name"] or saved.get("nurse_name", "")
        updated_dt = (
            saved.get("updated_dt", "")
            if performed_time and saved.get("updated_dt", "")
            else now_text
        )
        connection.execute(
            """INSERT INTO nursing_procedure_records(
                   patient_id,care_id,procedure_name,performed_time,
                   follow_up_note,nurse_code,nurse_name,entered_by_username,
                   source,sort_order,created_dt,updated_dt)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                str(patient_id or ""), care_id, row["procedure_name"],
                performed_time, follow_up_note, nurse_code, nurse_name,
                str(entered_by_username or ""), str(source or ""), position,
                saved.get("created_dt", "") or now_text,
                updated_dt,
            ),
        )
    return len(clean_rows)


def format_nursing_procedure_line(row):
    """One human-readable line: "08:05 - Quy trình ... - ĐD: X - Theo dõi: Y".

    Used for the legacy free-text intervention_procedure mirror and for any
    plain-text export, so the same wording appears everywhere."""
    row = row or {}
    parts = []
    time_text = str(row.get("performed_time", "") or "").strip()
    if time_text:
        parts.append(time_text)
    parts.append(str(row.get("procedure_name", "") or "").strip())
    nurse = str(row.get("nurse_name", "") or "").strip()
    if nurse:
        parts.append("ĐD: %s" % nurse)
    note = " ".join(str(row.get("follow_up_note", "") or "").split())
    if note:
        parts.append("Theo dõi: %s" % note)
    return " - ".join(part for part in parts if part)


def format_nursing_procedure_text(rows):
    """Whole list as text, one procedure per line."""
    return "\n".join(
        format_nursing_procedure_line(row)
        for row in (rows or [])
        if str((row or {}).get("procedure_name", "") or "").strip()
    )


def parse_nursing_procedure_text(raw_text):
    """Best-effort reverse of format_nursing_procedure_line(), so a legacy
    free-text Procedure Implementation box still turns into list rows the
    first time an old record is opened."""
    rows = []
    for line in str(raw_text or "").splitlines():
        line = line.strip().lstrip("-•*").strip()
        if not line:
            continue
        performed_time, note, nurse = "", "", ""
        segments = [seg.strip() for seg in line.split(" - ")]
        leading = normalize_procedure_time(segments[0]) if segments else ""
        if leading and re.match(r"^\d{1,2}\s*[:hH]\s*\d{1,2}$", segments[0]):
            performed_time = leading
            segments = segments[1:]
        keep = []
        for segment in segments:
            lowered = segment.lower()
            if lowered.startswith(("đd:", "dd:", "nurse:")):
                nurse = segment.split(":", 1)[1].strip()
            elif lowered.startswith(("theo dõi:", "theo doi:", "note:")):
                note = segment.split(":", 1)[1].strip()
            else:
                keep.append(segment)
        name = " - ".join(keep).strip()
        if not name:
            continue
        rows.append({
            "procedure_name": name, "performed_time": performed_time,
            "follow_up_note": note, "nurse_code": "", "nurse_name": nurse,
        })
    return rows


