def read_patient_diagnosis(connection, patient_id):
    """Current medical diagnosis of one patient, or "" when unknown.

    patients.diagnosis is the single source every screen and every export
    reads; nothing displays a snapshot copy. Call this right before a write
    so the audit trail can record the old value."""
    try:
        row = connection.execute(
            "SELECT diagnosis FROM patients WHERE id=?",
            (str(patient_id or ""),),
        ).fetchone()
    except sqlite3.Error:
        return ""
    return str((row[0] if row else "") or "")


def insert_registered_patient(
    connection, patient_id, values, user=None, department="",
    created_dt="", is_exam=False, exam_summary="", exam_question="",
):
    """Insert the canonical patient row used by Patients and Triage.

    Triage remains a separate record: this helper never inserts into
    ``triage_records``.
    """
    values = dict(values or {})
    user = dict(user or {})
    timestamp = str(created_dt or "").strip() or datetime.now().strftime(
        "%Y-%m-%d %H:%M:00"
    )
    connection.execute(
        """INSERT INTO patients(
           id,name,dob,gender,diagnosis,department,
           history_present_illness,past_medical_history,
           family_history,allergies,allergy_status,
           created_dt,updated_dt,created_by_username,created_by_role,
           is_exam,exam_summary,exam_question
           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            str(patient_id or "").strip(),
            str(values.get("name", "") or "").strip(),
            str(values.get("dob", "") or "").strip(),
            str(values.get("gender", "") or "").strip(),
            str(values.get("diagnosis", "") or "").strip(),
            str(department or "").strip(),
            str(values.get("history_present_illness", "") or "").strip(),
            str(values.get("past_medical_history", "") or "").strip(),
            str(values.get("family_history", "") or "").strip(),
            str(values.get("allergies", "") or "").strip(),
            str(values.get("allergy_status", "") or "").strip(),
            timestamp, timestamp,
            str(user.get("username", "") or "").strip(),
            str(user.get("role", "") or "").strip(),
            1 if is_exam else 0,
            str(exam_summary or "").strip(),
            str(exam_question or "").strip(),
        ),
    )


# Một tài khoản được coi là "đang online" nếu phiên của họ (Desktop hoặc
# Mobile Web) còn ghi nhịp tim trong khoảng này. Desktop ghi nhịp mỗi 60 giây,
# nên ngưỡng 5 phút vẫn báo đúng khi ứng dụng bị tắt đột ngột hay mất điện.
ONLINE_PRESENCE_WINDOW_MINUTES = 5
DESKTOP_HEARTBEAT_SECONDS = 60


def _parse_log_datetime(value):
    """Đọc mốc thời gian trong nhật ký, trả về None nếu không hợp lệ."""
    text = str(value or "").strip()
    if not text:
        return None
    for pattern in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d"):
        try:
            return datetime.strptime(text[:len("2026-08-06 12:00:00")], pattern)
        except ValueError:
            continue
    return None


def _minutes_between(start, end):
    """Số phút giữa hai mốc trong nhật ký; 0 nếu thiếu hoặc ngược thứ tự."""
    first, last = _parse_log_datetime(start), _parse_log_datetime(end)
    if first is None or last is None or last < first:
        return 0
    return int(round((last - first).total_seconds() / 60.0))


def _seconds_between(value, now=None):
    moment = _parse_log_datetime(value)
    if moment is None:
        return None
    return max(0, int(((now or datetime.now()) - moment).total_seconds()))


def _format_duration_minutes(minutes):
    """0 -> '0 phút', 95 -> '1 giờ 35 phút'."""
    minutes = max(0, int(minutes or 0))
    if minutes < 60:
        return "%d phút" % minutes
    hours, rest = divmod(minutes, 60)
    return "%d giờ %d phút" % (hours, rest) if rest else "%d giờ" % hours


def log_diagnosis_change(connection, patient_id, previous, current,
                         user=None, source=""):
    """Write one activity_logs row when the medical diagnosis really changed.

    Called from every write path (Mobile Web nursing care save, triage save,
    patient registration/edit, and the desktop upsert) so an instructor can
    always see who changed a diagnosis, when, and from what to what."""
    previous = " ".join(str(previous or "").split())
    current = " ".join(str(current or "").split())
    if previous == current:
        return False
    if previous and not current:
        # A blank incoming value never clears a diagnosis (see upsert_patient
        # and the web save paths), so there is nothing to record.
        return False
    user = dict(user or {})
    if user.get("username") and not user.get("full_name"):
        try:
            row = connection.execute(
                "SELECT full_name,role FROM users WHERE username=?",
                (user["username"],),
            ).fetchone()
            if row:
                user["full_name"] = row[0] or ""
                user["role"] = user.get("role") or (row[1] or "")
        except sqlite3.Error:
            pass
    try:
        connection.execute(
            """INSERT INTO activity_logs(
                   occurred_dt,username,full_name,role,source,action,details)
               VALUES(?,?,?,?,?,?,?)""",
            (
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                str(user.get("username", "") or ""),
                str(user.get("full_name", "") or ""),
                str(user.get("role", "") or ""),
                str(source or ""),
                "patient_diagnosis_created" if not previous
                else "patient_diagnosis_updated",
                "Patient %s | cũ: %s | mới: %s" % (
                    patient_id,
                    previous[:600] or "(trống)",
                    current[:600] or "(trống)",
                ),
            ),
        )
    except sqlite3.Error:
        return False
    return True


def ensure_activity_log_audit_schema(connection):
    """Add durable request/device context to every activity-log row."""
    columns = {
        row[1] for row in connection.execute(
            "PRAGMA table_info(activity_logs)"
        ).fetchall()
    }
    for column_name, column_sql in (
        ("device_id", "TEXT DEFAULT ''"),
        ("device_label", "TEXT DEFAULT ''"),
        ("client_ip", "TEXT DEFAULT ''"),
        ("session_login_dt", "TEXT DEFAULT ''"),
        ("request_path", "TEXT DEFAULT ''"),
    ):
        if column_name not in columns:
            connection.execute(
                "ALTER TABLE activity_logs ADD COLUMN %s %s"
                % (column_name, column_sql)
            )
    connection.execute(
        """CREATE INDEX IF NOT EXISTS idx_activity_logs_user_date
           ON activity_logs(username,occurred_dt,log_id)"""
    )
    table_names = {
        str(row[0]) for row in connection.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        ).fetchall()
    }
    if {"mobile_web_sessions", "active_sessions"}.issubset(table_names):
        connection.execute(
            """CREATE TRIGGER IF NOT EXISTS trg_activity_log_session_context
               AFTER INSERT ON activity_logs
               BEGIN
                 UPDATE activity_logs SET
                   device_id=COALESCE(NULLIF(device_id,''),(
                     SELECT device_id FROM mobile_web_sessions
                     WHERE username=NEW.username
                     ORDER BY datetime(login_dt) DESC LIMIT 1
                   ),''),
                   device_label=COALESCE(NULLIF(device_label,''),(
                     SELECT device_label FROM mobile_web_sessions
                     WHERE username=NEW.username
                     ORDER BY datetime(login_dt) DESC LIMIT 1
                   ),(
                     SELECT COALESCE(NULLIF(source,''),'Desktop') || ' / Desktop'
                     FROM active_sessions WHERE username=NEW.username
                     ORDER BY datetime(login_dt) DESC LIMIT 1
                   ),''),
                   client_ip=COALESCE(NULLIF(client_ip,''),(
                     SELECT client_ip FROM mobile_web_sessions
                     WHERE username=NEW.username
                     ORDER BY datetime(login_dt) DESC LIMIT 1
                   ),''),
                   session_login_dt=COALESCE(NULLIF(session_login_dt,''),(
                     SELECT login_dt FROM mobile_web_sessions
                     WHERE username=NEW.username
                     ORDER BY datetime(login_dt) DESC LIMIT 1
                   ),(
                     SELECT login_dt FROM active_sessions
                     WHERE username=NEW.username
                     ORDER BY datetime(login_dt) DESC LIMIT 1
                   ),'')
                 WHERE log_id=NEW.log_id;
               END"""
        )
def ensure_health_education_schema(connection):
    """Create health_education_records if missing. Safe to call repeatedly;
    called from both the desktop DatabaseManager and the web bootstrap."""
    connection.execute("""CREATE TABLE IF NOT EXISTS health_education_records (
        education_id INTEGER PRIMARY KEY AUTOINCREMENT,
        patient_id TEXT NOT NULL,
        care_id INTEGER,
        topic_key TEXT NOT NULL,
        content TEXT DEFAULT '',
        meta TEXT DEFAULT '{}',
        source TEXT DEFAULT '',
        entered_by_username TEXT DEFAULT '',
        sort_order INTEGER DEFAULT 0,
        created_dt TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS
        idx_health_education_care
        ON health_education_records(care_id,sort_order,education_id)""")
    connection.execute("""CREATE INDEX IF NOT EXISTS
        idx_health_education_patient
        ON health_education_records(patient_id,education_id)""")


def normalize_health_education(raw):
    """Coerce any shape into {"topics": {key: text}, "meta": {key: text}}."""
    raw = raw if isinstance(raw, dict) else {}
    topics_in = raw.get("topics", raw)
    topics_in = topics_in if isinstance(topics_in, dict) else {}
    meta_in = raw.get("meta", {})
    meta_in = meta_in if isinstance(meta_in, dict) else {}
    topics = {
        key: str(topics_in.get(key, "") or "").strip()[:6000]
        for key in HEALTH_EDUCATION_TOPIC_KEYS
    }
    meta = {
        key: str(meta_in.get(key, "") or "").strip()[:2000]
        for key in HEALTH_EDUCATION_META_KEYS
    }
    return {"topics": topics, "meta": meta}


def health_education_is_empty(education):
    education = normalize_health_education(education)
    return not any(education["topics"].values()) and not any(
        education["meta"].values()
    )


def load_health_education(connection, care_id=None, patient_id=""):
    """Read one care record's teaching content (or a patient's latest)."""
    try:
        ensure_health_education_schema(connection)
    except sqlite3.Error:
        return normalize_health_education({})
    if care_id:
        rows = connection.execute(
            """SELECT topic_key,content,meta FROM health_education_records
               WHERE care_id=? ORDER BY sort_order,education_id""",
            (int(care_id),),
        ).fetchall()
    else:
        rows = connection.execute(
            """SELECT topic_key,content,meta FROM health_education_records
               WHERE patient_id=? ORDER BY care_id DESC,sort_order,
               education_id""",
            (str(patient_id or ""),),
        ).fetchall()
    topics, meta = {}, {}
    for row in rows:
        topic_key = str(row[0] or "")
        if topic_key == "__meta__":
            try:
                parsed = json.loads(str(row[2] or "{}"))
            except (TypeError, ValueError):
                parsed = {}
            if isinstance(parsed, dict):
                for key, value in parsed.items():
                    meta.setdefault(key, value)
        elif topic_key not in topics:
            topics[topic_key] = str(row[1] or "")
    return normalize_health_education({"topics": topics, "meta": meta})


def replace_health_education(connection, patient_id, care_id, education,
                             source="", entered_by_username=""):
    """Replace one care record's teaching content in a single step."""
    care_id = int(care_id or 0)
    if not care_id:
        return 0
    ensure_health_education_schema(connection)
    education = normalize_health_education(education)
    now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    previous = {
        str(row[0] or ""): str(row[1] or "")
        for row in connection.execute(
            """SELECT topic_key,created_dt FROM health_education_records
               WHERE care_id=?""", (care_id,),
        ).fetchall()
    }
    connection.execute(
        "DELETE FROM health_education_records WHERE care_id=?", (care_id,)
    )
    written = 0
    for position, topic_key in enumerate(HEALTH_EDUCATION_TOPIC_KEYS):
        content = education["topics"].get(topic_key, "")
        if not content:
            continue
        connection.execute(
            """INSERT INTO health_education_records(
                   patient_id,care_id,topic_key,content,meta,source,
                   entered_by_username,sort_order,created_dt,updated_dt)
               VALUES(?,?,?,?,'{}',?,?,?,?,?)""",
            (
                str(patient_id or ""), care_id, topic_key, content,
                str(source or ""), str(entered_by_username or ""), position,
                previous.get(topic_key, "") or now_text, now_text,
            ),
        )
        written += 1
    if any(education["meta"].values()):
        connection.execute(
            """INSERT INTO health_education_records(
                   patient_id,care_id,topic_key,content,meta,source,
                   entered_by_username,sort_order,created_dt,updated_dt)
               VALUES(?,?,'__meta__','',?,?,?,?,?,?)""",
            (
                str(patient_id or ""), care_id,
                json.dumps(education["meta"], ensure_ascii=False),
                str(source or ""), str(entered_by_username or ""), 99,
                previous.get("__meta__", "") or now_text, now_text,
            ),
        )
        written += 1
    return written


def _eiu_pdf_logo_flowables(width_mm=42, gap_mm=3):
    """Shared, aspect-correct EIU logo header for every exported PDF."""
    try:
        from reportlab.lib.units import mm
        from reportlab.platypus import Image, Spacer
    except ImportError:
        return []
    logo_path = os.path.join(
        os.path.dirname(__file__), "static", "eiu-logo.png"
    )
    if not os.path.exists(logo_path):
        return []
    # The supplied EIU asset is 2048 x 710. Keep that aspect ratio so the
    # identity mark is never squeezed, and align it to the document frame's
    # upper-left corner consistently across portrait and landscape reports.
    logo_width = float(width_mm) * mm
    logo_height = logo_width * 710.0 / 2048.0
    logo = Image(logo_path, width=logo_width, height=logo_height)
    logo.hAlign = "LEFT"
    return [logo, Spacer(1, float(gap_mm) * mm)]


def generate_health_education_handout_pdf(patient, education,
                                          generated_dt=""):
    """Patient-facing handout: only the ten teaching topics, in large plain
    type. The nurse's needs assessment and teach-back notes stay in the
    record and are deliberately left out of the sheet given to the patient."""
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import mm
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.platypus import (
        Paragraph, SimpleDocTemplate, Spacer,
    )

    # Same Unicode font lookup the other exports use, so Vietnamese diacritics
    # render on Windows and on Linux alike.
    regular_font, bold_font = "Helvetica", "Helvetica-Bold"
    for regular_path, bold_path in (
        (
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arial.ttf"),
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arialbd.ttf"),
        ),
        (
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        ),
    ):
        if os.path.exists(regular_path):
            pdfmetrics.registerFont(TTFont("HandoutUnicode", regular_path))
            regular_font = "HandoutUnicode"
            if os.path.exists(bold_path):
                pdfmetrics.registerFont(
                    TTFont("HandoutUnicodeBold", bold_path)
                )
                bold_font = "HandoutUnicodeBold"
            else:
                bold_font = regular_font
            break

    education = normalize_health_education(education)
    patient = patient or {}
    output = io.BytesIO()
    doc = SimpleDocTemplate(
        output, pagesize=A4,
        leftMargin=18 * mm, rightMargin=18 * mm,
        topMargin=16 * mm, bottomMargin=18 * mm,
        title="Huong dan cham soc suc khoe",
    )
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="HEHeading", parent=styles["Title"], fontName=bold_font,
        fontSize=17, leading=21, spaceAfter=4,
    ))
    styles.add(ParagraphStyle(
        name="HEPatient", parent=styles["BodyText"], fontName=regular_font,
        fontSize=11, leading=15, spaceAfter=10,
        textColor=colors.HexColor("#33475e"),
    ))
    styles.add(ParagraphStyle(
        name="HETopic", parent=styles["Heading2"], fontName=bold_font,
        fontSize=13, leading=17, spaceBefore=11, spaceAfter=4,
        textColor=colors.HexColor("#0f4c81"),
    ))
    styles.add(ParagraphStyle(
        name="HEBody", parent=styles["BodyText"], fontName=regular_font,
        fontSize=12, leading=17.5, spaceAfter=3, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="HENote", parent=styles["BodyText"], fontName=regular_font,
        fontSize=9.5, leading=13, textColor=colors.HexColor("#5c7186"),
        spaceBefore=12,
    ))

    def escaped(value):
        return html.escape(str(value or "")).replace("\n", "<br/>")

    story = _eiu_pdf_logo_flowables()
    story.append(Paragraph(
        "HƯỚNG DẪN CHĂM SÓC SỨC KHỎE", styles["HEHeading"]
    ))
    identity = " &nbsp;|&nbsp; ".join(part for part in [
        "Người bệnh: %s" % escaped(patient.get("name", "")),
        ("Năm sinh: %s" % escaped(str(patient.get("dob", ""))[:4]))
        if patient.get("dob") else "",
        ("Mã người bệnh: %s" % escaped(patient.get("id", "")))
        if patient.get("id") else "",
    ] if part)
    story.append(Paragraph(identity, styles["HEPatient"]))
    printed = 0
    for topic_key, topic_label, _hint in HEALTH_EDUCATION_TOPICS:
        content = education["topics"].get(topic_key, "")
        if not content:
            continue
        printed += 1
        story.append(Paragraph(escaped(topic_label), styles["HETopic"]))
        story.append(Paragraph(escaped(content), styles["HEBody"]))
    if not printed:
        story.append(Paragraph(
            "Chưa có nội dung hướng dẫn nào được ghi.", styles["HEBody"]
        ))
    story.append(Spacer(1, 6))
    educator = education["meta"].get("educator_name", "")
    story.append(Paragraph(
        "Nếu có bất kỳ điều gì chưa rõ, hãy hỏi lại điều dưỡng hoặc bác sĩ "
        "đang chăm sóc bạn.%s%s" % (
            ("<br/>Điều dưỡng hướng dẫn: %s" % escaped(educator))
            if educator else "",
            ("<br/>Ngày in: %s" % escaped(generated_dt))
            if generated_dt else "",
        ), styles["HENote"]
    ))
    doc.build(story)
    return output.getvalue()


def request_openai_health_education(api_key, clinical_context,
                                    model=None, language="Vietnamese"):
    """Ask OpenAI to draft the ten health-education topics for one patient.

    Returns {"topics": {...}, "clinical_caveat": "..."}. The caller merges the
    draft into whatever the nurse has already typed - it never overwrites."""
    api_key = str(api_key or "").strip()
    if not api_key:
        raise ValueError("OPENAI_API_KEY is not configured on this computer.")
    model = model or DEFAULT_OPENAI_REVIEW_MODEL
    language = resolve_ai_language(language)
    schema = {
        "type": "object",
        "properties": {
            "topics": {
                "type": "object",
                "properties": {
                    key: {"type": "string"}
                    for key in HEALTH_EDUCATION_TOPIC_KEYS
                },
                "required": list(HEALTH_EDUCATION_TOPIC_KEYS),
                "additionalProperties": False,
            },
            "clinical_caveat": {"type": "string"},
        },
        "required": ["topics", "clinical_caveat"],
        "additionalProperties": False,
    }
    topic_brief = "\n".join(
        "- %s (%s): %s" % (key, label, hint)
        for key, label, hint in HEALTH_EDUCATION_TOPICS
    )
    safe_context = dict(clinical_context or {})
    safe_context.pop("_safety_identifier", None)
    payload = {
        "model": model,
        "store": False,
        "safety_identifier": str(
            (clinical_context or {}).get("_safety_identifier", "")
        ) or None,
        "instructions": (
            "You are an experienced nurse educator writing the patient "
            "education record for ONE patient, from that patient's own "
            "documented data only: medical diagnosis, medical history, "
            "allergies, vital signs, assessment findings, nursing diagnoses "
            "and care plan, current physician orders and medications, and "
            "laboratory/imaging results. Fill each of these ten teaching "
            "topics:\n%s\n"
            "Write for the patient and the family to read, not for "
            "clinicians: short sentences, everyday words, no abbreviations "
            "and no clinical jargon. Be concrete and specific to THIS "
            "patient - name the actual drugs, foods, figures and warning "
            "signs from the record rather than generic advice. Use short "
            "bullet lines separated by newlines. Never invent a diagnosis, "
            "a drug, a dose or an appointment that is not in the record; if "
            "the record does not support a topic, write a brief safe "
            "general statement and say the nurse will confirm the details. "
            "Do not give a medical prognosis. Write everything in %s. Put "
            "into clinical_caveat one sentence reminding the nurse this is "
            "a draft that must be reviewed and personalised before it is "
            "given to the patient." % (topic_brief, language)
        ),
        "input": [{
            "role": "user",
            "content": [{
                "type": "input_text",
                "text": json.dumps(safe_context, ensure_ascii=False),
            }],
        }],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "health_education_draft",
                "strict": True,
                "schema": schema,
            },
        },
    }
    if not payload["safety_identifier"]:
        payload.pop("safety_identifier", None)
    request = Request(
        openai_api_url("responses"),
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=180) as response:
            body = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        raise RuntimeError(
            "OpenAI request failed (%s): %s"
            % (exc.code, exc.read().decode("utf-8", "replace")[:400])
        )
    except URLError as exc:
        raise RuntimeError("Could not reach OpenAI: %s" % exc.reason)
    # Same output shape the other OpenAI calls in this file unpack.
    output_text = str(body.get("output_text", "") or "")
    if not output_text:
        for item in body.get("output", []) or []:
            if not isinstance(item, dict):
                continue
            for content_item in item.get("content", []) or []:
                if (isinstance(content_item, dict)
                        and content_item.get("type") == "output_text"):
                    output_text += str(content_item.get("text", "") or "")
    if not output_text.strip():
        raise RuntimeError("OpenAI returned an empty response.")
    try:
        parsed = json.loads(output_text)
    except (TypeError, ValueError):
        raise RuntimeError("OpenAI returned an unreadable response.")
    result = normalize_health_education({"topics": parsed.get("topics", {})})
    result["clinical_caveat"] = str(parsed.get("clinical_caveat", "") or "")
    return result


def resolve_ai_language(raw_value=""):
    """Normalize a user-supplied AI language choice (form field, combo box
    data, etc.) to the canonical string sent to OpenAI ("Vietnamese" or
    "English"). Falls back to OPENAI_NANDA_LANGUAGE (default "Vietnamese")
    when raw_value is blank or unrecognized, so every NANDA/NIC/NOC AI call
    point -- Desktop and the embedded Web server alike -- agrees on the
    same language without the caller needing to know the fallback rule."""
    text = " ".join(str(raw_value or "").split()).strip().lower()
    if text in ("vi", "vietnamese", "tiếng việt", "tieng viet"):
        return "Vietnamese"
    if text in ("en", "english"):
        return "English"
    fallback = str(
        os.getenv("OPENAI_NANDA_LANGUAGE", "Vietnamese") or "Vietnamese"
    ).strip()
    return "English" if fallback.lower() in ("en", "english") else "Vietnamese"


