# Build one authoritative list of page/tab groups. A key appearing twice or
# missing a group would make the Settings UI ambiguous, so fail early instead
# of rendering duplicate editable controls.
_ui_label_keys = [key for key, _description, _default in UI_LABEL_DEFINITIONS]
if len(_ui_label_keys) != len(set(_ui_label_keys)):
    raise RuntimeError("Duplicate interface-name setting key detected.")
_unmapped_ui_label_keys = [
    key for key in _ui_label_keys if key not in UI_LABEL_GROUPS
]
if _unmapped_ui_label_keys:
    raise RuntimeError(
        "Interface-name keys missing a page/tab group: %s"
        % ", ".join(_unmapped_ui_label_keys)
    )
UI_LABEL_PAGE_DEFINITIONS = tuple(
    (
        group_name,
        tuple(
            definition for definition in UI_LABEL_DEFINITIONS
            if UI_LABEL_GROUPS[definition[0]] == group_name
        ),
    )
    for group_name in dict.fromkeys(
        UI_LABEL_GROUPS[key] for key in _ui_label_keys
    )
)

