# Bộ quy trình được tích sẵn khi mở một buổi lượng giá trên một người bệnh.
DEFAULT_SKILL_SESSION_TECHNIQUES = tuple(
    name for _category, name, _description, _items
    in DEFAULT_NURSING_TECHNIQUE_SEED
)


def seed_default_nursing_techniques(connection, actor="system_default"):
    """Nạp các bảng kiểm quy trình mẫu, chỉ khi chưa có quy trình cùng tên.

    Dùng chung cho Desktop và Mobile Web. Quy trình do quản trị viên tự tạo
    hoặc đã chỉnh sửa không bao giờ bị ghi đè.
    """
    now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    added = 0
    for category, name, description, items in DEFAULT_NURSING_TECHNIQUE_SEED:
        existing = connection.execute(
            """SELECT technique_id FROM nursing_techniques
               WHERE technique_name=? COLLATE NOCASE""",
            (name,),
        ).fetchone()
        if existing:
            continue
        cursor = connection.execute(
            """INSERT INTO nursing_techniques(
                   category,technique_name,description,active,
                   created_by,created_dt,updated_dt
               ) VALUES(?,?,?,1,?,?,?)""",
            (category, name, description, actor, now_text, now_text),
        )
        technique_id = int(cursor.lastrowid or 0)
        if not technique_id:
            continue
        connection.executemany(
            """INSERT INTO nursing_technique_items(
                   technique_id,item_order,item_text
               ) VALUES(?,?,?)""",
            [
                (technique_id, order, item_text)
                for order, item_text in enumerate(items, 1)
            ],
        )
        added += 1
    return added


def is_skill_assessment_subject(role):
    """Return True only for student/employee accounts that may be assessed."""
    return str(role or "").strip().lower() not in SKILL_ASSESSOR_ROLES


def ensure_skill_assessment_extensions(connection):
    """Upgrade shared skill-assessment data without losing older student rows."""
    user_columns = {
        row[1] for row in connection.execute("PRAGMA table_info(users)")
    }
    if "department" not in user_columns:
        connection.execute(
            "ALTER TABLE users ADD COLUMN department TEXT DEFAULT ''"
        )

    assessment_columns = {
        row[1] for row in connection.execute(
            "PRAGMA table_info(student_technique_assessments)"
        )
    }
    additions = (
        ("class_id", "INTEGER DEFAULT 0"),
        ("department", "TEXT DEFAULT ''"),
        ("subject_username", "TEXT DEFAULT ''"),
        ("subject_code", "TEXT DEFAULT ''"),
        ("subject_name", "TEXT DEFAULT ''"),
        ("subject_role", "TEXT DEFAULT 'student'"),
        ("assessor_department", "TEXT DEFAULT ''"),
        ("overall_percent", "REAL"),
        ("scale_max", "INTEGER DEFAULT 4"),
        # Một buổi lượng giá = nhiều quy trình kỹ thuật do cùng một sinh
        # viên thực hiện trên cùng một người bệnh, trong cùng một lần chấm.
        ("session_id", "TEXT DEFAULT ''"),
        ("session_label", "TEXT DEFAULT ''"),
        ("patient_id", "TEXT DEFAULT ''"),
    )
    for column_name, column_type in additions:
        if column_name not in assessment_columns:
            connection.execute(
                "ALTER TABLE student_technique_assessments "
                "ADD COLUMN %s %s" % (column_name, column_type)
            )
    result_columns = {
        row[1] for row in connection.execute(
            "PRAGMA table_info(student_technique_results)"
        )
    }
    if "score_percent" not in result_columns:
        connection.execute(
            "ALTER TABLE student_technique_results "
            "ADD COLUMN score_percent REAL"
        )
    if "competency_level" not in result_columns:
        connection.execute(
            "ALTER TABLE student_technique_results "
            "ADD COLUMN competency_level INTEGER"
        )
    connection.execute(
        """CREATE INDEX IF NOT EXISTS idx_skill_assessment_session
           ON student_technique_assessments(session_id,assessment_id)"""
    )
    connection.execute(
        """CREATE INDEX IF NOT EXISTS idx_skill_assessment_class_session
           ON student_technique_assessments(class_id,session_id,assessment_id)"""
    )
    connection.execute(
        """UPDATE student_technique_assessments
           SET scale_max=4
           WHERE COALESCE(scale_max,0) NOT IN (4,5)"""
    )
    connection.execute(
        """UPDATE student_technique_results
           SET competency_level=score
           WHERE competency_level IS NULL"""
    )
    # Older releases stored competency on a 1-4 scale. Preserve the original
    # compatibility columns while exposing and using a true 0-100 percentage
    # for every checklist criterion and the overall skill result.
    connection.execute(
        """UPDATE student_technique_assessments
           SET overall_percent=CASE
               WHEN COALESCE(overall_score,0) BETWEEN 0 AND 4
                   THEN ROUND(COALESCE(overall_score,0)*25.0,2)
               ELSE ROUND(COALESCE(overall_score,0),2)
           END
           WHERE overall_percent IS NULL"""
    )
    connection.execute(
        """UPDATE student_technique_results
           SET score_percent=CASE
               WHEN COALESCE(score,0) BETWEEN 0 AND 4
                   THEN ROUND(COALESCE(score,0)*25.0,2)
               ELSE ROUND(COALESCE(score,0),2)
           END
           WHERE score_percent IS NULL"""
    )
    # Existing assessments remain fully usable and become generic subject rows.
    connection.execute(
        """UPDATE student_technique_assessments
           SET subject_username=student_username
           WHERE trim(COALESCE(subject_username,''))=''"""
    )
    connection.execute(
        """UPDATE student_technique_assessments
           SET subject_code=COALESCE((
                   SELECT nurse_code FROM users
                   WHERE users.username=student_technique_assessments.student_username
               ),''),
               subject_name=COALESCE((
                   SELECT full_name FROM users
                   WHERE users.username=student_technique_assessments.student_username
               ),''),
               subject_role=COALESCE(NULLIF((
                   SELECT role FROM users
                   WHERE users.username=student_technique_assessments.student_username
               ),''),'student')
           WHERE trim(COALESCE(subject_name,''))=''"""
    )


def load_skill_session_summary(connection, session_id):
    """Tổng hợp một buổi lượng giá: danh sách quy trình và điểm chung.

    Trả về ``{}`` khi không có buổi nào khớp. ``assessment_ids`` dùng để
    xuất PDF chung cho cả buổi.
    """
    session_id = str(session_id or "").strip()
    if not session_id:
        return {}
    # Chỉ chạy migration khi cột còn thiếu: hàm này được gọi trong luồng chỉ
    # đọc (xem kết quả, xuất PDF) nên không mở transaction ghi vô ích.
    columns = {
        row[1] for row in connection.execute(
            "PRAGMA table_info(student_technique_assessments)"
        )
    }
    if "session_id" not in columns or "class_id" not in columns:
        ensure_skill_assessment_extensions(connection)
        connection.commit()
    rows = connection.execute(
        """SELECT a.assessment_id,a.assessment_date,a.department,
                  COALESCE(a.class_id,0) AS class_id,
                  a.assessor_username,a.assessor_name,a.note,
                  a.session_id,a.session_label,a.patient_id,
                  COALESCE(NULLIF(a.subject_username,''),
                           a.student_username) AS subject_username,
                  COALESCE(NULLIF(a.subject_name,''),
                           a.student_username) AS subject_name,
                  COALESCE(NULLIF(a.subject_code,''),'') AS subject_code,
                  CASE WHEN COALESCE(a.scale_max,4)=5 THEN 5 ELSE 4 END
                      AS scale_max,
                  ROUND(COALESCE(a.overall_percent,0),2) AS overall_percent,
                  t.category,t.technique_name,
                  COALESCE(p.name,'') AS patient_name
           FROM student_technique_assessments a
           JOIN nursing_techniques t ON t.technique_id=a.technique_id
           LEFT JOIN patients p ON p.id=a.patient_id
           WHERE a.session_id=?
           ORDER BY a.assessment_id""",
        (session_id,),
    ).fetchall()
    if not rows:
        return {}
    techniques = [dict(row) for row in rows]
    percents = [float(row["overall_percent"] or 0) for row in techniques]
    first = techniques[0]
    return {
        "session_id": session_id,
        "class_id": int(first.get("class_id", 0) or 0),
        "session_label": first["session_label"] or "",
        "assessment_date": first["assessment_date"],
        "department": first["department"],
        "assessor_name": first["assessor_name"],
        "subject_username": first["subject_username"],
        "subject_name": first["subject_name"],
        "subject_code": first["subject_code"],
        "patient_id": first["patient_id"] or "",
        "patient_name": first["patient_name"] or "",
        "scale_max": int(first["scale_max"] or 4),
        "note": first["note"] or "",
        "techniques": techniques,
        "assessment_ids": [
            int(row["assessment_id"]) for row in techniques
        ],
        "technique_count": len(techniques),
        "overall_percent": round(
            sum(percents) / float(len(percents)), 2
        ) if percents else 0.0,
    }


def load_skill_assessment_report(connection, assessment_ids,
                                 subject_username=""):
    """Return one or more complete skill assessments for PDF output."""
    clean_ids = []
    for value in assessment_ids or []:
        try:
            assessment_id = int(value)
        except (TypeError, ValueError):
            continue
        if assessment_id > 0 and assessment_id not in clean_ids:
            clean_ids.append(assessment_id)
    if not clean_ids:
        return []
    ensure_skill_assessment_extensions(connection)
    placeholders = ",".join("?" for _value in clean_ids)
    parameters = list(clean_ids)
    subject_filter = ""
    if str(subject_username or "").strip():
        subject_filter = (
            """ AND COALESCE(NULLIF(a.subject_username,''),
                             a.student_username)=?"""
        )
        parameters.append(str(subject_username).strip())
    rows = connection.execute(
        """SELECT a.assessment_id,a.assessment_date,a.department,
                  a.assessor_username,a.assessor_name,a.note,a.source,
                  COALESCE(NULLIF(a.subject_username,''),
                           a.student_username) AS subject_username,
                  COALESCE(NULLIF(a.subject_code,''),person.nurse_code,'')
                      AS subject_code,
                  COALESCE(NULLIF(a.subject_name,''),person.full_name,
                           a.student_username) AS subject_name,
                  COALESCE(NULLIF(a.subject_role,''),person.role,'staff')
                      AS subject_role,
                  t.category,t.technique_name,t.description,
                  CASE WHEN COALESCE(a.scale_max,4)=5 THEN 5 ELSE 4 END
                      AS scale_max,
                  ROUND(CASE
                      WHEN COALESCE(a.overall_score,0) BETWEEN 1
                           AND CASE WHEN COALESCE(a.scale_max,4)=5
                                    THEN 5 ELSE 4 END
                          THEN COALESCE(a.overall_score,0)
                      ELSE COALESCE(
                          a.overall_percent,
                          CASE WHEN COALESCE(a.overall_score,0) BETWEEN 0 AND 4
                               THEN COALESCE(a.overall_score,0)*25.0
                               ELSE COALESCE(a.overall_score,0) END
                      ) * (CASE WHEN COALESCE(a.scale_max,4)=5
                                THEN 5.0 ELSE 4.0 END) / 100.0
                  END,2) AS overall_level,
                  ROUND(COALESCE(
                      a.overall_percent,
                      CASE WHEN COALESCE(a.overall_score,0) BETWEEN 0 AND 4
                           THEN COALESCE(a.overall_score,0)*25.0
                           ELSE COALESCE(a.overall_score,0) END
                  ),2) AS overall_percent
           FROM student_technique_assessments a
           JOIN nursing_techniques t ON t.technique_id=a.technique_id
           LEFT JOIN users person ON person.username=COALESCE(
               NULLIF(a.subject_username,''),a.student_username)
           WHERE a.assessment_id IN (%s)%s
           ORDER BY a.assessment_date,a.assessment_id"""
        % (placeholders, subject_filter),
        tuple(parameters),
    ).fetchall()
    report = []
    for row in rows:
        assessment = dict(row)
        assessment["items"] = [
            dict(item) for item in connection.execute(
                """SELECT i.item_order,i.item_text,
                          COALESCE(r.competency_level,r.score,1)
                              AS competency_level,
                          ROUND(COALESCE(
                              r.score_percent,
                              CASE WHEN COALESCE(r.score,0) BETWEEN 0 AND 4
                                   THEN COALESCE(r.score,0)*25.0
                                   ELSE COALESCE(r.score,0) END
                          ),2) AS score_percent,
                          r.note
                   FROM student_technique_results r
                   JOIN nursing_technique_items i
                     ON i.item_id=r.item_id
                   WHERE r.assessment_id=?
                   ORDER BY i.item_order,i.item_id""",
                (assessment["assessment_id"],),
            ).fetchall()
        ]
        report.append(assessment)
    return report


def generate_skill_assessment_pdf(assessments, session=None):
    """Create a Unicode PDF containing one or more skill assessments.

    ``session`` (kết quả của load_skill_session_summary) là buổi lượng giá
    nhiều quy trình trên một người bệnh: khi có, PDF mở đầu bằng bảng tổng
    hợp cả buổi rồi mới in từng bảng kiểm chi tiết.
    """
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        from reportlab.platypus import (
            SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle,
            PageBreak,
        )
    except ImportError:
        raise RuntimeError(
            "PDF support requires the reportlab package in this application."
        )
    if not assessments:
        raise ValueError("Select at least one completed skill assessment.")
    regular_font, bold_font = "Helvetica", "Helvetica-Bold"
    for regular_path, bold_path in (
        (
            os.path.join(
                os.environ.get("WINDIR", "C:\\Windows"),
                "Fonts", "arial.ttf",
            ),
            os.path.join(
                os.environ.get("WINDIR", "C:\\Windows"),
                "Fonts", "arialbd.ttf",
            ),
        ),
        (
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        ),
    ):
        if os.path.exists(regular_path):
            try:
                pdfmetrics.registerFont(
                    TTFont("SkillAssessmentUnicode", regular_path)
                )
                regular_font = "SkillAssessmentUnicode"
                if os.path.exists(bold_path):
                    pdfmetrics.registerFont(
                        TTFont("SkillAssessmentUnicodeBold", bold_path)
                    )
                    bold_font = "SkillAssessmentUnicodeBold"
                else:
                    bold_font = regular_font
            except Exception:
                regular_font, bold_font = "Helvetica", "Helvetica-Bold"
            break
    output = io.BytesIO()
    document = SimpleDocTemplate(
        output, pagesize=A4,
        leftMargin=14 * mm, rightMargin=14 * mm,
        topMargin=15 * mm, bottomMargin=15 * mm,
        title="Skill Assessment Results", author="EMR",
    )
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="SATitle", parent=styles["Title"], fontName=bold_font,
        fontSize=16, leading=20, alignment=TA_CENTER,
        textColor=colors.HexColor("#123b66"), spaceAfter=8,
    ))
    styles.add(ParagraphStyle(
        name="SAHeading", parent=styles["Heading2"], fontName=bold_font,
        fontSize=11, leading=14, textColor=colors.white,
        backColor=colors.HexColor("#1f5f8b"), borderPadding=5,
        spaceBefore=7, spaceAfter=6,
    ))
    styles.add(ParagraphStyle(
        name="SABody", parent=styles["BodyText"], fontName=regular_font,
        fontSize=8.5, leading=11, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="SASmall", parent=styles["BodyText"], fontName=regular_font,
        fontSize=7.5, leading=9.5, wordWrap="CJK",
    ))

    def paragraph(value, style="SABody"):
        text = html.escape(str(value or "")).replace("\n", "<br/>")
        return Paragraph(text or "-", styles[style])

    def make_table(rows, widths, header=False):
        converted = [
            [
                cell if hasattr(cell, "wrapOn") else paragraph(cell, "SASmall")
                for cell in row
            ]
            for row in rows
        ]
        table = Table(
            converted, colWidths=widths,
            repeatRows=1 if header else 0,
            hAlign="LEFT", splitByRow=1, splitInRow=1,
        )
        commands = [
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("GRID", (0, 0), (-1, -1), .35,
             colors.HexColor("#b8c7d5")),
            ("LEFTPADDING", (0, 0), (-1, -1), 4),
            ("RIGHTPADDING", (0, 0), (-1, -1), 4),
            ("TOPPADDING", (0, 0), (-1, -1), 4),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ("ROWBACKGROUNDS", (0, 1 if header else 0), (-1, -1),
             [colors.white, colors.HexColor("#f6f9fc")]),
        ]
        if header:
            commands.extend([
                ("BACKGROUND", (0, 0), (-1, 0),
                 colors.HexColor("#dceaf5")),
                ("FONTNAME", (0, 0), (-1, 0), bold_font),
            ])
        table.setStyle(TableStyle(commands))
        return table

    session_summary = session if isinstance(session, dict) else {}
    story = _eiu_pdf_logo_flowables() + [
        Paragraph(
            "K\u1ebeT QU\u1ea2 L\u01af\u1ee2NG GI\u00c1 K\u1ef8 N\u0102NG "
            "TR\u00caN M\u1ed8T NG\u01af\u1edcI B\u1ec6NH"
            if session_summary else "SKILL ASSESSMENT RESULTS",
            styles["SATitle"],
        ),
        paragraph(
            "Generated: %s | Completed assessments: %d"
            % (
                datetime.now().strftime("%Y-%m-%d %H:%M"),
                len(assessments),
            )
        ),
        Spacer(1, 5 * mm),
    ]
    if session_summary:
        # B\u1ea3ng t\u1ed5ng h\u1ee3p c\u1ea3 bu\u1ed5i: sinh vi\u00ean n\u00e0y \u0111\u00e3 l\u00e0m nh\u1eefng quy tr\u00ecnh
        # n\u00e0o tr\u00ean ng\u01b0\u1eddi b\u1ec7nh n\u00e0o, \u0111i\u1ec3m t\u1eebng quy tr\u00ecnh v\u00e0 \u0111i\u1ec3m chung.
        story.append(Paragraph(
            "T\u1ed5ng h\u1ee3p bu\u1ed5i l\u01b0\u1ee3ng gi\u00e1", styles["SAHeading"]
        ))
        story.append(make_table([
            ["Ng\u01b0\u1eddi \u0111\u01b0\u1ee3c l\u01b0\u1ee3ng gi\u00e1", "%s (%s)" % (
                session_summary.get("subject_name", ""),
                session_summary.get("subject_code", "")
                or session_summary.get("subject_username", ""),
            )],
            ["Ng\u01b0\u1eddi b\u1ec7nh", "%s %s" % (
                session_summary.get("patient_id", "") or "-",
                session_summary.get("patient_name", "") or "",
            )],
            ["Ng\u00e0y l\u01b0\u1ee3ng gi\u00e1", session_summary.get(
                "assessment_date", ""
            )],
            ["Khoa", session_summary.get("department", "") or "-"],
            ["Ng\u01b0\u1eddi ch\u1ea5m", session_summary.get("assessor_name", "")],
            ["Ghi ch\u00fa bu\u1ed5i", session_summary.get(
                "session_label", ""
            ) or "-"],
            ["S\u1ed1 quy tr\u00ecnh \u0111\u00e3 ch\u1ea5m", "%d" % int(
                session_summary.get("technique_count", 0) or 0
            )],
            ["\u0110i\u1ec3m chung c\u1ee7a bu\u1ed5i", "%.2f%%" % float(
                session_summary.get("overall_percent", 0) or 0
            )],
        ], [47 * mm, 131 * mm]))
        story.append(Spacer(1, 4 * mm))
        session_rows = [["#", "Quy tr\u00ecnh k\u1ef9 thu\u1eadt", "K\u1ebft qu\u1ea3"]]
        session_rows.extend([
            [
                "%d" % order,
                "%s - %s" % (
                    row.get("category", "") or "Chung",
                    row.get("technique_name", ""),
                ),
                "%.2f%%" % float(row.get("overall_percent", 0) or 0),
            ]
            for order, row in enumerate(
                session_summary.get("techniques", []), 1
            )
        ])
        story.append(make_table(session_rows, [10 * mm, 138 * mm, 30 * mm]))
        story.append(Spacer(1, 5 * mm))
    for index, assessment in enumerate(assessments):
        if index:
            story.append(PageBreak())
        story.append(Paragraph(
            "%s - %s" % (
                assessment.get("category", "") or "Skill",
                assessment.get("technique_name", ""),
            ),
            styles["SAHeading"],
        ))
        scale_max = (
            5 if int(assessment.get("scale_max") or 4) == 5 else 4
        )
        overall_level = float(
            assessment.get("overall_level") or 0
        )
        overall_percent = float(
            assessment.get("overall_percent") or 0
        )
        metadata = [
            ["Assessed person", assessment.get("subject_name", "")],
            ["Employee/student code", assessment.get("subject_code", "")],
            ["Role / department", "%s / %s" % (
                assessment.get("subject_role", ""),
                assessment.get("department", ""),
            )],
            ["Assessment date", assessment.get("assessment_date", "")],
            ["Assessor", assessment.get("assessor_name", "")],
            ["Competency scale", "1-%d" % scale_max],
            ["Overall result", "%.2f / %d (%.2f%%)" % (
                overall_level, scale_max, overall_percent
            )],
        ]
        if str(assessment.get("description", "") or "").strip():
            metadata.append([
                "Skill description", assessment.get("description", "")
            ])
        if str(assessment.get("note", "") or "").strip():
            metadata.append([
                "Assessor comment", assessment.get("note", "")
            ])
        story.append(make_table(metadata, [47 * mm, 131 * mm]))
        story.append(Spacer(1, 4 * mm))
        items = assessment.get("items", [])
        include_notes = any(
            str(item.get("note", "") or "").strip() for item in items
        )
        if include_notes:
            item_rows = [[
                "Checklist criterion", "Competency", "Percent", "Note"
            ]]
            item_rows.extend([
                [
                    item.get("item_text", ""),
                    "%s / %d" % (
                        item.get("competency_level", ""), scale_max
                    ),
                    "%.2f%%" % float(item.get("score_percent") or 0),
                    item.get("note", ""),
                ]
                for item in items
            ])
            story.append(make_table(
                item_rows,
                [92 * mm, 24 * mm, 24 * mm, 38 * mm],
                header=True,
            ))
        else:
            item_rows = [[
                "Checklist criterion", "Competency", "Percent"
            ]]
            item_rows.extend([
                [
                    item.get("item_text", ""),
                    "%s / %d" % (
                        item.get("competency_level", ""), scale_max
                    ),
                    "%.2f%%" % float(item.get("score_percent") or 0),
                ]
                for item in items
            ])
            story.append(make_table(
                item_rows, [125 * mm, 27 * mm, 26 * mm], header=True
            ))
    document.build(story)
    return output.getvalue()
