# ---------------------------------------------------------------------------
# Password storage / Lưu trữ mật khẩu
#
# The EMR runs over the hospital's internal Wi-Fi, where the SQLite file and
# any plain HTTP traffic are reachable by everyone on the same network.  A
# readable password column would therefore expose every account at once, so
# passwords are stored only as a salted PBKDF2-HMAC-SHA256 digest.
# Verification still accepts a legacy plain-text value so existing databases
# keep working; the row is rewritten in the hashed format immediately.
# ---------------------------------------------------------------------------
PASSWORD_HASH_SCHEME = "pbkdf2_sha256"
PASSWORD_HASH_ITERATIONS = 240000
PASSWORD_SALT_BYTES = 16
PASSWORD_MIN_LENGTH = 4


def hash_password(raw_password):
    """Return 'scheme$iterations$salt_hex$digest_hex' for a raw password."""
    raw = str(raw_password or "")
    salt = secrets.token_bytes(PASSWORD_SALT_BYTES)
    digest = hashlib.pbkdf2_hmac(
        "sha256", raw.encode("utf-8"), salt, PASSWORD_HASH_ITERATIONS
    )
    return "%s$%d$%s$%s" % (
        PASSWORD_HASH_SCHEME, PASSWORD_HASH_ITERATIONS,
        salt.hex(), digest.hex(),
    )


def is_password_hashed(stored_value):
    """True when the stored column already holds a digest, not a password."""
    return str(stored_value or "").startswith(PASSWORD_HASH_SCHEME + "$")


def verify_password(stored_value, raw_password):
    """Constant-time check against a hashed (or legacy plain-text) value."""
    stored = str(stored_value or "")
    raw = str(raw_password or "")
    if not stored:
        return False
    if not is_password_hashed(stored):
        # Row written before hashing existed: compare once, then the caller
        # rewrites it through password_needs_rehash().
        return secrets.compare_digest(stored, raw)
    parts = stored.split("$", 3)
    if len(parts) != 4:
        return False
    try:
        iterations = int(parts[1])
        salt = bytes.fromhex(parts[2])
        expected = bytes.fromhex(parts[3])
    except (ValueError, TypeError):
        return False
    candidate = hashlib.pbkdf2_hmac(
        "sha256", raw.encode("utf-8"), salt, iterations
    )
    return secrets.compare_digest(candidate, expected)


def password_needs_rehash(stored_value):
    """True when a stored value must be rewritten in the current format."""
    stored = str(stored_value or "")
    if not is_password_hashed(stored):
        return True
    parts = stored.split("$", 3)
    if len(parts) != 4:
        return True
    try:
        return int(parts[1]) < PASSWORD_HASH_ITERATIONS
    except ValueError:
        return True


def generate_temporary_password(length=10):
    """Readable one-time password an admin can hand to a user in person."""
    # Ambiguous glyphs (0/O, 1/l/I) are excluded so the password can be read
    # aloud or written on paper without transcription errors.
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789"
    return "".join(secrets.choice(alphabet) for _ in range(max(6, int(length))))


def _row_value(row, key, index):
    """Read a column from either a sqlite3.Row or a plain tuple."""
    try:
        return row[key]
    except (TypeError, IndexError, KeyError):
        return row[index]


def upgrade_stored_passwords(db):
    """Rewrite every readable password in `users` as a salted digest.

    Called on start-up so a database created by an older build is migrated
    without anyone having to reset a password.
    """
    try:
        rows = db.execute("SELECT username,password FROM users").fetchall()
    except sqlite3.Error:
        return 0
    upgraded = 0
    for row in rows:
        stored = _row_value(row, "password", 1)
        if is_password_hashed(stored):
            continue
        db.execute(
            "UPDATE users SET password=? WHERE username=?",
            (
                hash_password(str(stored or "")),
                _row_value(row, "username", 0),
            ),
        )
        upgraded += 1
    return upgraded


def ensure_role_permission_schema(db):
    """Create and safely seed the editable role-permission matrix."""
    db.execute("""CREATE TABLE IF NOT EXISTS role_feature_permissions (
        role TEXT NOT NULL,
        feature_key TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 0,
        updated_by TEXT DEFAULT '',
        updated_dt TEXT DEFAULT '',
        PRIMARY KEY(role,feature_key)
    )""")
    seed_rows = []
    for role, defaults in ROLE_PERMISSION_PRESETS.items():
        for feature_key in ROLE_ACCESS_LABELS:
            seed_rows.append((
                role, feature_key,
                1 if feature_key in defaults else 0,
            ))
    db.executemany(
        """INSERT OR IGNORE INTO role_feature_permissions(
               role,feature_key,allowed)
           VALUES(?,?,?)""",
        seed_rows,
    )
    db.execute("""CREATE TABLE IF NOT EXISTS account_feature_permissions (
        username TEXT NOT NULL,
        feature_key TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 0,
        granted_by TEXT DEFAULT '',
        updated_dt TEXT DEFAULT '',
        PRIMARY KEY(username,feature_key),
        FOREIGN KEY(username) REFERENCES users(username)
    )""")
    db.execute("""CREATE INDEX IF NOT EXISTS
        idx_account_feature_permissions_feature
        ON account_feature_permissions(feature_key,allowed,username)""")
    db.execute("""CREATE TABLE IF NOT EXISTS login_security_state (
        username TEXT PRIMARY KEY,
        failed_attempts INTEGER NOT NULL DEFAULT 0,
        first_failed_dt TEXT DEFAULT '',
        last_failed_dt TEXT DEFAULT '',
        locked_until REAL NOT NULL DEFAULT 0
    )""")


