def notification_settings_for_user(db, username):
    """Return validated preferences, using defaults until a user first saves."""
    settings = dict(NOTIFICATION_SETTING_DEFAULTS)
    row = db.execute(
        "SELECT * FROM user_notification_settings WHERE username=?",
        (str(username or ""),),
    ).fetchone()
    if row:
        for key in settings:
            if key in row.keys() and row[key] is not None:
                settings[key] = row[key]
    for key in (
        "master_enabled", "sound_enabled", "banner_enabled",
        "browser_notifications_enabled", "news_alerts_enabled",
        "medication_reminders_enabled", "lab_reminders_enabled",
        "general_reminders_enabled", "vital_alert_sound_enabled",
    ):
        settings[key] = 1 if int(settings.get(key) or 0) else 0
    settings["reminder_lead_minutes"] = max(
        0, min(120, int(settings.get("reminder_lead_minutes") or 0))
    )
    settings["repeat_minutes"] = max(
        1, min(60, int(settings.get("repeat_minutes") or 5))
    )
    settings["volume_percent"] = max(
        0, min(100, int(settings.get("volume_percent") or 0))
    )
    # web.33: one fresh notification row always owns exactly one beep.
    # Keep the legacy column for safe migrations, but do not let an older
    # per-row repeat value multiply the number of audible notifications.
    settings["sound_repeat_count"] = 1
    if settings.get("sound_style") not in ("beep", "chime", "urgent"):
        settings["sound_style"] = "beep"
    if settings.get("vital_alert_sound_style") not in (
        "beep", "chime", "urgent"
    ):
        settings["vital_alert_sound_style"] = "urgent"
    if settings.get("theme_key") not in APPEARANCE_THEME_KEYS:
        settings["theme_key"] = "current"
    if settings.get("patient_notification_scope") not in (
        "assigned", "department"
    ):
        settings["patient_notification_scope"] = "assigned"
    settings["vital_alert_thresholds"] = validated_vital_thresholds(
        settings.get("vital_alert_thresholds"), "alert"
    )
    settings["vital_bold_thresholds"] = validated_vital_thresholds(
        settings.get("vital_bold_thresholds"), "bold"
    )
    for key in (
        "news_warning_color", "news_critical_color",
        "medication_color", "lab_color", "general_color",
        "vital_alert_color", "vital_bold_color",
    ):
        value = str(settings.get(key) or "")
        if not re.match(r"^#[0-9a-fA-F]{6}$", value):
            settings[key] = NOTIFICATION_SETTING_DEFAULTS[key]
    return settings


def configured_role_permission_matrix(db):
    """Return every role and feature, falling back to secure defaults."""
    matrix = {
        role: set(features)
        for role, features in ROLE_PERMISSION_PRESETS.items()
    }
    try:
        rows = db.execute(
            """SELECT role,feature_key,allowed
               FROM role_feature_permissions"""
        ).fetchall()
    except sqlite3.Error:
        return matrix
    seen_roles = set()
    for row in rows:
        role = str(row["role"] or "").strip().lower()
        feature_key = str(row["feature_key"] or "").strip()
        if role not in matrix or feature_key not in ROLE_ACCESS_LABELS:
            continue
        if role not in seen_roles:
            matrix[role] = set()
            seen_roles.add(role)
        if int(row["allowed"] or 0):
            matrix[role].add(feature_key)
    # Admin's row is no longer forced to "everything" here: it is read from
    # role_feature_permissions like any other role and defaults to empty
    # (see ROLE_PERMISSION_PRESETS["admin"]) until an administrator ticks
    # boxes on the Accounts screen and saves. Note this only governs nav-
    # link visibility and the account/role editor - admin-only pages check
    # is_admin() directly, and clinical routes only apply this matrix to
    # staff/nurse accounts, so an admin can never be routed out of the app
    # by an empty or partial matrix here.
    for role in matrix:
        matrix[role].intersection_update(ROLE_PERMISSION_CEILINGS[role])
    return matrix


def ensure_classroom_management_schema(db):
    """Non-destructive classroom/group ownership migration."""
    db.execute("""CREATE TABLE IF NOT EXISTS classrooms (
        class_id INTEGER PRIMARY KEY AUTOINCREMENT,
        class_code TEXT UNIQUE NOT NULL,
        class_name TEXT NOT NULL,
        academic_year TEXT DEFAULT '',
        department TEXT DEFAULT '',
        description TEXT DEFAULT '',
        active INTEGER NOT NULL DEFAULT 1,
        created_by TEXT DEFAULT '',
        created_dt TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    columns = {
        row["name"] if isinstance(row, sqlite3.Row) else row[1]
        for row in db.execute("PRAGMA table_info(classrooms)").fetchall()
    }
    for column_name, definition in (
        ("subject_code", "TEXT DEFAULT ''"),
        ("semester", "TEXT DEFAULT ''"),
        ("group_number", "TEXT DEFAULT ''"),
    ):
        if column_name not in columns:
            db.execute(
                "ALTER TABLE classrooms ADD COLUMN %s %s"
                % (column_name, definition)
            )
    db.execute("""UPDATE classrooms
                  SET subject_code=class_code
                  WHERE trim(COALESCE(subject_code,''))=''""")
    db.execute("""UPDATE classrooms SET group_number='1'
                  WHERE trim(COALESCE(group_number,''))=''""")
    db.execute("""CREATE TABLE IF NOT EXISTS classroom_instructors (
        class_id INTEGER NOT NULL,
        username TEXT NOT NULL,
        assigned_dt TEXT DEFAULT '',
        assigned_by TEXT DEFAULT '',
        PRIMARY KEY(class_id,username),
        FOREIGN KEY(class_id) REFERENCES classrooms(class_id),
        FOREIGN KEY(username) REFERENCES users(username)
    )""")
    db.execute("""CREATE INDEX IF NOT EXISTS
        idx_classroom_instructors_username
        ON classroom_instructors(username,class_id)""")
    db.execute("""CREATE TABLE IF NOT EXISTS class_learning_ai_analyses (
        analysis_id INTEGER PRIMARY KEY AUTOINCREMENT,
        class_id INTEGER NOT NULL,
        requested_by_username TEXT DEFAULT '',
        requested_by_name TEXT DEFAULT '',
        requested_dt TEXT NOT NULL,
        model TEXT DEFAULT '',
        language TEXT DEFAULT 'English',
        metrics_json TEXT NOT NULL DEFAULT '{}',
        result_json TEXT NOT NULL DEFAULT '{}',
        source TEXT NOT NULL DEFAULT 'manual',
        FOREIGN KEY(class_id) REFERENCES classrooms(class_id)
    )""")
    db.execute("""CREATE INDEX IF NOT EXISTS idx_class_learning_ai_class_dt
        ON class_learning_ai_analyses(class_id,requested_dt,analysis_id)""")
    db.execute("""INSERT OR IGNORE INTO classroom_instructors(
                      class_id,username,assigned_dt,assigned_by)
                  SELECT c.class_id,c.created_by,
                         COALESCE(NULLIF(c.created_dt,''),?),c.created_by
                  FROM classrooms c JOIN users u
                    ON u.username=c.created_by
                  WHERE lower(u.role) IN ('instructor','lecturer','teacher')
                    AND trim(COALESCE(c.created_by,''))<>''""",
               (datetime.now().strftime("%Y-%m-%d %H:%M:%S"),))
    db.execute("""CREATE TABLE IF NOT EXISTS academic_year_catalog (
        academic_year TEXT PRIMARY KEY,
        active INTEGER NOT NULL DEFAULT 1,
        created_dt TEXT DEFAULT ''
    )""")
    db.execute("""CREATE TABLE IF NOT EXISTS semester_catalog (
        semester_name TEXT PRIMARY KEY,
        sort_order INTEGER NOT NULL DEFAULT 0,
        active INTEGER NOT NULL DEFAULT 1,
        created_dt TEXT DEFAULT ''
    )""")
    # Keep the legacy column/table names for database compatibility, while the
    # application now exposes four fixed quarters per academic year. Standard
    # Semester values from web.8/web.9 are converted in place; non-standard
    # legacy text is preserved in classrooms but is no longer offered when a
    # class is created or edited.
    for quarter_number in range(1, 5):
        db.execute(
            """UPDATE classrooms SET semester=?
               WHERE lower(trim(COALESCE(semester,'')))=?""",
            (
                "Quarter %d" % quarter_number,
                "semester %d" % quarter_number,
            ),
        )
    now = datetime.now()
    start_year = now.year if now.month >= 7 else now.year - 1
    created_dt = now.strftime("%Y-%m-%d %H:%M:%S")
    db.executemany(
        """INSERT OR IGNORE INTO academic_year_catalog(
               academic_year,active,created_dt) VALUES(?,1,?)""",
        [
            ("%d-%d" % (year, year + 1), created_dt)
            for year in range(start_year - 1, start_year + 2)
        ],
    )
    db.executemany(
        """INSERT OR IGNORE INTO semester_catalog(
               semester_name,sort_order,active,created_dt)
           VALUES(?,?,1,?)
           ON CONFLICT(semester_name) DO UPDATE SET
               sort_order=excluded.sort_order,active=1""",
        [
            ("Quarter 1", 1, created_dt),
            ("Quarter 2", 2, created_dt),
            ("Quarter 3", 3, created_dt),
            ("Quarter 4", 4, created_dt),
        ],
    )
    db.execute(
        """UPDATE semester_catalog SET active=0
           WHERE semester_name NOT IN (
               'Quarter 1','Quarter 2','Quarter 3','Quarter 4'
           )"""
    )
    db.execute("""INSERT OR IGNORE INTO academic_year_catalog(
                      academic_year,active,created_dt)
                  SELECT DISTINCT academic_year,1,?
                  FROM classrooms
                  WHERE trim(COALESCE(academic_year,''))<>''""", (created_dt,))
    db.execute("PRAGMA optimize")


# A subject label normally starts with the subject code: ``NUR 410``,
# ``NUR410 - Emergency Nursing``, ``NUR-410: Điều dưỡng cấp cứu``.
_SUBJECT_CODE_PATTERN = re.compile(
    r"^\s*([A-Za-z]{2,8})\s*[-_.]?\s*(\d{2,5})\s*[-–—:|]?\s*(.*)$"
)


def normalize_subject_code(value):
    """Comparison key for a subject code: ``NUR 410`` and ``nur-410`` match."""
    return "".join(
        character.upper() for character in str(value or "")
        if character.isalnum()
    )


def split_legacy_course_name(course_name):
    """Derive ``(subject code, subject name)`` from one legacy course label.

    The clinical target catalog used to store a single free-text course name.
    Practice targets are now shared by subject code, so every legacy label is
    split once during the migration: the leading ``letters + digits`` token
    becomes the subject code and the remainder becomes the subject name.
    """
    raw = " ".join(str(course_name or "").split())
    if not raw:
        return "", ""
    match = _SUBJECT_CODE_PATTERN.match(raw)
    if match:
        code = (match.group(1) + match.group(2)).upper()
        name = match.group(3).strip(" -–—:|")
        return code, (name or raw)
    for separator in (" - ", " – ", " — ", " | ", ": "):
        if separator in raw:
            head, tail = raw.split(separator, 1)
            head, tail = head.strip(), tail.strip()
            if head and tail and len(head) <= 20:
                return normalize_subject_code(head), tail
    # No recognisable code: build a short ASCII acronym from the initials so
    # the placeholder stays readable ("Điều dưỡng cơ bản" -> "DDCB"). The
    # instructor can replace it in the Subject targets tab.
    ascii_text = unicodedata.normalize("NFD", raw)
    ascii_text = "".join(
        character for character in ascii_text
        if not unicodedata.combining(character)
    ).replace("Đ", "D").replace("đ", "d")
    initials = "".join(
        word[0] for word in re.split(r"[^0-9A-Za-z]+", ascii_text) if word
    ).upper()[:10]
    return (initials or normalize_subject_code(raw)[:20]), raw


def subject_course_label(subject_code, subject_name):
    """Compatibility ``course_name`` key built from the code and the name.

    ``nur410_targets``, ``nur410_class_students`` and the report helpers all
    key on ``course_name``, so the label is kept in sync with the code/name
    pair instead of being replaced. It always starts with the subject code,
    which is what classroom matching relies on.
    """
    code = str(subject_code or "").strip()
    name = str(subject_name or "").strip()
    if code and name and normalize_subject_code(name) != normalize_subject_code(code):
        return "%s - %s" % (code, name)
    return code or name


def ensure_subject_target_schema(db):
    """Split the single-field clinical course catalog into code + name.

    Non-destructive: existing targets, class assignments and submitted student
    progress keep their ``course_name`` key. Only the catalog table gains the
    two descriptive columns, backfilled from the label already stored.
    """
    db.execute("""CREATE TABLE IF NOT EXISTS nur410_courses (
        course_id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_name TEXT UNIQUE NOT NULL)""")
    columns = {
        row["name"] if isinstance(row, sqlite3.Row) else row[1]
        for row in db.execute("PRAGMA table_info(nur410_courses)").fetchall()
    }
    for column_name, definition in (
        ("subject_code", "TEXT DEFAULT ''"),
        ("subject_name", "TEXT DEFAULT ''"),
    ):
        if column_name not in columns:
            db.execute(
                "ALTER TABLE nur410_courses ADD COLUMN %s %s"
                % (column_name, definition)
            )
    # Older databases sometimes carry targets for a course that was never
    # registered in the catalog table. Register those first so the backfill
    # below gives them a code as well.
    db.execute("""INSERT OR IGNORE INTO nur410_courses(course_name)
                  SELECT DISTINCT course_name FROM nur410_targets
                  WHERE trim(COALESCE(course_name,''))<>''""")
    rows = db.execute(
        """SELECT course_id,course_name,
                  COALESCE(subject_code,'') AS subject_code,
                  COALESCE(subject_name,'') AS subject_name
           FROM nur410_courses ORDER BY course_id"""
    ).fetchall()
    taken = {
        normalize_subject_code(row["subject_code"])
        for row in rows if str(row["subject_code"]).strip()
    }
    for row in rows:
        if str(row["subject_code"]).strip():
            continue
        code, name = split_legacy_course_name(row["course_name"])
        base = code or ("SUBJ%d" % int(row["course_id"]))
        candidate, suffix = base, 2
        # Two legacy labels can reduce to the same code (``NUR 410`` and
        # ``NUR410 - Emergency Nursing``). Keep them apart rather than merging
        # two target lists behind the instructor's back; the code can be fixed
        # in the Subject targets tab.
        while normalize_subject_code(candidate) in taken:
            candidate = "%s-%d" % (base, suffix)
            suffix += 1
        taken.add(normalize_subject_code(candidate))
        db.execute(
            """UPDATE nur410_courses SET subject_code=?,subject_name=?
               WHERE course_id=?""",
            (candidate, name or row["course_name"], int(row["course_id"])),
        )
    try:
        db.execute("""CREATE UNIQUE INDEX IF NOT EXISTS
            idx_nur410_courses_subject_code
            ON nur410_courses(subject_code COLLATE NOCASE)
            WHERE trim(COALESCE(subject_code,''))<>''""")
    except sqlite3.OperationalError:
        # Partial indexes need SQLite 3.8; uniqueness is also enforced by the
        # add/edit handlers, so an older engine simply skips the index.
        pass
    except sqlite3.IntegrityError:
        pass


def sync_subject_catalog_from_classrooms(db, classrooms):
    """Mirror the subject code / name of Quản lý lớp học into the catalog.

    Subjects are not invented in the target screen: the subject code and the
    subject name are owned by Classroom management. This keeps one catalog row
    per subject code so practice targets can hang off it, and renames that row
    in step whenever the classroom is edited. Group, quarter and academic year
    never take part - they belong to the classroom, not to the target list.

    Returns ``[{subject_code, subject_name, course_name, class_count}]``
    ordered by subject code.
    """
    by_code = {}
    for classroom in classrooms:
        keys = classroom.keys()

        def field(name):
            return (
                str(classroom[name] or "").strip() if name in keys else ""
            )

        code = field("subject_code") or field("class_code")
        key = normalize_subject_code(code)
        if not key:
            continue
        try:
            class_id = int(classroom["class_id"] or 0)
        except (KeyError, TypeError, ValueError):
            class_id = 0
        entry = by_code.setdefault(key, {
            "subject_code": code,
            "subject_name": field("class_name") or code,
            "class_count": 0,
            "_rank": -1,
        })
        entry["class_count"] += 1
        # The most recently created classroom carrying this code decides the
        # displayed name, so editing it in Classroom management propagates.
        if class_id > entry["_rank"]:
            entry["_rank"] = class_id
            entry["subject_code"] = code
            entry["subject_name"] = field("class_name") or code

    existing = {}
    for row in db.execute(
        """SELECT course_id,course_name,COALESCE(subject_code,'') AS subject_code,
                  COALESCE(subject_name,'') AS subject_name
           FROM nur410_courses"""
    ).fetchall():
        key = normalize_subject_code(
            row["subject_code"] or split_legacy_course_name(
                row["course_name"]
            )[0]
        )
        if key and key not in existing:
            existing[key] = row

    subjects = []
    for key in sorted(by_code):
        entry = by_code[key]
        code, name = entry["subject_code"], entry["subject_name"]
        desired_label = subject_course_label(code, name)
        row = existing.get(key)
        if row is None:
            # A subject taught by a classroom but with no catalog row yet.
            try:
                db.execute(
                    """INSERT INTO nur410_courses(
                           course_name,subject_code,subject_name)
                       VALUES(?,?,?)""",
                    (desired_label, code, name),
                )
            except sqlite3.IntegrityError:
                # Another label already occupies this course_name; reuse it.
                pass
            course_name = desired_label
        else:
            course_name = str(row["course_name"] or "")
            if (
                str(row["subject_code"] or "") != code
                or str(row["subject_name"] or "") != name
                or course_name != desired_label
            ):
                clash = db.execute(
                    """SELECT 1 FROM nur410_courses
                       WHERE course_name=? AND course_id<>?""",
                    (desired_label, int(row["course_id"])),
                ).fetchone()
                if clash:
                    # Keep the old label rather than collide; only refresh the
                    # descriptive columns.
                    db.execute(
                        """UPDATE nur410_courses
                           SET subject_code=?,subject_name=?
                           WHERE course_id=?""",
                        (code, name, int(row["course_id"])),
                    )
                else:
                    db.execute(
                        """UPDATE nur410_courses
                           SET course_name=?,subject_code=?,subject_name=?
                           WHERE course_id=?""",
                        (desired_label, code, name, int(row["course_id"])),
                    )
                    if course_name != desired_label:
                        # course_name is the shared key of the target list and
                        # the class roster, so rename it everywhere at once.
                        db.execute(
                            """UPDATE nur410_targets SET course_name=?
                               WHERE course_name=?""",
                            (desired_label, course_name),
                        )
                        db.execute(
                            """UPDATE nur410_class_students SET course_name=?
                               WHERE course_name=?""",
                            (desired_label, course_name),
                        )
                    course_name = desired_label
        counts = db.execute(
            """SELECT COUNT(*) AS target_count,
                      COALESCE(SUM(requirement),0) AS required_total
               FROM nur410_targets WHERE course_name=?""",
            (course_name,),
        ).fetchone()
        subjects.append({
            "subject_code": code,
            "subject_name": name,
            "course_name": course_name,
            "class_count": entry["class_count"],
            "target_count": int(counts["target_count"] or 0),
            "required_total": int(round(float(counts["required_total"] or 0))),
        })
    return subjects


def clinical_course_catalog(db):
    """Subject catalog rows ordered by code, with target counts."""
    return db.execute(
        """SELECT c.course_id,c.course_name,
                  COALESCE(NULLIF(trim(c.subject_code),''),c.course_name)
                      AS subject_code,
                  COALESCE(NULLIF(trim(c.subject_name),''),c.course_name)
                      AS subject_name,
                  (SELECT COUNT(*) FROM nur410_targets t
                    WHERE t.course_name=c.course_name) AS target_count,
                  (SELECT COALESCE(SUM(t.requirement),0) FROM nur410_targets t
                    WHERE t.course_name=c.course_name) AS required_total
           FROM nur410_courses c
           ORDER BY c.subject_code COLLATE NOCASE,c.course_name COLLATE NOCASE"""
    ).fetchall()


def _is_emergency_department(value):
    normalized = re.sub(r"[^a-z0-9]+", " ", str(value or "").strip().lower())
    normalized = " ".join(normalized.split())
    return normalized in {
        "emergency", "emergency dept", "emergency department",
        "ed", "cap cuu", "khoa cap cuu",
    }


def _xlsx_column_index(cell_reference):
    letters = "".join(
        character for character in str(cell_reference or "")
        if character.isalpha()
    ).upper()
    value = 0
    for character in letters:
        value = value * 26 + ord(character) - 64
    return max(0, value - 1)


def _normalized_import_header(value):
    text = unicodedata.normalize("NFKD", str(value or ""))
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    return " ".join(re.sub(r"[^a-zA-Z0-9]+", " ", text).lower().split())


def parse_account_import_xlsx(file_bytes):
    """Read the first worksheet of a normal .xlsx file using stdlib only."""
    if not file_bytes:
        raise ValueError("Select an Excel .xlsx file.")
    try:
        archive = zipfile.ZipFile(io.BytesIO(file_bytes))
    except (zipfile.BadZipFile, OSError) as exc:
        raise ValueError("The selected file is not a valid .xlsx workbook.") from exc
    with archive:
        archive_entries = archive.infolist()
        expanded_size = sum(max(0, int(info.file_size)) for info in archive_entries)
        if len(archive_entries) > 2000 or expanded_size > 64 * 1024 * 1024:
            raise ValueError(
                "The workbook expands beyond the safe processing limit."
            )
        names = set(archive.namelist())
        if "xl/workbook.xml" not in names:
            raise ValueError("The workbook does not contain an Excel worksheet.")
        shared_strings = []
        if "xl/sharedStrings.xml" in names:
            root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
            for item in root.findall("{*}si"):
                shared_strings.append("".join(
                    node.text or "" for node in item.findall(".//{*}t")
                ))
        workbook = ET.fromstring(archive.read("xl/workbook.xml"))
        first_sheet = workbook.find(".//{*}sheet")
        if first_sheet is None:
            raise ValueError("The workbook has no worksheets.")
        relation_id = first_sheet.attrib.get(
            "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id",
            "",
        )
        sheet_path = "xl/worksheets/sheet1.xml"
        rels_path = "xl/_rels/workbook.xml.rels"
        if relation_id and rels_path in names:
            rels = ET.fromstring(archive.read(rels_path))
            for relation in rels.findall("{*}Relationship"):
                if relation.attrib.get("Id") != relation_id:
                    continue
                target = str(relation.attrib.get("Target", "") or "")
                sheet_path = (
                    target.lstrip("/")
                    if target.startswith("/xl/") else
                    "xl/" + target.lstrip("/")
                )
                break
        if sheet_path not in names:
            raise ValueError("The first worksheet cannot be read.")
        sheet = ET.fromstring(archive.read(sheet_path))
        rows = []
        for row in sheet.findall(".//{*}sheetData/{*}row"):
            values = {}
            for cell in row.findall("{*}c"):
                index = _xlsx_column_index(cell.attrib.get("r", ""))
                cell_type = cell.attrib.get("t", "")
                if cell_type == "inlineStr":
                    value = "".join(
                        node.text or "" for node in cell.findall(".//{*}t")
                    )
                else:
                    value_node = cell.find("{*}v")
                    value = value_node.text if value_node is not None else ""
                    if cell_type == "s" and str(value).isdigit():
                        position = int(value)
                        value = (
                            shared_strings[position]
                            if position < len(shared_strings) else ""
                        )
                values[index] = str(value or "").strip()
            if values:
                width = max(values) + 1
                rows.append([values.get(index, "") for index in range(width)])
        if not rows:
            raise ValueError("The workbook contains no account rows.")
        aliases = {
            "full_name": {"full name", "ho ten", "ho va ten", "name"},
            "birth_year": {"birth year", "year of birth", "nam sinh"},
            "account_id": {"id", "account id", "student id", "staff id", "ma"},
            "password": {"password", "mat khau", "default password"},
        }
        normalized_headers = [
            _normalized_import_header(value) for value in rows[0]
        ]
        positions = {}
        for field, choices in aliases.items():
            for index, header in enumerate(normalized_headers):
                if header in choices:
                    positions[field] = index
                    break
        required = ("full_name", "birth_year", "account_id")
        if any(field not in positions for field in required):
            raise ValueError(
                "The first row must contain Full name, Birth year and ID."
            )
        records = []
        for row_number, row in enumerate(rows[1:], start=2):
            def cell(field):
                index = positions.get(field, -1)
                return row[index].strip() if 0 <= index < len(row) else ""
            if not any(cell(field) for field in required):
                continue
            records.append({
                "row_number": row_number,
                "full_name": cell("full_name"),
                "birth_year": cell("birth_year"),
                "account_id": cell("account_id"),
                "password": cell("password") or "123456",
            })
        if not records:
            raise ValueError("The workbook has no populated account rows.")
        return records


def _split_clinical_datetime(value, fallback=None):
    """Return an HTML/desktop friendly date and time pair."""
    text = str(value or "").strip()
    fallback_text = str(fallback or "").strip()
    for candidate in (text, fallback_text):
        if not candidate:
            continue
        normalized = candidate.replace("T", " ")
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
                    "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M"):
            try:
                parsed = datetime.strptime(normalized, fmt)
                return parsed.strftime("%Y-%m-%d"), parsed.strftime("%H:%M:%S")
            except ValueError:
                continue
    now = datetime.now()
    return now.strftime("%Y-%m-%d"), now.strftime("%H:%M:%S")


def _normalized_section_datetimes(raw, care_datetime):
    """Backfill per-section timestamps for records created by older versions."""
    source = raw if isinstance(raw, dict) else {}
    care_date, care_time = _split_clinical_datetime(
        source.get("care_time", ""), care_datetime
    )
    care_text = care_date + " " + care_time
    normalized = {"care_time": care_text}
    for key in NURSING_SECTION_KEYS[1:]:
        date_text, time_text = _split_clinical_datetime(source.get(key, ""), care_text)
        normalized[key] = date_text + " " + time_text
    return normalized


def _sanitized_review_data(value):
    """Remove common direct identifiers before sending clinical work for AI review."""
    sensitive_keys = {
        "patient_id", "patient_name", "student_username", "student_code", "student_name",
        "nurse_code", "nurse_name", "username", "full_name", "entered_by",
        "entered_by_username", "dob", "date_of_birth", "address", "phone", "email",
    }
    if isinstance(value, dict):
        return {
            str(key): _sanitized_review_data(item)
            for key, item in value.items()
            if str(key).strip().lower() not in sensitive_keys
        }
    if isinstance(value, list):
        return [_sanitized_review_data(item) for item in value]
    return value


def _score_to_100(value, score_scale=100):
    if value is None or value == "":
        return None
    try:
        scale = int(score_scale or 10)
    except (TypeError, ValueError):
        scale = 10
    numeric = float(value)
    return max(0.0, min(100.0, numeric * 10.0 if scale == 10 else numeric))


def _section_scores_to_100(sections, score_scale=100):
    converted = {}
    for key, item in (sections or {}).items():
        if not isinstance(item, dict):
            continue
        score = _score_to_100(item.get("score"), score_scale)
        converted[key] = {
            "score": score,
            "comment": str(item.get("comment", "") or ""),
        }
    return converted


def _nursing_review_score(section_reviews, fallback=None):
    scores = []
    for key in NURSING_REVIEW_SECTION_KEYS:
        item = (section_reviews or {}).get(key, {})
        score = item.get("score") if isinstance(item, dict) else None
        if score is None:
            return fallback
        scores.append(float(score))
    return round(sum(scores) / float(len(scores)), 1) if scores else fallback


def _decoded_json(raw, default):
    try:
        value = json.loads(raw or "")
        return value if isinstance(value, type(default)) else default
    except (TypeError, ValueError):
        return default


def _progression_text_list(value):
    if isinstance(value, (list, tuple)):
        source_values = value
    else:
        source_values = str(value or "").splitlines()
    result = []
    seen = set()
    for raw_value in source_values:
        text = " ".join(str(raw_value or "").split()).strip()
        if not text:
            continue
        folded = text.casefold()
        if folded in seen:
            continue
        seen.add(folded)
        result.append(text)
    return result


_PROGRESSION_DIAGNOSIS_PREFIX_RE = re.compile(r"^\[(\d+)\]\s*(.*)$")

# Written into a Heading 5 line whose Heading 3/4 partner has not been
# evaluated yet, so the "[N]" evaluation lines stay aligned one-for-one
# with the goals/interventions they belong to.
NOT_YET_EVALUATED_PLACEHOLDER = "(chưa lượng giá)"


def _progression_leaf(value, evaluation=None):
    """Normalize one Heading 3/4 leaf (a goal or an intervention) into
    ``{"text": ..., "evaluation": ...}``, its own Heading 5 evaluation."""
    if isinstance(value, dict):
        text = " ".join(
            str(value.get("text", value.get("value", "")) or "").split()
        ).strip()
        eval_text = " ".join(str(value.get("evaluation", "") or "").split()).strip()
        source = str(value.get("source", "") or "").strip()
    else:
        text = " ".join(str(value or "").split()).strip()
        eval_text = " ".join(str(evaluation or "").split()).strip()
        source = ""
    if not text:
        return None
    leaf = {"text": text, "evaluation": eval_text}
    if source:
        leaf["source"] = source
    return leaf


def _normalized_leaf_list(raw_list, evaluations=None):
    """Normalize a list of goal/intervention leaves. When raw_list holds
    plain strings (legacy/flat shape), pair each one positionally with the
    evaluation at the same index in the parallel evaluations list."""
    if not isinstance(raw_list, list):
        raw_list = []
    legacy_evaluations = evaluations if isinstance(evaluations, list) else []
    result = []
    seen = set()
    for index, raw_value in enumerate(raw_list):
        legacy_eval = legacy_evaluations[index] if index < len(legacy_evaluations) else ""
        leaf = _progression_leaf(raw_value, legacy_eval)
        if not leaf:
            continue
        folded = leaf["text"].casefold()
        if folded in seen:
            continue
        seen.add(folded)
        result.append(leaf)
    return result


def _normalized_diagnosis_entry(raw_diagnosis, causes=None, goals=None,
                                 interventions=None, goal_evaluations=None,
                                 intervention_evaluations=None):
    """Normalize one Heading 2 node: a nursing diagnosis together with its
    own Heading 2b causes, Heading 3 goals and Heading 4 interventions
    (each goal/intervention already carrying its Heading 5 evaluation)."""
    source = ""
    priority = None
    if isinstance(raw_diagnosis, dict):
        text = " ".join(str(
            raw_diagnosis.get("diagnosis", raw_diagnosis.get("text", "")) or ""
        ).split()).strip()
        causes = raw_diagnosis.get("causes", causes)
        goals = raw_diagnosis.get("goals", goals)
        interventions = raw_diagnosis.get("interventions", interventions)
        goal_evaluations = raw_diagnosis.get("goal_evaluations", goal_evaluations)
        intervention_evaluations = raw_diagnosis.get(
            "intervention_evaluations", intervention_evaluations
        )
        source = str(raw_diagnosis.get("source", "") or "").strip()
        priority = raw_diagnosis.get("priority", None)
    else:
        text = " ".join(str(raw_diagnosis or "").split()).strip()
    normalized_causes = _progression_text_list(causes or [])
    normalized_goals = _normalized_leaf_list(goals or [], goal_evaluations)
    normalized_interventions = _normalized_leaf_list(
        interventions or [], intervention_evaluations
    )
    if not (text or normalized_causes or normalized_goals or normalized_interventions):
        return None
    entry = {
        "diagnosis": text,
        "causes": normalized_causes,
        "goals": normalized_goals,
        "interventions": normalized_interventions,
    }
    if source:
        entry["source"] = source
    if priority is not None:
        try:
            entry["priority"] = int(priority)
        except (TypeError, ValueError):
            pass
    return entry


def _split_diagnosis_prefixed_lines(lines, diagnosis_count):
    """Split flat ``"[N] text"`` lines (the web/legacy textarea convention
    for linking Heading 2b/3/4/5 text to the Nth Heading-2 diagnosis, by
    1-based position) into per-diagnosis buckets. Lines without a
    recognized ``[N]`` prefix are attached to the first diagnosis so no
    previously captured clinical text is ever silently dropped."""
    buckets = {index: [] for index in range(1, diagnosis_count + 1)}
    unattached = []
    for raw_line in lines or []:
        line = str(raw_line or "").strip()
        if not line:
            continue
        match = _PROGRESSION_DIAGNOSIS_PREFIX_RE.match(line)
        if match:
            number = int(match.group(1))
            text = match.group(2).strip()
            if text and 1 <= number <= diagnosis_count:
                buckets[number].append(text)
            elif text:
                unattached.append(text)
            continue
        unattached.append(line)
    if diagnosis_count and unattached:
        buckets[1].extend(unattached)
        unattached = []
    return buckets, unattached


def _normalized_nursing_progression(value):
    """Normalize the shared Problem -> Diagnosis -> Goal/Intervention map.

    Each pathway (one "sơ đồ vấn đề" node) is::

        {
            "problems": ["..."],
            "diagnoses": [
                {
                    "diagnosis": "...",
                    "causes": ["..."],
                    "goals": [{"text": "...", "evaluation": "..."}],
                    "interventions": [{"text": "...", "evaluation": "..."}],
                },
                ...
            ],
        }

    so every diagnosis carries its own list of measurable goals and its
    own list of interventions, and every goal/intervention carries its
    own Heading-5 evaluation. Pathways saved by earlier releases (and the
    Web form, which still submits flat, parallel per-heading text lists)
    used flat lists with no link between a diagnosis and its own
    goals/interventions; those are migrated here on read, matching every
    ``"[N] text"`` line to the Nth diagnosis by position, so no previously
    captured clinical text is lost.
    """
    if not isinstance(value, list):
        return []
    result = []
    for raw_pathway in value:
        if not isinstance(raw_pathway, dict):
            continue
        problems = _progression_text_list(raw_pathway.get("problems", []))
        # Pathway-level like "problems": one Procedure Implementation list per
        # care record, because a technique is performed once at one time even
        # when it serves several nursing diagnoses.
        procedures = _progression_text_list(raw_pathway.get("procedures", []))
        raw_diagnoses = raw_pathway.get("diagnoses", [])
        diagnoses = []
        already_nested = bool(raw_diagnoses) and all(
            isinstance(item, dict)
            and ("diagnosis" in item or "goals" in item or "interventions" in item)
            for item in raw_diagnoses
        )
        if already_nested:
            for raw_diagnosis in raw_diagnoses:
                entry = _normalized_diagnosis_entry(raw_diagnosis)
                if entry:
                    diagnoses.append(entry)
        else:
            legacy_diagnoses = _progression_text_list(raw_diagnoses)
            diagnosis_count = len(legacy_diagnoses)
            cause_buckets, _ = _split_diagnosis_prefixed_lines(
                raw_pathway.get("causes", []), diagnosis_count
            )
            goal_buckets, _ = _split_diagnosis_prefixed_lines(
                raw_pathway.get("goals", []), diagnosis_count
            )
            interv_buckets, _ = _split_diagnosis_prefixed_lines(
                raw_pathway.get("interventions", []), diagnosis_count
            )
            goal_eval_buckets, _ = _split_diagnosis_prefixed_lines(
                raw_pathway.get("goal_evaluations", []), diagnosis_count
            )
            interv_eval_buckets, _ = _split_diagnosis_prefixed_lines(
                raw_pathway.get("intervention_evaluations", []), diagnosis_count
            )
            if legacy_diagnoses:
                for index, diagnosis_text in enumerate(legacy_diagnoses, start=1):
                    entry = _normalized_diagnosis_entry(
                        diagnosis_text,
                        causes=cause_buckets.get(index, []),
                        goals=goal_buckets.get(index, []),
                        interventions=interv_buckets.get(index, []),
                        goal_evaluations=goal_eval_buckets.get(index, []),
                        intervention_evaluations=interv_eval_buckets.get(index, []),
                    )
                    if entry:
                        diagnoses.append(entry)
            else:
                # No diagnosis text was captured; keep any goals/interventions
                # that were entered anyway under a single unnamed diagnosis.
                entry = _normalized_diagnosis_entry(
                    "",
                    causes=raw_pathway.get("causes", []),
                    goals=raw_pathway.get("goals", []),
                    interventions=raw_pathway.get("interventions", []),
                    goal_evaluations=raw_pathway.get("goal_evaluations", []),
                    intervention_evaluations=raw_pathway.get(
                        "intervention_evaluations", []
                    ),
                )
                if entry:
                    diagnoses.append(entry)
        if problems or diagnoses or procedures:
            result.append({
                "problems": problems, "diagnoses": diagnoses,
                "procedures": procedures,
            })
    return result


def _flatten_nursing_progression_for_form(pathway):
    """Flatten one nested pathway back into the classic flat, per-heading
    text lists the Web textarea form (and any legacy export) uses, linking
    every cause/goal/intervention/evaluation back to its diagnosis with a
    leading ``"[N]"`` matching that diagnosis's 1-based position, so the
    Web form and the Desktop map editor stay in sync."""
    diagnoses = pathway.get("diagnoses", []) if isinstance(pathway, dict) else []
    flat = {
        "problems": list(pathway.get("problems", [])) if isinstance(pathway, dict) else [],
        "procedures": list(pathway.get("procedures", [])) if isinstance(pathway, dict) else [],
        "diagnoses": [], "causes": [], "goals": [], "interventions": [],
        "goal_evaluations": [], "intervention_evaluations": [],
    }
    for index, diagnosis in enumerate(diagnoses, start=1):
        flat["diagnoses"].append(diagnosis.get("diagnosis", ""))
        prefix = "[%d] " % index
        for cause in diagnosis.get("causes", []):
            flat["causes"].append(prefix + cause)
        goals = list(diagnosis.get("goals", []))
        interventions = list(diagnosis.get("interventions", []))
        # Heading 5 lines are matched back to their Heading 3/4 line by
        # position inside the same "[N]" bucket, so once any goal (or any
        # intervention) of this diagnosis has been evaluated, every one of
        # them must emit a line -- otherwise a blank evaluation would shift
        # all the following evaluations onto the wrong goal/intervention.
        goals_evaluated = any(goal.get("evaluation") for goal in goals)
        interventions_evaluated = any(
            item.get("evaluation") for item in interventions
        )
        for goal in goals:
            flat["goals"].append(prefix + goal.get("text", ""))
            if goals_evaluated:
                flat["goal_evaluations"].append(
                    prefix + (
                        goal.get("evaluation")
                        or NOT_YET_EVALUATED_PLACEHOLDER
                    )
                )
        for intervention in interventions:
            flat["interventions"].append(prefix + intervention.get("text", ""))
            if interventions_evaluated:
                flat["intervention_evaluations"].append(
                    prefix + (
                        intervention.get("evaluation")
                        or NOT_YET_EVALUATED_PLACEHOLDER
                    )
                )
    return flat


# "Giống / Khác / Một phần" - whether the textbook picture and this
# patient's real presentation agree. Anything else is stored verbatim so a
# nurse writing in English is never silently overwritten.
CLINICAL_SUPPORT_VERDICTS = ("Giống", "Một phần", "Khác")

# Hai nhóm y lệnh tạo nên phần "Cận lâm sàng" của Hỗ trợ lâm sàng.
PARACLINICAL_CATEGORIES = ("Laboratory", "Imaging")
PARACLINICAL_CATEGORY_LABELS = {
    "Laboratory": "Xét nghiệm",
    "Imaging": "Chẩn đoán hình ảnh",
}
PARACLINICAL_FIELDS = (
    ("test", "Tên xét nghiệm / chẩn đoán hình ảnh (theo y lệnh)"),
    ("purpose", "Mục đích / ý nghĩa lâm sàng"),
    ("result", "Kết quả trên người bệnh"),
    ("nursing_note", "Nhận định và theo dõi điều dưỡng"),
)


def _split_ordered_medications(text):
    """One medication order per line of the Medication order summary.

    Unlike a diagnosis list, a medication line legitimately contains "/"
    and "+" ("1g / TM / 2 times/day"), so only line breaks separate the
    drugs. The leading "Order [n]" marker and any trailing execution-state
    note in brackets are stripped, leaving the drug as ordered."""
    drugs = []
    seen = set()
    for line in str(text or "").splitlines():
        cleaned = re.sub(r"^\s*(?:Order\s*\[\d+\]|[-*\u2022])\s*", "", line)
        cleaned = re.sub(r"\s*\((?:pending|last)[^)]*\)\s*$", "", cleaned)
        cleaned = " ".join(cleaned.split())
        if not cleaned:
            continue
        folded = cleaned.casefold()
        if folded in seen:
            continue
        seen.add(folded)
        drugs.append(cleaned)
    return drugs


def _split_medical_diagnoses(text):
    """One medical-diagnosis field can hold several diseases. Split it on
    the separators nurses actually use (new line, semicolon, slash, comma
    or a numbered list) so each disease gets its own pathophysiology
    block."""
    raw = str(text or "")
    for separator in (";", "/", "|", "+"):
        raw = raw.replace(separator, "\n")
    diseases = []
    seen = set()
    for line in raw.splitlines():
        cleaned = re.sub(r"^\s*[-*\u2022]?\s*\d*[.)]?\s*", "", line).strip()
        cleaned = " ".join(cleaned.split())
        if not cleaned:
            continue
        folded = cleaned.casefold()
        if folded in seen:
            continue
        seen.add(folded)
        diseases.append(cleaned)
    return diseases


def _normalized_clinical_support(value):
    """Normalize the Clinical Support block: one pathophysiology entry per
    diagnosed disease, plus the theory-versus-bedside comparison rows.

        {
            "pathophysiology": [
                {"disease": "...", "mechanism": "...", "presentation": "..."},
            ],
            "comparisons": [
                {"topic": "...", "theory": "...", "practice": "...",
                 "verdict": "Giống|Một phần|Khác", "explanation": "..."},
            ],
            "medications": [
                {"drug": "...", "main_effect": "...",
                 "side_effects": "...", "nursing_monitoring": "..."},
            ],
            "paraclinical": [
                {"test": "...", "category": "Laboratory|Imaging",
                 "purpose": "...", "result": "...",
                 "nursing_note": "..."},
            ],
            "note": "...",
        }

    Khối "medications" và "paraclinical" luôn được đồng bộ lại từ y lệnh
    của người bệnh (xem merge_clinical_support_orders): thuốc lấy từ y lệnh
    thuốc, cận lâm sàng lấy từ y lệnh Xét nghiệm và Chẩn đoán hình ảnh.
    """
    source = value if isinstance(value, dict) else {}

    def clean(raw):
        return " ".join(str(raw or "").split())

    def clean_block(raw):
        return "\n".join(
            " ".join(line.split())
            for line in str(raw or "").splitlines()
            if line.strip()
        )

    pathophysiology = []
    raw_pathophysiology = source.get("pathophysiology", [])
    if isinstance(raw_pathophysiology, list):
        for raw_entry in raw_pathophysiology:
            entry = raw_entry if isinstance(raw_entry, dict) else {
                "disease": raw_entry
            }
            record = {
                "disease": clean(entry.get("disease", "")),
                "mechanism": clean_block(
                    entry.get("mechanism", entry.get("pathophysiology", ""))
                ),
                "presentation": clean_block(
                    entry.get("presentation", entry.get("clinical_link", ""))
                ),
            }
            if any(record.values()):
                pathophysiology.append(record)

    comparisons = []
    raw_comparisons = source.get("comparisons", [])
    if isinstance(raw_comparisons, list):
        for raw_entry in raw_comparisons:
            if not isinstance(raw_entry, dict):
                continue
            verdict = clean(raw_entry.get("verdict", ""))
            record = {
                "topic": clean(raw_entry.get("topic", "")),
                "theory": clean_block(raw_entry.get("theory", "")),
                "practice": clean_block(raw_entry.get("practice", "")),
                "verdict": verdict,
                "explanation": clean_block(raw_entry.get("explanation", "")),
            }
            if any(record.values()):
                comparisons.append(record)

    # Thuốc điều trị: one row per drug the patient is actually on, with its
    # therapeutic action, the adverse effects to expect, and what the nurse
    # must monitor because of it.
    medications = []
    raw_medications = source.get("medications", [])
    if isinstance(raw_medications, list):
        for raw_entry in raw_medications:
            entry = raw_entry if isinstance(raw_entry, dict) else {
                "drug": raw_entry
            }
            record = {
                "drug": clean(entry.get("drug", entry.get("name", ""))),
                "main_effect": clean_block(
                    entry.get("main_effect", entry.get("action", ""))
                ),
                "side_effects": clean_block(
                    entry.get("side_effects", entry.get("side_effect", ""))
                ),
                "nursing_monitoring": clean_block(
                    entry.get(
                        "nursing_monitoring", entry.get("monitoring", "")
                    )
                ),
            }
            if any(record.values()):
                medications.append(record)

    # Cận lâm sàng: mỗi dòng là một xét nghiệm hoặc một chỉ định chẩn đoán
    # hình ảnh đã có y lệnh, kèm mục đích, kết quả trên người bệnh và nhận
    # định/theo dõi của điều dưỡng.
    paraclinical = []
    raw_paraclinical = source.get(
        "paraclinical", source.get("investigations", [])
    )
    if isinstance(raw_paraclinical, list):
        for raw_entry in raw_paraclinical:
            entry = raw_entry if isinstance(raw_entry, dict) else {
                "test": raw_entry
            }
            category = clean(entry.get("category", entry.get("type", "")))
            if category not in PARACLINICAL_CATEGORIES:
                category = ""
            record = {
                "test": clean(entry.get("test", entry.get("name", ""))),
                "category": category,
                "purpose": clean_block(
                    entry.get("purpose", entry.get("indication", ""))
                ),
                "result": clean_block(
                    entry.get("result", entry.get("finding", ""))
                ),
                "nursing_note": clean_block(
                    entry.get(
                        "nursing_note", entry.get("nursing_monitoring", "")
                    )
                ),
            }
            if any(value for key, value in record.items()
                   if key != "category") or record["test"]:
                paraclinical.append(record)

    return {
        "pathophysiology": pathophysiology,
        "comparisons": comparisons,
        "medications": medications,
        "paraclinical": paraclinical,
        "note": clean_block(source.get("note", "")),
    }


def _ordered_item_key(text):
    """Khóa so khớp một dòng y lệnh: phần tên đứng trước dấu "|"."""
    head = str(text or "").split("|", 1)[0]
    return " ".join(head.split()).casefold()


def _recorded_result_for(test_text, result_summary):
    """Kết quả đã ghi nhận của một xét nghiệm/CĐHA, lấy từ bảng kết quả.

    Dòng tóm tắt có dạng "<ngày giờ> | <Loại> <Tên>: <giá trị>", nên chỉ
    cần đối chiếu tên chỉ định là ghép được kết quả vào đúng dòng.
    """
    name = _ordered_item_key(test_text)
    if not name:
        return ""
    matched = []
    for line in str(result_summary or "").splitlines():
        clean_line = " ".join(line.split())
        if clean_line and name in clean_line.casefold():
            matched.append(clean_line)
    return "\n".join(matched)


def merge_clinical_support_orders(support, order_summaries=None,
                                  result_summary=""):
    """Đồng bộ Hỗ trợ lâm sàng với y lệnh hiện hành của người bệnh.

    - Thuốc điều trị: mỗi y lệnh thuốc là một dòng; y lệnh mới được thêm
      vào cuối, nội dung điều dưỡng đã ghi không bị đụng tới.
    - Cận lâm sàng: mỗi y lệnh Xét nghiệm / Chẩn đoán hình ảnh là một dòng;
      ô "Kết quả trên người bệnh" tự điền từ kết quả đã ghi nhận khi điều
      dưỡng chưa nhập tay.

    Nhờ vậy y lệnh thêm sau vẫn hiện ra, chứ không chỉ điền một lần lúc
    tạo phiếu.
    """
    normalized = _normalized_clinical_support(support)
    summaries = order_summaries if isinstance(order_summaries, dict) else {}

    medications = list(normalized["medications"])
    seen_drugs = {
        _ordered_item_key(row["drug"]) for row in medications if row["drug"]
    }
    for drug in _split_ordered_medications(summaries.get("Medication", "")):
        key = _ordered_item_key(drug)
        if not key or key in seen_drugs:
            continue
        seen_drugs.add(key)
        medications.append({
            "drug": drug, "main_effect": "", "side_effects": "",
            "nursing_monitoring": "",
        })
    normalized["medications"] = medications

    paraclinical = list(normalized["paraclinical"])
    seen_tests = {
        _ordered_item_key(row["test"]) for row in paraclinical if row["test"]
    }
    for category in PARACLINICAL_CATEGORIES:
        for test in _split_ordered_medications(summaries.get(category, "")):
            key = _ordered_item_key(test)
            if not key or key in seen_tests:
                continue
            seen_tests.add(key)
            paraclinical.append({
                "test": test, "category": category, "purpose": "",
                "result": "", "nursing_note": "",
            })
    if result_summary:
        for row in paraclinical:
            if row["result"]:
                continue
            row["result"] = _recorded_result_for(row["test"], result_summary)
    normalized["paraclinical"] = paraclinical
    return normalized


def _patient_age(date_of_birth):
    text = str(date_of_birth or "").strip()
    for pattern in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y"):
        try:
            born = datetime.strptime(text[:10], pattern).date()
            today = datetime.now().date()
            return today.year - born.year - ((today.month, today.day) < (born.month, born.day))
        except ValueError:
            continue
    return ""


def _calculate_bmi(height_cm, weight_kg):
    """Return BMI with two decimals when height (cm) and weight (kg) are valid."""
    height_text = str(height_cm or "").strip().replace(",", ".")
    weight_text = str(weight_kg or "").strip().replace(",", ".")
    if not height_text or not weight_text:
        return ""
    try:
        height = float(height_text)
        weight = float(weight_text)
    except (TypeError, ValueError):
        return ""
    if not math.isfinite(height) or not math.isfinite(weight):
        return ""
    if height <= 0 or weight <= 0:
        return ""
    return "%.2f" % (weight / ((height / 100.0) ** 2))


def _clinical_datetime_value(value):
    text = str(value or "").strip().replace("T", " ")
    for pattern in (
        "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
        "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M",
    ):
        try:
            return datetime.strptime(text, pattern)
        except ValueError:
            continue
    return None


def _triage_review_summary(entry):
    """Return a readable, complete Triage summary for Student Preview."""
    if not isinstance(entry, dict):
        return "No linked Triage record is available for this Nursing Care entry."
    data = entry.get("triage", {})
    if not isinstance(data, dict):
        data = {}
    quick = data.get("quick_assessment", {})
    vitals = data.get("vital_signs", {})
    abcde = data.get("abcde", {})
    if not isinstance(quick, dict):
        quick = {}
    if not isinstance(vitals, dict):
        vitals = {}
    if not isinstance(abcde, dict):
        abcde = {}
    lines = [
        "Triage date/time: " + str(entry.get("triage_datetime", "") or ""),
        "Attribution: " + (
            "Documented by the selected student"
            if entry.get("is_selected_student_triage")
            else "Closest patient Triage record; student attribution not confirmed"
        ),
        "System: " + str(data.get("system", "") or ""),
        "Level/category: %s - %s (%s), target %s minute(s)" % (
            data.get("level", ""), data.get("category", ""),
            data.get("color", ""), data.get("target_minutes", ""),
        ),
        "Chief complaint: " + str(data.get("chief_complaint", "") or ""),
        "Arrival mode: " + str(data.get("arrival_mode", "") or ""),
        "Look: " + str(quick.get("look", "") or ""),
        "Listen: " + str(quick.get("listen", "") or ""),
        "Smell: " + str(quick.get("smell", "") or ""),
        "Vital signs: " + ", ".join(
            "%s=%s" % (key, value)
            for key, value in vitals.items() if str(value or "").strip()
        ),
    ]
    for key, label in TRIAGE_ABCDE_FIELDS:
        item = abcde.get(key, {})
        if not isinstance(item, dict):
            item = {}
        lines.append("%s: %s%s" % (
            label,
            str(item.get("status", "") or ""),
            (" - " + str(item.get("note", "") or ""))
            if str(item.get("note", "") or "").strip() else "",
        ))
    lines.extend((
        "Classification reason/discriminator: "
        + str(data.get("classification_reason", "") or ""),
        "Immediate action, disposition and reassessment plan: "
        + str(data.get("immediate_action", "") or ""),
    ))
    return "\n".join(lines)


def _patient_report_date_range(period, date_from="", date_to=""):
    """Normalize the Today, all-days, or custom report range."""
    period = str(period or "today").strip().lower()
    today = datetime.now().strftime("%Y-%m-%d")
    if period == "all":
        return "", "", "All treatment dates"
    if period == "today":
        return today, today, "Current date: " + today
    if period != "range":
        raise ValueError("Select Current date, Date range, or All treatment dates.")
    start = str(date_from or "").strip()
    end = str(date_to or "").strip()
    try:
        start_date = datetime.strptime(start, "%Y-%m-%d").date()
        end_date = datetime.strptime(end, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("Use YYYY-MM-DD for the report date range.")
    if end_date < start_date:
        raise ValueError("Report end date cannot be earlier than start date.")
    return start, end, "%s to %s" % (start, end)


STUDENT_REVIEW_REPORT_SECTIONS = (
    ("nursing_care", "Nursing Care"),
    ("skill_practice", "Skill Practice"),
    ("clinical_targets", "Clinical Targets"),
)


def _ensure_table_column(connection, table_name, column_name, column_sql):
    """Add one SQLite column when upgrading an older shared database."""
    columns = {
        str(row[1]) for row in connection.execute(
            "PRAGMA table_info(%s)" % table_name
        ).fetchall()
    }
    if column_name not in columns:
        connection.execute(
            "ALTER TABLE %s ADD COLUMN %s %s"
            % (table_name, column_name, column_sql)
        )


def ensure_exam_schema(connection):
    """Create the patient-based group examination workspace.

    The legacy exam tables are intentionally left intact so an upgrade never
    destroys historical data.  New code uses exam_groups,
    exam_group_members, exam_patient_groups and exam_attempts, while the
    clinical work itself remains in nursing_care.
    """
    for column_name, column_sql in (
        ("created_by_username", "TEXT DEFAULT ''"),
        ("created_by_role", "TEXT DEFAULT ''"),
        ("is_exam", "INTEGER DEFAULT 0"),
        ("exam_summary", "TEXT DEFAULT ''"),
        ("exam_question", "TEXT DEFAULT ''"),
    ):
        _ensure_table_column(
            connection, "patients", column_name, column_sql
        )
    _ensure_table_column(
        connection, "nursing_care", "exam_attempt_id", "INTEGER"
    )

    connection.execute("""CREATE TABLE IF NOT EXISTS exam_groups (
        group_id INTEGER PRIMARY KEY AUTOINCREMENT,
        group_name TEXT NOT NULL COLLATE NOCASE UNIQUE,
        description TEXT DEFAULT '',
        active INTEGER DEFAULT 1,
        created_by_username TEXT DEFAULT '',
        created_by_name TEXT DEFAULT '',
        created_dt TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_group_members (
        group_id INTEGER NOT NULL,
        username TEXT NOT NULL,
        assigned_dt TEXT DEFAULT '',
        assigned_by_username TEXT DEFAULT '',
        PRIMARY KEY(group_id,username),
        FOREIGN KEY(group_id) REFERENCES exam_groups(group_id),
        FOREIGN KEY(username) REFERENCES users(username)
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_exam_group_member_user
        ON exam_group_members(username,group_id)""")
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_patient_groups (
        exam_patient_group_id INTEGER PRIMARY KEY AUTOINCREMENT,
        patient_id TEXT NOT NULL,
        group_id INTEGER NOT NULL,
        active INTEGER DEFAULT 1,
        assigned_dt TEXT DEFAULT '',
        assigned_by_username TEXT DEFAULT '',
        assigned_by_name TEXT DEFAULT '',
        UNIQUE(patient_id,group_id),
        FOREIGN KEY(patient_id) REFERENCES patients(id),
        FOREIGN KEY(group_id) REFERENCES exam_groups(group_id)
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_exam_patient_group
        ON exam_patient_groups(patient_id,group_id,active)""")
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_attempts (
        attempt_id INTEGER PRIMARY KEY AUTOINCREMENT,
        exam_patient_group_id INTEGER NOT NULL,
        patient_id TEXT NOT NULL,
        group_id INTEGER NOT NULL,
        examinee_username TEXT NOT NULL,
        status TEXT DEFAULT 'Assigned',
        assigned_dt TEXT DEFAULT '',
        started_dt TEXT DEFAULT '',
        submitted_dt TEXT DEFAULT '',
        nursing_score REAL,
        nursing_section_reviews TEXT DEFAULT '{}',
        nursing_comment TEXT DEFAULT '',
        skill_score REAL,
        skill_comment TEXT DEFAULT '',
        total_score REAL,
        graded_by_username TEXT DEFAULT '',
        graded_by_name TEXT DEFAULT '',
        graded_dt TEXT DEFAULT '',
        UNIQUE(exam_patient_group_id,examinee_username),
        FOREIGN KEY(exam_patient_group_id)
            REFERENCES exam_patient_groups(exam_patient_group_id),
        FOREIGN KEY(patient_id) REFERENCES patients(id),
        FOREIGN KEY(group_id) REFERENCES exam_groups(group_id),
        FOREIGN KEY(examinee_username) REFERENCES users(username)
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_exam_attempt_user
        ON exam_attempts(examinee_username,status,attempt_id)""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_exam_attempt_patient
        ON exam_attempts(patient_id,group_id,attempt_id)""")

    # Keep the former tables readable for historical databases.  They are no
    # longer linked from either the desktop or web Exam interface.
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_settings (
        setting_key TEXT PRIMARY KEY,
        setting_value TEXT DEFAULT ''
    )""")
    connection.execute("""INSERT OR IGNORE INTO exam_settings(
        setting_key,setting_value
    ) VALUES('exam_mode_enabled','0')""")
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_cases (
        case_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_code TEXT NOT NULL COLLATE NOCASE UNIQUE,
        title TEXT NOT NULL,
        summary TEXT DEFAULT '',
        question_text TEXT DEFAULT '',
        reference_patient_json TEXT DEFAULT '{}',
        active INTEGER DEFAULT 1,
        created_by_username TEXT DEFAULT '',
        created_by_name TEXT DEFAULT '',
        created_dt TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_skills (
        skill_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL,
        skill_order INTEGER DEFAULT 0,
        skill_name TEXT NOT NULL,
        max_score REAL DEFAULT 10,
        FOREIGN KEY(case_id) REFERENCES exam_cases(case_id)
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_exam_skills_case
        ON exam_skills(case_id,skill_order,skill_id)""")
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_assignments (
        assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL,
        student_username TEXT NOT NULL,
        assigned_dt TEXT DEFAULT '',
        assigned_by_username TEXT DEFAULT '',
        assigned_by_name TEXT DEFAULT '',
        status TEXT DEFAULT 'Assigned',
        started_dt TEXT DEFAULT '',
        submitted_dt TEXT DEFAULT '',
        answer_patient_json TEXT DEFAULT '{}',
        student_note TEXT DEFAULT '',
        score REAL,
        total_score REAL,
        instructor_comment TEXT DEFAULT '',
        graded_by_username TEXT DEFAULT '',
        graded_by_name TEXT DEFAULT '',
        graded_dt TEXT DEFAULT '',
        UNIQUE(case_id,student_username),
        FOREIGN KEY(case_id) REFERENCES exam_cases(case_id)
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_exam_assignment_student
        ON exam_assignments(student_username,status,assignment_id)""")
    connection.execute("""CREATE TABLE IF NOT EXISTS exam_skill_scores (
        assignment_id INTEGER NOT NULL,
        skill_id INTEGER NOT NULL,
        score REAL DEFAULT 0,
        comment TEXT DEFAULT '',
        PRIMARY KEY(assignment_id,skill_id),
        FOREIGN KEY(assignment_id)
            REFERENCES exam_assignments(assignment_id),
        FOREIGN KEY(skill_id) REFERENCES exam_skills(skill_id)
    )""")

    # OSCE is kept inside the Exam module but uses a dedicated, auditable
    # structure: one Admin-created examination date, twenty fixed rooms,
    # one Nursing Technique and responsible instructor per room, and one
    # independent checklist result per student/room.
    connection.execute("""CREATE TABLE IF NOT EXISTS osce_exams (
        osce_exam_id INTEGER PRIMARY KEY AUTOINCREMENT,
        exam_name TEXT NOT NULL,
        exam_date TEXT NOT NULL,
        scale_max INTEGER NOT NULL DEFAULT 4 CHECK(scale_max IN (4,5)),
        active INTEGER NOT NULL DEFAULT 1,
        created_by_username TEXT DEFAULT '',
        created_by_name TEXT DEFAULT '',
        created_dt TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_osce_exam_date
        ON osce_exams(exam_date,osce_exam_id)""")
    connection.execute("""CREATE TABLE IF NOT EXISTS osce_rooms (
        room_id INTEGER PRIMARY KEY AUTOINCREMENT,
        room_number INTEGER NOT NULL UNIQUE CHECK(room_number BETWEEN 1 AND 20),
        room_name TEXT NOT NULL,
        camera_url TEXT DEFAULT '',
        microphone_url TEXT DEFAULT '',
        active INTEGER NOT NULL DEFAULT 1,
        updated_by_username TEXT DEFAULT '',
        updated_dt TEXT DEFAULT ''
    )""")
    now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    connection.executemany(
        """INSERT OR IGNORE INTO osce_rooms(
               room_number,room_name,active,updated_dt)
           VALUES(?,?,1,?)""",
        [
            (room_number, "OSCE Room %02d" % room_number, now_text)
            for room_number in range(1, 21)
        ],
    )
    connection.execute("""CREATE TABLE IF NOT EXISTS osce_exam_rooms (
        osce_exam_id INTEGER NOT NULL,
        room_id INTEGER NOT NULL,
        technique_id INTEGER NOT NULL,
        instructor_username TEXT NOT NULL,
        instructions TEXT DEFAULT '',
        active INTEGER NOT NULL DEFAULT 1,
        updated_by_username TEXT DEFAULT '',
        updated_dt TEXT DEFAULT '',
        PRIMARY KEY(osce_exam_id,room_id),
        FOREIGN KEY(osce_exam_id) REFERENCES osce_exams(osce_exam_id),
        FOREIGN KEY(room_id) REFERENCES osce_rooms(room_id),
        FOREIGN KEY(technique_id) REFERENCES nursing_techniques(technique_id),
        FOREIGN KEY(instructor_username) REFERENCES users(username)
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_osce_room_instructor
        ON osce_exam_rooms(instructor_username,osce_exam_id,room_id)""")
    connection.execute("""CREATE TABLE IF NOT EXISTS osce_assignments (
        assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
        osce_exam_id INTEGER NOT NULL,
        room_id INTEGER NOT NULL,
        student_username TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'Assigned',
        assigned_dt TEXT DEFAULT '',
        assigned_by_username TEXT DEFAULT '',
        overall_level REAL,
        overall_percent REAL,
        instructor_comment TEXT DEFAULT '',
        graded_by_username TEXT DEFAULT '',
        graded_by_name TEXT DEFAULT '',
        graded_dt TEXT DEFAULT '',
        UNIQUE(osce_exam_id,room_id,student_username),
        FOREIGN KEY(osce_exam_id) REFERENCES osce_exams(osce_exam_id),
        FOREIGN KEY(room_id) REFERENCES osce_rooms(room_id),
        FOREIGN KEY(student_username) REFERENCES users(username)
    )""")
    connection.execute("""CREATE INDEX IF NOT EXISTS idx_osce_assignment_student
        ON osce_assignments(student_username,osce_exam_id,room_id)""")
    connection.execute("""CREATE TABLE IF NOT EXISTS osce_item_scores (
        assignment_id INTEGER NOT NULL,
        item_id INTEGER NOT NULL,
        competency_level INTEGER NOT NULL,
        score_percent REAL NOT NULL,
        comment TEXT DEFAULT '',
        PRIMARY KEY(assignment_id,item_id),
        FOREIGN KEY(assignment_id) REFERENCES osce_assignments(assignment_id),
        FOREIGN KEY(item_id) REFERENCES nursing_technique_items(item_id)
    )""")


def sync_exam_attempts(connection, group_id=None,
                       exam_patient_group_id=None):
    """Create one private attempt per current group member."""
    where = ["pg.active=1", "g.active=1", "p.is_exam=1"]
    params = []
    if group_id is not None:
        where.append("pg.group_id=?")
        params.append(int(group_id))
    if exam_patient_group_id is not None:
        where.append("pg.exam_patient_group_id=?")
        params.append(int(exam_patient_group_id))
    connection.execute(
        """INSERT OR IGNORE INTO exam_attempts(
               exam_patient_group_id,patient_id,group_id,
               examinee_username,status,assigned_dt
           )
           SELECT pg.exam_patient_group_id,pg.patient_id,pg.group_id,
                  gm.username,'Assigned',
                  COALESCE(NULLIF(pg.assigned_dt,''),?)
           FROM exam_patient_groups pg
           JOIN exam_groups g ON g.group_id=pg.group_id
           JOIN patients p ON p.id=pg.patient_id
           JOIN exam_group_members gm ON gm.group_id=pg.group_id
           WHERE %s""" % " AND ".join(where),
        [datetime.now().strftime("%Y-%m-%d %H:%M:%S")] + params,
    )


def exam_attempt_for_user(connection, patient_id, username):
    """Return the active private attempt for one user and exam patient."""
    ensure_exam_schema(connection)
    return connection.execute(
        """SELECT a.*,g.group_name,p.exam_summary,p.exam_question
           FROM exam_attempts a
           JOIN exam_patient_groups pg
             ON pg.exam_patient_group_id=a.exam_patient_group_id
            AND pg.active=1
           JOIN exam_groups g ON g.group_id=a.group_id AND g.active=1
           JOIN exam_group_members gm
             ON gm.group_id=a.group_id
            AND gm.username=a.examinee_username
           JOIN patients p ON p.id=a.patient_id AND p.is_exam=1
           WHERE a.patient_id=? AND a.examinee_username=?
           ORDER BY a.attempt_id DESC LIMIT 1""",
        (str(patient_id or ""), str(username or "")),
    ).fetchone()


def exam_mode_enabled(connection):
    ensure_exam_schema(connection)
    row = connection.execute(
        """SELECT setting_value FROM exam_settings
           WHERE setting_key='exam_mode_enabled'"""
    ).fetchone()
    value = row[0] if row else "0"
    return str(value or "").strip().lower() in ("1", "true", "yes", "on")


