def _student_review_report_sections(selected=None):
    """Normalize checkbox selections for a Student Reviews PDF."""
    available = tuple(
        key for key, _label in STUDENT_REVIEW_REPORT_SECTIONS
    )
    if selected is None:
        return available
    if isinstance(selected, str):
        selected = [
            item.strip() for item in selected.split(",") if item.strip()
        ]
    normalized = []
    for value in selected:
        key = str(value or "").strip().lower()
        if key == "all":
            return available
        if key in available and key not in normalized:
            normalized.append(key)
    if not normalized:
        raise ValueError(
            "Select Nursing Care, Skill Practice, Clinical Targets, or All."
        )
    return tuple(normalized)


def _query_dict_rows(connection, sql, arguments=()):
    cursor = connection.execute(sql, arguments)
    columns = [item[0] for item in cursor.description]
    return [dict(zip(columns, row)) for row in cursor.fetchall()]


def _patient_report_rows(connection, table, datetime_column, patient_id,
                         date_from="", date_to="", columns="*",
                         order_by=""):
    clauses = ["patient_id=?"]
    arguments = [patient_id]
    if date_from:
        clauses.append("date(%s)>=?" % datetime_column)
        arguments.append(date_from)
    if date_to:
        clauses.append("date(%s)<=?" % datetime_column)
        arguments.append(date_to)
    sql = "SELECT %s FROM %s WHERE %s" % (
        columns, table, " AND ".join(clauses)
    )
    if order_by:
        sql += " ORDER BY " + order_by
    return _query_dict_rows(connection, sql, arguments)


def build_patient_report_data(connection, patient_id, date_from="", date_to="",
                              period_label="All treatment dates"):
    """Collect a complete patient-linked clinical timeline for PDF output."""
    patient_rows = _query_dict_rows(
        connection,
        """SELECT id,name,dob,gender,diagnosis,address,department,
                  history_present_illness,past_medical_history,
                  family_history,allergies,allergy_status,
                  created_dt,updated_dt
           FROM patients WHERE id=?""",
        (patient_id,),
    )
    if not patient_rows:
        raise ValueError("Patient not found.")
    triage_rows = _patient_report_rows(
        connection, "triage_records", "triage_dt", patient_id,
        date_from, date_to,
        "triage_id,triage_dt,nurse_code,nurse_name,triage_data,source",
        "datetime(triage_dt),triage_id",
    )
    for row in triage_rows:
        row["triage"] = _decoded_json(row.pop("triage_data", "{}"), {})
    care_rows = _patient_report_rows(
        connection, "nursing_care", "care_dt", patient_id,
        date_from, date_to,
        """care_id,care_dt,nurse_code,nurse_name,vitals,exam_summary,
           dx_list,ct_list,csdd,gdsk,bg,snapshot""",
        "datetime(care_dt),care_id",
    )
    # Mốc ghi nhận ĐẦU TIÊN không phụ thuộc khoảng thời gian lọc của báo
    # cáo, và được tính RIÊNG CHO TỪNG TÀI KHOẢN ghi hồ sơ (nurse_code),
    # giống hệt Web và Desktop, để bản ghi đầu tiên của mỗi sinh viên vẫn in
    # đầy đủ Nursing Process, SOAP, SBAR và Giáo dục sức khỏe.
    first_timepoint_care_id = first_care_record_id(connection, patient_id)
    first_timepoint_by_nurse = {}
    for row in care_rows:
        owner_code = str(row.get("nurse_code") or "").strip().lower()
        if owner_code in first_timepoint_by_nurse:
            continue
        first_timepoint_by_nurse[owner_code] = first_care_record_id(
            connection, patient_id, None, owner_code
        ) if owner_code else first_timepoint_care_id
    for row in care_rows:
        for key, default in (
            ("vitals", {}), ("exam_summary", []), ("dx_list", []),
            ("ct_list", []), ("csdd", []), ("gdsk", []), ("bg", []),
            ("snapshot", {}),
        ):
            row[key] = _decoded_json(row.get(key), default)
        try:
            row_care_id = int(row.get("care_id") or 0)
        except (TypeError, ValueError):
            row_care_id = 0
        owner_code = str(row.get("nurse_code") or "").strip().lower()
        owner_first_care_id = first_timepoint_by_nurse.get(
            owner_code, first_timepoint_care_id
        )
        row["is_first_timepoint"] = bool(
            not owner_first_care_id
            or row_care_id == owner_first_care_id
        )
        snapshot_value = row.get("snapshot")
        row_extras = (
            snapshot_value.get("extras", {})
            if isinstance(snapshot_value, dict) else {}
        )
        row["follow_up_care"] = normalize_follow_up_care(
            row_extras.get("follow_up_care", {})
            if isinstance(row_extras, dict) else {}
        )
        # Procedure Implementation rows straight from the shared table, so the
        # PDF prints whatever the last client (web or desktop) saved.
        try:
            row["procedures"] = load_nursing_procedures(
                connection, care_id=row.get("care_id")
            )
        except sqlite3.Error:
            row["procedures"] = []
        try:
            row["health_education"] = load_health_education(
                connection, care_id=row.get("care_id")
            )
        except sqlite3.Error:
            row["health_education"] = normalize_health_education({})
        if not row["procedures"]:
            for entry in row.get("ct_list", []) or []:
                if (isinstance(entry, dict)
                        and entry.get("loai") == "Procedure Implementation"):
                    row["procedures"] = parse_nursing_procedure_text(
                        entry.get("chi_tiet", "")
                    )
                    break
    result_rows = _patient_report_rows(
        connection, "lab_imaging_results", "result_dt", patient_id,
        date_from, date_to,
        """result_id,order_id,care_id,result_type,test_name,result_value,
           unit,reference_range,interpretation,result_dt,
           entered_by_code,entered_by_name,source""",
        "datetime(result_dt),result_id",
    )
    execution_rows = _patient_report_rows(
        connection, "nursing_med_records", "performed_dt", patient_id,
        date_from, date_to,
        """record_id,care_id,order_id,category,order_text,performed_dt,
           nurse_code,nurse_name,drug_action,side_effect,abnormal_note,source""",
        "datetime(performed_dt),record_id",
    )
    order_rows = _patient_report_rows(
        connection, "physician_orders", "created_dt", patient_id,
        "", "",
        """order_id,category,item_name,strength,dose,route,
           frequency_per_day,details,created_dt,doctor_name,
           scheduled_start_dt,scheduled_end_dt,status,updated_dt,
           entered_by_username,entered_by_code,entered_by_name,
           entered_by_role,source""",
        "datetime(created_dt),order_id",
    )
    if date_from or date_to:
        linked_order_ids = {
            int(row["order_id"]) for row in result_rows + execution_rows
            if row.get("order_id") not in (None, "")
        }

        def order_overlaps_period(row):
            try:
                order_id = int(row.get("order_id"))
            except (TypeError, ValueError):
                order_id = 0
            if order_id in linked_order_ids:
                return True
            start_value = (
                row.get("scheduled_start_dt") or row.get("created_dt") or ""
            )
            end_value = row.get("scheduled_end_dt") or ""
            if (
                not end_value
                and str(row.get("status") or "Active") != "Active"
            ):
                end_value = row.get("updated_dt") or ""
            start_dt = _clinical_datetime_value(start_value)
            end_dt = _clinical_datetime_value(end_value)
            start_date = start_dt.strftime("%Y-%m-%d") if start_dt else ""
            end_date = end_dt.strftime("%Y-%m-%d") if end_dt else ""
            if date_to and start_date and start_date > date_to:
                return False
            if date_from and end_date and end_date < date_from:
                return False
            return bool(start_date or order_id in linked_order_ids)

        order_rows = [
            row for row in order_rows if order_overlaps_period(row)
        ]
    return {
        "patient": patient_rows[0],
        "first_timepoint_care_id": first_timepoint_care_id,
        "date_from": date_from,
        "date_to": date_to,
        "period_label": period_label,
        "generated_dt": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "triage": triage_rows,
        "nursing_care": care_rows,
        "orders": order_rows,
        "results": result_rows,
        "order_executions": execution_rows,
    }


def _patient_report_value(value):
    """Convert nested clinical structures to readable multiline text."""
    if value in (None, "", [], {}):
        return ""
    if isinstance(value, dict):
        lines = []
        seen_texts = set()
        for key, item in value.items():
            text = _patient_report_value(item)
            # Several clinical entries (exam/dx/intervention rows) store the
            # same value twice under a legacy Vietnamese key and an English
            # alias key (e.g. "muc"/"category", "chi_tiet"/"details",
            # "chan_doan"/"diagnosis", "muc_tieu"/"goal", "loai"/"type") for
            # backward compatibility. Skip the alias so the PDF does not
            # print the identical text twice under two different labels.
            if text and text not in seen_texts:
                seen_texts.add(text)
                lines.append("%s: %s" % (
                    str(key).replace("_", " ").title(), text
                ))
        return "\n".join(lines)
    if isinstance(value, list):
        return "\n".join(
            "%d. %s" % (index, _patient_report_value(item))
            for index, item in enumerate(value, 1)
            if _patient_report_value(item)
        )
    return str(value)



# Các khoá trong vitals mang cấu trúc riêng (bảng dịch theo giờ, tổng kết,
# MEWS). Chúng có mục in riêng trong báo cáo nên phải loại khỏi bảng
# "Vital / monitoring item" - nếu không sẽ bị đổ ra dạng khoá/giá trị thô
# ("Fluid Chart / 1. Hour: 06:40 / Iv Ml: 500"), rất khó đọc.
PDF_STRUCTURED_VITAL_KEYS = ("fluid_chart", "fluid_totals", "mews")


def _pdf_vital_rows(vitals, value_cell=None):
    """Các dòng sinh hiệu đơn giản cho bảng PDF, kèm một dòng MEWS đọc được."""
    vitals = vitals if isinstance(vitals, dict) else {}
    rows = []
    for key, value in vitals.items():
        if key in PDF_STRUCTURED_VITAL_KEYS:
            continue
        if not str(value or "").strip():
            continue
        label = str(key).replace("_", " ").title()
        if key == "avpu":
            label = "AVPU (tri giác)"
        rows.append([
            label,
            value_cell(key, value, vitals) if value_cell else value,
        ])
    mews = mews_from_vitals_blob(vitals)
    if mews.get("measured"):
        detail = ", ".join(
            "%s: %s" % (label, mews["components"][key])
            for key, label in MEWS_PARAMETER_LABELS
            if key in mews["components"]
        )
        rows.append([
            "MEWS (Modified Early Warning Score)",
            "%d/14 - %s\n%s%s" % (
                mews["score"], mews["level"], detail,
                ("\nChưa đo: " + ", ".join(
                    dict(MEWS_PARAMETER_LABELS).get(key, key)
                    for key in mews["missing"]
                )) if mews["missing"] else "",
            ),
        ])
    return rows


# Ô MEWS là chuỗi nhiều dòng ghép từ số liệu nên không tra được nguyên chuỗi
# trong danh mục dịch; vì vậy dựng thẳng theo ngôn ngữ đang chọn.
_PDF_MEWS_WORDS = {
    "en": {
        "high": "HIGH risk", "mid": "MODERATE risk", "low": "LOW risk",
        "params": "(%d of 5 parameters)",
        "flag": "One parameter scores 3",
    },
    "vi": {
        "high": "Nguy c\u01a1 CAO", "mid": "Nguy c\u01a1 TRUNG B\u00ccNH",
        "low": "Nguy c\u01a1 TH\u1ea4P",
        "params": "(m\u1edbi \u0111o %d/5 th\u00f4ng s\u1ed1)",
        "flag": "C\u00f3 th\u00f4ng s\u1ed1 \u0111\u1ea1t 3 \u0111i\u1ec3m",
    },
}


def _pdf_mews_cell(vitals, language=DEFAULT_APP_LANGUAGE):
    """Ô MEWS cho bảng các mốc theo dõi sinh hiệu trong bản in.

    Hiển thị điểm, mức nguy cơ và số thông số đã đo - mốc đo thiếu thông số
    không bị nhầm với người bệnh thật sự ổn định.
    """
    mews = mews_from_vitals_blob(vitals)
    if not mews.get("measured"):
        return "-"
    words = _PDF_MEWS_WORDS.get(
        normalize_app_language(language), _PDF_MEWS_WORDS["en"]
    )
    text_value = "%d/14\n%s" % (
        mews["score"], words.get(mews.get("kind", ""), ""),
    )
    if mews.get("measured", 0) < 5:
        text_value += "\n" + (words["params"] % mews["measured"])
    if mews.get("red_flag") and mews.get("kind") != "high":
        text_value += "\n" + words["flag"]
    return text_value


def _pdf_fluid_chart_rows(vitals):
    """Bảng theo dõi dịch theo giờ + tổng kết 12 giờ / 24 giờ cho PDF."""
    vitals = vitals if isinstance(vitals, dict) else {}
    chart = vitals.get("fluid_chart")
    if not isinstance(chart, list) or not chart:
        return [], []
    rows = [[
        "Giờ\nTime", "Dịch truyền\nIV fluid", "mL", "Ăn uống\nOral intake",
        "mL", "Nước tiểu\nUrine", "Ra khác\nOther output",
        "Ghi chú bất thường\nAbnormal note",
    ]]
    for item in chart:
        if not isinstance(item, dict):
            continue
        rows.append([
            item.get("hour", "") or "-",
            item.get("iv", "") or "-", item.get("iv_ml", "") or "-",
            item.get("oral", "") or "-", item.get("oral_ml", "") or "-",
            item.get("urine_ml", "") or "-",
            item.get("other_out_ml", "") or "-",
            item.get("note", "") or "-",
        ])
    totals = vitals.get("fluid_totals")
    totals = totals if isinstance(totals, dict) else {}
    total_rows = []
    if totals:
        # Cột "Mất qua da và hơi thở" là một phần của Tổng dịch ra, in tách
        # ra để người đọc thấy vì sao cân bằng nhỏ hơn hiệu số đo được.
        def out_cell(label):
            measured = totals.get("measured_out_" + label)
            insensible = totals.get("insensible_" + label)
            if measured is None or insensible is None:
                return totals.get("out_" + label, "-")
            # Ngoặc bao cả hai mảnh chuỗi: thiếu nó thì "%" chỉ gắn vào
            # mảnh cuối và ba tham số rơi vào một chỗ giữ.
            return (
                "%s\n(đo được / measured %s + qua da và hơi thở / "
                "insensible %s)"
            ) % (
                totals.get("out_" + label, "-"), measured, insensible,
            )

        total_rows = [
            ["Mốc tổng kết\nPeriod", "Tổng dịch vào (mL)\nTotal intake",
             "Tổng dịch ra (mL)\nTotal output",
             "Cân bằng (mL)\nBalance"],
            ["12 giờ đầu\nFirst 12 hours", totals.get("in_12h", "-"),
             out_cell("12h"), totals.get("balance_12h", "-")],
            ["24 giờ\n24 hours", totals.get("in_24h", "-"),
             out_cell("24h"), totals.get("balance_24h", "-")],
        ]
        note = str(totals.get("insensible_note", "") or "")
        if note:
            total_rows.append([
                "Mất nước qua da và hơi thở\nInsensible water loss",
                "%s%s" % (
                    note,
                    " (điều dưỡng nhập tay)"
                    if totals.get("insensible_source_24h") == "manual"
                    else " (máy tự tính)",
                ),
                "", "",
            ])
    return rows, total_rows


def _pdf_care_plan_rows(row, extras):
    """Bảng Kế hoạch chăm sóc điều dưỡng bốn cột cho bản in.

    Trả về danh sách dòng đã sẵn sàng đưa vào ``data_table``:

        Chẩn đoán điều dưỡng | Mục tiêu | Can thiệp | Lượng giá

    Nguồn chính là sơ đồ Nursing Process (``extras.nursing_progression``):
    mỗi chẩn đoán mang theo mục tiêu và can thiệp của chính nó, mỗi mục
    tiêu / can thiệp lại mang lượng giá riêng - đúng bốn cột cần in, không
    phải suy đoán gì thêm.

    Bản ghi cũ (hoặc client chỉ ghi danh sách phẳng) không có sơ đồ này thì
    dựng lại từ ``dx_list`` (chẩn đoán + mục tiêu + ghi chú lượng giá) và
    ``ct_list`` (can thiệp). Thà in một kế hoạch gần đúng còn hơn in bảng
    trống cho hồ sơ đã ghi đầy đủ trên bản cũ.
    """
    header = [[
        "Ch\u1ea9n \u0111o\u00e1n \u0111i\u1ec1u d\u01b0\u1ee1ng\n"
        "Nursing diagnosis",
        "M\u1ee5c ti\u00eau\nGoal",
        "Can thi\u1ec7p\nIntervention",
        "L\u01b0\u1ee3ng gi\u00e1\nEvaluation",
    ]]
    rows = []
    numbering = 0
    for pathway in _normalized_nursing_progression(
        extras.get("nursing_progression", [])
    ):
        problems = pathway.get("problems", []) or []
        for diagnosis in pathway.get("diagnoses", []) or []:
            goals = diagnosis.get("goals", []) or []
            interventions = diagnosis.get("interventions", []) or []
            if not (
                diagnosis.get("diagnosis") or goals or interventions
            ):
                continue
            numbering += 1
            diagnosis_cell = "%d. %s" % (
                numbering,
                diagnosis.get("diagnosis", "")
                or "(ch\u01b0a ghi ch\u1ea9n \u0111o\u00e1n)",
            )
            # Vấn đề của người bệnh và nguyên nhân in kèm chẩn đoán: chúng
            # là lý do chẩn đoán đó tồn tại, tách ra cột riêng thì bảng
            # thành sáu cột và không còn đọc được trên khổ A4.
            if problems:
                diagnosis_cell += "\nV\u1ea5n \u0111\u1ec1: " + "; ".join(
                    problems
                )
            if diagnosis.get("causes"):
                diagnosis_cell += (
                    "\nNguy\u00ean nh\u00e2n: "
                    + "; ".join(diagnosis["causes"])
                )
            goal_lines, evaluation_lines = [], []
            for goal_index, goal in enumerate(goals, 1):
                text = str(goal.get("text", "") or "").strip()
                if text:
                    goal_lines.append("%d.%d. %s" % (
                        numbering, goal_index, text,
                    ))
                evaluation = str(goal.get("evaluation", "") or "").strip()
                if evaluation:
                    evaluation_lines.append("%d.%d. %s" % (
                        numbering, goal_index, evaluation,
                    ))
            intervention_lines = []
            for item_index, item in enumerate(interventions, 1):
                text = str(item.get("text", "") or "").strip()
                if text:
                    intervention_lines.append("%d.%d. %s" % (
                        numbering, item_index, text,
                    ))
                evaluation = str(item.get("evaluation", "") or "").strip()
                if evaluation:
                    evaluation_lines.append(
                        "Can thi\u1ec7p %d.%d: %s" % (
                            numbering, item_index, evaluation,
                        )
                    )
            rows.append([
                diagnosis_cell,
                "\n".join(goal_lines) or "-",
                "\n".join(intervention_lines) or "-",
                "\n".join(evaluation_lines) or "-",
            ])
    if rows:
        return header + rows

    # ---- Bản ghi cũ: dựng lại từ dx_list + ct_list ------------------------
    diagnosis_entries = [
        item for item in (row.get("dx_list") or [])
        if isinstance(item, dict)
    ]
    intervention_lines = []
    for item in row.get("ct_list") or []:
        if not isinstance(item, dict):
            text = " ".join(str(item or "").split())
            if text:
                intervention_lines.append(text)
            continue
        kind = str(item.get("loai", item.get("type", "")) or "").strip()
        detail = str(item.get("chi_tiet", item.get("details", "")) or "").strip()
        if not detail:
            continue
        # Tiền tố "[N]" gắn can thiệp với chẩn đoán thứ N, và nó phải nằm ở
        # ĐẦU dòng thì _split_diagnosis_prefixed_lines mới đọc được. Ghép
        # "loại: nội dung" trước sẽ đẩy "[N]" vào giữa dòng và mọi can thiệp
        # rơi hết về chẩn đoán 1, nên tách tiền tố ra rồi ghép lại phía trước.
        prefix = ""
        match = re.match(r"^\[(\d+)\]\s*", detail)
        if match:
            prefix = "[%s] " % match.group(1)
            detail = detail[match.end():].strip()
        if not detail:
            continue
        intervention_lines.append(
            prefix + ("%s: %s" % (kind, detail) if kind else detail)
        )
    if not diagnosis_entries and not intervention_lines:
        return []
    if not diagnosis_entries:
        # Có can thiệp nhưng chưa có chẩn đoán nào: vẫn in để phần đã ghi
        # không biến mất khỏi bản in.
        return header + [[
            "-", "-", "\n".join(intervention_lines), "-",
        ]]
    # Can thiệp trong bản ghi cũ được gắn với chẩn đoán thứ N bằng tiền tố
    # "[N]"; dòng không có tiền tố thuộc về mọi chẩn đoán nên in ở dòng đầu.
    # _split_diagnosis_prefixed_lines đã tự dồn dòng không có tiền tố vào
    # chẩn đoán 1, nên ở đây chỉ việc đọc từng rổ.
    buckets, _unattached = _split_diagnosis_prefixed_lines(
        intervention_lines, len(diagnosis_entries)
    )
    for index, item in enumerate(diagnosis_entries, 1):
        own = list(buckets.get(index, []))
        nested = item.get("evaluation")
        nested = nested if isinstance(nested, dict) else {}
        evaluation = str(
            item.get("evaluation_note", "") or nested.get("note", "") or ""
        ).strip()
        status = str(
            item.get("evaluation_status", "") or nested.get("status", "") or ""
        ).strip()
        if status:
            evaluation = (status + "\n" + evaluation).strip()
        rows.append([
            "%d. %s" % (
                index,
                str(item.get("chan_doan", item.get("diagnosis", "")) or "")
                or "(ch\u01b0a ghi ch\u1ea9n \u0111o\u00e1n)",
            ),
            str(item.get("muc_tieu", item.get("goal", "")) or "") or "-",
            "\n".join(own) or "-",
            evaluation or "-",
        ])
    return header + rows


def _pdf_risk_scale_rows(extras, language=DEFAULT_APP_LANGUAGE):
    """Bảng JHFRAT + Braden cho PDF; trả [] khi bản ghi chưa lượng giá."""
    extras = extras if isinstance(extras, dict) else {}
    scales = normalize_risk_scales(extras.get("risk_scales", {}))
    jhfrat, braden = scales["jhfrat"], scales["braden"]
    rows = []
    if jhfrat["answered"] and jhfrat["level"]:
        picked = []
        for key, label, options in JHFRAT_SINGLE_GROUPS:
            chosen = jhfrat["selections"].get(key, "")
            for option_value, option_label, points in options:
                if option_value and option_value == chosen:
                    picked.append("%s: %s (+%d)" % (
                        translate_ui_text(label, language),
                        translate_ui_text(option_label, language), points,
                    ))
        for key, label, options in JHFRAT_MULTI_GROUPS:
            for option_value, option_label, points in options:
                if option_value in jhfrat["selections"].get(key, []):
                    picked.append("%s: %s (+%d)" % (
                        translate_ui_text(label, language),
                        translate_ui_text(option_label, language), points,
                    ))
        advice = risk_interventions(
            FALL_RISK_INTERVENTIONS,
            fall_risk_band(
                jhfrat["score"],
                "high" if jhfrat["direct"].get("fall_this_admission")
                else ("low" if jhfrat["direct"].get("complete_immobility")
                      else ""),
            ),
            language,
        )
        if advice:
            picked.append(
                translate_ui_text("Can thiệp khuyến cáo", language) + ":"
            )
            picked.extend("- " + line for line in advice)
        rows.append([
            translate_ui_text(
                "Nguy cơ té ngã - Johns Hopkins (JHFRAT)", language
            ),
            "%d/35 %s - %s\n%s%s" % (
                jhfrat["score"],
                translate_ui_text("Điểm", language).lower(),
                translate_ui_text(jhfrat["level"], language),
                "\n".join(picked) or translate_ui_text(
                    "Không có yếu tố nguy cơ nào được chọn.", language
                ),
                ("\n%s: %s" % (
                    translate_ui_text("Ghi chú", language), jhfrat["note"]
                )) if jhfrat["note"] else "",
            ),
        ])
    if braden["answered"] and braden["total"] is not None:
        point_word = translate_ui_text("Điểm", language).lower()
        detail = "\n".join(
            "%s: %s %s" % (
                translate_ui_text(label, language),
                braden["scores"].get(key), point_word,
            )
            for key, label, _options in BRADEN_ITEMS
            if braden["scores"].get(key) is not None
        )
        pressure_advice = risk_interventions(
            PRESSURE_RISK_INTERVENTIONS,
            pressure_risk_band(braden["total"]), language,
        )
        if pressure_advice:
            detail += "\n" + translate_ui_text(
                "Can thiệp khuyến cáo", language
            ) + ":\n" + "\n".join(
                "- " + line for line in pressure_advice
            )
        rows.append([
            translate_ui_text(
                "Nguy cơ loét tì đè - Braden Scale", language
            ),
            "%d/23 %s - %s\n%s%s" % (
                braden["total"], point_word,
                translate_ui_text(braden["level"], language), detail,
                ("\n%s: %s" % (
                    translate_ui_text("Ghi chú", language), braden["note"]
                )) if braden["note"] else "",
            ),
        ])
    return rows


def generate_patient_report_pdf(report_data, language=None):
    """Create a polished, Unicode patient timeline PDF and return its bytes."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        from reportlab.platypus import (
            SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle,
            PageBreak, KeepTogether,
        )
    except ImportError:
        raise RuntimeError(
            "PDF support requires the reportlab package in this application."
        )

    # Mốc thời gian lâm sàng in ra chỉ đến phút. Bọc Paragraph ngay tại đây để
    # áp dụng cho CẢ các tiêu đề mục gọi Paragraph() trực tiếp, không chỉ các ô
    # bảng đi qua hàm paragraph() bên dưới. Chỉ cắt khi giây đúng bằng 00 - dòng
    # "Generated" của bản in vẫn giữ giây thật vì đó là dấu vết kết xuất.
    _ReportlabParagraph = Paragraph
    report_language = normalize_app_language(
        language if language is not None
        else report_data.get("language", DEFAULT_APP_LANGUAGE)
    )
    report_vital_bold_thresholds = validated_vital_thresholds(
        report_data.get("vital_bold_thresholds"), "bold"
    )
    report_vital_bold_color = str(
        report_data.get("vital_bold_color", "#991b1b") or "#991b1b"
    )
    if not re.match(r"^#[0-9a-fA-F]{6}$", report_vital_bold_color):
        report_vital_bold_color = "#991b1b"

    def Paragraph(report_text, *args, **kwargs):
        return _ReportlabParagraph(
            translate_ui_text(
                strip_clinical_seconds(report_text), report_language
            ),
            *args, **kwargs
        )

    regular_font = "Helvetica"
    bold_font = "Helvetica-Bold"
    font_candidates = (
        (
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arial.ttf"),
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arialbd.ttf"),
        ),
        (
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        ),
    )
    for regular_path, bold_path in font_candidates:
        if os.path.exists(regular_path):
            pdfmetrics.registerFont(TTFont("EMRUnicode", regular_path))
            regular_font = "EMRUnicode"
            if os.path.exists(bold_path):
                pdfmetrics.registerFont(TTFont("EMRUnicodeBold", bold_path))
                bold_font = "EMRUnicodeBold"
            else:
                bold_font = regular_font
            break

    output = io.BytesIO()
    doc = SimpleDocTemplate(
        output, pagesize=A4,
        rightMargin=14 * mm, leftMargin=14 * mm,
        topMargin=18 * mm, bottomMargin=17 * mm,
        title="Patient Clinical Record",
        author="EMR",
    )
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="ReportTitle", parent=styles["Title"], fontName=bold_font,
        fontSize=17, leading=21, textColor=colors.HexColor("#123b66"),
        alignment=TA_CENTER, spaceAfter=8,
    ))
    styles.add(ParagraphStyle(
        name="SectionTitle", parent=styles["Heading2"], fontName=bold_font,
        fontSize=12, leading=15, textColor=colors.white,
        backColor=colors.HexColor("#1f5f8b"), borderPadding=6,
        spaceBefore=10, spaceAfter=7,
    ))
    styles.add(ParagraphStyle(
        name="EntryTitle", parent=styles["Heading3"], fontName=bold_font,
        fontSize=10.5, leading=13, textColor=colors.HexColor("#123b66"),
        spaceBefore=7, spaceAfter=4,
    ))
    styles.add(ParagraphStyle(
        name="ReportBody", parent=styles["BodyText"], fontName=regular_font,
        fontSize=8.5, leading=11, spaceAfter=3, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="ReportSmall", parent=styles["BodyText"], fontName=regular_font,
        fontSize=7.3, leading=9.2, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="ReportLabel", parent=styles["BodyText"], fontName=bold_font,
        fontSize=8.2, leading=10, textColor=colors.HexColor("#23415f"),
    ))

    def paragraph(value, style="ReportBody"):
        # Bản in cũng theo quy ước chỉ giờ:phút cho mốc lâm sàng.
        text = html.escape(
            strip_clinical_seconds(_patient_report_value(value))
        ).replace("\n", "<br/>")
        return Paragraph(text or "-", styles[style])

    def vital_paragraph(key, value, vitals=None, style="ReportSmall"):
        text = html.escape(strip_clinical_seconds(str(value or "")))
        if vital_value_is_abnormal(
            key, value, vitals, report_vital_bold_thresholds
        ):
            text = '<font color="%s"><b>%s</b></font>' % (
                report_vital_bold_color, text
            )
        return Paragraph(text or "-", styles[style])

    def vital_summary_paragraph(vitals, style="ReportSmall"):
        return Paragraph(
            _vital_summary_pdf_markup(
                vitals, report_vital_bold_thresholds,
                report_vital_bold_color,
            ),
            styles[style],
        )

    def data_table(rows, widths=None, header=True):
        converted = [
            [cell if hasattr(cell, "wrapOn") else paragraph(cell, "ReportSmall")
             for cell in row]
            for row in rows
        ]
        table = Table(
            converted, colWidths=widths,
            repeatRows=1 if header and converted else 0,
            hAlign="LEFT",
            # A single clinical note (assessment, care plan, clinical support)
            # is regularly taller than one A4 frame. Without these two flags
            # ReportLab raises LayoutError and the whole patient PDF fails to
            # export, which is exactly the "cannot export PDF" report.
            splitByRow=1, splitInRow=1,
        )
        commands = [
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#b8c7d5")),
            ("LEFTPADDING", (0, 0), (-1, -1), 4),
            ("RIGHTPADDING", (0, 0), (-1, -1), 4),
            ("TOPPADDING", (0, 0), (-1, -1), 3),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
            ("ROWBACKGROUNDS", (0, 1 if header else 0), (-1, -1),
             [colors.white, colors.HexColor("#f6f9fc")]),
        ]
        if header and converted:
            commands.extend((
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#dceaf5")),
                ("FONTNAME", (0, 0), (-1, 0), bold_font),
            ))
        table.setStyle(TableStyle(commands))
        return table

    story = _eiu_pdf_logo_flowables()
    patient = report_data["patient"]
    story.append(Paragraph("PATIENT CLINICAL RECORD", styles["ReportTitle"]))
    story.append(paragraph(
        "Report period: %s | Generated: %s" % (
            report_data["period_label"], report_data["generated_dt"]
        ), "ReportSmall"
    ))
    story.append(Spacer(1, 5))
    story.append(data_table([
        ["Patient ID", patient.get("id", ""), "Full name", patient.get("name", "")],
        ["DOB", patient.get("dob", ""), "Gender", patient.get("gender", "")],
        ["Department", patient.get("department", ""), "Diagnosis",
         patient.get("diagnosis", "")],
        ["Address", patient.get("address", ""), "Record created",
         patient.get("created_dt", "")],
    ], [25 * mm, 57 * mm, 27 * mm, 70 * mm], header=False))
    story.append(Spacer(1, 5))
    story.append(Paragraph("Medical history", styles["SectionTitle"]))
    story.append(data_table([
        ["History of present illness",
         patient.get("history_present_illness", "")],
        ["Past medical history (personal)",
         patient.get("past_medical_history", "")],
        ["Family history", patient.get("family_history", "")],
        ["Allergy status", (
            "Has an allergy history"
            if normalized_allergy_status(
                patient.get("allergy_status", ""),
                patient.get("allergies", ""),
            ) == ALLERGY_STATUS_HAS else
            "No allergy history recorded to date"
            if normalized_allergy_status(
                patient.get("allergy_status", ""),
                patient.get("allergies", ""),
            ) == ALLERGY_STATUS_NONE_REPORTED else
            "Not documented"
        )],
        ["Allergy details", patient.get("allergies", "")],
    ], [54 * mm, 125 * mm], header=False))
    story.append(Paragraph(
        "<b>Bold / In đậm:</b> vital sign outside the configured review "
        "range, including capillary blood glucose. Clinical context and local "
        "policy prevail.",
        styles["ReportSmall"],
    ))

    story.append(Paragraph("1. Triage timeline", styles["SectionTitle"]))
    if not report_data["triage"]:
        story.append(paragraph("No Triage record in the selected period."))
    for index, row in enumerate(report_data["triage"], 1):
        triage = row["triage"]
        quick = triage.get("quick_assessment", {})
        vitals = triage.get("vital_signs", {})
        abcde = triage.get("abcde", {})
        story.append(Paragraph(
            "Triage %d - %s" % (index, row.get("triage_dt", "")),
            styles["EntryTitle"],
        ))
        story.append(data_table([
            ["Recorded by", "%s (%s)" % (
                row.get("nurse_name", ""), row.get("nurse_code", "")
            ), "Source", row.get("source", "")],
            ["Level", "%s - %s (%s)" % (
                triage.get("level", ""), triage.get("category", ""),
                triage.get("color", "")
            ), "Target", "%s minute(s)" % triage.get("target_minutes", "")],
            ["Arrival", triage.get("arrival_mode", ""), "Chief complaint",
             triage.get("chief_complaint", "")],
        ], [27 * mm, 58 * mm, 25 * mm, 69 * mm], header=False))
        story.append(Paragraph("Rapid assessment", styles["EntryTitle"]))
        story.append(data_table([
            ["Look", quick.get("look", "")],
            ["Listen", quick.get("listen", "")],
            ["Smell", quick.get("smell", "")],
        ], [28 * mm, 151 * mm], header=False))
        story.append(Paragraph("Vital signs at triage", styles["EntryTitle"]))
        vital_rows = [["Parameter", "Value"]]
        vital_rows.extend([
            [str(key).replace("_", " ").title(),
             vital_paragraph(key, value, vitals)]
            for key, value in vitals.items() if str(value or "").strip()
        ])
        story.append(data_table(vital_rows, [55 * mm, 124 * mm]))
        story.append(Paragraph("ABCDE primary assessment", styles["EntryTitle"]))
        abcde_rows = [["Step", "Status", "Finding / intervention"]]
        for key, label in TRIAGE_ABCDE_FIELDS:
            item = abcde.get(key, {}) if isinstance(abcde, dict) else {}
            if not isinstance(item, dict):
                item = {}
            abcde_rows.append([
                label, item.get("status", ""), item.get("note", "")
            ])
        story.append(data_table(
            abcde_rows, [32 * mm, 42 * mm, 105 * mm]
        ))
        story.append(data_table([
            ["Classification reason", triage.get("classification_reason", "")],
            ["Immediate action / disposition / reassessment",
             triage.get("immediate_action", "")],
            ["Handoff", triage.get("handoff", {})],
        ], [55 * mm, 124 * mm], header=False))

    story.append(PageBreak())
    story.append(Paragraph("2. Physician Orders", styles["SectionTitle"]))
    order_rows = [[
        "Order / time", "Category and item", "Dose / route / frequency",
        "Clinical indication / schedule / status",
    ]]
    for row in report_data["orders"]:
        frequency = str(row.get("frequency_per_day", "") or "").strip()
        entered_by = " ".join(
            part for part in (
                str(row.get("entered_by_name", "") or "").strip(),
                ("(%s)" % row.get("entered_by_code"))
                if str(row.get("entered_by_code", "") or "").strip() else "",
                ("[%s]" % row.get("entered_by_role"))
                if str(row.get("entered_by_role", "") or "").strip() else "",
            ) if part
        ) or "Legacy / desktop"
        dose_route_frequency = "\n".join(
            part for part in (
                str(row.get("dose", "") or "").strip(),
                str(row.get("route", "") or "").strip(),
                (frequency + " time(s)/day") if frequency else "",
            ) if part
        )
        order_rows.append([
            "#%s\n%s\nPrescriber: %s\nEntered by: %s" % (
                row.get("order_id", ""), row.get("created_dt", ""),
                row.get("doctor_name", ""),
                entered_by,
            ),
            "%s\n%s\n%s" % (
                row.get("category", ""), row.get("item_name", ""),
                row.get("strength", "")
            ),
            dose_route_frequency,
            "%s\nStart: %s\nEnd: %s\nStatus: %s\nUpdated: %s" % (
                row.get("details", ""), row.get("scheduled_start_dt", ""),
                row.get("scheduled_end_dt", ""), row.get("status", ""),
                row.get("updated_dt", ""),
            ),
        ])
    story.append(data_table(
        order_rows if len(order_rows) > 1 else
        [["Orders", "No physician order in the selected period.", "", ""]],
        [35 * mm, 46 * mm, 42 * mm, 56 * mm],
        header=len(order_rows) > 1,
    ))

    story.append(Paragraph("3. Laboratory and Imaging Results",
                           styles["SectionTitle"]))
    result_rows = [[
        "Result time", "Order / type", "Test / imaging",
        "Result / reference / interpretation",
    ]]
    for row in report_data["results"]:
        result_rows.append([
            row.get("result_dt", ""),
            "Order #%s\n%s" % (
                row.get("order_id", ""), row.get("result_type", "")
            ),
            row.get("test_name", ""),
            "%s %s\nReference: %s\nInterpretation: %s\nEntered by: %s (%s)" % (
                row.get("result_value", ""), row.get("unit", ""),
                row.get("reference_range", ""), row.get("interpretation", ""),
                row.get("entered_by_name", ""), row.get("entered_by_code", "")
            ),
        ])
    story.append(data_table(
        result_rows if len(result_rows) > 1 else
        [["Results", "No Laboratory/Imaging result in the selected period.",
          "", ""]],
        [36 * mm, 38 * mm, 45 * mm, 60 * mm],
        header=len(result_rows) > 1,
    ))

    story.append(PageBreak())
    story.append(Paragraph("4. Nursing Process",
                           styles["SectionTitle"]))

    # Every Nursing Care Time observation, in one place, so the monitoring
    # timepoints are unambiguous. Nursing Process never creates a timepoint of
    # its own: it is always bound to one of the rows printed here.
    story.append(Paragraph(
        "4.1 M\u1ed1c th\u1eddi gian theo d\u00f5i d\u1ea5u sinh hi\u1ec7u - "
        "Vital signs monitoring timepoints",
        styles["SectionTitle"],
    ))
    timeline_rows = [[
        "#", "Th\u1eddi \u0111i\u1ec3m theo d\u00f5i / Timepoint",
        "D\u1ea5u sinh hi\u1ec7u / Vital signs",
        # C\u1ed9t MEWS \u0111i k\u00e8m t\u1eebng m\u1ed1c theo d\u00f5i sinh hi\u1ec7u, gi\u1ed1ng b\u1ea3ng
        # Follow-up History tr\u00ean Web. B\u1ea3n ghi c\u0169 l\u01b0u tr\u01b0\u1edbc khi c\u00f3 MEWS v\u1eabn
        # hi\u1ec7n \u0111i\u1ec3m v\u00ec \u0111\u01b0\u1ee3c t\u00ednh l\u1ea1i t\u1eeb sinh hi\u1ec7u \u0111\u00e3 ghi.
        "MEWS",
        "\u0110i\u1ec1u d\u01b0\u1ee1ng / Recorded by",
        "Lo\u1ea1i m\u1ed1c / Nursing Process",
    ]]
    for timeline_index, timeline_row in enumerate(
        report_data["nursing_care"], 1
    ):
        timeline_snapshot = (
            timeline_row["snapshot"]
            if isinstance(timeline_row["snapshot"], dict) else {}
        )
        timeline_extras = timeline_snapshot.get("extras", {})
        if not isinstance(timeline_extras, dict):
            timeline_extras = {}
        timeline_times = _normalized_section_datetimes(
            timeline_extras.get("section_datetimes", {}),
            timeline_row.get("care_dt", ""),
        )
        bound = (
            "C\u00f3 - " + timeline_times.get("process", "")
            if str(timeline_times.get("process", ""))
            == str(timeline_times.get("care_time", ""))
            else "Theo m\u1ed1c: " + str(timeline_times.get("process", ""))
        )
        # Ch\u1ec9 m\u1ed1c ghi nh\u1eadn \u0111\u1ea7u ti\u00ean m\u1edbi c\u00f3 \u0111\u1ee7 Nursing Process, SOAP,
        # SBAR v\u00e0 Gi\u00e1o d\u1ee5c s\u1ee9c kh\u1ecfe.
        if timeline_row.get("is_first_timepoint", True):
            bound = "M\u1ed1c ghi nh\u1eadn \u0111\u1ea7u ti\u00ean\n" + bound
        else:
            bound = (
                "M\u1ed1c theo d\u00f5i ti\u1ebfp theo\n"
                "Nursing Process/SOAP/SBAR/GDSK: -"
            )
        timeline_rows.append([
            "%d" % timeline_index,
            "%s\nCare #%s" % (
                timeline_times.get("care_time", "")
                or timeline_row.get("care_dt", ""),
                timeline_row.get("care_id", ""),
            ),
            vital_summary_paragraph(timeline_row["vitals"]),
            _pdf_mews_cell(timeline_row["vitals"], report_language),
            "%s (%s)" % (
                timeline_row.get("nurse_name", ""),
                timeline_row.get("nurse_code", ""),
            ),
            bound,
        ])
    story.append(data_table(
        timeline_rows if len(timeline_rows) > 1 else
        [["Timepoints",
          "Ch\u01b0a c\u00f3 m\u1ed1c theo d\u00f5i d\u1ea5u sinh hi\u1ec7u "
          "n\u00e0o trong k\u1ef3 b\u00e1o c\u00e1o.", "", "", "", ""]],
        [7 * mm, 34 * mm, 50 * mm, 22 * mm, 28 * mm, 38 * mm],
        header=len(timeline_rows) > 1,
    ))
    story.append(Spacer(1, 5))

    if not report_data["nursing_care"]:
        story.append(paragraph("No Nursing Care record in the selected period."))

    # Mốc ghi nhận đầy đủ (có Nursing Process) và mốc theo dõi sinh hiệu tiếp
    # theo được in ở HAI GIAI ĐOẠN khác nhau, nên phần thân của vòng lặp cũ
    # được tách thành các hàm phát nội dung dưới đây. Nội dung từng phần giữ
    # nguyên; chỉ thứ tự đọc thay đổi.
    def record_context(row):
        snapshot = row["snapshot"] if isinstance(row["snapshot"], dict) else {}
        extras = snapshot.get("extras", {})
        if not isinstance(extras, dict):
            extras = {}
        section_times = _normalized_section_datetimes(
            extras.get("section_datetimes", {}), row.get("care_dt", "")
        )
        return snapshot, extras, section_times

    def record_title(row, index, suffix=""):
        story.append(Paragraph(
            "Nursing Care %d - %s - %s (%s)%s" % (
                index, row.get("care_dt", ""), row.get("nurse_name", ""),
                row.get("nurse_code", ""), suffix,
            ), styles["EntryTitle"],
        ))

    def emit_assessment(row, index, snapshot, extras, section_times):
        section_vitals = extras.get("section_vitals", {})
        if not isinstance(section_vitals, dict):
            section_vitals = {}
        vital_sources = extras.get("section_vital_sources", {})
        if not isinstance(vital_sources, dict):
            vital_sources = {}
        process_source = str(vital_sources.get("process", "") or "current")
        if process_source.startswith("saved:"):
            process_binding = (
                "G\u1eafn v\u00e0o m\u1ed1c sinh hi\u1ec7u \u0111\u00e3 ghi "
                "Care #%s" % process_source.split(":", 1)[1]
            )
        else:
            process_binding = (
                "G\u1eafn v\u00e0o m\u1ed1c Nursing Care Time c\u1ee7a "
                "ch\u00ednh phi\u1ebfu n\u00e0y (Care #%s)"
                % (row.get("care_id", "") or "-")
            )
        story.append(data_table([
            ["Nursing Care Time (m\u1ed1c theo d\u00f5i sinh hi\u1ec7u)",
             section_times.get("care_time", "")],
            ["Nursing Process timestamp",
             "%s\n%s\nNursing Process kh\u00f4ng t\u1ea1o m\u1ed1c th\u1eddi "
             "gian m\u1edbi." % (
                 section_times.get("process", ""), process_binding,
             )],
            ["SOAP timestamp (k\u1ebf th\u1eeba Nursing Care Time)",
             section_times.get("soap", "")],
            ["SBAR timestamp (k\u1ebf th\u1eeba Nursing Care Time)",
             section_times.get("sbar", "")],
            ["Evaluation timestamp", extras.get("eval_time", "")],
        ], [55 * mm, 124 * mm], header=False))
        vital_rows = [["Vital / monitoring item", "Value"]]
        vital_rows.extend(_pdf_vital_rows(row["vitals"], vital_paragraph))
        story.append(Paragraph(
            "Vital signs and monitoring - m\u1ed1c %s"
            % (section_times.get("care_time", "") or "-"),
            styles["EntryTitle"],
        ))
        story.append(data_table(
            vital_rows if len(vital_rows) > 1 else
            [["Vital signs",
              "Ch\u01b0a ghi d\u1ea5u sinh hi\u1ec7u cho m\u1ed1c n\u00e0y."]],
            [60 * mm, 119 * mm], header=len(vital_rows) > 1,
        ))
        # Bảng theo dõi dịch theo giờ in thành bảng thật, thay vì bị đổ ra
        # dạng khoá/giá trị trong bảng sinh hiệu ở trên.
        fluid_rows, fluid_totals = _pdf_fluid_chart_rows(row["vitals"])
        if fluid_rows:
            # Bảng theo dõi dịch là MỘT PHẦN CỦA Nursing Assessment, không
            # phải một mục riêng: cân bằng dịch chính là dữ kiện nhận định.
            story.append(Paragraph(
                "Nursing Assessment - Theo d\u00f5i d\u1ecbch v\u00e0o - "
                "d\u1ecbch ra theo gi\u1edd / Hourly fluid intake and "
                "output chart", styles["EntryTitle"],
            ))
            story.append(data_table(
                fluid_rows,
                [16 * mm, 32 * mm, 14 * mm, 32 * mm, 14 * mm, 18 * mm,
                 16 * mm, 37 * mm],
            ))
            if fluid_totals:
                story.append(data_table(
                    fluid_totals, [45 * mm, 45 * mm, 45 * mm, 44 * mm],
                ))
        # Hai thang l\u01b0\u1ee3ng gi\u00e1 nguy c\u01a1 c\u1ee7a Nursing
        # Assessment.
        risk_rows = _pdf_risk_scale_rows(extras, report_language)
        if risk_rows:
            story.append(Paragraph(
                "L\u01b0\u1ee3ng gi\u00e1 nguy c\u01a1 (JHFRAT / Braden)",
                styles["EntryTitle"],
            ))
            story.append(data_table(
                risk_rows, [55 * mm, 124 * mm], header=False,
            ))
        # The eight vital signs the Nursing Process documents, copied from the
        # bound timepoint - printed even when blank so the reader can see that
        # no observation was attached rather than that it was omitted.
        process_vitals = _process_vitals_from_record(
            section_vitals.get("process", row["vitals"])
        )
        story.append(Paragraph(
            "Nursing Process - d\u1ea5u sinh hi\u1ec7u t\u1ea1i m\u1ed1c "
            "\u0111\u00e3 g\u1eafn (%s)" % (
                section_times.get("process", "") or "-"
            ),
            styles["EntryTitle"],
        ))
        story.append(data_table([
            ["M\u1ea1ch (l/p)", vital_paragraph(
                "pulse", process_vitals.get("pulse", ""), process_vitals)],
            ["Huy\u1ebft \u00e1p (mmHg)", vital_paragraph("bp", "/".join(
                part for part in (
                    process_vitals.get("bp_sys", ""),
                    process_vitals.get("bp_dia", ""),
                ) if part
            ), process_vitals)],
            ["Nhi\u1ec7t \u0111\u1ed9 (\u00b0C)",
             vital_paragraph("temp", process_vitals.get("temp", ""), process_vitals)],
            ["Nh\u1ecbp th\u1edf (l/p)", vital_paragraph(
                "rr", process_vitals.get("rr", ""), process_vitals)],
            ["SpO2 (%)", vital_paragraph(
                "spo2", process_vitals.get("spo2", ""), process_vitals)],
            ["\u0110i\u1ec3m \u0111au (0-10)",
             vital_paragraph("pain_score", process_vitals.get("pain_score", ""), process_vitals)],
            ["\u0110\u01b0\u1eddng huy\u1ebft (mmol/L)",
             vital_paragraph("bg", process_vitals.get("bg", ""), process_vitals)],
        ], [60 * mm, 119 * mm], header=False))
        story.append(Paragraph("Nursing assessment",
                               styles["EntryTitle"]))
        story.append(paragraph(row["exam_summary"]))
    def emit_clinical_support(row, index, snapshot, extras, section_times):
        clinical_support = _normalized_clinical_support(
            extras.get("clinical_support", {})
        )
        # Printed for every Nursing Care entry, blank when nothing was
        # entered, so a reader can tell "not documented" apart from
        # "dropped by the export".
        story.append(Paragraph(
            "Hỗ trợ lâm sàng - Clinical support", styles["EntryTitle"]
        ))
        if not (
            clinical_support["pathophysiology"]
            or clinical_support["comparisons"]
            or clinical_support["medications"]
            or clinical_support["paraclinical"]
            or clinical_support["note"]
        ):
            story.append(data_table([[
                "H\u1ed7 tr\u1ee3 l\u00e2m s\u00e0ng",
                "Ch\u01b0a nh\u1eadp / Not documented.",
            ]], [55 * mm, 124 * mm], header=False))
        else:
            for entry in clinical_support["pathophysiology"]:
                story.append(paragraph(
                    "%s\nCơ chế bệnh sinh: %s\nBiểu hiện trên người bệnh: %s"
                    % (
                        entry["disease"] or "(chưa ghi tên bệnh)",
                        entry["mechanism"] or "-",
                        entry["presentation"] or "-",
                    )
                ))
            if clinical_support["comparisons"]:
                comparison_rows = [[
                    "Nội dung", "Cơ sở lý thuyết", "Thực tế",
                    "Giống/Khác", "Giải thích",
                ]]
                comparison_rows.extend([
                    [
                        entry["topic"], entry["theory"], entry["practice"],
                        entry["verdict"], entry["explanation"],
                    ]
                    for entry in clinical_support["comparisons"]
                ])
                story.append(data_table(
                    comparison_rows,
                    [30 * mm, 40 * mm, 40 * mm, 20 * mm, 49 * mm],
                ))
            # Thuốc điều trị - tác dụng chính, tác dụng phụ và theo dõi
            # điều dưỡng, one row per drug.
            medication_rows = [[
                "Thu\u1ed1c \u0111i\u1ec1u tr\u1ecb",
                "T\u00e1c d\u1ee5ng ch\u00ednh",
                "T\u00e1c d\u1ee5ng ph\u1ee5",
                "Theo d\u00f5i \u0111i\u1ec1u d\u01b0\u1ee1ng",
            ]]
            medication_rows.extend([
                [
                    entry["drug"] or "-",
                    entry["main_effect"] or "-",
                    entry["side_effects"] or "-",
                    entry["nursing_monitoring"] or "-",
                ]
                for entry in clinical_support["medications"]
            ])
            story.append(data_table(
                medication_rows if len(medication_rows) > 1 else
                [["Thu\u1ed1c \u0111i\u1ec1u tr\u1ecb",
                  "Ch\u01b0a nh\u1eadp / Not documented.", "", ""]],
                [42 * mm, 46 * mm, 45 * mm, 46 * mm],
                header=len(medication_rows) > 1,
            ))
            # C\u1eadn l\u00e2m s\u00e0ng - m\u1ed7i y l\u1ec7nh X\u00e9t nghi\u1ec7m / Ch\u1ea9n \u0111o\u00e1n h\u00ecnh
            # \u1ea3nh l\u00e0 m\u1ed9t d\u00f2ng: m\u1ee5c \u0111\u00edch, k\u1ebft qu\u1ea3 tr\u00ean ng\u01b0\u1eddi b\u1ec7nh v\u00e0
            # nh\u1eadn \u0111\u1ecbnh/theo d\u00f5i c\u1ee7a \u0111i\u1ec1u d\u01b0\u1ee1ng.
            paraclinical_rows = [[
                "C\u1eadn l\u00e2m s\u00e0ng",
                "Nh\u00f3m",
                "M\u1ee5c \u0111\u00edch",
                "K\u1ebft qu\u1ea3 tr\u00ean ng\u01b0\u1eddi b\u1ec7nh",
                "Nh\u1eadn \u0111\u1ecbnh / theo d\u00f5i \u0110D",
            ]]
            paraclinical_rows.extend([
                [
                    entry["test"] or "-",
                    PARACLINICAL_CATEGORY_LABELS.get(
                        entry["category"], entry["category"] or "-"
                    ),
                    entry["purpose"] or "-",
                    entry["result"] or "-",
                    entry["nursing_note"] or "-",
                ]
                for entry in clinical_support["paraclinical"]
            ])
            story.append(data_table(
                paraclinical_rows if len(paraclinical_rows) > 1 else
                [["C\u1eadn l\u00e2m s\u00e0ng",
                  "Ch\u01b0a c\u00f3 y l\u1ec7nh x\u00e9t nghi\u1ec7m / ch\u1ea9n \u0111o\u00e1n h\u00ecnh \u1ea3nh.",
                  "", "", ""]],
                [38 * mm, 20 * mm, 40 * mm, 42 * mm, 39 * mm],
                header=len(paraclinical_rows) > 1,
            ))
            if clinical_support["note"]:
                story.append(paragraph(clinical_support["note"]))
    def emit_procedures(row, index, snapshot, extras, section_times):
        procedure_rows = row.get("procedures", []) or []
        if procedure_rows:
            story.append(Paragraph(
                "Procedure Implementation - quy trình kỹ thuật điều dưỡng",
                styles["EntryTitle"],
            ))
            procedure_table = [[
                "Giờ", "Quy trình kỹ thuật", "Ghi chú theo dõi",
                "Điều dưỡng thực hiện",
            ]]
            procedure_table.extend([
                [
                    entry.get("performed_time", "") or "-",
                    entry.get("procedure_name", ""),
                    entry.get("follow_up_note", "") or "-",
                    entry.get("nurse_name", "") or "-",
                ]
                for entry in procedure_rows
            ])
            story.append(data_table(
                procedure_table, [16 * mm, 73 * mm, 55 * mm, 35 * mm]
            ))
    def emit_followup(row, index, snapshot, extras, section_times):
        follow_up = normalize_follow_up_care(
            row.get("follow_up_care", {})
        )
        if follow_up_care_is_empty(follow_up):
            # Bản ghi cũ / bản ghi từ client khác: dựng lại từ ct_list.
            kind_to_key = {
                kind: key for key, kind
                in FOLLOW_UP_CARE_INTERVENTION_KINDS.items()
            }
            recovered = {"problems": []}
            for entry in row.get("ct_list", []) or []:
                if not isinstance(entry, dict):
                    continue
                key = kind_to_key.get(
                    str(entry.get("loai", entry.get("type", "")) or "")
                )
                if key:
                    recovered[key] = entry.get(
                        "chi_tiet", entry.get("details", "")
                    )
            follow_up = normalize_follow_up_care(recovered)
        story.append(data_table([
            ["Nursing Care Time (m\u1ed1c theo d\u00f5i sinh hi\u1ec7u)",
             section_times.get("care_time", "")
             or row.get("care_dt", "") or "-"],
            ["Lo\u1ea1i m\u1ed1c",
             "M\u1ed1c theo d\u00f5i ti\u1ebfp theo - ch\u1ec9 ghi Nursing Care Time, "
             "v\u1ea5n \u0111\u1ec1 c\u1ee7a ng\u01b0\u1eddi b\u1ec7nh v\u00e0 can thi\u1ec7p NIC."],
        ], [55 * mm, 124 * mm], header=False))
        followup_vital_rows = [["Vital / monitoring item", "Value"]]
        followup_vital_rows.extend([
            [str(key).replace("_", " ").title(),
             vital_paragraph(key, value, row["vitals"])]
            for key, value in row["vitals"].items()
            if str(value or "").strip()
        ])
        story.append(Paragraph(
            "Vital signs and monitoring - m\u1ed1c %s"
            % (section_times.get("care_time", "") or "-"),
            styles["EntryTitle"],
        ))
        story.append(data_table(
            followup_vital_rows if len(followup_vital_rows) > 1 else
            [["Vital signs",
              "Ch\u01b0a ghi d\u1ea5u sinh hi\u1ec7u cho m\u1ed1c n\u00e0y."]],
            [60 * mm, 119 * mm], header=len(followup_vital_rows) > 1,
        ))
        followup_fluid, followup_totals = _pdf_fluid_chart_rows(
            row["vitals"]
        )
        if followup_fluid:
            story.append(Paragraph(
                "Theo d\u00f5i d\u1ecbch v\u00e0o - d\u1ecbch ra theo "
                "gi\u1edd / Hourly fluid intake and output chart",
                styles["EntryTitle"],
            ))
            story.append(data_table(
                followup_fluid,
                [16 * mm, 32 * mm, 14 * mm, 32 * mm, 14 * mm, 18 * mm,
                 16 * mm, 37 * mm],
            ))
            if followup_totals:
                story.append(data_table(
                    followup_totals,
                    [45 * mm, 45 * mm, 45 * mm, 44 * mm],
                ))
        story.append(Paragraph(
            FOLLOW_UP_CARE_TITLE, styles["EntryTitle"]
        ))
        follow_up_table = [
            ["N\u1ed9i dung", "Ghi nh\u1eadn t\u1ea1i m\u1ed1c n\u00e0y"],
            [
                FOLLOW_UP_PROBLEM_LABEL,
                "\n".join(follow_up["problems"]) or "-",
            ],
        ]
        follow_up_table.extend(
            [field_label, follow_up.get(field_key, "") or "-"]
            for field_key, field_label in FOLLOW_UP_CARE_FIELDS
        )
        # Hai ô đã gỡ khỏi giao diện (y lệnh thuốc / cận lâm sàng) chỉ
        # in ra khi bản ghi cũ thực sự có nội dung, để không mất dữ liệu
        # đã ghi trước đây. Y lệnh thực hiện mới nằm ở mục 5 của báo cáo.
        follow_up_table.extend(
            [field_label, follow_up.get(field_key, "")]
            for field_key, field_label in FOLLOW_UP_CARE_RETIRED_FIELDS
            if follow_up.get(field_key, "")
        )
        story.append(data_table(follow_up_table, [62 * mm, 117 * mm]))
        story.append(data_table([
            ["Nursing Process", "-"],
            ["SOAP", "-"],
            ["SBAR", "-"],
            ["Gi\u00e1o d\u1ee5c s\u1ee9c kh\u1ecfe", "-"],
            ["Ghi ch\u00fa",
             "Nursing Process, SOAP, SBAR v\u00e0 Gi\u00e1o d\u1ee5c s\u1ee9c kh\u1ecfe ch\u1ec9 "
             "\u0111\u01b0\u1ee3c ghi \u1edf m\u1ed1c th\u1eddi gian ghi nh\u1eadn \u0111\u1ea7u ti\u00ean c\u1ee7a ng\u01b0\u1eddi "
             "b\u1ec7nh."],
        ], [55 * mm, 124 * mm], header=False))
        return
    def emit_education(row, index, snapshot, extras, section_times):
        # Health education: the full record version, i.e. the ten teaching
        # topics plus the nurse's needs assessment and teach-back notes. The
        # separate patient handout deliberately prints the topics only.
        education = normalize_health_education(
            row.get("health_education", {})
        )
        story.append(Paragraph(
            "Giáo dục sức khỏe - Health education", styles["EntryTitle"]
        ))
        if health_education_is_empty(education):
            # Nothing was taught or assessed yet: print the heading and a
            # single blank line. Listing twenty empty rows would bury the
            # entries that do have content.
            story.append(Spacer(1, 11))
        else:
            # As soon as anything is documented the whole block is printed -
            # all ten needs-assessment fields and all ten teaching topics -
            # so a blank row reads as "not covered", not as "cut from the
            # export".
            story.append(data_table(
                [["Mục", "Nội dung"]] + [
                    [label, education["meta"].get(key, "")]
                    for key, label in HEALTH_EDUCATION_META_FIELDS
                ],
                [62 * mm, 117 * mm],
            ))
            story.append(data_table(
                [["Nhóm nội dung", "Đã hướng dẫn"]] + [
                    [label, education["topics"].get(key, "")]
                    for key, label, _hint in HEALTH_EDUCATION_TOPICS
                ],
                [62 * mm, 117 * mm],
            ))
    def emit_tail(row, index, snapshot, extras, section_times):
        # SOAP/SBAR sống trong extras, bản ghi rất cũ thì nằm thẳng ở snapshot.
        soap = extras.get("soap", snapshot.get("soap", {}))
        sbar = extras.get("sbar", snapshot.get("sbar", {}))
        story.append(data_table([
            ["Care level", extras.get("care_level", "")],
            ["Intake/output entries", extras.get("io_entries", [])],
            ["Nutrition / care regimen", row["csdd"]],
            ["Health education", row["gdsk"]],
            ["Additional monitoring", row["bg"]],
            ["Evaluation status", snapshot.get(
                "evaluation_status", extras.get("eval_status", "")
            )],
            ["Evaluation note", snapshot.get(
                "evaluation_note", extras.get("eval_note", "")
            )],
        ], [55 * mm, 124 * mm], header=False))
        story.append(Paragraph("SOAP", styles["EntryTitle"]))
        story.append(data_table([
            ["S - Subjective", soap.get("S", "") if isinstance(soap, dict) else soap],
            ["O - Objective", soap.get("O", "") if isinstance(soap, dict) else ""],
            ["A - Assessment", soap.get("A", "") if isinstance(soap, dict) else ""],
            ["P - Plan", soap.get("P", "") if isinstance(soap, dict) else ""],
        ], [42 * mm, 137 * mm], header=False))
        story.append(Paragraph("SBAR", styles["EntryTitle"]))
        story.append(data_table([
            ["S - Situation", sbar.get("S", "") if isinstance(sbar, dict) else sbar],
            ["B - Background", sbar.get("B", "") if isinstance(sbar, dict) else ""],
            ["A - Assessment", sbar.get("A", "") if isinstance(sbar, dict) else ""],
            ["R - Recommendation", sbar.get("R", "") if isinstance(sbar, dict) else ""],
        ], [42 * mm, 137 * mm], header=False))


    full_records = [
        (index, row)
        for index, row in enumerate(report_data["nursing_care"], 1)
        if row.get("is_first_timepoint", True)
    ]
    followup_records = [
        (index, row)
        for index, row in enumerate(report_data["nursing_care"], 1)
        if not row.get("is_first_timepoint", True)
    ]

    # ---- 4.2 Nursing Assessment (kèm bảng theo dõi dịch vào - dịch ra) ----
    story.append(Paragraph(
        "4.2 Nh\u1eadn \u0111\u1ecbnh \u0111i\u1ec1u d\u01b0\u1ee1ng - "
        "Nursing Assessment", styles["SectionTitle"],
    ))
    if not full_records:
        story.append(paragraph(
            "Ch\u01b0a c\u00f3 m\u1ed1c ghi nh\u1eadn n\u00e0o c\u00f3 "
            "Nursing Process trong k\u1ef3 b\u00e1o c\u00e1o."
        ))
    for index, row in full_records:
        snapshot, extras, section_times = record_context(row)
        record_title(row, index)
        emit_assessment(row, index, snapshot, extras, section_times)

    # ---- 4.3 Hỗ trợ lâm sàng ---------------------------------------------
    if full_records:
        story.append(Paragraph(
            "4.3 H\u1ed7 tr\u1ee3 l\u00e2m s\u00e0ng - Clinical support",
            styles["SectionTitle"],
        ))
        for index, row in full_records:
            snapshot, extras, section_times = record_context(row)
            record_title(row, index)
            emit_clinical_support(row, index, snapshot, extras, section_times)

    # ---- 4.4 Kế hoạch chăm sóc điều dưỡng (bốn cột) ----------------------
    if full_records:
        story.append(Paragraph(
            "4.4 K\u1ebf ho\u1ea1ch ch\u0103m s\u00f3c \u0111i\u1ec1u "
            "d\u01b0\u1ee1ng - Nursing Care Plan", styles["SectionTitle"],
        ))
        story.append(paragraph(
            "Tr\u00edch t\u1eeb Nursing Process c\u1ee7a ch\u00ednh "
            "ng\u01b0\u1eddi b\u1ec7nh: m\u1ed7i ch\u1ea9n \u0111o\u00e1n "
            "\u0111i\u1ec1u d\u01b0\u1ee1ng \u0111i k\u00e8m m\u1ee5c "
            "ti\u00eau, can thi\u1ec7p v\u00e0 l\u01b0\u1ee3ng gi\u00e1 "
            "c\u1ee7a ch\u00ednh n\u00f3."
        ))
        for index, row in full_records:
            snapshot, extras, section_times = record_context(row)
            record_title(row, index)
            plan_rows = _pdf_care_plan_rows(row, extras)
            if len(plan_rows) > 1:
                story.append(data_table(
                    plan_rows, [46 * mm, 44 * mm, 45 * mm, 44 * mm],
                ))
            else:
                story.append(data_table([[
                    "K\u1ebf ho\u1ea1ch ch\u0103m s\u00f3c",
                    "Ch\u01b0a nh\u1eadp / Not documented.",
                ]], [55 * mm, 124 * mm], header=False))
            emit_procedures(row, index, snapshot, extras, section_times)

    # ---- 4.5 Các mốc theo dõi sinh hiệu tiếp theo ------------------------
    if followup_records:
        story.append(Paragraph(
            "4.5 C\u00e1c m\u1ed1c theo d\u00f5i sinh hi\u1ec7u ti\u1ebfp "
            "theo - v\u1ea5n \u0111\u1ec1 c\u1ee7a ng\u01b0\u1eddi "
            "b\u1ec7nh v\u00e0 can thi\u1ec7p", styles["SectionTitle"],
        ))
        for index, row in followup_records:
            snapshot, extras, section_times = record_context(row)
            record_title(row, index)
            emit_followup(row, index, snapshot, extras, section_times)

    # ---- 4.6 Giáo dục sức khỏe -------------------------------------------
    if full_records:
        story.append(Paragraph(
            "4.6 Gi\u00e1o d\u1ee5c s\u1ee9c kh\u1ecfe - Health education",
            styles["SectionTitle"],
        ))
        for index, row in full_records:
            snapshot, extras, section_times = record_context(row)
            record_title(row, index)
            emit_education(row, index, snapshot, extras, section_times)

    # ---- 4.7 Các phần còn lại của mỗi mốc ghi nhận ------------------------
    if full_records:
        story.append(Paragraph(
            "4.7 SOAP, SBAR v\u00e0 l\u01b0\u1ee3ng gi\u00e1 chung",
            styles["SectionTitle"],
        ))
        for index, row in full_records:
            snapshot, extras, section_times = record_context(row)
            record_title(row, index)
            emit_tail(row, index, snapshot, extras, section_times)

    story.append(PageBreak())
    story.append(Paragraph("5. Nursing execution of Orders",
                           styles["SectionTitle"]))
    execution_rows = [[
        "Performed time", "Linked records", "Order / action",
        "Response, adverse effect and escalation",
    ]]
    for row in report_data["order_executions"]:
        execution_rows.append([
            row.get("performed_dt", ""),
            "Order #%s\n%s\n%s" % (
                row.get("order_id", ""),
                # Ghi thẳng ở trang người bệnh thì không gắn mốc Nursing
                # Care nào, in "Care #None" chỉ làm người đọc bối rối.
                "Care #%s" % row["care_id"]
                if row.get("care_id") not in (None, "", 0)
                else "Ghi ở trang người bệnh",
                row.get("nurse_name", "")
            ),
            "%s\n%s" % (
                row.get("category", ""), row.get("order_text", "")
            ),
            "Response/action: %s\nSide effect: %s\nAbnormal/escalation: %s" % (
                row.get("drug_action", ""), row.get("side_effect", ""),
                row.get("abnormal_note", "")
            ),
        ])
    story.append(data_table(
        execution_rows if len(execution_rows) > 1 else
        [["Execution", "No documented order execution in the selected period.",
          "", ""]],
        [36 * mm, 38 * mm, 49 * mm, 56 * mm],
        header=len(execution_rows) > 1,
    ))

    def page_frame(canvas, document):
        canvas.saveState()
        canvas.setFont(regular_font, 7)
        canvas.setFillColor(colors.HexColor("#536b86"))
        canvas.drawString(
            14 * mm, 9 * mm,
            "Patient ID: %s | Confidential clinical record"
            % patient.get("id", "")
        )
        canvas.drawRightString(
            A4[0] - 14 * mm, 9 * mm, "Page %d" % document.page
        )
        canvas.setStrokeColor(colors.HexColor("#b8c7d5"))
        canvas.line(14 * mm, 13 * mm, A4[0] - 14 * mm, 13 * mm)
        canvas.restoreState()

    doc.build(story, onFirstPage=page_frame, onLaterPages=page_frame)
    return output.getvalue()


def build_student_reviews_report_data(connection, student_username="",
                                      date_from="", date_to="",
                                      period_label="All dates",
                                      included_sections=None):
    """Collect complete clinical reviews and skill practice by student/date."""
    included_sections = _student_review_report_sections(included_sections)
    student_rows = _query_dict_rows(
        connection,
        """SELECT username,nurse_code,full_name,role FROM users
           WHERE lower(role)='student'
           ORDER BY full_name COLLATE NOCASE,username""",
    )
    if student_username:
        student_rows = [
            row for row in student_rows
            if str(row["username"]) == str(student_username)
        ]
    students = {
        str(row["username"]): {
            "profile": row, "triage_records": [], "care_records": [],
            "orders": [], "lab_results": [], "order_executions": [],
            "coaching": [],
            "technique_assessments": [], "target_progress": [],
            "courses": [],
        }
        for row in student_rows
    }
    care_rows = _query_dict_rows(
        connection,
        """SELECT n.care_id,n.patient_id,n.care_dt,n.nurse_code,n.nurse_name,
                  n.vitals,n.exam_summary,n.dx_list,n.ct_list,n.csdd,n.gdsk,
                  n.bg,n.snapshot,p.name AS patient_name,p.dob,p.gender,
                  p.diagnosis,p.department,
                  r.student_username AS review_student_username,
                  r.student_code AS review_student_code,
                  r.student_name AS review_student_name,
                  r.instructor_username,r.instructor_code,r.instructor_name,
                  r.score,r.score_scale,r.comment,r.section_reviews,r.reviewed_dt
           FROM nursing_care n
           LEFT JOIN patients p ON p.id=n.patient_id
           LEFT JOIN student_reviews r ON r.care_id=n.care_id
           ORDER BY datetime(n.care_dt),n.care_id""",
    )
    for row in care_rows:
        care_date = str(row.get("care_dt") or "")[:10]
        if date_from and care_date < date_from:
            continue
        if date_to and care_date > date_to:
            continue
        snapshot = _decoded_json(row.get("snapshot"), {})
        username = str(
            row.get("review_student_username")
            or snapshot.get("student_username", "") or ""
        )
        if username not in students:
            continue
        row["snapshot"] = snapshot
        for key, default in (
            ("vitals", {}), ("exam_summary", []), ("dx_list", []),
            ("ct_list", []), ("csdd", []), ("gdsk", []), ("bg", []),
        ):
            row[key] = _decoded_json(row.get(key), default)
        # Techniques the student actually performed, for the review PDF.
        try:
            row["procedures"] = load_nursing_procedures(
                connection, care_id=row.get("care_id")
            )
        except sqlite3.Error:
            row["procedures"] = []
        # Giáo dục sức khỏe nằm ở bảng riêng health_education_records chứ
        # không còn ở cột nursing_care.gdsk, nên phải nạp từ đó. Đọc cột cũ
        # thì bản in luôn trống dù điều dưỡng đã ghi đầy đủ.
        try:
            row["health_education"] = load_health_education(
                connection, care_id=row.get("care_id")
            )
        except sqlite3.Error:
            row["health_education"] = normalize_health_education({})
        sections = _section_scores_to_100(
            _decoded_json(row.get("section_reviews"), {}),
            row.get("score_scale", 100),
        )
        row["normalized_section_reviews"] = sections
        row["normalized_nursing_score"] = _nursing_review_score(
            sections, _score_to_100(
                row.get("score"), int(row.get("score_scale") or 100)
            )
        )
        triage_rows = _query_dict_rows(
            connection,
            """SELECT triage_id,triage_dt,nurse_code,nurse_name,
                      triage_data,source
               FROM triage_records WHERE patient_id=?
               ORDER BY datetime(triage_dt),triage_id""",
            (row["patient_id"],),
        )
        care_dt = _clinical_datetime_value(row.get("care_dt"))
        closest = None
        if triage_rows:
            closest = min(
                triage_rows,
                key=lambda item: (
                    abs((
                        (_clinical_datetime_value(item.get("triage_dt"))
                         or datetime.min) - (care_dt or datetime.min)
                    ).total_seconds())
                ),
            )
            closest_triage_data = _decoded_json(
                closest.get("triage_data"), {}
            )
            profile = students[username]["profile"]
            entered_username = str(
                closest_triage_data.get("entered_by_username", "") or ""
            ).strip().lower()
            triage_code = str(
                closest.get("nurse_code") or ""
            ).strip().lower()
            triage_name = str(
                closest.get("nurse_name") or ""
            ).strip().lower()
            attributable = bool(
                (entered_username and entered_username == username.lower())
                or (
                    triage_code
                    and triage_code == str(
                        profile.get("nurse_code") or ""
                    ).strip().lower()
                )
                or (
                    triage_name
                    and triage_name == str(
                        profile.get("full_name") or ""
                    ).strip().lower()
                )
            )
            closest = {
                "triage_datetime": closest.get("triage_dt", ""),
                "nurse_code": closest.get("nurse_code", ""),
                "nurse_name": closest.get("nurse_name", ""),
                "source": closest.get("source", ""),
                "is_selected_student_triage": attributable,
                "triage": closest_triage_data,
            }
        row["linked_triage"] = closest
        students[username]["care_records"].append(row)

    triage_rows = _query_dict_rows(
        connection,
        """SELECT t.triage_id,t.patient_id,p.name AS patient_name,
                  t.triage_dt,t.nurse_code,t.nurse_name,t.triage_data,t.source
           FROM triage_records t
           LEFT JOIN patients p ON p.id=t.patient_id
           ORDER BY datetime(t.triage_dt),t.triage_id""",
    )
    for row in triage_rows:
        triage_date = str(row.get("triage_dt") or "")[:10]
        if date_from and triage_date < date_from:
            continue
        if date_to and triage_date > date_to:
            continue
        triage_data = _decoded_json(row.get("triage_data"), {})
        entered_username = str(
            triage_data.get("entered_by_username", "") or ""
        ).strip().lower()
        nurse_code = str(row.get("nurse_code") or "").strip().lower()
        nurse_name = str(row.get("nurse_name") or "").strip().lower()
        for username, student in students.items():
            profile = student["profile"]
            matches = (
                entered_username == username.strip().lower()
                if entered_username else
                (
                    bool(nurse_code)
                    and nurse_code
                    == str(profile.get("nurse_code") or "").strip().lower()
                )
                or (
                    bool(nurse_name)
                    and nurse_name
                    == str(profile.get("full_name") or "").strip().lower()
                )
            )
            if not matches:
                continue
            student["triage_records"].append({
                "triage_datetime": row.get("triage_dt", ""),
                "nurse_code": row.get("nurse_code", ""),
                "nurse_name": row.get("nurse_name", ""),
                "source": row.get("source", ""),
                "patient_id": row.get("patient_id", ""),
                "patient_name": row.get("patient_name", ""),
                "is_selected_student_triage": True,
                "triage": triage_data,
            })
            break

    def dated_rows(sql, username):
        rows = _query_dict_rows(connection, sql, (username,))
        filtered = []
        for row in rows:
            value = str(
                row.get("report_date") or row.get("practice_date")
                or row.get("assessment_date") or row.get("note_date") or ""
            )[:10]
            if date_from and value < date_from:
                continue
            if date_to and value > date_to:
                continue
            filtered.append(row)
        return filtered

    for username, student in students.items():
        profile = student["profile"]
        student_code = str(profile.get("nurse_code") or "")
        student_name = str(profile.get("full_name") or "")
        student["orders"] = dated_rows(
            """SELECT o.order_id,o.patient_id,p.name AS patient_name,
                      o.created_dt AS report_date,o.category,o.item_name,
                      o.strength,o.dose,o.route,o.frequency_per_day,o.details,
                      o.doctor_name,o.scheduled_start_dt,o.scheduled_end_dt,
                      o.status,o.entered_by_role,o.source
               FROM physician_orders o
               LEFT JOIN patients p ON p.id=o.patient_id
               WHERE o.entered_by_username=?
               ORDER BY datetime(o.created_dt),o.order_id""",
            username,
        )
        result_rows = _query_dict_rows(
            connection,
            """SELECT r.result_id,r.patient_id,p.name AS patient_name,
                      r.result_dt AS report_date,r.order_id,r.result_type,
                      r.test_name,r.result_value,r.unit,r.reference_range,
                      r.interpretation,r.entered_by_code,r.entered_by_name,
                      r.source,o.details AS order_details
               FROM lab_imaging_results r
               LEFT JOIN patients p ON p.id=r.patient_id
               LEFT JOIN physician_orders o ON o.order_id=r.order_id
               WHERE (trim(?)<>''
                      AND lower(trim(COALESCE(r.entered_by_code,'')))=
                          lower(trim(?)))
                  OR (trim(?)<>''
                      AND lower(trim(COALESCE(r.entered_by_name,'')))=
                          lower(trim(?)))
               ORDER BY datetime(r.result_dt),r.result_id""",
            (student_code, student_code, student_name, student_name),
        )
        student["lab_results"] = [
            row for row in result_rows
            if (not date_from or str(row.get("report_date") or "")[:10]
                >= date_from)
            and (not date_to or str(row.get("report_date") or "")[:10]
                 <= date_to)
        ]
        execution_rows = _query_dict_rows(
            connection,
            """SELECT x.record_id,x.patient_id,p.name AS patient_name,
                      x.performed_dt AS report_date,x.care_id,x.order_id,
                      x.category,x.order_text,x.drug_action,x.side_effect,
                      x.abnormal_note,x.nurse_code,x.nurse_name,x.source,
                      o.item_name,o.details AS order_details
               FROM nursing_med_records x
               LEFT JOIN patients p ON p.id=x.patient_id
               LEFT JOIN physician_orders o ON o.order_id=x.order_id
               WHERE (trim(?)<>''
                      AND lower(trim(COALESCE(x.nurse_code,'')))=
                          lower(trim(?)))
                  OR (trim(?)<>''
                      AND lower(trim(COALESCE(x.nurse_name,'')))=
                          lower(trim(?)))
               ORDER BY datetime(x.performed_dt),x.record_id""",
            (student_code, student_code, student_name, student_name),
        )
        student["order_executions"] = [
            row for row in execution_rows
            if (not date_from or str(row.get("report_date") or "")[:10]
                >= date_from)
            and (not date_to or str(row.get("report_date") or "")[:10]
                 <= date_to)
        ]
        student["coaching"] = dated_rows(
            """SELECT note_id,note_date AS report_date,reminder_note,
                      improvement_goal,improvement_note,status,
                      created_by_username,created_by_name,source,
                      created_dt,updated_dt
               FROM student_daily_coaching WHERE student_username=?
               ORDER BY note_date,note_id""",
            username,
        )
        assessments = dated_rows(
            """SELECT a.assessment_id,a.assessment_date AS report_date,
                      ROUND(COALESCE(
                          a.overall_percent,
                          CASE WHEN COALESCE(a.overall_score,0) BETWEEN 0 AND 4
                               THEN COALESCE(a.overall_score,0)*25.0
                               ELSE COALESCE(a.overall_score,0) END
                      ),2) AS overall_score,
                      a.note,a.assessor_username,
                      a.assessor_name,a.source,a.created_dt,a.updated_dt,
                      t.category,t.technique_name,t.description
               FROM student_technique_assessments a
               JOIN nursing_techniques t ON t.technique_id=a.technique_id
               WHERE a.student_username=?
               ORDER BY a.assessment_date,a.assessment_id""",
            username,
        )
        for assessment in assessments:
            assessment["checklist_results"] = _query_dict_rows(
                connection,
                """SELECT i.item_order,i.item_text,
                          ROUND(COALESCE(
                              r.score_percent,
                              CASE WHEN COALESCE(r.score,0) BETWEEN 0 AND 4
                                   THEN COALESCE(r.score,0)*25.0
                                   ELSE COALESCE(r.score,0) END
                          ),2) AS score,
                          r.note
                   FROM student_technique_results r
                   JOIN nursing_technique_items i ON i.item_id=r.item_id
                   WHERE r.assessment_id=?
                   ORDER BY i.item_order,i.item_id""",
                (assessment["assessment_id"],),
            )
        student["technique_assessments"] = assessments
        student["target_progress"] = dated_rows(
            """SELECT p.progress_id,p.practice_date AS report_date,
                      p.daily_count,p.weekly_count,p.total_count,p.note,
                      p.confirmed_by,p.confirmed_dt,
                      t.course_name,t.category,t.target_text,t.requirement
               FROM student_target_progress p
               JOIN nur410_targets t ON t.target_id=p.target_id
               WHERE p.student_username=?
               ORDER BY p.practice_date,t.course_name,t.category,t.target_text""",
            username,
        )
        student["courses"] = [
            row["course_name"] for row in _query_dict_rows(
                connection,
                """SELECT course_name FROM nur410_class_students
                   WHERE student_username=?
                   ORDER BY course_name COLLATE NOCASE""",
                (username,),
            )
        ]
    return {
        "students": list(students.values()),
        "date_from": date_from, "date_to": date_to,
        "period_label": period_label,
        "included_sections": included_sections,
        "generated_dt": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }


def generate_classroom_roster_pdf(classroom, students, instructors, language="en"):
    """Create a printable roster for one exact subject/group assignment."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        from reportlab.platypus import (
            SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image,
        )
    except ImportError:
        raise RuntimeError("PDF support requires reportlab.")
    regular_font, bold_font = "Helvetica", "Helvetica-Bold"
    for regular_path, bold_path in (
        (
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"), "Fonts", "arial.ttf"),
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"), "Fonts", "arialbd.ttf"),
        ),
        (
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        ),
    ):
        if os.path.exists(regular_path):
            pdfmetrics.registerFont(TTFont("ClassRosterUnicode", regular_path))
            regular_font = "ClassRosterUnicode"
            if os.path.exists(bold_path):
                pdfmetrics.registerFont(TTFont("ClassRosterUnicodeBold", bold_path))
                bold_font = "ClassRosterUnicodeBold"
            else:
                bold_font = regular_font
            break
    output = io.BytesIO()
    doc = SimpleDocTemplate(
        output, pagesize=A4, leftMargin=14 * mm, rightMargin=14 * mm,
        topMargin=12 * mm, bottomMargin=14 * mm,
        title="Classroom Student Roster", author="EIU Mobile Nursing Care",
    )
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="RosterTitle", parent=styles["Title"], fontName=bold_font,
        fontSize=15, leading=18, textColor=colors.HexColor("#16456f"),
        spaceAfter=6,
    ))
    styles.add(ParagraphStyle(
        name="RosterBody", parent=styles["BodyText"], fontName=regular_font,
        fontSize=9, leading=12, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="RosterSmall", parent=styles["BodyText"], fontName=regular_font,
        fontSize=8, leading=10, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="RosterHeader", parent=styles["BodyText"], fontName=bold_font,
        fontSize=8, leading=10, textColor=colors.white, wordWrap="CJK",
    ))

    def p(value, style="RosterBody"):
        return Paragraph(
            html.escape(str(value or "-")).replace("\n", "<br/>"),
            styles[style],
        )

    story = _eiu_pdf_logo_flowables()
    title = (
        "DANH SÁCH SINH VIÊN THEO NHÓM"
        if normalize_app_language(language) == "vi"
        else "CLASSROOM STUDENT ROSTER"
    )
    story.append(Paragraph(title, styles["RosterTitle"]))
    subject_code = classroom.get("subject_code") or classroom.get("class_code")
    meta_rows = [
        [p("Mã môn học / Subject code"), p(subject_code),
         p("Tên lớp / Class name"), p(classroom.get("class_name"))],
        [p("Nhóm / Group"), p(classroom.get("group_number") or "1"),
         p("Quý / Quarter"), p(translate_ui_text(
             classroom.get("semester") or "-", language
         ))],
        [p("Năm học / Academic year"), p(classroom.get("academic_year")),
         p("Khoa / Department"), p(classroom.get("department"))],
        [p("Giảng viên / Instructors"), p(", ".join(
             str(row.get("full_name") or row.get("username") or "")
             for row in instructors
         ) or "-"), p("Số sinh viên / Students"), p(len(students))],
    ]
    meta = Table(meta_rows, colWidths=[39 * mm, 49 * mm, 39 * mm, 49 * mm])
    meta.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, -1), regular_font),
        ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#eaf2f8")),
        ("BACKGROUND", (2, 0), (2, -1), colors.HexColor("#eaf2f8")),
        ("GRID", (0, 0), (-1, -1), .5, colors.HexColor("#9fb3c8")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    story.extend([meta, Spacer(1, 5 * mm)])
    rows = [[
        p("STT", "RosterHeader"), p("Mã SV / ID", "RosterHeader"),
        p("Họ và tên / Full name", "RosterHeader"),
        p("Năm sinh / Birth year", "RosterHeader"),
        p("Khoa / Department", "RosterHeader"),
    ]]
    for index, student in enumerate(students, 1):
        rows.append([
            p(index, "RosterSmall"),
            p(student.get("nurse_code") or student.get("username"), "RosterSmall"),
            p(student.get("full_name"), "RosterSmall"),
            p(student.get("birth_year") or "-", "RosterSmall"),
            p(student.get("department") or "-", "RosterSmall"),
        ])
    roster = Table(
        rows, colWidths=[12 * mm, 32 * mm, 58 * mm, 27 * mm, 47 * mm],
        repeatRows=1,
    )
    roster.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, -1), regular_font),
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#16456f")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("GRID", (0, 0), (-1, -1), .45, colors.HexColor("#b6c5d3")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#f6f9fc")]),
        ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    story.append(roster)
    doc.build(story)
    return output.getvalue()


def generate_student_reviews_report_pdf(report_data):
    """Render complete Student Reviews and skill-practice data as PDF."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        from reportlab.platypus import (
            SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak,
            KeepTogether, CondPageBreak,
        )
    except ImportError:
        raise RuntimeError(
            "PDF support requires the reportlab package in this application."
        )

    # Mốc thời gian lâm sàng in ra chỉ đến phút. Bọc Paragraph ngay tại đây để
    # áp dụng cho CẢ các tiêu đề mục gọi Paragraph() trực tiếp, không chỉ các ô
    # bảng đi qua hàm paragraph() bên dưới. Chỉ cắt khi giây đúng bằng 00 - dòng
    # "Generated" của bản in vẫn giữ giây thật vì đó là dấu vết kết xuất.
    _ReportlabParagraph = Paragraph
    report_vital_bold_thresholds = validated_vital_thresholds(
        report_data.get("vital_bold_thresholds"), "bold"
    )
    report_vital_bold_color = str(
        report_data.get("vital_bold_color", "#991b1b") or "#991b1b"
    )
    if not re.match(r"^#[0-9a-fA-F]{6}$", report_vital_bold_color):
        report_vital_bold_color = "#991b1b"

    def Paragraph(report_text, *args, **kwargs):
        return _ReportlabParagraph(
            strip_clinical_seconds(report_text), *args, **kwargs
        )
    regular_font, bold_font = "Helvetica", "Helvetica-Bold"
    for regular_path, bold_path in (
        (
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arial.ttf"),
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arialbd.ttf"),
        ),
        (
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        ),
    ):
        if os.path.exists(regular_path):
            pdfmetrics.registerFont(TTFont("StudentReviewUnicode", regular_path))
            regular_font = "StudentReviewUnicode"
            if os.path.exists(bold_path):
                pdfmetrics.registerFont(
                    TTFont("StudentReviewUnicodeBold", bold_path)
                )
                bold_font = "StudentReviewUnicodeBold"
            else:
                bold_font = regular_font
            break
    output = io.BytesIO()
    doc = SimpleDocTemplate(
        output, pagesize=A4, leftMargin=13 * mm, rightMargin=13 * mm,
        topMargin=18 * mm, bottomMargin=17 * mm,
        title="Student Reviews Clinical and Skill Practice Report",
        author="EMR",
    )
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="SRTitle", parent=styles["Title"], fontName=bold_font,
        fontSize=16, leading=20, alignment=TA_CENTER,
        textColor=colors.HexColor("#123b66"), spaceAfter=7,
    ))
    styles.add(ParagraphStyle(
        name="SRSection", parent=styles["Heading2"], fontName=bold_font,
        fontSize=11.5, leading=14, textColor=colors.white,
        backColor=colors.HexColor("#1f5f8b"), borderPadding=5,
        spaceBefore=9, spaceAfter=6,
    ))
    styles.add(ParagraphStyle(
        name="SREntry", parent=styles["Heading3"], fontName=bold_font,
        fontSize=9.5, leading=12, textColor=colors.HexColor("#123b66"),
        spaceBefore=6, spaceAfter=3,
    ))
    styles.add(ParagraphStyle(
        name="SRBody", parent=styles["BodyText"], fontName=regular_font,
        fontSize=7.8, leading=10, wordWrap="CJK", spaceAfter=2,
    ))
    styles.add(ParagraphStyle(
        name="SRSmall", parent=styles["BodyText"], fontName=regular_font,
        fontSize=7, leading=8.6, wordWrap="CJK",
    ))

    def p(value, style="SRBody"):
        text = html.escape(_patient_report_value(value)).replace("\n", "<br/>")
        return Paragraph(text or "-", styles[style])

    def vital_summary_p(vitals, style="SRSmall"):
        return Paragraph(
            _vital_summary_pdf_markup(
                vitals, report_vital_bold_thresholds,
                report_vital_bold_color,
            ),
            styles[style],
        )

    def table(rows, widths, header=True):
        converted = [
            [cell if hasattr(cell, "wrapOn") else p(cell, "SRSmall")
             for cell in row]
            for row in rows
        ]
        result = Table(
            converted, colWidths=widths,
            repeatRows=1 if header and converted else 0, hAlign="LEFT",
            # Clinical assessments and feedback can be longer than one page.
            # Permit ReportLab to split a single tall row across page frames
            # instead of raising LayoutError during PDF export.
            splitByRow=1, splitInRow=1,
        )
        commands = [
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("GRID", (0, 0), (-1, -1), .35, colors.HexColor("#b8c7d5")),
            ("LEFTPADDING", (0, 0), (-1, -1), 3),
            ("RIGHTPADDING", (0, 0), (-1, -1), 3),
            ("TOPPADDING", (0, 0), (-1, -1), 3),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
            ("ROWBACKGROUNDS", (0, 1 if header else 0), (-1, -1),
             [colors.white, colors.HexColor("#f6f9fc")]),
        ]
        if header:
            commands += [
                ("BACKGROUND", (0, 0), (-1, 0),
                 colors.HexColor("#dceaf5")),
                ("FONTNAME", (0, 0), (-1, 0), bold_font),
            ]
        result.setStyle(TableStyle(commands))
        return result

    included_sections = set(_student_review_report_sections(
        report_data.get("included_sections")
    ))
    included_labels = ", ".join(
        label for key, label in STUDENT_REVIEW_REPORT_SECTIONS
        if key in included_sections
    )

    def section_heading(title):
        if len(included_sections) == len(STUDENT_REVIEW_REPORT_SECTIONS):
            return title
        return re.sub(r"^[A-F]\.\s*", "", title)

    class FilteredStory(list):
        """Ignore flowables belonging to unchecked report sections."""

        enabled = True

        def append(self, item):
            if self.enabled:
                super().append(item)

    story = FilteredStory(_eiu_pdf_logo_flowables() + [
        Paragraph("STUDENT REVIEWS - CLINICAL AND SKILL PRACTICE",
                  styles["SRTitle"]),
        p("Report period: %s | Contents: %s | Generated: %s | Students: %d" % (
            report_data["period_label"], included_labels,
            report_data["generated_dt"], len(report_data["students"]),
        ), "SRSmall"),
        Spacer(1, 4),
    ])
    if not report_data["students"]:
        story.append(p("No student data matched the selected report filters."))
    for student_index, student in enumerate(report_data["students"], 1):
        story.enabled = True
        if student_index > 1:
            story.append(PageBreak())
        profile = student["profile"]
        story.append(Paragraph(
            "Student: %s" % (
                profile.get("full_name") or profile.get("username")
            ), styles["SRSection"],
        ))
        story.append(table([
            ["Username", profile.get("username", ""),
             "Student code", profile.get("nurse_code", "")],
            ["Courses", ", ".join(student["courses"]) or "-",
             "Report period", report_data["period_label"]],
        ], [28 * mm, 59 * mm, 29 * mm, 68 * mm], header=False))

        story.enabled = "nursing_care" in included_sections
        story.append(Paragraph(section_heading("A. Student Triage activity"),
                               styles["SRSection"]))
        if not student["triage_records"]:
            story.append(p("No student-attributed Triage record in this period."))
        for triage_index, triage in enumerate(
            student["triage_records"], 1
        ):
            story.append(Paragraph(
                "Triage %d - Patient %s (%s) - %s" % (
                    triage_index, triage.get("patient_name", ""),
                    triage.get("patient_id", ""),
                    triage.get("triage_datetime", ""),
                ), styles["SREntry"],
            ))
            story.append(p(_triage_review_summary(triage)))

        story.append(Paragraph(section_heading(
            "B. Clinical records and instructor reviews"
        ),
                               styles["SRSection"]))
        if not student["care_records"]:
            story.append(p("No student Nursing Care record in this period."))
        for record_index, row in enumerate(student["care_records"], 1):
            snapshot = row["snapshot"]
            extras = snapshot.get("extras", {})
            if not isinstance(extras, dict):
                extras = {}
            times = _normalized_section_datetimes(
                extras.get("section_datetimes", {}), row.get("care_dt", "")
            )
            soap = extras.get("soap", snapshot.get("soap", {}))
            sbar = extras.get("sbar", snapshot.get("sbar", {}))
            story.append(Paragraph(
                "Clinical record %d - Patient %s (%s) - %s" % (
                    record_index, row.get("patient_name", ""),
                    row.get("patient_id", ""), row.get("care_dt", ""),
                ), styles["SREntry"],
            ))
            story.append(table([
                ["Patient profile", "%s | %s | %s | %s" % (
                    row.get("dob", ""), row.get("gender", ""),
                    row.get("department", ""), row.get("diagnosis", "")
                )],
                ["Documented by", "%s (%s)" % (
                    row.get("nurse_name", ""), row.get("nurse_code", "")
                )],
                ["Care / Process / SOAP / SBAR times", "%s | %s | %s | %s" % (
                    times.get("care_time", ""), times.get("process", ""),
                    times.get("soap", ""), times.get("sbar", ""),
                )],
            ], [53 * mm, 131 * mm], header=False))
            story.append(Paragraph("Linked Triage", styles["SREntry"]))
            linked = row.get("linked_triage")
            story.append(p(
                _triage_review_summary(linked)
                if linked else "No linked Triage record."
            ))
            story.append(Paragraph("Nursing Process", styles["SREntry"]))
            story.append(table([
                ["Vital signs", vital_summary_p(row["vitals"])],
                ["Assessment", row["exam_summary"]],
                ["Nursing diagnoses and goals", row["dx_list"]],
                ["Care plan / interventions", row["ct_list"]],
                ["Procedure Implementation (quy trình kỹ thuật)", [
                    format_nursing_procedure_line(entry)
                    for entry in row.get("procedures", []) or []
                ] or "-"],
                ["Nutrition / monitoring",
                 {"nutrition": row["csdd"], "monitoring": row["bg"]}],
                ["Evaluation", {
                    "status": snapshot.get(
                        "evaluation_status", extras.get("eval_status", "")
                    ),
                    "time": extras.get("eval_time", ""),
                    "note": snapshot.get(
                        "evaluation_note", extras.get("eval_note", "")
                    ),
                }],
            ], [52 * mm, 132 * mm], header=False))
            story.append(Paragraph("SOAP and SBAR", styles["SREntry"]))
            story.append(table([
                ["SOAP", soap], ["SBAR", sbar],
            ], [35 * mm, 149 * mm], header=False))
            # ---- Giáo dục sức khỏe / Health education -------------------
            # In đủ phần đánh giá trước khi hướng dẫn, 10 nhóm nội dung và
            # phần xác nhận sau khi hướng dẫn. Ô trống nghĩa là "chưa hướng
            # dẫn mục này", không phải bị cắt khỏi bản in.
            education = normalize_health_education(
                row.get("health_education", {})
            )
            story.append(Paragraph(
                "Giáo dục sức khỏe - Health education", styles["SREntry"]
            ))
            if health_education_is_empty(education):
                story.append(p("Chưa ghi nội dung giáo dục sức khỏe cho mốc "
                               "này."))
            else:
                story.append(table(
                    [["Mục", "Nội dung"]] + [
                        [label, education["meta"].get(key, "")]
                        for key, label in HEALTH_EDUCATION_META_FIELDS
                    ],
                    [62 * mm, 122 * mm],
                ))
                story.append(table(
                    [["Nhóm nội dung", "Đã hướng dẫn"]] + [
                        [label, education["topics"].get(key, "")]
                        for key, label, _hint in HEALTH_EDUCATION_TOPICS
                    ],
                    [62 * mm, 122 * mm],
                ))
            sections = row["normalized_section_reviews"]
            review_rows = [["Section", "Score / 100", "Instructor feedback"]]
            for key, label in REVIEW_SECTION_FIELDS:
                item = sections.get(key, {})
                review_rows.append([
                    label,
                    "" if item.get("score") is None else item.get("score"),
                    item.get("comment", ""),
                ])
            story.append(Paragraph("Instructor review", styles["SREntry"]))
            story.append(table(
                review_rows, [38 * mm, 28 * mm, 118 * mm]
            ))
            story.append(KeepTogether([
                Paragraph("Overall instructor assessment",
                          styles["SREntry"]),
                table([
                    ["Nursing overall score (Triage excluded)",
                     row.get("normalized_nursing_score", "")],
                    ["Overall comment", row.get("comment", "")],
                    ["Instructor / reviewed time", "%s (%s) | %s" % (
                        row.get("instructor_name", ""),
                        row.get("instructor_code", ""),
                        row.get("reviewed_dt", ""),
                    )],
                ], [62 * mm, 122 * mm], header=False),
            ]))

        story.append(Paragraph(
            section_heading("C. Orders, results and nursing execution"),
            styles["SRSection"],
        ))
        order_rows = [[
            "Date / patient", "Order", "Schedule / status",
            "Details / simulation source",
        ]]
        for row in student["orders"]:
            order_rows.append([
                "%s\n%s (%s)" % (
                    row.get("report_date", ""),
                    row.get("patient_name", ""),
                    row.get("patient_id", ""),
                ),
                "#%s | %s\n%s %s | %s | %s/day" % (
                    row.get("order_id", ""), row.get("category", ""),
                    row.get("item_name", ""), row.get("strength", ""),
                    row.get("dose", ""), row.get("frequency_per_day", ""),
                ),
                "%s to %s\n%s" % (
                    row.get("scheduled_start_dt", ""),
                    row.get("scheduled_end_dt", ""),
                    row.get("status", ""),
                ),
                "%s\nDoctor: %s\n%s | %s" % (
                    row.get("details", ""), row.get("doctor_name", ""),
                    row.get("entered_by_role", ""), row.get("source", ""),
                ),
            ])
        story.append(Paragraph("Orders entered by the student",
                               styles["SREntry"]))
        story.append(table(
            order_rows if len(order_rows) > 1 else
            [["Orders", "No student-entered Order in this period.", "", ""]],
            [36 * mm, 52 * mm, 42 * mm, 54 * mm],
            header=len(order_rows) > 1,
        ))
        result_rows = [[
            "Date / patient", "Ordered test", "Result",
            "Interpretation / clinical indication",
        ]]
        for row in student["lab_results"]:
            result_rows.append([
                "%s\n%s (%s)" % (
                    row.get("report_date", ""),
                    row.get("patient_name", ""),
                    row.get("patient_id", ""),
                ),
                "#%s | %s\n%s" % (
                    row.get("order_id", ""), row.get("result_type", ""),
                    row.get("test_name", ""),
                ),
                "%s %s\nReference: %s" % (
                    row.get("result_value", ""), row.get("unit", ""),
                    row.get("reference_range", ""),
                ),
                "%s\nOrder indication: %s" % (
                    row.get("interpretation", ""),
                    row.get("order_details", ""),
                ),
            ])
        story.append(Paragraph(
            "Laboratory and Imaging results entered by the student",
            styles["SREntry"],
        ))
        story.append(table(
            result_rows if len(result_rows) > 1 else
            [["Results", "No student-entered result in this period.", "", ""]],
            [36 * mm, 47 * mm, 43 * mm, 58 * mm],
            header=len(result_rows) > 1,
        ))
        execution_rows = [[
            "Performed / patient", "Linked Order", "Nursing action",
            "Response / adverse or abnormal findings",
        ]]
        for row in student["order_executions"]:
            execution_rows.append([
                "%s\n%s (%s)" % (
                    row.get("report_date", ""),
                    row.get("patient_name", ""),
                    row.get("patient_id", ""),
                ),
                "#%s | %s\n%s" % (
                    row.get("order_id", ""), row.get("category", ""),
                    row.get("item_name", "") or row.get("order_text", ""),
                ),
                row.get("order_text", ""),
                "Response: %s\nSide effect: %s\nAbnormal: %s" % (
                    row.get("drug_action", ""),
                    row.get("side_effect", ""),
                    row.get("abnormal_note", ""),
                ),
            ])
        story.append(Paragraph(
            "Orders documented as performed by the student",
            styles["SREntry"],
        ))
        story.append(table(
            execution_rows if len(execution_rows) > 1 else
            [["Execution", "No documented student Order execution.", "", ""]],
            [36 * mm, 47 * mm, 47 * mm, 54 * mm],
            header=len(execution_rows) > 1,
        ))

        story.enabled = "skill_practice" in included_sections
        story.append(Paragraph(section_heading(
            "D. Daily coaching and improvement"
        ),
                               styles["SRSection"]))
        coaching_rows = [[
            "Date", "Reminder / issue", "Expected improvement",
            "Student response / status / recorder",
        ]]
        for row in student["coaching"]:
            coaching_rows.append([
                row.get("report_date", ""), row.get("reminder_note", ""),
                row.get("improvement_goal", ""),
                "%s\nStatus: %s\nRecorded by: %s\nUpdated: %s" % (
                    row.get("improvement_note", ""), row.get("status", ""),
                    row.get("created_by_name", ""), row.get("updated_dt", ""),
                ),
            ])
        story.append(table(
            coaching_rows if len(coaching_rows) > 1 else
            [["Coaching", "No coaching record.", "", ""]],
            [26 * mm, 48 * mm, 48 * mm, 62 * mm],
            header=len(coaching_rows) > 1,
        ))

        story.append(CondPageBreak(90 * mm))
        story.append(Paragraph(section_heading(
            "E. Nursing technique skill practice"
        ),
                               styles["SRSection"]))
        if not student["technique_assessments"]:
            story.append(p("No technique assessment in this period."))
        for assessment in student["technique_assessments"]:
            story.append(Paragraph(
                "%s - %s - %.2f%%" % (
                    assessment.get("report_date", ""),
                    assessment.get("technique_name", ""),
                    float(assessment.get("overall_score") or 0),
                ), styles["SREntry"],
            ))
            story.append(table([
                ["Category / description", "%s | %s" % (
                    assessment.get("category", ""),
                    assessment.get("description", ""),
                )],
                ["Assessor / feedback", "%s | %s" % (
                    assessment.get("assessor_name", ""),
                    assessment.get("note", ""),
                )],
            ], [48 * mm, 136 * mm], header=False))
            checklist_rows = [["Checklist item", "Result", "Item note"]]
            checklist_rows.extend([
                [item.get("item_text", ""), "%g%%" % float(
                    item.get("score") or 0
                ),
                 item.get("note", "")]
                for item in assessment["checklist_results"]
            ])
            story.append(table(
                checklist_rows, [110 * mm, 20 * mm, 54 * mm]
            ))

        progress_rows = [[
            "Date / course", "Category / target", "Counts",
            "Note / instructor confirmation",
        ]]
        for row in student["target_progress"]:
            progress_rows.append([
                "%s\n%s" % (
                    row.get("report_date", ""), row.get("course_name", "")
                ),
                "%s\n%s\nRequirement: %s" % (
                    row.get("category", ""), row.get("target_text", ""),
                    row.get("requirement", ""),
                ),
                "Daily: %s\nWeekly: %s\nTotal: %s" % (
                    row.get("daily_count", ""), row.get("weekly_count", ""),
                    row.get("total_count", ""),
                ),
                "%s\nConfirmed by: %s\n%s" % (
                    row.get("note", ""), row.get("confirmed_by", ""),
                    row.get("confirmed_dt", ""),
                ),
            ])
        story.enabled = "clinical_targets" in included_sections
        story.append(KeepTogether([
            Paragraph(section_heading(
                "F. Course target / skill-practice progress"
            ),
                      styles["SRSection"]),
            table(
                progress_rows if len(progress_rows) > 1 else
                [["Progress", "No target progress in this period.", "", ""]],
                [34 * mm, 62 * mm, 36 * mm, 52 * mm],
                header=len(progress_rows) > 1,
            ),
        ]))
        story.enabled = True

    def page_frame(canvas, document):
        canvas.saveState()
        canvas.setFont(regular_font, 7)
        canvas.setFillColor(colors.HexColor("#536b86"))
        canvas.drawString(
            13 * mm, 9 * mm,
            "Student Reviews | Confidential educational record"
        )
        canvas.drawRightString(
            A4[0] - 13 * mm, 9 * mm, "Page %d" % document.page
        )
        canvas.setStrokeColor(colors.HexColor("#b8c7d5"))
        canvas.line(13 * mm, 13 * mm, A4[0] - 13 * mm, 13 * mm)
        canvas.restoreState()

    doc.build(story, onFirstPage=page_frame, onLaterPages=page_frame)
    return output.getvalue()


# Monday..Sunday week that contains ``reference_date`` (SQLite expressions).
_TARGET_WEEK_START = "date(?,'weekday 0','-6 days')"
_TARGET_WEEK_END = "date(?,'weekday 0')"


def clinical_target_status(confirmed_total, pending_total, requirement):
    """Classify one student's progress on a single practice target.

    Shared by Mobile Web, the desktop app, and the PDF export so the
    remark column always agrees across all three:
      - met         Dat chi tieu (confirmed total >= requirement) -> green
      - in_progress Dang thuc hien - chua dat (submitted, not yet met) -> yellow
      - not_started Chua thuc hien (nothing submitted at all) -> red
      - not_set     Khong co yeu cau (requirement is 0/undefined) -> neutral
    Returns (status_key, label, bg_hex, fg_hex).
    """
    requirement = int(round(float(requirement or 0)))
    confirmed_total = int(round(float(confirmed_total or 0)))
    pending_total = int(round(float(pending_total or 0)))
    if requirement <= 0:
        return ("not_set", "Không có yêu cầu", "#e2e8f0", "#334155")
    if confirmed_total >= requirement:
        return ("met", "Đạt chỉ tiêu", "#dcfce7", "#166534")
    if confirmed_total > 0 or pending_total > 0:
        return ("in_progress", "Đang thực hiện - chưa đạt", "#fef9c3", "#854d0e")
    return ("not_started", "Chưa thực hiện", "#fee2e2", "#991b1b")


def clinical_course_pending_overview(
    connection, course_name, limit=200, class_id=0
):
    """Every unconfirmed daily submission in one course, newest date first.

    An instructor could previously only find a submission by guessing both
    the right student AND the right date: the page listed who submitted on
    the selected date, and the "other dates" list was scoped to whichever
    student happened to be selected. Anything submitted by another student
    on another date was invisible, so it sat waiting for confirmation with
    nothing on screen pointing to it.

    Returns [{"student_username", "full_name", "nurse_code",
              "practice_date", "pending", "entries"}], newest first.
    """
    if not course_name:
        return []
    try:
        class_filter = (
            " AND COALESCE(p.class_id,0) IN (0,?)" if class_id else ""
        )
        args = [course_name]
        if class_id:
            args.append(int(class_id))
        args.append(int(limit))
        rows = connection.execute(
            """SELECT p.student_username AS student_username,
                      p.practice_date AS practice_date,
                      COALESCE(u.full_name, p.student_username) AS full_name,
                      COALESCE(u.nurse_code, '') AS nurse_code,
                      COALESCE(SUM(p.daily_count),0) AS pending,
                      COUNT(*) AS entries
               FROM student_target_progress p
               JOIN nur410_targets t ON t.target_id=p.target_id
               LEFT JOIN users u ON u.username=p.student_username
               WHERE t.course_name=?
                 AND COALESCE(p.daily_count,0)>0
                  AND trim(COALESCE(p.note,''))=''%s
               GROUP BY p.student_username,p.practice_date,
                        u.full_name,u.nurse_code
               ORDER BY p.practice_date DESC,
                        full_name COLLATE NOCASE
               LIMIT ?""" % class_filter,
            args,
        ).fetchall()
    except sqlite3.Error:
        return []
    return [
        {
            "student_username": str(row["student_username"] or ""),
            "full_name": str(row["full_name"] or ""),
            "nurse_code": str(row["nurse_code"] or ""),
            "practice_date": str(row["practice_date"] or ""),
            "pending": int(round(float(row["pending"] or 0))),
            "entries": int(row["entries"] or 0),
        }
        for row in rows
    ]


def clinical_student_pending_totals(
    connection, course_name, practice_date="", class_id=0
):
    """Per-student confirmation backlog for one course.

    {username: {"pending_total", "pending_days", "pending_today",
                "confirmed_today", "submitted_today", "latest_pending_date"}}

    Shared by Mobile Web and the desktop dialog so both clients flag the
    same students as waiting, from the same rows.
    """
    totals = {}
    for entry in clinical_course_pending_overview(
        connection, course_name, class_id=class_id
    ):
        bucket = totals.setdefault(entry["student_username"], {
            "pending_total": 0, "pending_days": 0, "pending_today": 0,
            "confirmed_today": 0, "submitted_today": 0,
            "latest_pending_date": "",
        })
        bucket["pending_total"] += entry["pending"]
        bucket["pending_days"] += 1
        if not bucket["latest_pending_date"]:
            bucket["latest_pending_date"] = entry["practice_date"]
        if practice_date and entry["practice_date"] == practice_date:
            bucket["pending_today"] += entry["pending"]
    if not practice_date or not course_name:
        return totals
    try:
        class_filter = (
            " AND COALESCE(p.class_id,0) IN (0,?)" if class_id else ""
        )
        args = [course_name, practice_date]
        if class_id:
            args.append(int(class_id))
        rows = connection.execute(
            """SELECT p.student_username AS username,
                      COALESCE(SUM(p.daily_count),0) AS submitted,
                      COALESCE(SUM(CASE WHEN trim(COALESCE(p.note,''))<>''
                           THEN p.daily_count ELSE 0 END),0) AS confirmed
               FROM student_target_progress p
               JOIN nur410_targets t ON t.target_id=p.target_id
               WHERE t.course_name=? AND p.practice_date=?
                  AND COALESCE(p.daily_count,0)>0%s
               GROUP BY p.student_username""" % class_filter,
            args,
        ).fetchall()
    except sqlite3.Error:
        return totals
    for row in rows:
        bucket = totals.setdefault(str(row["username"]), {
            "pending_total": 0, "pending_days": 0, "pending_today": 0,
            "confirmed_today": 0, "submitted_today": 0,
            "latest_pending_date": "",
        })
        bucket["submitted_today"] = int(round(float(row["submitted"] or 0)))
        bucket["confirmed_today"] = int(round(float(row["confirmed"] or 0)))
    return totals


def build_clinical_target_report_data(
    connection, course_name, student_username, reference_date, class_id=0,
    context=None
):
    """Collect one student's practice-target results for a course.

    Shared by Mobile Web and the desktop app so the daily / weekly / whole-course
    review and the exported PDF stay identical on both platforms. Confirmed = the
    progress row carries a non-empty ``note`` (an Instructor/Admin confirmation);
    everything else is a pending student submission.
    """
    student = connection.execute(
        "SELECT username,full_name,nurse_code FROM users WHERE username=?",
        (student_username,),
    ).fetchone()
    full_name = (student["full_name"] if student else "") or student_username
    nurse_code = (student["nurse_code"] if student else "") or ""
    targets = connection.execute(
        """SELECT target_id,category,target_text,requirement
           FROM nur410_targets WHERE course_name=?
           ORDER BY parent_id,target_id""",
        (course_name,),
    ).fetchall()
    target_order = {int(t["target_id"]): index for index, t in enumerate(targets)}
    class_filter = " AND COALESCE(class_id,0) IN (0,?)" if class_id else ""
    aliased_class_filter = (
        " AND COALESCE(p.class_id,0) IN (0,?)" if class_id else ""
    )

    summary_rows = []
    course_required = course_confirmed = course_pending = 0
    week_confirmed_total = week_pending_total = 0
    for target in targets:
        tid = int(target["target_id"])
        # confirmed_by / confirmed_dt are read further down for the tooltip and
        # the PDF, so they must be part of this SELECT.
        today_args = [tid, student_username, reference_date]
        if class_id:
            today_args.append(int(class_id))
        today = connection.execute(
            """SELECT daily_count,note,confirmed_by,confirmed_dt
               FROM student_target_progress
               WHERE target_id=? AND student_username=? AND practice_date=?%s"""
            % class_filter,
            today_args,
        ).fetchone()
        agg_args = [
            reference_date, reference_date, reference_date, reference_date,
            tid, student_username,
        ]
        if class_id:
            agg_args.append(int(class_id))
        agg = connection.execute(
            """SELECT
                COALESCE(SUM(CASE WHEN trim(COALESCE(note,''))<>'' THEN daily_count ELSE 0 END),0) AS course_confirmed,
                COALESCE(SUM(CASE WHEN trim(COALESCE(note,''))='' THEN daily_count ELSE 0 END),0) AS course_pending,
                COALESCE(SUM(CASE WHEN trim(COALESCE(note,''))<>'' AND practice_date BETWEEN """
            + _TARGET_WEEK_START + " AND " + _TARGET_WEEK_END
            + """ THEN daily_count ELSE 0 END),0) AS week_confirmed,
                COALESCE(SUM(CASE WHEN trim(COALESCE(note,''))='' AND practice_date BETWEEN """
            + _TARGET_WEEK_START + " AND " + _TARGET_WEEK_END
            + """ THEN daily_count ELSE 0 END),0) AS week_pending
               FROM student_target_progress WHERE target_id=? AND student_username=?%s"""
            % class_filter,
            agg_args,
        ).fetchone()
        requirement = int(round(float(target["requirement"] or 0)))
        row = {
            "target_id": tid,
            "category": target["category"] or "",
            "target_text": target["target_text"] or "",
            "requirement": requirement,
            "done_today": int(round(float(today["daily_count"] or 0))) if today else 0,
            "today_exists": today is not None,
            "today_confirmed": bool(today and str(today["note"] or "").strip()),
            "today_confirmed_by": (today["confirmed_by"] or "") if today else "",
            "today_confirmed_dt": (today["confirmed_dt"] or "") if today else "",
            "week_confirmed": int(round(float(agg["week_confirmed"] or 0))),
            "week_pending": int(round(float(agg["week_pending"] or 0))),
            "course_confirmed": int(round(float(agg["course_confirmed"] or 0))),
            "course_pending": int(round(float(agg["course_pending"] or 0))),
        }
        row["remaining"] = max(0, requirement - row["course_confirmed"])
        status_key, status_label, status_bg, status_fg = clinical_target_status(
            row["course_confirmed"], row["course_pending"], requirement
        )
        row["status_key"] = status_key
        row["status_label"] = status_label
        row["status_bg"] = status_bg
        row["status_fg"] = status_fg
        summary_rows.append(row)
        course_required += requirement
        course_confirmed += row["course_confirmed"]
        course_pending += row["course_pending"]
        week_confirmed_total += row["week_confirmed"]
        week_pending_total += row["week_pending"]

    # Every dated submission for this student on this course, newest first, so an
    # instructor can review exactly what was entered day by day.
    daily_args = [course_name, student_username]
    if class_id:
        daily_args.append(int(class_id))
    daily_rows = connection.execute(
        """SELECT p.practice_date,p.target_id,p.daily_count,p.note,
                  p.confirmed_by,p.confirmed_dt,t.category,t.target_text
           FROM student_target_progress p
           JOIN nur410_targets t ON t.target_id=p.target_id
           WHERE t.course_name=? AND p.student_username=?
              AND COALESCE(p.daily_count,0)>0%s
           ORDER BY p.practice_date DESC,t.parent_id,t.target_id"""
        % aliased_class_filter,
        daily_args,
    ).fetchall()
    by_day = {}
    for r in daily_rows:
        day = r["practice_date"]
        confirmed = bool(str(r["note"] or "").strip())
        entry = {
            "target_id": int(r["target_id"]),
            "category": r["category"] or "",
            "target_text": r["target_text"] or "",
            "daily_count": int(round(float(r["daily_count"] or 0))),
            "confirmed": confirmed,
            "confirmed_by": r["confirmed_by"] or "",
            "confirmed_dt": r["confirmed_dt"] or "",
            "order": target_order.get(int(r["target_id"]), 9999),
        }
        by_day.setdefault(day, {"date": day, "entries": [], "confirmed": 0,
                                "pending": 0})
        bucket = by_day[day]
        bucket["entries"].append(entry)
        if confirmed:
            bucket["confirmed"] += entry["daily_count"]
        else:
            bucket["pending"] += entry["daily_count"]
    day_list = []
    for day in sorted(by_day.keys(), reverse=True):
        bucket = by_day[day]
        bucket["entries"].sort(key=lambda e: e["order"])
        day_list.append(bucket)

    week_start = connection.execute(
        "SELECT " + _TARGET_WEEK_START, (reference_date,)
    ).fetchone()[0]
    week_end = connection.execute(
        "SELECT " + _TARGET_WEEK_END, (reference_date,)
    ).fetchone()[0]

    # Subject / group / quarter / academic year of the classroom this report
    # belongs to. Supplied by the caller when a classroom is selected; derived
    # from the catalog otherwise so the header is never blank.
    if context is None:
        classroom = connection.execute(
            """SELECT COALESCE(NULLIF(trim(subject_code),''),class_code)
                          AS subject_code,
                      class_name,group_number,semester,academic_year
               FROM classrooms WHERE class_id=?""",
            (int(class_id or 0),),
        ).fetchone() if class_id else None
        catalog = connection.execute(
            """SELECT COALESCE(NULLIF(trim(subject_code),''),'') AS subject_code,
                      COALESCE(NULLIF(trim(subject_name),''),'') AS subject_name
               FROM nur410_courses WHERE course_name=?""",
            (course_name,),
        ).fetchone()
        derived_code, derived_name = split_legacy_course_name(course_name)
        context = {
            "subject_code": (
                (str(classroom["subject_code"] or "").strip()
                 if classroom else "")
                or (str(catalog["subject_code"]) if catalog else "")
                or derived_code
            ),
            "subject_name": (
                (str(catalog["subject_name"]) if catalog else "")
                or derived_name or course_name
            ),
            "group_number": (
                str(classroom["group_number"] or "").strip()
                if classroom else ""
            ),
            "semester": (
                str(classroom["semester"] or "").strip() if classroom else ""
            ),
            "academic_year": (
                str(classroom["academic_year"] or "").strip()
                if classroom else ""
            ),
            "class_name": (
                str(classroom["class_name"] or "").strip() if classroom else ""
            ),
        }
    context = dict(context)
    context.setdefault("semester_label", context.get("semester", ""))

    return {
        "course_name": course_name,
        "subject_code": context.get("subject_code", ""),
        "subject_name": context.get("subject_name", ""),
        "group_number": context.get("group_number", ""),
        "semester": context.get("semester", ""),
        "semester_label": context.get("semester_label", ""),
        "academic_year": context.get("academic_year", ""),
        "class_name": context.get("class_name", ""),
        "class_id": int(class_id or 0),
        "student_username": student_username,
        "student_full_name": full_name,
        "student_nurse_code": nurse_code,
        "reference_date": reference_date,
        "week_start": week_start,
        "week_end": week_end,
        "summary_rows": summary_rows,
        "days": day_list,
        "totals": {
            "required": course_required,
            "course_confirmed": course_confirmed,
            "course_pending": course_pending,
            "week_confirmed": week_confirmed_total,
            "week_pending": week_pending_total,
        },
        "generated_dt": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }


def generate_clinical_target_report_pdf(report, language=None):
    """Render one student's practice-target results as a PDF (filename by name).

    ``language`` selects the caption language; the figures are identical in
    both languages so an English and a Vietnamese export stay comparable.
    """
    report_language = normalize_app_language(
        language or report.get("language") or DEFAULT_APP_LANGUAGE
    )

    def label(text):
        return translate_ui_text(text, report_language)

    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        from reportlab.platypus import (
            SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle,
        )
    except ImportError:
        raise RuntimeError(
            "PDF support requires the reportlab package in this application."
        )
    regular_font, bold_font = "Helvetica", "Helvetica-Bold"
    for regular_path, bold_path in (
        (
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arial.ttf"),
            os.path.join(os.environ.get("WINDIR", "C:\\Windows"),
                         "Fonts", "arialbd.ttf"),
        ),
        (
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        ),
    ):
        if os.path.exists(regular_path):
            pdfmetrics.registerFont(TTFont("ClinicalTargetUnicode", regular_path))
            regular_font = "ClinicalTargetUnicode"
            if os.path.exists(bold_path):
                pdfmetrics.registerFont(
                    TTFont("ClinicalTargetUnicodeBold", bold_path)
                )
                bold_font = "ClinicalTargetUnicodeBold"
            else:
                bold_font = regular_font
            break
    output = io.BytesIO()
    doc = SimpleDocTemplate(
        output, pagesize=A4, leftMargin=13 * mm, rightMargin=13 * mm,
        topMargin=16 * mm, bottomMargin=16 * mm,
        title="Clinical practice targets - %s" % report.get("student_full_name", ""),
        author="EMR",
    )
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="CTTitle", parent=styles["Title"], fontName=bold_font,
        fontSize=15, leading=19, alignment=TA_CENTER,
        textColor=colors.HexColor("#123b66"), spaceAfter=4,
    ))
    styles.add(ParagraphStyle(
        name="CTSection", parent=styles["Heading2"], fontName=bold_font,
        fontSize=11, leading=13, textColor=colors.white,
        backColor=colors.HexColor("#1f5f8b"), borderPadding=5,
        spaceBefore=9, spaceAfter=5,
    ))
    styles.add(ParagraphStyle(
        name="CTBody", parent=styles["BodyText"], fontName=regular_font,
        fontSize=8, leading=10, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="CTSmall", parent=styles["BodyText"], fontName=regular_font,
        fontSize=7.4, leading=9, wordWrap="CJK",
    ))
    styles.add(ParagraphStyle(
        name="CTMuted", parent=styles["BodyText"], fontName=regular_font,
        fontSize=8, leading=10.5, textColor=colors.HexColor("#4b6076"),
    ))

    def cell(value, style="CTSmall"):
        text = html.escape("" if value is None else str(value)).replace("\n", "<br/>")
        return Paragraph(text or "-", styles[style])

    def styled_table(rows, widths, header=True, extra_commands=None):
        table = Table(rows, colWidths=widths, repeatRows=1 if header else 0)
        commands = [
            ("FONTNAME", (0, 0), (-1, -1), regular_font),
            ("FONTSIZE", (0, 0), (-1, -1), 7.4),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#c3d0dd")),
            ("ROWBACKGROUNDS", (0, 1 if header else 0), (-1, -1),
             [colors.white, colors.HexColor("#eef4fa")]),
            ("LEFTPADDING", (0, 0), (-1, -1), 3),
            ("RIGHTPADDING", (0, 0), (-1, -1), 3),
            ("TOPPADDING", (0, 0), (-1, -1), 2),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
        ]
        if extra_commands:
            commands += extra_commands
        if header:
            commands += [
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1f5f8b")),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                ("FONTNAME", (0, 0), (-1, 0), bold_font),
            ]
        table.setStyle(TableStyle(commands))
        return table

    story = _eiu_pdf_logo_flowables()
    story.append(Paragraph(
        html.escape(label("Clinical Practice Targets")), styles["CTTitle"]
    ))
    story.append(Paragraph(
        "%s (%s)" % (
            html.escape(str(report.get("student_full_name", ""))),
            html.escape(str(report.get("student_nurse_code", "") or "-")),
        ), styles["CTMuted"]
    ))
    # Spell out the subject and the exact class this report belongs to: the
    # same subject targets are used by several groups, quarters and academic
    # years, so an anonymous course label would make two reports look alike.
    story.append(Paragraph(
        " &nbsp;|&nbsp; ".join(
            "%s: %s" % (
                html.escape(label(caption)),
                html.escape(label(str(value))),
            )
            for caption, value in (
                ("Subject code", report.get("subject_code", "")),
                ("Subject name", report.get("subject_name", "")),
                ("Group", report.get("group_number", "")),
                ("Semester", report.get("semester_label")
                 or report.get("semester", "")),
                ("Academic year", report.get("academic_year", "")),
            ) if str(value or "").strip()
        ) or html.escape(str(report.get("course_name", ""))),
        styles["CTMuted"]
    ))
    totals = report.get("totals", {})
    # Weekly figures are deliberately not printed: the report tracks the daily
    # entry and the whole-course total only, matching Mobile Web and desktop.
    story.append(Paragraph(
        "%s %s &nbsp;|&nbsp; %s %d / %d (%s %d) &nbsp;|&nbsp; %s %s" % (
            html.escape(label("Reference date")),
            html.escape(str(report.get("reference_date", ""))),
            html.escape(label("Course confirmed")),
            totals.get("course_confirmed", 0), totals.get("required", 0),
            html.escape(label("pending")),
            totals.get("course_pending", 0),
            html.escape(label("Generated")),
            html.escape(str(report.get("generated_dt", ""))),
        ), styles["CTMuted"]
    ))
    story.append(Paragraph(
        html.escape(label(
            "Only Instructor/Admin-confirmed entries count toward the "
            "confirmed course total. Pending values are student submissions "
            "waiting for confirmation."
        )), styles["CTMuted"]
    ))
    story.append(Spacer(1, 4))

    story.append(Paragraph(label("A. Target summary"), styles["CTSection"]))
    # Page-1 summary is course-level only: no per-day column here. The
    # day-by-day figures are still printed in section B below.
    # This is a summary, so it carries one number per target: how much the
    # student has actually completed. Entries still waiting for confirmation
    # are not a summary figure - they are listed per day in section B.
    summary = [[
        cell(label("Group"), "CTSmall"),
        cell(label("Practice target"), "CTSmall"),
        cell(label("Required"), "CTSmall"),
        cell(label("Total completed"), "CTSmall"),
        cell(label("Remaining"), "CTSmall"),
        cell(label("Target status"), "CTSmall"),
    ]]
    status_bg_commands = []
    for row_index, row in enumerate(report.get("summary_rows", []), start=1):
        summary.append([
            cell(row["category"]), cell(row["target_text"]),
            cell(row["requirement"]),
            cell(row["course_confirmed"]),
            cell(row["remaining"]),
            cell(row.get("status_label", "")),
        ])
        status_bg = row.get("status_bg")
        status_fg = row.get("status_fg")
        if status_bg:
            status_bg_commands.append(
                ("BACKGROUND", (5, row_index), (5, row_index), colors.HexColor(status_bg))
            )
        if status_fg:
            status_bg_commands.append(
                ("TEXTCOLOR", (5, row_index), (5, row_index), colors.HexColor(status_fg))
            )
    if len(summary) == 1:
        summary.append([
            cell(label(
                "No practice targets are configured for this course."
            )), cell(""), cell(""), cell(""), cell(""), cell(""),
        ])
    story.append(styled_table(
        summary, [24 * mm, 62 * mm, 18 * mm, 28 * mm, 19 * mm, 28 * mm],
        extra_commands=status_bg_commands,
    ))

    story.append(Paragraph(label("B. Daily submissions"), styles["CTSection"]))
    day_rows = [[
        cell(label("Date"), "CTSmall"), cell(label("Group"), "CTSmall"),
        cell(label("Practice target"), "CTSmall"),
        cell(label("Done"), "CTSmall"),
        cell(label("Status"), "CTSmall"),
        cell(label("Confirmed by"), "CTSmall"),
    ]]
    for day in report.get("days", []):
        for index, entry in enumerate(day["entries"]):
            day_rows.append([
                cell(day["date"] if index == 0 else ""),
                cell(entry["category"]), cell(entry["target_text"]),
                cell(entry["daily_count"]),
                cell(label("Confirmed" if entry["confirmed"] else "Pending")),
                cell(entry["confirmed_by"] if entry["confirmed"] else "-"),
            ])
    if len(day_rows) == 1:
        day_rows.append([
            cell(label(
                "No dated submissions were recorded for this course."
            )), cell(""), cell(""), cell(""), cell(""), cell(""),
        ])
    story.append(styled_table(
        day_rows, [22 * mm, 24 * mm, 58 * mm, 14 * mm, 20 * mm, 30 * mm]
    ))

    def footer(canvas, document):
        canvas.saveState()
        canvas.setFont(regular_font, 7)
        canvas.setFillColor(colors.HexColor("#536b86"))
        canvas.drawString(
            13 * mm, 9 * mm,
            "%s | %s" % (
                label("Clinical practice targets"),
                report.get("student_full_name", ""),
            )
        )
        canvas.drawRightString(A4[0] - 13 * mm, 9 * mm, "Page %d" % document.page)
        canvas.setStrokeColor(colors.HexColor("#b8c7d5"))
        canvas.line(13 * mm, 13 * mm, A4[0] - 13 * mm, 13 * mm)
        canvas.restoreState()

    doc.build(story, onFirstPage=footer, onLaterPages=footer)
    return output.getvalue()


def build_patient_ai_review_data(
    connection, patient_id, selected_care_id,
    selected_student_username=""
):
    """Build one patient-level review from the complete care timeline."""
    patient = connection.execute(
        """SELECT dob,gender,diagnosis,department,address,
                  history_present_illness,past_medical_history,
                  family_history,allergies,allergy_status
           FROM patients WHERE id=?""", (patient_id,)
    ).fetchone()
    rows = connection.execute("""SELECT care_id,care_dt,nurse_code,nurse_name,
        vitals,exam_summary,dx_list,ct_list,csdd,gdsk,bg,snapshot FROM nursing_care
        WHERE patient_id=? ORDER BY datetime(care_dt),care_id""", (patient_id,)).fetchall()
    timeline = []
    selected_student_username = str(
        selected_student_username or ""
    ).strip().lower()
    selected_context = {
        "care_datetime": "",
        "student_username": "",
        "student_code": "",
        "student_name": "",
    }
    # Resolve the selected student's identity before walking the timeline so
    # every one of that student's entries can be marked for one patient-level
    # assessment, including entries recorded before the selected row.
    for row in rows:
        if int(row["care_id"]) != int(selected_care_id):
            continue
        selected_snapshot = _decoded_json(row["snapshot"], {})
        selected_context = {
            "care_datetime": str(row["care_dt"] or ""),
            "student_username": str(
                selected_student_username
                or selected_snapshot.get("student_username", "") or ""
            ),
            "student_code": str(
                selected_snapshot.get("student_code", "")
                or row["nurse_code"] or ""
            ),
            "student_name": str(
                selected_snapshot.get("student_name", "")
                or row["nurse_name"] or ""
            ),
        }
        break
    selected_username = selected_context["student_username"].strip().lower()
    selected_code = selected_context["student_code"].strip().lower()
    selected_name = selected_context["student_name"].strip().lower()
    same_care_ids = set()
    for sequence, row in enumerate(rows, 1):
        snapshot = _decoded_json(row["snapshot"], {})
        extras = snapshot.get("extras", {}) if isinstance(snapshot.get("extras"), dict) else {}
        section_datetimes = _normalized_section_datetimes(
            extras.get("section_datetimes", {}), row["care_dt"]
        )
        section_vitals = extras.get("section_vitals", {})
        if not isinstance(section_vitals, dict):
            section_vitals = {}
        record_vitals = _decoded_json(row["vitals"], {})
        row_username = str(
            snapshot.get("student_username", "") or ""
        ).strip().lower()
        row_code = str(
            snapshot.get("student_code", "") or row["nurse_code"] or ""
        ).strip().lower()
        row_name = str(
            snapshot.get("student_name", "") or row["nurse_name"] or ""
        ).strip().lower()
        same_student = bool(
            (selected_username and row_username == selected_username)
            or (selected_code and row_code == selected_code)
            or (selected_name and row_name == selected_name)
        )
        is_selected = (
            same_student
            if selected_student_username
            else int(row["care_id"]) == int(selected_care_id)
        )
        if is_selected:
            same_care_ids.add(int(row["care_id"]))
        timeline.append({
            "sequence": sequence,
            "care_datetime": str(row["care_dt"] or ""),
            "is_selected_student_record": is_selected,
            "nursing_care_time": {
                "care_datetime": section_datetimes["care_time"],
                "vital_signs_and_monitoring": section_vitals.get("care_time", record_vitals),
                "intake_output_entries": extras.get("io_entries", []),
                "care_level": extras.get("care_level", ""),
                "evaluation_time": extras.get("eval_time", ""),
            },
            "nursing_process": {
                "recorded_datetime": section_datetimes["process"],
                "vital_signs_at_documentation": section_vitals.get("process", record_vitals),
                "assessment": _decoded_json(row["exam_summary"], []),
                "assessment_categories": snapshot.get("mobile_assessment_categories", {}),
                "assessment_summary": snapshot.get("mobile_assessment", ""),
                "nursing_diagnoses": _decoded_json(row["dx_list"], []),
                "nursing_goals": snapshot.get("mobile_goal", ""),
                "care_plan_and_interventions": _decoded_json(row["ct_list"], []),
                "intervention_summary": snapshot.get("mobile_intervention", ""),
                "evaluation_status": snapshot.get(
                    "evaluation_status", extras.get("eval_status", "")
                ),
                "evaluation_note": snapshot.get(
                    "evaluation_note", extras.get("eval_note", "")
                ),
                "nutrition_or_care_regimen": _decoded_json(row["csdd"], []),
                "health_education": _decoded_json(row["gdsk"], []),
                "additional_monitoring": _decoded_json(row["bg"], []),
            },
            # SOAP and SBAR remain clinical documentation, but are deliberately
            # excluded from the AI student-assessment payload.
        })

    triage_timeline = []
    try:
        triage_rows = connection.execute(
            """SELECT triage_id,triage_dt,nurse_code,nurse_name,triage_data
               FROM triage_records WHERE patient_id=?
               ORDER BY datetime(triage_dt),triage_id""",
            (patient_id,),
        ).fetchall()
    except sqlite3.Error:
        triage_rows = []
    selected_dt = _clinical_datetime_value(selected_context["care_datetime"])
    for sequence, row in enumerate(triage_rows, 1):
        triage_data = _decoded_json(row["triage_data"], {})
        entered_username = str(
            triage_data.get("entered_by_username", "") or ""
        ).strip().lower()
        entered_code = str(row["nurse_code"] or "").strip().lower()
        entered_name = str(row["nurse_name"] or "").strip().lower()
        attributable = bool(
            (selected_username and entered_username == selected_username)
            or (selected_code and entered_code == selected_code)
            or (selected_name and entered_name == selected_name)
        )
        triage_dt = _clinical_datetime_value(row["triage_dt"])
        distance_seconds = (
            abs((triage_dt - selected_dt).total_seconds())
            if triage_dt is not None and selected_dt is not None else None
        )
        triage_timeline.append({
            "sequence": sequence,
            "triage_datetime": str(row["triage_dt"] or ""),
            "is_selected_student_triage": attributable,
            "seconds_from_selected_nursing_record": distance_seconds,
            "triage": triage_data,
        })
    closest_triage = None
    attributed = [
        item for item in triage_timeline if item["is_selected_student_triage"]
    ]
    eligible = attributed or triage_timeline
    if eligible:
        closest_triage = min(
            eligible,
            key=lambda item: (
                item["seconds_from_selected_nursing_record"] is None,
                item["seconds_from_selected_nursing_record"]
                if item["seconds_from_selected_nursing_record"] is not None else float("inf"),
                item["sequence"],
            ),
        )
        closest_triage["is_selected_for_review"] = True
    try:
        lab_rows = connection.execute(
            """SELECT result_type,test_name,result_value,unit,reference_range,
                      interpretation,result_dt,entered_by_code,entered_by_name
               FROM lab_imaging_results WHERE patient_id=?
               ORDER BY datetime(result_dt),result_id""",
            (patient_id,),
        ).fetchall()
        lab_timeline = [
            {
                "result_type": str(row["result_type"] or ""),
                "test_name": str(row["test_name"] or ""),
                "result": str(row["result_value"] or ""),
                "unit": str(row["unit"] or ""),
                "reference_range": str(row["reference_range"] or ""),
                "documented_interpretation": str(row["interpretation"] or ""),
                "result_datetime": str(row["result_dt"] or ""),
                "entered_by_code": str(row["entered_by_code"] or ""),
                "entered_by_name": str(row["entered_by_name"] or ""),
            }
            for row in lab_rows
        ]
    except sqlite3.Error:
        lab_timeline = []
    try:
        order_rows = connection.execute(
            """SELECT order_id,category,item_name,strength,dose,route,
                      frequency_per_day,details,created_dt,
                      scheduled_start_dt,scheduled_end_dt,status
               FROM physician_orders WHERE patient_id=?
               ORDER BY category COLLATE NOCASE,order_id""",
            (patient_id,),
        ).fetchall()
        orders_timeline = [
            {
                "order_id": int(row["order_id"]),
                "category": str(row["category"] or ""),
                "item_name": str(row["item_name"] or ""),
                "strength": str(row["strength"] or ""),
                "dose": str(row["dose"] or ""),
                "route": str(row["route"] or ""),
                "frequency_per_day": str(row["frequency_per_day"] or ""),
                "details": str(row["details"] or ""),
                "created_datetime": str(row["created_dt"] or ""),
                "scheduled_start_datetime": str(row["scheduled_start_dt"] or ""),
                "scheduled_end_datetime": str(row["scheduled_end_dt"] or ""),
                "status": str(row["status"] or "Active"),
            }
            for row in order_rows
        ]
    except sqlite3.Error:
        orders_timeline = []
    try:
        execution_rows = connection.execute(
            """SELECT care_id,order_id,category,order_text,performed_dt,
                      nurse_code,nurse_name,drug_action,side_effect,
                      abnormal_note
               FROM nursing_med_records WHERE patient_id=?
               ORDER BY datetime(performed_dt),record_id""",
            (patient_id,),
        ).fetchall()
        execution_timeline = []
        for row in execution_rows:
            row_code = str(row["nurse_code"] or "").strip().lower()
            row_name = str(row["nurse_name"] or "").strip().lower()
            row_care_id = row["care_id"]
            same_student = bool(
                (row_care_id is not None
                 and int(row_care_id) in same_care_ids)
                or (selected_code and row_code == selected_code)
                or (selected_name and row_name == selected_name)
            )
            execution_timeline.append({
                "care_id": row_care_id,
                "order_id": row["order_id"],
                "category": str(row["category"] or ""),
                "order_text": str(row["order_text"] or ""),
                "performed_datetime": str(row["performed_dt"] or ""),
                "is_selected_student_record": same_student,
                "response_or_action_taken": str(row["drug_action"] or ""),
                "side_effect_documented": str(row["side_effect"] or ""),
                "abnormal_finding_or_escalation": str(
                    row["abnormal_note"] or ""
                ),
            })
    except sqlite3.Error:
        execution_timeline = []
    return {
        "patient_clinical_profile": {
            "age": _patient_age(patient["dob"]) if patient else "",
            "gender": str(patient["gender"] or "") if patient else "",
            "diagnosis": str(patient["diagnosis"] or "") if patient else "",
            "department": str(patient["department"] or "") if patient else "",
            "history_present_illness": str(
                patient["history_present_illness"] or ""
            ) if patient else "",
            "past_medical_history": str(
                patient["past_medical_history"] or ""
            ) if patient else "",
            "family_history": str(
                patient["family_history"] or ""
            ) if patient else "",
            "allergies": str(patient["allergies"] or "") if patient else "",
            "allergy_status": normalized_allergy_status(
                patient["allergy_status"] if patient else "",
                patient["allergies"] if patient else "",
            ),
        },
        "selected_record_sequence": next(
            (item["sequence"] for item in timeline if item["is_selected_student_record"]), None
        ),
        "selected_student_record_count": sum(
            1 for item in timeline
            if item["is_selected_student_record"]
        ),
        "timeline_entry_count": len(timeline),
        "complete_chronological_nursing_timeline": timeline,
        "triage_timeline_entry_count": len(triage_timeline),
        "triage_attribution": (
            "selected_student" if attributed
            else ("closest_patient_episode" if triage_timeline else "no_triage_record")
        ),
        "selected_triage_record": closest_triage,
        "complete_chronological_triage_timeline": triage_timeline,
        "lab_imaging_timeline_entry_count": len(lab_timeline),
        "complete_chronological_lab_imaging_timeline": lab_timeline,
        "physician_orders_timeline_entry_count": len(orders_timeline),
        "complete_physician_orders_timeline": orders_timeline,
        "medication_and_order_execution_timeline_entry_count": len(
            execution_timeline
        ),
        "complete_chronological_medication_and_order_execution_timeline":
            execution_timeline,
    }


def build_nanda_suggestion_data(connection, patient_id, current_record=None):
    """Build de-identified, longitudinal context for advisory NANDA suggestions."""
    patient_id = str(patient_id or "").strip()
    if not patient_id:
        raise ValueError("A patient is required before requesting NANDA suggestions.")
    latest = connection.execute(
        """SELECT care_id FROM nursing_care WHERE patient_id=?
           ORDER BY datetime(care_dt) DESC,care_id DESC LIMIT 1""",
        (patient_id,),
    ).fetchone()
    selected_care_id = (
        int((current_record or {}).get("care_id") or 0)
        if isinstance(current_record, dict) else 0
    )
    if not selected_care_id and latest:
        selected_care_id = int(latest["care_id"])
    context = build_patient_ai_review_data(
        connection, patient_id, selected_care_id or -1
    )
    for timeline_item in context.get(
        "complete_chronological_nursing_timeline", []
    ):
        if isinstance(timeline_item, dict):
            # The normalized fields above already contain the clinical data.
            # Exclude raw desktop widget snapshots, which may contain duplicate
            # administrative identifiers under UI-generated keys.
            timeline_item.pop("complete_nursing_record_snapshot", None)
    patient = connection.execute(
        """SELECT dob,gender,diagnosis,department,address,
                  history_present_illness,past_medical_history,
                  family_history,allergies,allergy_status
           FROM patients WHERE id=?""",
        (patient_id,),
    ).fetchone()
    profile = context.setdefault("patient_clinical_profile", {})
    if patient:
        profile.update({
            "age": _patient_age(patient["dob"]),
            "gender": str(patient["gender"] or ""),
            "medical_diagnosis": str(patient["diagnosis"] or ""),
            "department": str(patient["department"] or ""),
            "administrative_context": {
                "address": str(patient["address"] or ""),
            },
            "history_present_illness": str(
                patient["history_present_illness"] or ""
            ),
            "past_medical_history": str(
                patient["past_medical_history"] or ""
            ),
            "family_history": str(patient["family_history"] or ""),
            "allergies": str(patient["allergies"] or ""),
            "allergy_status": normalized_allergy_status(
                patient["allergy_status"], patient["allergies"]
            ),
        })
        profile.pop("diagnosis", None)
    try:
        order_rows = connection.execute(
            """SELECT order_id,category,item_name,strength,dose,route,
                      frequency_per_day,details,created_dt,
                      scheduled_start_dt,scheduled_end_dt,status
               FROM physician_orders WHERE patient_id=?
               AND COALESCE(status,'Active')='Active'
               ORDER BY category COLLATE NOCASE,order_id""",
            (patient_id,),
        ).fetchall()
    except sqlite3.Error:
        order_rows = []
    context["current_physician_orders"] = [
        {
            "order_id": int(row["order_id"]),
            "category": str(row["category"] or ""),
            "item_name": str(row["item_name"] or ""),
            "strength": str(row["strength"] or ""),
            "dose": str(row["dose"] or ""),
            "route": str(row["route"] or ""),
            "frequency_per_day": str(row["frequency_per_day"] or ""),
            "details": str(row["details"] or ""),
            "created_datetime": str(row["created_dt"] or ""),
            "scheduled_start_datetime": str(row["scheduled_start_dt"] or ""),
            "scheduled_end_datetime": str(row["scheduled_end_dt"] or ""),
            "status": str(row["status"] or "Active"),
        }
        for row in order_rows
    ]
    if isinstance(current_record, dict) and current_record:
        context["current_unsaved_or_edited_record"] = current_record
    context["_safety_identifier"] = hashlib.sha256(
        ("nanda:" + patient_id).encode("utf-8")
    ).hexdigest()[:32]
    return context


def request_openai_student_review(api_key, record_data, model=None, language="English"):
    """Return a structured AI grading suggestion from the OpenAI Responses API."""
    api_key = str(api_key or "").strip()
    if not api_key:
        raise ValueError("OpenAI API key is not configured.")
    model = str(model or DEFAULT_OPENAI_REVIEW_MODEL).strip() or DEFAULT_OPENAI_REVIEW_MODEL
    language = "Vietnamese" if str(language or "").strip().lower() in (
        "vi", "vietnamese", "tiếng việt", "tieng viet"
    ) else "English"
    schema = {
        "type": "object",
        "properties": {
            "comment": {"type": "string"},
            "sections": {
                "type": "object",
                "properties": {
                    key: {
                        "type": "object",
                        "properties": {
                            "score": {"type": "number", "minimum": 0, "maximum": 100},
                            "comment": {"type": "string"},
                        },
                        "required": ["score", "comment"],
                        "additionalProperties": False,
                    }
                    for key in REVIEW_SECTION_KEYS
                },
                "required": list(REVIEW_SECTION_KEYS),
                "additionalProperties": False,
            },
        },
        "required": ["comment", "sections"],
        "additionalProperties": False,
    }
    clinical_data = json.dumps(
        _sanitized_review_data(record_data), ensure_ascii=False, separators=(",", ":")
    )
    payload = {
        "model": model,
        "instructions": (
            "You are an expert nursing clinical instructor evaluating a student's written "
            "Nursing Record. Evaluate documentation quality and clinical reasoning only; "
            "do not provide patient treatment advice and do not invent missing facts. "
            "Score triage only from the documented chief complaint, rapid Look/Listen/Smell "
            "assessment, vital signs, ABCDE findings, Manchester level and discriminator, "
            "immediate action, disposition and reassessment plan. Identify missing or "
            "contradictory triage evidence and do not invent findings. Score care_time for "
            "timely and internally consistent documentation. In the process comment, give "
            "separate, actionable improvement feedback for: (1) nursing diagnoses supported "
            "by assessment evidence, (2) patient-centred measurable plan/goals with a time "
            "frame, (3) prioritized and diagnosis-linked interventions, and (4) evaluation "
            "that verifies whether every planned intervention was documented as completed "
            "and compares the patient's response with each goal. For every medication documented, "
            "identify what the student administered, verify the indication/order and safe "
            "administration documentation, and check whether therapeutic effect, adverse effects "
            "and the patient's response were reassessed after administration. For every laboratory "
            "or imaging order/intervention, verify that the student followed the result, documented "
            "an interpretation against the reference range or clinical context, recognized abnormal "
            "findings, escalated them, and recorded an action appropriate to the nursing role. "
            "Explicitly evaluate every documented NEWS/EWS value or warning: state whether it is "
            "low, concerning or high according to the documentation/local escalation pathway, "
            "whether monitoring frequency and escalation were appropriate, and whether relevant "
            "falls, deterioration, aspiration, pressure injury, medication or other nursing "
            "prevention measures were documented. Never infer a normal result, medication effect "
            "or completed action when it was not recorded. SOAP and SBAR are clinical "
            "documentation tools only and must not be scored or discussed in this AI review. "
            "Missing, incomplete or "
            "unsupported information must lower the relevant score. The overall comment must "
            "summarize strengths, safety concerns and the highest-priority improvements across "
            "Triage, Nursing Care and Nursing Process only. Read every chronological "
            "Nursing Care, Triage, physician order and medication/order execution "
            "entry and all documented timestamps before scoring. "
            "Produce one combined assessment for this patient, not separate scores by "
            "date or time. Evaluate all entries marked is_selected_student_record together "
            "as the selected student's complete care process for this patient. Use every "
            "other entry only as longitudinal patient context; do not attribute another author's documentation to the selected "
            "student. For triage, prefer selected_triage_record and explicitly note when it "
            "could not be attributed to the selected student. Mention time trends only "
            "when they support a finding; do not list or grade the care as separate "
            "timestamped records. "
            "Score every section from 0 to 100. Treat the Triage score as independent; "
            "do not include it in the Nursing overall score, which is the average of "
            "Nursing Care and Nursing Process only. Return specific feedback in %s. "
            "Use the requested language for the overall comment "
            "and every section comment. The result is an advisory draft that a human "
            "instructor must review before saving." % language
        ),
        "input": (
            "Complete de-identified chronological Nursing Care, Triage, "
            "physician orders, medication/order execution and Lab/Imaging "
            "result timeline JSON:\n" + clinical_data
        ),
        # Student reviews inform instructor feedback but never update marks
        # automatically, so use considered reasoning for the advisory draft.
        "reasoning": {"effort": "medium"},
        "text": {
            "verbosity": "medium",
            "format": {
                "type": "json_schema",
                "name": "student_nursing_review",
                "description": "Suggested nursing student score and instructor feedback.",
                "strict": True,
                "schema": schema,
            },
        },
    }
    request = Request(
        openai_api_url("responses"),
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=90) as response:
            response_data = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        try:
            error_data = json.loads(exc.read().decode("utf-8", errors="replace"))
            message = error_data.get("error", {}).get("message", "")
        except Exception:
            message = ""
        raise RuntimeError(message or "OpenAI API request failed (HTTP %s)." % exc.code)
    except URLError as exc:
        raise RuntimeError("Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc))
    except (ValueError, OSError) as exc:
        raise RuntimeError("Invalid response from OpenAI API: %s" % exc)

    output_text = str(response_data.get("output_text", "") or "")
    if not output_text:
        for output_item in response_data.get("output", []) or []:
            for content_item in output_item.get("content", []) or []:
                if content_item.get("type") == "refusal":
                    raise RuntimeError(content_item.get("refusal") or "The AI declined this review.")
                if content_item.get("type") == "output_text":
                    output_text += str(content_item.get("text", "") or "")
    if not output_text.strip():
        raise RuntimeError("OpenAI API returned no review text.")
    try:
        result = json.loads(output_text)
        sections = result["sections"]
        normalized_sections = {}
        for key in REVIEW_SECTION_KEYS:
            section_score = float(sections[key]["score"])
            if not 0 <= section_score <= 100:
                raise ValueError()
            normalized_sections[key] = {
                "score": section_score,
                "comment": str(sections[key].get("comment", "") or "").strip(),
            }
        return {
            "score": round(sum(
                normalized_sections[key]["score"]
                for key in NURSING_REVIEW_SECTION_KEYS
            ) / float(len(NURSING_REVIEW_SECTION_KEYS)), 1),
            "triage_score": normalized_sections["triage"]["score"],
            "comment": str(result.get("comment", "") or "").strip(),
            "sections": normalized_sections,
            "model": model,
            "language": language,
            "timeline_entry_count": int(record_data.get("timeline_entry_count", 1) or 1)
            if isinstance(record_data, dict) else 1,
            "triage_timeline_entry_count": int(
                record_data.get("triage_timeline_entry_count", 0) or 0
            ) if isinstance(record_data, dict) else 0,
        }
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        raise RuntimeError("OpenAI API returned an invalid review structure.")


def request_openai_class_learning_analysis(
    api_key, class_metrics, model=None, language="English"
):
    """Analyze one de-identified classroom snapshot on explicit request.

    The caller supplies stable student references (S001, S002, ...), never
    patient identifiers or account names.  The response is advisory and is
    persisted separately from marks, assessments and clinical requirements.
    """
    api_key = str(api_key or "").strip()
    if not api_key:
        raise ValueError("OpenAI API key is not configured.")
    model = str(model or DEFAULT_OPENAI_REVIEW_MODEL).strip()
    model = model or DEFAULT_OPENAI_REVIEW_MODEL
    language = (
        "Vietnamese" if str(language or "").strip().lower() in (
            "vi", "vietnamese", "tiếng việt", "tieng viet"
        ) else "English"
    )
    student_schema = {
        "type": "object",
        "properties": {
            "student_ref": {"type": "string"},
            "alert_level": {
                "type": "string", "enum": ["none", "watch", "high"]
            },
            "summary": {"type": "string"},
            "strengths": {"type": "array", "items": {"type": "string"}},
            "risks": {"type": "array", "items": {"type": "string"}},
            "recommended_actions": {
                "type": "array", "items": {"type": "string"}
            },
        },
        "required": [
            "student_ref", "alert_level", "summary", "strengths", "risks",
            "recommended_actions",
        ],
        "additionalProperties": False,
    }
    schema = {
        "type": "object",
        "properties": {
            "group_summary": {"type": "string"},
            "group_strengths": {
                "type": "array", "items": {"type": "string"}
            },
            "group_risks": {"type": "array", "items": {"type": "string"}},
            "recommended_actions": {
                "type": "array", "items": {"type": "string"}
            },
            "students": {"type": "array", "items": student_schema},
        },
        "required": [
            "group_summary", "group_strengths", "group_risks",
            "recommended_actions", "students",
        ],
        "additionalProperties": False,
    }
    payload = {
        "model": model,
        "instructions": (
            "You are a nursing education learning-analytics assistant. Analyze "
            "only the supplied aggregate classroom metrics: nursing record "
            "reviews, nursing skill assessments, confirmed clinical-practice "
            "requirements and open coaching reminders. Do not infer facts from "
            "missing data and do not treat missing evidence as failure. Note small "
            "sample sizes and avoid ranking students unfairly. A high alert is only "
            "for clear repeated performance or safety concerns; watch is for gaps, "
            "decline, incomplete confirmed targets or limited evidence. Give "
            "specific evidence-based teaching actions. For each student, make at "
            "least one recommended action a short, respectful reminder draft that "
            "an instructor can review and send manually about the next learning "
            "step, clinical target or open coaching item. Never send a reminder, "
            "change a grade or change a clinical record. Return exactly one item "
            "for every supplied "
            "student_ref, using the same reference. Write all narrative text in %s. "
            "This is a manual advisory report that an instructor must interpret."
            % language
        ),
        "input": "De-identified classroom learning metrics JSON:\n" + json.dumps(
            class_metrics, ensure_ascii=False, separators=(",", ":")
        ),
        # Classroom recommendations combine several evidence streams
        # (reviews, skills, confirmed targets and coaching reminders), so use
        # the same considered reasoning level as clinical/Nursing Plan drafts.
        "reasoning": {"effort": "medium"},
        "text": {
            "verbosity": "medium",
            "format": {
                "type": "json_schema",
                "name": "class_learning_analysis",
                "description": "Advisory individual and group learning analysis.",
                "strict": True,
                "schema": schema,
            },
        },
    }
    request = Request(
        openai_api_url("responses"),
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=90) as response:
            response_data = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        try:
            error_data = json.loads(exc.read().decode("utf-8", errors="replace"))
            message = error_data.get("error", {}).get("message", "")
        except Exception:
            message = ""
        raise RuntimeError(message or "OpenAI API request failed (HTTP %s)." % exc.code)
    except URLError as exc:
        raise RuntimeError(
            "Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc)
        )
    except (ValueError, OSError) as exc:
        raise RuntimeError("Invalid response from OpenAI API: %s" % exc)

    output_text = str(response_data.get("output_text", "") or "")
    if not output_text:
        for output_item in response_data.get("output", []) or []:
            for content_item in output_item.get("content", []) or []:
                if content_item.get("type") == "refusal":
                    raise RuntimeError(
                        content_item.get("refusal")
                        or "The AI declined this classroom analysis."
                    )
                if content_item.get("type") == "output_text":
                    output_text += str(content_item.get("text", "") or "")
    try:
        result = json.loads(output_text)
        expected_refs = {
            str(item.get("student_ref", "") or "")
            for item in class_metrics.get("students", [])
        }
        normalized_students = []
        seen_refs = set()
        for item in result["students"]:
            student_ref = str(item["student_ref"] or "").strip()
            alert_level = str(item["alert_level"] or "").strip().lower()
            if (
                student_ref not in expected_refs
                or student_ref in seen_refs
                or alert_level not in ("none", "watch", "high")
            ):
                raise ValueError()
            seen_refs.add(student_ref)
            normalized_students.append({
                "student_ref": student_ref,
                "alert_level": alert_level,
                "summary": str(item.get("summary", "") or "").strip(),
                "strengths": [str(value or "").strip() for value in item.get("strengths", []) if str(value or "").strip()],
                "risks": [str(value or "").strip() for value in item.get("risks", []) if str(value or "").strip()],
                "recommended_actions": [str(value or "").strip() for value in item.get("recommended_actions", []) if str(value or "").strip()],
            })
        if seen_refs != expected_refs:
            raise ValueError()
        return {
            "group_summary": str(result.get("group_summary", "") or "").strip(),
            "group_strengths": [str(value or "").strip() for value in result.get("group_strengths", []) if str(value or "").strip()],
            "group_risks": [str(value or "").strip() for value in result.get("group_risks", []) if str(value or "").strip()],
            "recommended_actions": [str(value or "").strip() for value in result.get("recommended_actions", []) if str(value or "").strip()],
            "students": normalized_students,
            "model": str(response_data.get("model", "") or model),
            "language": language,
        }
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        raise RuntimeError("OpenAI API returned an invalid classroom analysis structure.")


def request_openai_nanda_suggestions(
    api_key, clinical_context, model=None, language="English"
):
    """Return structured, advisory nursing diagnoses, goals and interventions."""
    api_key = str(api_key or "").strip()
    if not api_key:
        raise ValueError("OpenAI API key is not configured.")
    model = str(model or DEFAULT_OPENAI_REVIEW_MODEL).strip() or DEFAULT_OPENAI_REVIEW_MODEL
    language = "Vietnamese" if str(language or "").strip().lower() in (
        "vi", "vietnamese", "tiếng việt", "tieng viet"
    ) else "English"
    intervention_schema = {
        "type": "object",
        "properties": {
            "category": {
                "type": "string",
                "enum": [
                    "Nursing Care",
                    "Medication Administration",
                    "Blood Sample Collection / Laboratory",
                    "Nutrition",
                    "Procedure Implementation",
                ],
            },
            "action": {"type": "string"},
        },
        "required": ["category", "action"],
        "additionalProperties": False,
    }
    diagnosis_schema = {
        "type": "object",
        "properties": {
            "priority": {"type": "integer", "minimum": 1, "maximum": 6},
            "label": {"type": "string"},
            "diagnosis_statement": {"type": "string"},
            "evidence": {
                "type": "array",
                "items": {"type": "string"},
                "maxItems": 8,
            },
            "goal": {"type": "string"},
            "interventions": {
                "type": "array",
                "items": intervention_schema,
                "maxItems": 12,
            },
        },
        "required": [
            "priority", "label", "diagnosis_statement", "evidence",
            "goal", "interventions",
        ],
        "additionalProperties": False,
    }
    schema = {
        "type": "object",
        "properties": {
            "diagnoses": {
                "type": "array",
                "items": diagnosis_schema,
                "minItems": 1,
                "maxItems": 6,
            },
            "clinical_caveat": {"type": "string"},
        },
        "required": ["diagnoses", "clinical_caveat"],
        "additionalProperties": False,
    }
    safe_context = _sanitized_review_data(clinical_context)
    if isinstance(safe_context, dict):
        safe_context.pop("_safety_identifier", None)
    payload = {
        "model": model,
        "store": False,
        "safety_identifier": str(
            (clinical_context or {}).get("_safety_identifier", "")
        ) or None,
        "instructions": (
            "You are an expert nursing clinical instructor. Suggest evidence-based "
            "nursing diagnoses using standard NANDA-style terminology from the documented "
            "data only. Use the patient clinical profile, administrative clinical context, "
            "vital signs, assessment findings, every chronological Nursing Care entry, "
            "laboratory/imaging results and current physician orders. Do not invent findings. "
            "Do not diagnose a medical condition, prescribe a medicine, create a physician "
            "order, or state that an intervention was completed. Medication, laboratory and "
            "nutrition actions must explicitly remain subject to an existing physician order "
            "and local policy. Treat nursing diagnoses and interventions already selected from "
            "the administrator-managed catalog as the baseline plan: retain them, do not "
            "replace them, and suggest only missing goals, interventions, or evaluation points "
            "needed to make that selected plan complete. Prioritize actual problems before "
            "risks when supported. Each "
            "goal must be patient-centred, measurable and time-bound. Each intervention must "
            "be specific, safe, linked to the diagnosis and categorized for the Nursing "
            "Process form. Evidence must cite concise documented facts or timestamps. Return "
            "an advisory draft in %s for a student to select and a licensed instructor to "
            "review before it is added to the record." % language
        ),
        "input": (
            "Complete de-identified clinical context JSON:\n"
            + json.dumps(
                safe_context, ensure_ascii=False, separators=(",", ":")
            )
        ),
        "reasoning": {"effort": "medium"},
        "text": {
            "verbosity": "medium",
            "format": {
                "type": "json_schema",
                "name": "nanda_nursing_process_suggestions",
                "description": (
                    "Advisory nursing diagnoses, measurable goals and categorized interventions."
                ),
                "strict": True,
                "schema": schema,
            },
        },
    }
    if not payload["safety_identifier"]:
        payload.pop("safety_identifier", None)
    request = Request(
        openai_api_url("responses"),
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=90) as response:
            response_data = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        try:
            error_data = json.loads(exc.read().decode("utf-8", errors="replace"))
            message = error_data.get("error", {}).get("message", "")
        except Exception:
            message = ""
        raise RuntimeError(message or "OpenAI API request failed (HTTP %s)." % exc.code)
    except URLError as exc:
        raise RuntimeError(
            "Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc)
        )
    except (ValueError, OSError) as exc:
        raise RuntimeError("Invalid response from OpenAI API: %s" % exc)
    output_text = str(response_data.get("output_text", "") or "")
    if not output_text:
        for output_item in response_data.get("output", []) or []:
            for content_item in output_item.get("content", []) or []:
                if content_item.get("type") == "refusal":
                    raise RuntimeError(
                        content_item.get("refusal")
                        or "The AI declined this NANDA suggestion request."
                    )
                if content_item.get("type") == "output_text":
                    output_text += str(content_item.get("text", "") or "")
    if not output_text.strip():
        raise RuntimeError("OpenAI API returned no NANDA suggestion text.")
    try:
        result = json.loads(output_text)
        normalized = []
        for item in result["diagnoses"]:
            interventions = [
                {
                    "category": str(entry["category"] or "").strip(),
                    "action": str(entry["action"] or "").strip(),
                }
                for entry in item["interventions"]
                if str(entry.get("action", "") or "").strip()
            ]
            normalized.append({
                "priority": int(item["priority"]),
                "label": str(item["label"] or "").strip(),
                "diagnosis_statement": str(
                    item["diagnosis_statement"] or ""
                ).strip(),
                "evidence": [
                    str(value or "").strip() for value in item["evidence"]
                    if str(value or "").strip()
                ],
                "goal": str(item["goal"] or "").strip(),
                "interventions": interventions,
            })
        if not normalized:
            raise ValueError()
        normalized.sort(key=lambda item: item["priority"])
        return {
            "diagnoses": normalized,
            "clinical_caveat": str(result.get("clinical_caveat", "") or "").strip(),
            "model": model,
            "language": language,
        }
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        raise RuntimeError("OpenAI API returned an invalid NANDA suggestion structure.")


NURSING_PROGRESSION_HEADING_CATALOG_KEYS = {
    "problem": "patient_problem",
    "diagnosis": "nursing_diagnosis",
    "cause": "nursing_cause",
    "goal": "nursing_goal",
    "intervention": "nursing_intervention",
    "goal_evaluation": "goal_evaluation",
    "intervention_evaluation": "intervention_evaluation",
}
NURSING_PROGRESSION_HEADING_LABELS = {
    "problem": "Vấn đề của người bệnh (Heading 1)",
    "diagnosis": "Chẩn đoán điều dưỡng (Heading 2)",
    "cause": "Nguyên nhân (Heading 2)",
    "goal": "Mục tiêu (Heading 3)",
    "intervention": "Can thiệp điều dưỡng (Heading 4)",
    "goal_evaluation": "Lượng giá mục tiêu (Heading 5)",
    "intervention_evaluation": "Lượng giá can thiệp (Heading 5)",
}


def _catalog_match_score(candidate, context_terms):
    """Rank one shared-catalog item against the words already captured
    upstream in the map (e.g. the diagnosis text when ranking its goals)."""
    if not context_terms:
        return 0.0
    folded = candidate.casefold()
    score = 0.0
    for term in context_terms:
        term = term.casefold().strip()
        if len(term) < 3:
            continue
        if term in folded:
            score += 2.0
        else:
            score += difflib.SequenceMatcher(None, term, folded).ratio()
    return score


def rank_catalog_suggestions(catalog_values, context_text="", top_n=5):
    """Rank the administrator-managed shared catalog for one heading
    against the free text already captured upstream (problem/diagnosis/
    prior heading wording), most relevant first. AI is intentionally not
    involved here: this is the catalog-first pass that always runs before
    any AI suggestion is requested."""
    context_terms = [
        term for term in re.split(r"[\s,;/()\-]+", str(context_text or ""))
        if term
    ]
    seen = set()
    scored = []
    for position, value in enumerate(catalog_values or []):
        text = " ".join(str(value or "").split()).strip()
        if not text:
            continue
        folded = text.casefold()
        if folded in seen:
            continue
        seen.add(folded)
        score = _catalog_match_score(text, context_terms)
        scored.append((score, position, text))
    scored.sort(key=lambda item: (-item[0], item[1]))
    top_n = max(int(top_n or 5), 0)
    return [
        {"text": text, "source": "catalog"}
        for _score, _position, text in scored[:top_n]
    ]


def merge_ranked_suggestions(catalog_ranked, ai_items, top_n=5):
    """Combine the catalog-first ranked list with AI-proposed additions,
    de-duplicated and capped at top_n; catalog entries always outrank new
    AI text, and AI only fills the remaining slots."""
    top_n = max(int(top_n or 5), 0)
    seen = {item["text"].casefold() for item in catalog_ranked}
    merged = list(catalog_ranked)
    for raw_item in ai_items or []:
        text = " ".join(str(
            raw_item.get("text", "") if isinstance(raw_item, dict) else raw_item or ""
        ).split()).strip()
        if not text:
            continue
        folded = text.casefold()
        if folded in seen:
            continue
        seen.add(folded)
        merged.append({
            "text": text,
            "source": "ai",
            "rationale": (
                str(raw_item.get("rationale", "") or "").strip()
                if isinstance(raw_item, dict) else ""
            ),
        })
        if len(merged) >= top_n:
            break
    return merged[:top_n]


def merge_template_suggestions(template_values, other_suggestions, context_text="", top_n=5):
    """Prioritize the administrator-curated standard map templates (Desktop
    Settings > "Sơ đồ cây") ahead of the plain shared catalog and any AI
    suggestions for the same heading. Templates are read-only for AI and
    for the ranked pickers -- they only ever fill the remaining slots
    after every relevant template item has been offered first."""
    top_n = max(int(top_n or 5), 0)
    merged = []
    seen = set()
    for item in rank_catalog_suggestions(template_values, context_text, top_n=top_n):
        text = item.get("text", "")
        folded = text.casefold()
        if not text or folded in seen:
            continue
        seen.add(folded)
        merged.append({"text": text, "source": "template"})
    for item in other_suggestions or []:
        text = str(item.get("text", "") if isinstance(item, dict) else item or "").strip()
        folded = text.casefold()
        if not text or folded in seen:
            continue
        seen.add(folded)
        merged.append(item if isinstance(item, dict) else {"text": text, "source": "catalog"})
        if len(merged) >= top_n:
            break
    return merged[:top_n]


def _flatten_template_diagnoses(templates):
    entries = []
    for template in templates or []:
        for diagnosis in (template or {}).get("diagnoses", []) or []:
            if diagnosis.get("diagnosis"):
                entries.append(diagnosis)
    return entries


def _best_template_diagnosis_match(templates, context_text):
    context_fold = str(context_text or "").casefold()
    if not context_fold:
        return None
    best = None
    best_len = 0
    for entry in _flatten_template_diagnoses(templates):
        dx_fold = str(entry.get("diagnosis", "")).strip().casefold()
        if dx_fold and dx_fold in context_fold and len(dx_fold) > best_len:
            best = entry
            best_len = len(dx_fold)
    return best


def _template_entry_by_diagnosis_text(templates, diagnosis_text):
    key = " ".join(str(diagnosis_text or "").split()).strip().casefold()
    if not key:
        return None
    for entry in _flatten_template_diagnoses(templates):
        entry_key = " ".join(
            str(entry.get("diagnosis", "")).split()
        ).strip().casefold()
        if entry_key == key:
            return entry
    return None


def template_values_for_heading(templates, heading_key, context_text=""):
    """Scope the admin-curated standard-map templates (Desktop Settings >
    "Sơ đồ cây") to one Nursing Care Progression heading, for the ranked
    picker to offer with top priority: the full diagnosis list for the
    "diagnosis" heading, the flattened problem list for "problem", or (for
    every other heading) the matching diagnosis's own causes/goals/
    interventions/evaluations -- matched by whether that diagnosis's text
    already appears in the clinical context captured upstream. Used
    identically by the Desktop map editor and the Web ``/heading-suggest``
    endpoint so a template is prioritized on both platforms the same way."""
    if heading_key == "problem":
        return [
            problem for template in (templates or [])
            for problem in (template or {}).get("problems", []) if problem
        ]
    if heading_key == "diagnosis":
        return [
            entry.get("diagnosis", "")
            for entry in _flatten_template_diagnoses(templates)
        ]
    entry = _best_template_diagnosis_match(templates, context_text)
    if entry is None:
        return []
    if heading_key == "cause":
        return list(entry.get("causes", []))
    if heading_key == "goal":
        return [g.get("text", "") for g in entry.get("goals", []) if g.get("text")]
    if heading_key == "intervention":
        return [
            i.get("text", "") for i in entry.get("interventions", [])
            if i.get("text")
        ]
    if heading_key == "goal_evaluation":
        return [
            g.get("evaluation", "") for g in entry.get("goals", [])
            if g.get("evaluation")
        ]
    if heading_key == "intervention_evaluation":
        return [
            i.get("evaluation", "") for i in entry.get("interventions", [])
            if i.get("evaluation")
        ]
    return []


def request_openai_heading_suggestions(
    api_key, heading_key, context_text, existing_catalog,
    already_chosen=None, model=None, language="English", top_n=5,
):
    """Ask OpenAI for up to top_n additional items for one Nursing Care
    Progression heading that the shared catalog does not already cover,
    so the ranked 1-5 picker can fill any gap after catalog matches are
    exhausted. AI only supplements the catalog; it never replaces it."""
    api_key = str(api_key or "").strip()
    if not api_key:
        raise ValueError("OpenAI API key is not configured.")
    model = str(model or DEFAULT_OPENAI_REVIEW_MODEL).strip() or DEFAULT_OPENAI_REVIEW_MODEL
    language = "Vietnamese" if str(language or "").strip().lower() in (
        "vi", "vietnamese", "tiếng việt", "tieng viet"
    ) else "English"
    heading_label = NURSING_PROGRESSION_HEADING_LABELS.get(heading_key, heading_key)
    top_n = max(int(top_n or 5), 1)
    schema = {
        "type": "object",
        "properties": {
            "suggestions": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "text": {"type": "string"},
                        "rationale": {"type": "string"},
                    },
                    "required": ["text", "rationale"],
                    "additionalProperties": False,
                },
                "maxItems": top_n,
            },
            "clinical_caveat": {"type": "string"},
        },
        "required": ["suggestions", "clinical_caveat"],
        "additionalProperties": False,
    }
    payload = {
        "model": model,
        "store": False,
        "instructions": (
            "You are an expert nursing clinical instructor completing one "
            "heading of a Problem -> Nursing Diagnosis -> Goal/Intervention "
            "-> Evaluation map (%s). The shared, administrator-managed "
            "catalog for this heading already contains: %s. Do not repeat "
            "any of those items. Suggest at most %d additional, clinically "
            "appropriate items only when the existing catalog and the "
            "clinical context below do not already cover the need; return "
            "fewer items, or an empty list, when the catalog is already "
            "sufficient. Keep every suggestion specific, safe and "
            "consistent with standard nursing-process terminology "
            "(NANDA/NOC/NIC style). Do not diagnose a medical condition, "
            "prescribe medication, or state an intervention was completed. "
            "Return the result in %s as an advisory draft for a student to "
            "select and a licensed instructor to review before it is added "
            "to the record."
            % (
                heading_label,
                json.dumps(list(existing_catalog or [])[:60], ensure_ascii=False),
                top_n,
                language,
            )
        ),
        "input": (
            "Clinical context already captured upstream in the map "
            "(problem / diagnosis / prior heading text), JSON:\n"
            + json.dumps(
                {
                    "context_text": str(context_text or ""),
                    "already_chosen_in_this_heading": list(already_chosen or []),
                },
                ensure_ascii=False,
            )
        ),
        "reasoning": {"effort": "low"},
        "text": {
            "verbosity": "low",
            "format": {
                "type": "json_schema",
                "name": "nursing_progression_heading_suggestions",
                "description": "Advisory additions for one Nursing Care Progression heading.",
                "strict": True,
                "schema": schema,
            },
        },
    }
    request = Request(
        openai_api_url("responses"),
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=60) as response:
            response_data = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        try:
            error_data = json.loads(exc.read().decode("utf-8", errors="replace"))
            message = error_data.get("error", {}).get("message", "")
        except Exception:
            message = ""
        raise RuntimeError(message or "OpenAI API request failed (HTTP %s)." % exc.code)
    except URLError as exc:
        raise RuntimeError("Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc))
    except (ValueError, OSError) as exc:
        raise RuntimeError("Invalid response from OpenAI API: %s" % exc)
    output_text = str(response_data.get("output_text", "") or "")
    if not output_text:
        for output_item in response_data.get("output", []) or []:
            for content_item in output_item.get("content", []) or []:
                if content_item.get("type") == "refusal":
                    raise RuntimeError(
                        content_item.get("refusal")
                        or "The AI declined this suggestion request."
                    )
                if content_item.get("type") == "output_text":
                    output_text += str(content_item.get("text", "") or "")
    if not output_text.strip():
        raise RuntimeError("OpenAI API returned no suggestion text.")
    try:
        result = json.loads(output_text)
        suggestions = [
            {
                "text": str(item["text"] or "").strip(),
                "rationale": str(item.get("rationale", "") or "").strip(),
            }
            for item in result["suggestions"]
            if str(item.get("text", "") or "").strip()
        ]
        return {
            "suggestions": suggestions[:top_n],
            "clinical_caveat": str(result.get("clinical_caveat", "") or "").strip(),
            "model": model,
            "language": language,
        }
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        raise RuntimeError("OpenAI API returned an invalid suggestion structure.")


def build_ranked_heading_suggestions(
    heading_key, catalog_values, context_text="", already_chosen=None,
    api_key=None, model=None, language="English", top_n=5,
):
    """Catalog-first, ranked (1..top_n) suggestions for one heading: the
    shared catalog is always searched and ranked first; AI is asked to
    propose additional items only when the catalog does not already fill
    top_n slots, so AI always supplements the existing catalog rather than
    replacing it. Used identically by the Desktop map editor and the Web
    Nursing Care Progression form (the ``/heading-suggest`` endpoint)."""
    top_n = max(int(top_n or 5), 1)
    already_chosen_folded = {
        str(value or "").casefold() for value in (already_chosen or [])
    }
    catalog_ranked = [
        item for item in rank_catalog_suggestions(
            catalog_values, context_text, top_n=top_n * 3
        )
        if item["text"].casefold() not in already_chosen_folded
    ][:top_n]
    result = {
        "suggestions": catalog_ranked,
        "clinical_caveat": "",
        "model": "",
        "language": language,
    }
    api_key = str(api_key or "").strip()
    if len(catalog_ranked) < top_n and api_key:
        try:
            ai_result = request_openai_heading_suggestions(
                api_key, heading_key, context_text, catalog_values,
                already_chosen=already_chosen, model=model,
                language=language, top_n=top_n - len(catalog_ranked),
            )
            result["suggestions"] = merge_ranked_suggestions(
                catalog_ranked, ai_result.get("suggestions", []), top_n=top_n
            )
            result["clinical_caveat"] = ai_result.get("clinical_caveat", "")
            result["model"] = ai_result.get("model", "")
        except Exception as exc:
            result["ai_error"] = str(exc)
    return result


class HeadingSuggestionWorker(QThread):
    suggestions_ready = pyqtSignal(dict)
    suggestions_failed = pyqtSignal(str)

    def __init__(self, heading_key, catalog_values, context_text,
                 already_chosen, api_key, model, language, top_n=5, parent=None):
        super().__init__(parent)
        self.heading_key = heading_key
        self.catalog_values = catalog_values
        self.context_text = context_text
        self.already_chosen = already_chosen
        self.api_key = api_key
        self.model = model
        self.language = language
        self.top_n = top_n

    def run(self):
        try:
            self.suggestions_ready.emit(
                build_ranked_heading_suggestions(
                    self.heading_key, self.catalog_values, self.context_text,
                    self.already_chosen, self.api_key, self.model,
                    self.language, self.top_n,
                )
            )
        except Exception as exc:
            self.suggestions_failed.emit(str(exc))


def _snap_to_catalog(text, catalog_values, threshold=0.86):
    """If an AI-proposed string is a very close match to an existing
    catalog item, snap to the catalog's exact wording and report it as a
    catalog hit; otherwise keep the AI text as a new ("ai") item. This is
    the "AI ưu tiên dùng danh mục có sẵn trước" rule applied item by item."""
    text = " ".join(str(text or "").split()).strip()
    if not text:
        return "", ""
    folded = text.casefold()
    best_value, best_ratio = "", 0.0
    for candidate in catalog_values or []:
        candidate_text = " ".join(str(candidate or "").split()).strip()
        if not candidate_text:
            continue
        if candidate_text.casefold() == folded:
            return candidate_text, "catalog"
        ratio = difflib.SequenceMatcher(
            None, folded, candidate_text.casefold()
        ).ratio()
        if ratio > best_ratio:
            best_ratio, best_value = ratio, candidate_text
    if best_ratio >= threshold:
        return best_value, "catalog"
    return text, "ai"


def request_openai_clinical_support(
    api_key, clinical_context, medical_diagnoses, model=None,
    language="English",
):
    """Ask OpenAI for the Clinical Support block of the Nursing Process:

    1. For every disease listed in the Medical Diagnosis field, a short
       pathophysiology summary and how that mechanism actually shows up in
       THIS patient's documented data.
    2. A theory-versus-bedside comparison table: what the textbook picture
       says, what was really observed, whether the two agree, and why they
       differ when they do.

    This is teaching support for a nurse or student. It never diagnoses,
    never prescribes, and is always an editable draft."""
    api_key = str(api_key or "").strip()
    if not api_key:
        raise ValueError("OpenAI API key is not configured.")
    model = str(
        model or DEFAULT_OPENAI_REVIEW_MODEL
    ).strip() or DEFAULT_OPENAI_REVIEW_MODEL
    language = "Vietnamese" if str(language or "").strip().lower() in (
        "vi", "vietnamese", "tiếng việt", "tieng viet"
    ) else "English"
    diseases = [
        str(item or "").strip() for item in (medical_diagnoses or [])
        if str(item or "").strip()
    ]
    schema = {
        "type": "object",
        "properties": {
            "pathophysiology": {
                "type": "array", "minItems": 1, "maxItems": 8,
                "items": {
                    "type": "object",
                    "properties": {
                        "disease": {"type": "string"},
                        "mechanism": {"type": "string"},
                        "presentation": {"type": "string"},
                    },
                    "required": ["disease", "mechanism", "presentation"],
                    "additionalProperties": False,
                },
            },
            "comparisons": {
                "type": "array", "minItems": 3, "maxItems": 12,
                "items": {
                    "type": "object",
                    "properties": {
                        "topic": {"type": "string"},
                        "theory": {"type": "string"},
                        "practice": {"type": "string"},
                        "verdict": {
                            "type": "string",
                            "enum": ["Giống", "Một phần", "Khác"],
                        },
                        "explanation": {"type": "string"},
                    },
                    "required": [
                        "topic", "theory", "practice", "verdict",
                        "explanation",
                    ],
                    "additionalProperties": False,
                },
            },
            "medications": {
                "type": "array", "minItems": 0, "maxItems": 20,
                "items": {
                    "type": "object",
                    "properties": {
                        "drug": {"type": "string"},
                        "main_effect": {"type": "string"},
                        "side_effects": {"type": "string"},
                        "nursing_monitoring": {"type": "string"},
                    },
                    "required": [
                        "drug", "main_effect", "side_effects",
                        "nursing_monitoring",
                    ],
                    "additionalProperties": False,
                },
            },
            "paraclinical": {
                "type": "array", "minItems": 0, "maxItems": 20,
                "items": {
                    "type": "object",
                    "properties": {
                        "test": {"type": "string"},
                        "category": {
                            "type": "string",
                            "enum": ["Laboratory", "Imaging"],
                        },
                        "purpose": {"type": "string"},
                        "result": {"type": "string"},
                        "nursing_note": {"type": "string"},
                    },
                    "required": [
                        "test", "category", "purpose", "result",
                        "nursing_note",
                    ],
                    "additionalProperties": False,
                },
            },
            "note": {"type": "string"},
            "clinical_caveat": {"type": "string"},
        },
        "required": [
            "pathophysiology", "comparisons", "medications", "paraclinical",
            "note", "clinical_caveat",
        ],
        "additionalProperties": False,
    }
    safe_context = _sanitized_review_data(clinical_context)
    if isinstance(safe_context, dict):
        safe_context.pop("_safety_identifier", None)
    payload = {
        "model": model,
        "store": False,
        "safety_identifier": str(
            (clinical_context or {}).get("_safety_identifier", "")
        ) or None,
        "instructions": (
            "You are a nursing clinical instructor writing the teaching "
            "support section of a nursing record. Read the de-identified "
            "patient profile: vital signs, assessment findings, every "
            "chronological Nursing Care entry, laboratory/imaging results "
            "and current physician orders.\n"
            "Part 1 - pathophysiology. The Medical Diagnosis field lists "
            "these diseases: %s. Write one entry per disease, in that same "
            "order. \"mechanism\" is a compact textbook summary of how the "
            "disease develops and produces its typical signs. "
            "\"presentation\" states which of those mechanisms can actually "
            "be traced in THIS patient's documented data, naming the "
            "specific figures or findings that show it. If the record "
            "contains nothing about a disease, say so plainly instead of "
            "inventing findings.\n"
            "Part 2 - theory versus bedside. Build a comparison table. Each "
            "row takes one clinically meaningful item (a typical symptom, "
            "sign, vital-sign pattern or laboratory result of the diseases "
            "above) and fills: \"topic\" the item; \"theory\" what the "
            "textbook expects; \"practice\" what this patient's record "
            "actually shows, with the documented values; \"verdict\" one of "
            "Giống, Một phần, Khác; and \"explanation\" WHY they agree or "
            "differ - treatment already given, comorbidity, stage of "
            "illness, age, an atypical presentation, or simply that the "
            "item has not been assessed yet. Cover both the items that "
            "match and the items that do not; a table where everything "
            "matches is almost never honest.\n"
            "Part 3 - medications. For every drug in this patient's "
            "Medication orders, write one entry: \"drug\" the medication "
            "exactly as ordered (name, strength, route, dose); "
            "\"main_effect\" what it is being given for in THIS patient "
            "and how it works; \"side_effects\" the adverse effects a "
            "nurse should expect and watch for, most important first; and "
            "\"nursing_monitoring\" the concrete nursing monitoring the "
            "drug demands - which vital sign, laboratory value, symptom or "
            "patient instruction, and how often. Do not add a drug that "
            "was not ordered, and do not suggest a dose change.\n"
            "Part 4 - paraclinical investigations. For every Laboratory and "
            "Imaging order this patient has, write one entry: \"test\" the "
            "investigation exactly as ordered; \"category\" either "
            "Laboratory or Imaging; \"purpose\" why it was ordered for "
            "THIS patient and what it is expected to show; \"result\" the "
            "documented result with its actual values, or plainly that no "
            "result has been recorded yet; and \"nursing_note\" what the "
            "nurse must conclude from it and keep monitoring, including any "
            "preparation or aftercare the investigation requires. Do not "
            "add an investigation that was not ordered and never invent a "
            "result.\n"
            "Use only documented data. Do not diagnose a new medical "
            "condition, prescribe, create a physician order, or claim an "
            "intervention was performed. Write in %s. This is an advisory "
            "draft the nurse reviews and edits before saving."
            % (
                json.dumps(diseases, ensure_ascii=False)
                if diseases else
                "(the Medical Diagnosis field is empty - infer the most "
                "likely documented problems instead and say so)",
                language,
            )
        ),
        "input": (
            "Complete de-identified clinical context JSON:\n"
            + json.dumps(
                safe_context, ensure_ascii=False, separators=(",", ":")
            )
        ),
        "reasoning": {"effort": "medium"},
        "text": {
            "verbosity": "medium",
            "format": {
                "type": "json_schema",
                "name": "nursing_clinical_support",
                "description": (
                    "Pathophysiology per diagnosed disease, a "
                    "theory-versus-bedside comparison table, the ordered "
                    "medications with action, adverse effects and nursing "
                    "monitoring, and the ordered laboratory/imaging "
                    "investigations with purpose, result and nursing "
                    "interpretation."
                ),
                "strict": True,
                "schema": schema,
            },
        },
    }
    if not payload["safety_identifier"]:
        payload.pop("safety_identifier", None)
    request = Request(
        openai_api_url("responses"),
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=90) as response:
            response_data = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        try:
            error_data = json.loads(exc.read().decode("utf-8", errors="replace"))
            message = error_data.get("error", {}).get("message", "")
        except Exception:
            message = ""
        raise RuntimeError(
            message or "OpenAI API request failed (HTTP %s)." % exc.code
        )
    except URLError as exc:
        raise RuntimeError(
            "Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc)
        )
    except (ValueError, OSError) as exc:
        raise RuntimeError("Invalid response from OpenAI API: %s" % exc)
    output_text = str(response_data.get("output_text", "") or "")
    if not output_text:
        for output_item in response_data.get("output", []) or []:
            for content_item in output_item.get("content", []) or []:
                if content_item.get("type") == "refusal":
                    raise RuntimeError(
                        content_item.get("refusal")
                        or "The AI declined this clinical support request."
                    )
                if content_item.get("type") == "output_text":
                    output_text += str(content_item.get("text", "") or "")
    if not output_text.strip():
        raise RuntimeError("OpenAI API returned no clinical support text.")
    try:
        result = json.loads(output_text)
    except json.JSONDecodeError:
        raise RuntimeError(
            "OpenAI API returned an invalid clinical support structure."
        )
    if not isinstance(result, dict):
        raise RuntimeError(
            "OpenAI API returned an invalid clinical support structure."
        )
    support = _normalized_clinical_support(result)
    if (
        not support["pathophysiology"]
        and not support["comparisons"]
        and not support["medications"]
        and not support["paraclinical"]
    ):
        raise RuntimeError("OpenAI API returned no clinical support content.")
    support["clinical_caveat"] = " ".join(
        str(result.get("clinical_caveat", "") or "").split()
    )
    support["model"] = model
    support["language"] = language
    return support


def request_openai_nursing_map_suggestions(
    api_key, clinical_context, catalogs, model=None, language="English",
    templates=None,
):
    """Ask OpenAI to read the patient's complete record and propose a full
    Problem -> Nursing Diagnosis -> Cause/Goal/Intervention map in one
    pass: Heading 1 patient problems (current and relevant long-standing
    ones), and for every nursing diagnosis its own causes, goals and
    categorized interventions, diagnoses ranked from the most critical /
    emergent down to stable and least impactful. The prompt is told
    exactly which items already exist in the shared catalog for every
    heading and is instructed to reuse that wording first and only invent
    new text for what the catalog does not already cover."""
    api_key = str(api_key or "").strip()
    if not api_key:
        raise ValueError("OpenAI API key is not configured.")
    model = str(model or DEFAULT_OPENAI_REVIEW_MODEL).strip() or DEFAULT_OPENAI_REVIEW_MODEL
    language = "Vietnamese" if str(language or "").strip().lower() in (
        "vi", "vietnamese", "tiếng việt", "tieng viet"
    ) else "English"
    intervention_schema = {
        "type": "object",
        "properties": {
            "category": {
                "type": "string",
                "enum": [
                    "Nursing Care",
                    "Medication Administration",
                    "Blood Sample Collection / Laboratory",
                    "Nutrition",
                    "Procedure Implementation",
                ],
            },
            "action": {"type": "string"},
            # Heading 5: how this one intervention will be evaluated.
            "evaluation": {"type": "string"},
        },
        "required": ["category", "action", "evaluation"],
        "additionalProperties": False,
    }
    goal_schema = {
        "type": "object",
        "properties": {
            "text": {"type": "string"},
            # Heading 5: how this one goal will be evaluated.
            "evaluation": {"type": "string"},
        },
        "required": ["text", "evaluation"],
        "additionalProperties": False,
    }
    diagnosis_schema = {
        "type": "object",
        "properties": {
            "priority": {"type": "integer", "minimum": 1, "maximum": 6},
            "diagnosis": {"type": "string"},
            "causes": {
                "type": "array", "items": {"type": "string"},
                "minItems": 1, "maxItems": 6,
            },
            "goals": {
                "type": "array", "items": goal_schema,
                "minItems": 1, "maxItems": 4,
            },
            "interventions": {
                "type": "array", "items": intervention_schema,
                "minItems": 1, "maxItems": 12,
            },
        },
        "required": ["priority", "diagnosis", "causes", "goals", "interventions"],
        "additionalProperties": False,
    }
    schema = {
        "type": "object",
        "properties": {
            "problems": {
                "type": "array", "items": {"type": "string"},
                "minItems": 1, "maxItems": 8,
            },
            "diagnoses": {
                "type": "array", "items": diagnosis_schema,
                "minItems": 1, "maxItems": 6,
            },
            "clinical_caveat": {"type": "string"},
        },
        "required": ["problems", "diagnoses", "clinical_caveat"],
        "additionalProperties": False,
    }
    safe_context = _sanitized_review_data(clinical_context)
    if isinstance(safe_context, dict):
        safe_context.pop("_safety_identifier", None)
    catalog_summary = {
        key: list((catalogs or {}).get(key, []))[:60]
        for key in (
            "patient_problem", "nursing_diagnosis", "nursing_cause",
            "nursing_goal", "nursing_intervention",
            # The technique catalog is sent whole (not truncated below) so
            # the model can only pick procedures the institution recognises.
            "nursing_procedure",
        )
    }
    catalog_summary["nursing_procedure"] = list(
        (catalogs or {}).get("nursing_procedure", [])
    )
    template_summary = [
        {
            "diagnosis": entry.get("diagnosis", ""),
            "causes": list(entry.get("causes", []))[:6],
            "goals": [
                g.get("text", "") for g in entry.get("goals", [])[:4]
                if g.get("text")
            ],
            "interventions": [
                i.get("text", "") for i in entry.get("interventions", [])[:12]
                if i.get("text")
            ],
        }
        for entry in _flatten_template_diagnoses(templates)[:20]
    ]
    payload = {
        "model": model,
        "store": False,
        "safety_identifier": str(
            (clinical_context or {}).get("_safety_identifier", "")
        ) or None,
        "instructions": (
            "You are an expert nursing clinical instructor building a "
            "complete Problem -> Nursing Diagnosis -> Cause/Goal/"
            "Intervention map from the documented data only. Read the "
            "patient clinical profile, vital signs, assessment findings, "
            "every chronological Nursing Care entry, laboratory/imaging "
            "results and current physician orders. First identify the "
            "patient's abnormal problems, both currently active ones and "
            "clinically relevant long-standing/chronic ones. Then propose "
            "the nursing diagnoses that address those problems. For every "
            "heading (patient problems, diagnoses, causes, goals, "
            "interventions) you are given the administrator-managed shared "
            "catalog already configured in this system: %s. You are also "
            "given the administrator-curated standard maps for this "
            "institution (Settings > \"Sơ đồ cây\"), read-only reference "
            "data you must never edit or contradict: %s. When a diagnosis "
            "you propose matches one of these standard maps, you must "
            "reuse its exact causes/goals/interventions wording instead of "
            "inventing your own, and only add genuinely new items the "
            "standard map does not already cover. Otherwise reuse the "
            "exact wording from the shared catalog whenever an item fits; "
            "only write new text for what neither the standard map nor "
            "the catalog already covers. Order diagnoses by priority from "
            "1 (most critical / life-threatening, needs immediate action) "
            "through stable and least-impactful (up to 6). Each goal must "
            "be patient-centred, measurable and time-bound. Each "
            "intervention must be specific, safe, linked to its diagnosis "
            "and categorized. When an intervention is a formal nursing "
            "TECHNIQUE performed at a point in time (inserting a peripheral "
            "IV or urinary catheter, giving an IM/SC/IV injection, drawing "
            "blood, passing or feeding through a nasogastric tube, "
            "suctioning, starting oxygen, changing a dressing, and so on), "
            "set its category to \"Procedure Implementation\" and copy the "
            "wording EXACTLY from the nursing_procedure catalog supplied "
            "above; never invent a technique that is not in that catalog. "
            "Ongoing care, monitoring, positioning, education and "
            "prevention are NOT techniques - give those the \"Nursing "
            "Care\" category instead. You must return a COMPLETE map that fills "
            "every one of the five headings for every diagnosis, leaving "
            "nothing blank: Heading 1 patient problems, Heading 2 nursing "
            "diagnosis with at least one cause, Heading 3 at least one "
            "measurable goal, Heading 4 at least one categorized "
            "intervention, and Heading 5 an evaluation sentence for every "
            "single goal and for every single intervention you propose. "
            "Each Heading 5 evaluation must state the observable criterion "
            "and the moment the nurse will re-check it (for example "
            "\"Re-assess the pain score after 30 minutes; goal met when "
            "the score is 3/10 or lower\"). Do not invent findings, diagnose a medical "
            "condition, prescribe medication, create a physician order, or "
            "state an intervention was completed. Return an advisory "
            "draft in %s for a nurse to review, confirm or edit before it "
            "is saved; nothing is saved automatically."
            % (
                json.dumps(catalog_summary, ensure_ascii=False),
                json.dumps(template_summary, ensure_ascii=False),
                language,
            )
        ),
        "input": (
            "Complete de-identified clinical context JSON:\n"
            + json.dumps(safe_context, ensure_ascii=False, separators=(",", ":"))
        ),
        "reasoning": {"effort": "medium"},
        "text": {
            "verbosity": "medium",
            "format": {
                "type": "json_schema",
                "name": "nursing_problem_diagnosis_map",
                "description": (
                    "Advisory Problem -> Diagnosis -> Cause/Goal/Intervention map."
                ),
                "strict": True,
                "schema": schema,
            },
        },
    }
    if not payload["safety_identifier"]:
        payload.pop("safety_identifier", None)
    request = Request(
        openai_api_url("responses"),
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=90) as response:
            response_data = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        try:
            error_data = json.loads(exc.read().decode("utf-8", errors="replace"))
            message = error_data.get("error", {}).get("message", "")
        except Exception:
            message = ""
        raise RuntimeError(message or "OpenAI API request failed (HTTP %s)." % exc.code)
    except URLError as exc:
        raise RuntimeError("Could not connect to OpenAI API: %s" % getattr(exc, "reason", exc))
    except (ValueError, OSError) as exc:
        raise RuntimeError("Invalid response from OpenAI API: %s" % exc)
    output_text = str(response_data.get("output_text", "") or "")
    if not output_text:
        for output_item in response_data.get("output", []) or []:
            for content_item in output_item.get("content", []) or []:
                if content_item.get("type") == "refusal":
                    raise RuntimeError(
                        content_item.get("refusal")
                        or "The AI declined this suggestion request."
                    )
                if content_item.get("type") == "output_text":
                    output_text += str(content_item.get("text", "") or "")
    if not output_text.strip():
        raise RuntimeError("OpenAI API returned no suggestion text.")
    try:
        result = json.loads(output_text)
    except json.JSONDecodeError:
        raise RuntimeError("OpenAI API returned an invalid map structure.")
    try:
        problems = [
            str(item or "").strip() for item in result["problems"]
            if str(item or "").strip()
        ]
        diagnoses_raw = list(result["diagnoses"])
    except (KeyError, TypeError):
        raise RuntimeError("OpenAI API returned an invalid map structure.")
    if not diagnoses_raw:
        raise RuntimeError("OpenAI API returned no nursing diagnoses.")
    diagnoses_raw.sort(key=lambda item: int(item.get("priority", 99) or 99))
    return {
        "problems": problems,
        "diagnoses": diagnoses_raw,
        "clinical_caveat": str(result.get("clinical_caveat", "") or "").strip(),
        "model": model,
        "language": language,
    }


def build_ai_nursing_problem_map(api_key, clinical_context, catalogs,
                                  model=None, language="English",
                                  templates=None):
    """Call the AI map suggestion, then snap every proposed problem/cause/
    goal/intervention/diagnosis to the shared catalog wherever it is a
    close match (source="catalog"); anything that genuinely is not in the
    catalog is kept as the AI's own text (source="ai"). Finally, any
    diagnosis that matches an administrator-curated standard map template
    (Settings > "Sơ đồ cây") has its causes/goals/interventions replaced
    with that template's exact, prioritized content (source="template")
    -- the template itself is only ever read here, never modified.
    Returns one ready-to-review nested pathway."""
    ai_result = request_openai_nursing_map_suggestions(
        api_key, clinical_context, catalogs, model, language, templates,
    )
    problem_catalog = list((catalogs or {}).get("patient_problem", []))
    diagnosis_catalog = list((catalogs or {}).get("nursing_diagnosis", []))
    cause_catalog = list((catalogs or {}).get("nursing_cause", []))
    goal_catalog = list((catalogs or {}).get("nursing_goal", []))
    intervention_catalog = list((catalogs or {}).get("nursing_intervention", []))
    procedure_catalog = list((catalogs or {}).get("nursing_procedure", []))
    # Techniques the model proposed. They are snapped to the administrator's
    # nursing_procedure catalog and collected at pathway level, because a
    # technique is performed once even when it serves several diagnoses.
    procedures = []
    seen_procedures = set()
    problems = []
    seen_problems = set()
    for raw_problem in ai_result.get("problems", []):
        text, _source = _snap_to_catalog(raw_problem, problem_catalog)
        if text and text.casefold() not in seen_problems:
            seen_problems.add(text.casefold())
            problems.append(text)
    diagnoses = []
    for raw_diagnosis in ai_result.get("diagnoses", []):
        diagnosis_text, diagnosis_source = _snap_to_catalog(
            raw_diagnosis.get("diagnosis", ""), diagnosis_catalog
        )
        if not diagnosis_text:
            continue
        causes = []
        for raw_cause in raw_diagnosis.get("causes", []) or []:
            cause_text, _source = _snap_to_catalog(raw_cause, cause_catalog)
            if cause_text:
                causes.append(cause_text)
        goals = []
        for raw_goal in raw_diagnosis.get("goals", []) or []:
            # The model now returns {"text": ..., "evaluation": ...} so
            # Heading 5 is filled in the same pass; plain strings from an
            # older response shape are still accepted.
            if isinstance(raw_goal, dict):
                raw_goal_text = raw_goal.get("text", "")
                raw_goal_evaluation = raw_goal.get("evaluation", "")
            else:
                raw_goal_text, raw_goal_evaluation = raw_goal, ""
            goal_text, goal_source = _snap_to_catalog(
                raw_goal_text, goal_catalog
            )
            if goal_text:
                goals.append({
                    "text": goal_text,
                    "evaluation": " ".join(
                        str(raw_goal_evaluation or "").split()
                    ),
                    "source": goal_source,
                })
        interventions = []
        for raw_intervention in raw_diagnosis.get("interventions", []) or []:
            raw_action = raw_intervention.get("action", "")
            # A "Procedure Implementation" item is a timed nursing technique:
            # it leaves the intervention list and joins the procedure list.
            if str(
                raw_intervention.get("category", "") or ""
            ).strip() == "Procedure Implementation":
                procedure_text, _procedure_source = _snap_to_catalog(
                    raw_action, procedure_catalog
                )
                if (procedure_text
                        and procedure_text.casefold() not in seen_procedures):
                    seen_procedures.add(procedure_text.casefold())
                    procedures.append(procedure_text)
                continue
            action_text, action_source = _snap_to_catalog(
                raw_action, intervention_catalog
            )
            if action_text:
                interventions.append({
                    "text": action_text,
                    "evaluation": " ".join(
                        str(
                            raw_intervention.get("evaluation", "") or ""
                        ).split()
                    ),
                    "source": action_source,
                })
        template_entry = _template_entry_by_diagnosis_text(
            templates, diagnosis_text
        )
        if template_entry is not None:
            # The standard map template outranks both the AI's own text
            # and the plain catalog match for this diagnosis: its causes,
            # goals and interventions (with their preset evaluations) are
            # used first, and the AI/catalog result only adds whatever the
            # template genuinely does not already cover.
            diagnosis_source = "template"
            template_causes = list(template_entry.get("causes", []))
            template_causes_folded = {c.casefold() for c in template_causes}
            causes = template_causes + [
                c for c in causes if c.casefold() not in template_causes_folded
            ]
            # A template goal without its own preset Heading 5 evaluation
            # keeps the evaluation the AI just wrote for the same wording,
            # so Heading 5 never comes back empty after the merge.
            ai_goal_evaluations = {
                g["text"].casefold(): g.get("evaluation", "") for g in goals
            }
            template_goals = [
                {
                    "text": g.get("text", ""),
                    "evaluation": (
                        g.get("evaluation", "")
                        or ai_goal_evaluations.get(
                            str(g.get("text", "")).casefold(), ""
                        )
                    ),
                    "source": "template",
                }
                for g in template_entry.get("goals", []) if g.get("text")
            ]
            template_goal_texts = {g["text"].casefold() for g in template_goals}
            goals = template_goals + [
                g for g in goals if g["text"].casefold() not in template_goal_texts
            ]
            ai_intervention_evaluations = {
                i["text"].casefold(): i.get("evaluation", "")
                for i in interventions
            }
            template_interventions = [
                {
                    "text": i.get("text", ""),
                    "evaluation": (
                        i.get("evaluation", "")
                        or ai_intervention_evaluations.get(
                            str(i.get("text", "")).casefold(), ""
                        )
                    ),
                    "source": "template",
                }
                for i in template_entry.get("interventions", []) if i.get("text")
            ]
            template_intervention_texts = {
                i["text"].casefold() for i in template_interventions
            }
            interventions = template_interventions + [
                i for i in interventions
                if i["text"].casefold() not in template_intervention_texts
            ]
        diagnoses.append({
            "diagnosis": diagnosis_text,
            "source": diagnosis_source,
            "priority": raw_diagnosis.get("priority"),
            "causes": causes,
            "goals": goals,
            "interventions": interventions,
        })
    return {
        "problems": problems,
        "diagnoses": diagnoses,
        "procedures": procedures,
        "clinical_caveat": ai_result.get("clinical_caveat", ""),
    }


class NursingMapAutoFillWorker(QThread):
    map_ready = pyqtSignal(dict)
    map_failed = pyqtSignal(str)

    def __init__(self, api_key, clinical_context, catalogs, model, language,
                 parent=None, templates=None):
        super().__init__(parent)
        self.api_key = api_key
        self.clinical_context = clinical_context
        self.catalogs = catalogs
        self.model = model
        self.language = language
        self.templates = templates or []

    def run(self):
        try:
            pathway = build_ai_nursing_problem_map(
                self.api_key, self.clinical_context, self.catalogs,
                self.model, self.language, self.templates,
            )
            self.map_ready.emit(pathway)
        except Exception as exc:
            self.map_failed.emit(str(exc))


