    LOGIN_LOCK_SECONDS = 15 * 60
    DEVICE_LOGIN_REQUEST_TTL = 5 * 60
    DEVICE_COOKIE_TTL = 365 * 24 * 60 * 60
    # Keep unfinished local drafts for up to one year unless a successful save
