            def form(self):
                """Đọc trọn vẹn thân yêu cầu POST.

                Bản cũ chỉ đọc tối đa 1 MiB rồi bỏ dở phần còn lại trong
                socket: biểu mẫu Triage dài (ABCDE + bệnh sử + tiền sử) có thể
                vượt ngưỡng, csrf bị cắt mất và người dùng nhận 403 "Invalid
                request" hoặc kết nối treo. Nay hạn mức là 8 MiB, phần dư
                (nếu có) được đọc bỏ để giữ kết nối sạch, và cờ
                ``_form_truncated`` báo cho handler trả lỗi 413 rõ ràng.
                """
                self._form_truncated = False
                try:
                    declared = int(self.headers.get("Content-Length", 0) or 0)
                except (TypeError, ValueError):
                    declared = 0
                if declared <= 0:
                    return {}
                limit = 8388608
                wanted = min(declared, limit)
                chunks = []
                remaining = wanted
                while remaining > 0:
                    chunk = self.rfile.read(min(65536, remaining))
                    if not chunk:
                        break
                    chunks.append(chunk)
                    remaining -= len(chunk)
                if declared > limit:
                    self._form_truncated = True
                    leftover = declared - limit
                    while leftover > 0:
                        chunk = self.rfile.read(min(65536, leftover))
                        if not chunk:
                            break
                        leftover -= len(chunk)
                raw = b"".join(chunks)
                content_type = str(
                    self.headers.get("Content-Type", "") or ""
                )
                if content_type.lower().startswith("multipart/form-data"):
                    message = BytesParser(policy=email_policy).parsebytes(
                        (
                            "Content-Type: %s\r\nMIME-Version: 1.0\r\n\r\n"
                            % content_type
                        ).encode("utf-8") + raw
                    )
                    values = {}
                    for part in message.iter_parts():
                        if part.get_content_disposition() != "form-data":
                            continue
                        name = str(part.get_param(
                            "name", header="content-disposition"
                        ) or "")
                        if not name:
                            continue
                        payload = part.get_payload(decode=True) or b""
                        filename = part.get_filename()
                        if filename is not None:
                            values[name] = {
                                "filename": str(filename),
                                "content_type": str(
                                    part.get_content_type() or ""
                                ),
                                "data": payload,
                            }
                        else:
                            charset = part.get_content_charset() or "utf-8"
                            values[name] = payload.decode(
                                charset, "replace"
                            )
                    return values
                return {k: v[-1] for k, v in parse_qs(
                    raw.decode("utf-8", "replace"), keep_blank_values=True
                ).items()}

            def e(self, value, quote=True):
                return html.escape(str(value or ""), quote=quote)

            def ui_label(self, setting_key, default_value=""):
                """Read shared interface captions once per web request."""
                if not hasattr(self, "_ui_label_values"):
                    values = dict(UI_LABEL_DEFAULTS)
                    db = owner.connect()
                    try:
                        rows = db.execute(
                            """SELECT setting_key,setting_value
                               FROM ui_label_settings"""
                        ).fetchall()
                    finally:
                        db.close()
                    for row in rows:
                        key = str(row["setting_key"] or "")
                        value = str(row["setting_value"] or "").strip()
                        if key in values and value:
                            values[key] = value
                    self._ui_label_values = values
                return self._ui_label_values.get(
                    str(setting_key or ""), default_value
                )

