            def language(self):
                """Ngôn ngữ của yêu cầu hiện tại.

                Thứ tự ưu tiên: tham số ?lang= -> cookie emr_lang -> lựa chọn
                đã lưu của cả hệ thống -> mặc định Tiếng Anh.
                """
                if getattr(self, "_language", None):
                    return self._language
                query = parse_qs(urlparse(self.path).query)
                chosen = str(query.get("lang", [""])[0] or "").strip()
                if not chosen:
                    chosen = self.cookies().get("emr_lang", "")
                if not chosen:
                    db = owner.connect()
                    try:
                        chosen = read_app_language(db)
                    finally:
                        db.close()
                self._language = normalize_app_language(chosen)
                return self._language

            def tr(self, english, vietnamese):
                """Return request-language text for dynamic web-only labels."""
                return vietnamese if self.language() == "vi" else english

            def gender_display(self, value):
                """Render a stored gender value in the active interface language.

                The database keeps the stable English option values so records are
                portable; labels, barcode sheets, and scanner results are translated
                only when they are displayed.
                """
                raw = str(value or "").strip()
                key = raw.casefold()
                if key in {"male", "m", "nam", "man"}:
                    return self.tr("Male", "Nam")
                if key in {"female", "f", "nữ", "nu", "woman"}:
                    return self.tr("Female", "Nữ")
                if key in {"other", "khác", "khac"}:
                    return self.tr("Other", "Khác")
                return raw or "-"

            def ai_configuration(self):
                db = owner.connect()
                try:
                    return read_ai_configuration(db)
                finally:
                    db.close()

            def openai_api_key(self):
                return resolve_openai_api_key(owner.db_path)[0]

            def openai_text_model(self):
                configured = self.ai_configuration()["text_model"]
                requested = str(
                    os.environ.get("OPENAI_REVIEW_MODEL", "")
                    or os.environ.get("OPENAI_NANDA_MODEL", "")
                    or configured
                ).strip()
                # Environment overrides are convenient for deployment, but a
                # typo must not make every clinical/classroom AI workflow
                # fail at request time.  Use only models exposed in the
                # Admin-controlled picker, otherwise return the safe default.
                return (
                    requested if requested in OPENAI_TEXT_MODELS
                    else DEFAULT_OPENAI_REVIEW_MODEL
                )

            def role(self, user):
                return str((user or {}).get("role", "") or "").strip().lower()

            def access_role(self, user):
                role = self.role(user)
                if self.is_admin(user):
                    return "admin"
                if role in ("lecturer", "teacher"):
                    return "instructor"
                return role if role in ROLE_PERMISSION_PRESETS else "guest"

            def staff_position(self, user):
                position = str(
                    (user or {}).get("position_title", "") or ""
                ).strip().lower()
                return (
                    position if position in STAFF_POSITION_KEYS
                    else "staff_member"
                )

            def can_manage_patient_assignments(self, user):
                return bool(
                    self.is_admin(user)
                    or self.staff_position(user)
                    in PATIENT_ASSIGNMENT_MANAGER_POSITIONS
                )

            def can_broadcast_all_notifications(self, user):
                return bool(
                    self.is_admin(user)
                    or "notifications_broadcast_all"
                    in self.effective_role_features(user)
                )

            def effective_role_features(self, user):
                """Resolve the role defaults plus per-account overrides.

                A role supplies the default capabilities. Per-account rows are
                stored only where an administrator changed a tick away from the
                role default, and they override it in both directions.
                """
                if self.is_admin(user):
                    # The Admin row is an editable configuration template;
                    # it is not an access restriction on the administrator.
                    return set(ROLE_ACCESS_LABELS)
                access_role = self.access_role(user)
                db = owner.connect()
                try:
                    features = set(configured_role_permission_matrix(db).get(
                        access_role,
                        set(ROLE_PERMISSION_PRESETS["guest"]),
                    ))
                    # Account-level ticks are stored only where they differ
                    # from the role default, and they are a true override:
                    # allowed=1 adds the feature, allowed=0 removes it.  An
                    # account with no override rows keeps following its role,
                    # so a later change to the role matrix reaches it at once.
                    overrides = db.execute(
                        """SELECT feature_key,allowed
                           FROM account_feature_permissions
                           WHERE username=?""",
                        (user.get("username", ""),),
                    ).fetchall()
                    for row in overrides:
                        feature_key = str(row["feature_key"] or "")
                        if feature_key not in ROLE_ACCESS_LABELS:
                            continue
                        if int(row["allowed"] or 0):
                            features.add(feature_key)
                        else:
                            features.discard(feature_key)
                    return features
                finally:
                    db.close()

