                    def flag(name):
                        return 1 if str(f.get(name, "")).lower() in (
                            "1", "true", "yes", "on"
                        ) else 0

                    def bounded_int(name, default, minimum, maximum):
                        try:
                            value = int(str(f.get(name, default)).strip())
                        except (TypeError, ValueError):
                            value = default
                        return max(minimum, min(maximum, value))

                    def submitted_thresholds(kind):
                        result = {}
                        for key, spec in VITAL_THRESHOLD_SPEC_BY_KEY.items():
                            default_pair = default_vital_thresholds(kind)[key]
                            pair = {}
                            for edge in ("min", "max"):
                                field_name = "%s_%s_%s" % (kind, key, edge)
                                raw = str(
                                    f.get(field_name, default_pair[edge])
                                ).strip().replace(",", ".")
                                try:
                                    number = float(raw)
                                except (TypeError, ValueError):
                                    raise ValueError(
                                        "Invalid numeric threshold: %s"
                                        % field_name
                                    )
                                if (
                                    not math.isfinite(number)
                                    or number < spec["hard_min"]
                                    or number > spec["hard_max"]
                                ):
                                    raise ValueError(
                                        "Threshold outside the allowed range: %s"
                                        % field_name
                                    )
                                pair[edge] = number
                            if pair["min"] > pair["max"]:
                                raise ValueError(
                                    "%s: minimum threshold cannot exceed maximum"
                                    % spec["label_en"]
                                )
                            result[key] = pair
                        return result

                    sound_style = str(f.get("sound_style", "beep")).strip()
