    def update_user_account(self, username: str, nurse_code: str, full_name: str,
                            role: str, new_password: str = "", current_username: str = "",
                            department: str = ""):
        username = username.strip()
        role = role.strip().lower()
        if role not in (
            "staff", "nurse", "physician", "pharmacist",
            "imaging_technician", "lab_technician", "dietitian_physician",
            "student", "instructor", "admin",
        ):
            raise ValueError("Invalid account role.")
        cursor = self.conn.cursor()
        row = cursor.execute("SELECT role FROM users WHERE username = ?", (username,)).fetchone()
        if not row:
            raise ValueError("Account not found.")
        if username == current_username and row[0] == "admin" and role != "admin":
            raise ValueError("You cannot remove the administrator role from the account currently in use.")
        if row[0] == "admin" and role != "admin":
            admin_count = cursor.execute("SELECT COUNT(*) FROM users WHERE role='admin'").fetchone()[0]
            if admin_count <= 1:
                raise ValueError("At least one administrator account must remain.")
        department = (department or "").strip()
        if new_password:
            cursor.execute(
                "UPDATE users SET nurse_code=?, full_name=?, role=?, password=?, department=? WHERE username=?",
                (
                    nurse_code.strip(), full_name.strip(), role,
                    hash_password(new_password), department, username,
                )
            )
        else:
            cursor.execute(
                "UPDATE users SET nurse_code=?, full_name=?, role=?, department=? WHERE username=?",
                (nurse_code.strip(), full_name.strip(), role, department, username)
            )
        self.conn.commit()
        self.log_activity(username, full_name, role, "Desktop", "account_updated", "Account details updated")

    def delete_user_account(self, username: str, current_username: str = ""):
        username = username.strip()
        if username == current_username:
            raise ValueError("You cannot delete the account currently in use.")
        cursor = self.conn.cursor()
        row = cursor.execute("SELECT role FROM users WHERE username = ?", (username,)).fetchone()
        if not row:
            raise ValueError("Account not found.")
        if row[0] == "admin":
            admin_count = cursor.execute("SELECT COUNT(*) FROM users WHERE role='admin'").fetchone()[0]
            if admin_count <= 1:
                raise ValueError("The last administrator account cannot be deleted.")
        cursor.execute("DELETE FROM users WHERE username = ?", (username,))
        cursor.execute("DELETE FROM account_feature_permissions WHERE username = ?", (username,))
        self.conn.commit()
        self.log_activity(username, "", row[0], "Desktop", "account_deleted", "Account deleted")

    def user_can_access_feature(self, username, role, feature_key):
        """Resolve access from the role matrix plus per-account overrides.

        Mirrors the Mobile Web resolver: the role supplies the defaults and
        any per-account row saved in Account Management overrides it in both
        directions.
        """
        role = str(role or "").strip().lower()
        if role == "admin":
            return True
        if not username:
            return True
        features = set(configured_role_permission_matrix(self.conn).get(
            role, set(ROLE_PERMISSION_PRESETS["guest"]),
        ))
        for row in self.conn.execute(
            "SELECT feature_key,allowed FROM account_feature_permissions "
            "WHERE username=?", (username,),
        ).fetchall():
            key = str(row[0] or "")
            if key not in ROLE_ACCESS_LABELS:
                continue
            if int(row[1] or 0):
                features.add(key)
            else:
                features.discard(key)
        return feature_key in features
    def log_activity(self, username, full_name, role, source, action, details=""):
        self.conn.execute(
            "INSERT INTO activity_logs(occurred_dt,username,full_name,role,source,action,details) VALUES(?,?,?,?,?,?,?)",
            (datetime.now().strftime("%Y-%m-%d %H:%M:%S"), username or "", full_name or "", role or "", source or "", action, details or "")
        )
        self.conn.commit()

    def list_activity_logs(self, limit=500, date_from="", date_to="",
                           username="", source="", kind=""):
        """Nhật ký hoạt động, có lọc để tab Activity Log dùng lại.

        ``kind`` gom nhóm hành động cho người xem không cần nhớ tên kỹ thuật:
        ``login`` (đăng nhập/đăng xuất), ``data`` (mọi thao tác ghi dữ liệu),
        ``account`` (tạo/sửa/xoá tài khoản). Bỏ trống là lấy tất cả.
        """
        where, args = [], []
        if date_from:
            where.append("date(occurred_dt)>=?")
            args.append(date_from)
        if date_to:
            where.append("date(occurred_dt)<=?")
            args.append(date_to)
        if username:
            where.append("lower(username)=lower(?)")
            args.append(username)
        if source:
            where.append("source=?")
            args.append(source)
        kind = str(kind or "").strip().lower()
        if kind == "login":
            where.append("lower(action) IN ('login','logout')")
        elif kind == "data":
            where.append(
                "lower(action) NOT IN ('login','logout') "
                "AND lower(action) NOT LIKE 'account_%'"
            )
        elif kind == "account":
            where.append("lower(action) LIKE 'account_%'")
        clause = (" WHERE " + " AND ".join(where)) if where else ""
        return self.conn.execute(
            "SELECT occurred_dt,username,full_name,role,action,details,"
            "device_label,client_ip,session_login_dt "
            "FROM activity_logs" + clause + " ORDER BY log_id DESC LIMIT ?",
            args + [int(limit)],
        ).fetchall()

    def activity_log_usernames(self):
        return [
            str(row[0] or "") for row in self.conn.execute(
                "SELECT DISTINCT username FROM activity_logs "
                "WHERE TRIM(COALESCE(username,''))<>'' "
                "ORDER BY username COLLATE NOCASE"
            ).fetchall()
        ]

    # --- Hiện diện: đang online + thống kê theo ngày/tuần ------------------
    # "Đang online" = có nhịp tim trong ONLINE_PRESENCE_WINDOW_MINUTES phút
    # gần nhất. "Đã hiện diện" trong một ngày = có bất kỳ dòng activity_logs
    # nào của ngày đó; khoảng hiện diện tính từ thao tác đầu đến thao tác
    # cuối, nên phản ánh làm việc thực tế chứ không chỉ mỗi lần đăng nhập.

    def touch_active_session(self, session_key, username, full_name="",
                             role="", source="Desktop"):
        """Ghi/làm mới nhịp tim của một phiên đang mở."""
        now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.conn.execute(
            """INSERT INTO active_sessions(
                   session_key,username,full_name,role,source,
                   login_dt,last_seen)
               VALUES(?,?,?,?,?,?,?)
               ON CONFLICT(session_key) DO UPDATE SET
                   username=excluded.username,
                   full_name=excluded.full_name,
                   role=excluded.role,
                   source=excluded.source,
                   last_seen=excluded.last_seen""",
            (
                str(session_key), username or "", full_name or "", role or "",
                source or "Desktop", now_text, now_text,
            ),
        )
        self.conn.commit()

    def end_active_session(self, session_key):
        self.conn.execute(
            "DELETE FROM active_sessions WHERE session_key=?",
            (str(session_key),),
        )
        self.conn.commit()

    def list_online_users(self, within_minutes=ONLINE_PRESENCE_WINDOW_MINUTES):
        """Ai đang online ngay lúc này, gộp phiên Desktop và Mobile Web.

        Một người mở cả hai nơi chỉ hiện một dòng, cột Nguồn ghi cả hai.
        """
        now = datetime.now()
        cutoff = (
            now - timedelta(minutes=max(1, int(within_minutes)))
        ).strftime("%Y-%m-%d %H:%M:%S")
        merged = {}

        def absorb(username, full_name, role, source, login_dt, last_seen):
            username = str(username or "").strip()
            if not username:
                return
            entry = merged.setdefault(username, {
                "username": username, "full_name": "", "role": "",
                "sources": [], "login_dt": "", "last_seen": "",
            })
            if full_name and not entry["full_name"]:
                entry["full_name"] = str(full_name)
            if role and not entry["role"]:
                entry["role"] = str(role)
            source = str(source or "").strip()
            if source and source not in entry["sources"]:
                entry["sources"].append(source)
            login_dt = str(login_dt or "")
            if login_dt and (not entry["login_dt"]
                             or login_dt < entry["login_dt"]):
                entry["login_dt"] = login_dt
            last_seen = str(last_seen or "")
            if last_seen > entry["last_seen"]:
                entry["last_seen"] = last_seen

        for row in self.conn.execute(
            """SELECT username,full_name,role,source,login_dt,last_seen
               FROM active_sessions WHERE last_seen>=?""",
            (cutoff,),
        ).fetchall():
            absorb(row[0], row[1], row[2], row[3] or "Desktop", row[4], row[5])

        # Bảng phiên của Mobile Web do máy chủ web tạo; nếu chưa từng chạy
        # web thì bảng có thể chưa tồn tại, khi đó chỉ tính phiên Desktop.
        try:
            web_rows = self.conn.execute(
                """SELECT m.username,COALESCE(u.full_name,''),
                          COALESCE(u.role,''),m.last_seen
                   FROM mobile_web_sessions m
                   LEFT JOIN users u ON u.username=m.username
                   WHERE m.expires>=? AND m.last_seen>=?""",
                (now.timestamp(), cutoff),
            ).fetchall()
        except sqlite3.Error:
            web_rows = []
        for row in web_rows:
            absorb(row[0], row[1], row[2], "Mobile Web", "", row[3])

        for entry in merged.values():
            if not entry["full_name"] or not entry["role"]:
                account = self.conn.execute(
                    "SELECT full_name,role FROM users WHERE username=?",
                    (entry["username"],),
                ).fetchone()
                if account:
                    entry["full_name"] = entry["full_name"] or str(
                        account[0] or ""
                    )
                    entry["role"] = entry["role"] or str(account[1] or "")
            entry["source"] = " + ".join(entry["sources"]) or "Desktop"
            entry["idle_seconds"] = _seconds_between(entry["last_seen"], now)
        return sorted(
            merged.values(), key=lambda item: item["last_seen"], reverse=True
        )

    def _presence_day_rows(self, date_from, date_to):
        """Một dòng cho mỗi (tài khoản, ngày) có hoạt động."""
        return self.conn.execute(
            """SELECT username,
                      date(occurred_dt) AS day,
                      MAX(full_name) AS full_name,
                      MAX(role) AS role,
                      MIN(occurred_dt) AS first_dt,
                      MAX(occurred_dt) AS last_dt,
                      COUNT(*) AS events,
                      SUM(CASE WHEN lower(action)='login'
                               THEN 1 ELSE 0 END) AS logins,
                      SUM(CASE WHEN lower(action) NOT IN ('login','logout')
                               THEN 1 ELSE 0 END) AS writes,
                      GROUP_CONCAT(DISTINCT source) AS sources
               FROM activity_logs
               WHERE date(occurred_dt) BETWEEN ? AND ?
                 AND TRIM(COALESCE(username,''))<>''
               GROUP BY username, date(occurred_dt)""",
            (date_from, date_to),
        ).fetchall()

    def presence_by_day(self, day=None):
        day = str(day or datetime.now().strftime("%Y-%m-%d"))
        online = {
            entry["username"]: entry
            for entry in self.list_online_users()
        }
        result = []
        for row in self._presence_day_rows(day, day):
            username = str(row[0] or "")
            first_dt, last_dt = str(row[4] or ""), str(row[5] or "")
            result.append({
                "username": username,
                "full_name": str(row[2] or ""),
                "role": str(row[3] or ""),
                "day": str(row[1] or day),
                "first_dt": first_dt,
                "last_dt": last_dt,
                "minutes": _minutes_between(first_dt, last_dt),
                "events": int(row[6] or 0),
                "logins": int(row[7] or 0),
                "writes": int(row[8] or 0),
                "sources": str(row[9] or "").replace(",", " + "),
                "online": username in online,
            })
        result.sort(key=lambda item: (item["first_dt"], item["username"]))
        return result

    @staticmethod
    def week_start_for(day=None):
        """Thứ Hai của tuần chứa ``day`` (chuỗi YYYY-MM-DD)."""
        if isinstance(day, str) and day:
            try:
                base = datetime.strptime(day[:10], "%Y-%m-%d")
            except ValueError:
                base = datetime.now()
        elif isinstance(day, datetime):
            base = day
        else:
            base = datetime.now()
        return (base - timedelta(days=base.weekday())).strftime("%Y-%m-%d")

    def presence_by_week(self, week_start=None):
        start_text = self.week_start_for(week_start)
        start = datetime.strptime(start_text, "%Y-%m-%d")
        end_text = (start + timedelta(days=6)).strftime("%Y-%m-%d")
        online = {
            entry["username"] for entry in self.list_online_users()
        }
        people = {}
        for row in self._presence_day_rows(start_text, end_text):
            username = str(row[0] or "")
            entry = people.setdefault(username, {
                "username": username, "full_name": "", "role": "",
                "week_start": start_text, "week_end": end_text,
                "days": {}, "days_present": 0, "minutes": 0,
                "events": 0, "logins": 0, "writes": 0, "sources": [],
            })
            if row[2] and not entry["full_name"]:
                entry["full_name"] = str(row[2])
            if row[3] and not entry["role"]:
                entry["role"] = str(row[3])
            minutes = _minutes_between(str(row[4] or ""), str(row[5] or ""))
            entry["days"][str(row[1] or "")] = minutes
            entry["days_present"] += 1
            entry["minutes"] += minutes
            entry["events"] += int(row[6] or 0)
            entry["logins"] += int(row[7] or 0)
            entry["writes"] += int(row[8] or 0)
            for name in str(row[9] or "").split(","):
                name = name.strip()
                if name and name not in entry["sources"]:
                    entry["sources"].append(name)
        result = []
        for entry in people.values():
            entry["sources"] = " + ".join(entry["sources"])
            entry["online"] = entry["username"] in online
            result.append(entry)
        result.sort(
            key=lambda item: (-item["days_present"], item["username"].lower())
        )
        return result

