    PATIENT_HISTORY_FIELDS = (
        "history_present_illness",
        "past_medical_history",
        "family_history",
        "allergies",
    )

    def get_patient_history(self, patient_id):
        """Read the four Tiền sử bệnh fields for one patient.

        Returns None when the patient does not exist. Desktop and Mobile Web
        read the exact same columns, so both clients always show the same
        medical history."""
        row = self.conn.execute(
            """SELECT history_present_illness,past_medical_history,
               family_history,allergies FROM patients WHERE id=?""",
            (str(patient_id or ""),),
        ).fetchone()
        if row is None:
            return None
        return {
            key: str(row[index] or "")
            for index, key in enumerate(self.PATIENT_HISTORY_FIELDS)
        }

    def update_patient_history(self, patient_id, values):
        """Update only the Tiền sử bệnh fields, leaving every other patient
        column untouched. Returns the list of fields that actually changed,
        or None when the patient id does not exist."""
        patient_id = str(patient_id or "").strip()
        if not patient_id:
            return None
        previous = self.get_patient_history(patient_id)
        if previous is None:
            return None
        cleaned = {
            key: str(values.get(key, "") or "").strip()
            for key in self.PATIENT_HISTORY_FIELDS
        }
        changed = [
            key for key in self.PATIENT_HISTORY_FIELDS
            if previous[key] != cleaned[key]
        ]
        self.conn.execute(
            """UPDATE patients SET history_present_illness=?,
               past_medical_history=?,family_history=?,allergies=?,
               allergy_status=CASE
                   WHEN trim(?)<>'' THEN ?
                   WHEN allergy_status=? THEN ''
                   ELSE allergy_status END,
               updated_dt=? WHERE id=?""",
            (
                cleaned["history_present_illness"],
                cleaned["past_medical_history"],
                cleaned["family_history"],
                cleaned["allergies"],
                cleaned["allergies"],
                ALLERGY_STATUS_HAS,
                ALLERGY_STATUS_HAS,
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                patient_id,
            ),
        )
        self.conn.commit()
        return changed

    def _extract_gender_from_snapshot(self, snapshot):
        if not snapshot:
            return ""
        try:
            snap = json.loads(snapshot) if isinstance(snapshot, str) else snapshot
            if isinstance(snap, dict):
                value = snap.get("cb_admin_gender") or snap.get("gender")
                return str(value).strip() if value is not None else ""
        except Exception:
            pass
        return ""

    def _build_patient_list_rows(self, rows):
        """Chuẩn hóa dòng cho bảng danh sách người bệnh.

        Trả về (id, name, gender, dob, care_level, department, diagnosis).
        Cột Bed và cột Care cũ đã bỏ; thay bằng Care Level lấy từ ghi chép
        điều dưỡng gần nhất, đúng như Mobile Web hiển thị.
        """
        normalized = []
        cursor = self.conn.cursor()
        for row in rows or []:
            pid = row[0] if len(row) > 0 else ""
            name = row[1] if len(row) > 1 else ""
            dob = row[2] if len(row) > 2 else ""
            gender = row[3] if len(row) > 3 else ""
            diagnosis = row[4] if len(row) > 4 else ""
            department = row[5] if len(row) > 5 else ""
            care_level = ""
            if pid:
                try:
                    cursor.execute('''SELECT snapshot FROM nursing_care
                                      WHERE patient_id = ?
                                      ORDER BY datetime(care_dt) DESC, care_id DESC
                                      LIMIT 1''', (pid,))
                    last = cursor.fetchone()
                    raw_snapshot = last[0] if last else ""
                    if not gender:
                        gender = self._extract_gender_from_snapshot(
                            raw_snapshot
                        )
                    care_level = latest_recorded_care_level(self.conn, pid)
                except Exception:
                    gender = gender or ""
            normalized.append((
                pid or "", name or "", gender or "", dob or "",
                care_level, department or "", diagnosis or ""
            ))
        return normalized

    def get_patient_list_rows(
        self, selected_date=None, query="", current_user=None
    ):
        cursor = self.conn.cursor()
        where = []
        args = []
        selected_date = str(selected_date or "").strip()
        query = str(query or "").strip()
        role = str((current_user or {}).get("role", "") or "").lower()
        username = str(
            (current_user or {}).get("username", "") or ""
        )
        if current_user and role not in (
            "admin", "instructor", "lecturer", "teacher"
        ):
            where.append("""(
                COALESCE(is_exam,0)=0 OR EXISTS (
                    SELECT 1 FROM exam_attempts ea
                    JOIN exam_patient_groups epg
                      ON epg.exam_patient_group_id=
                         ea.exam_patient_group_id
                     AND epg.active=1
                    JOIN exam_group_members egm
                      ON egm.group_id=ea.group_id
                     AND egm.username=ea.examinee_username
                    WHERE ea.patient_id=patients.id
                      AND ea.examinee_username=?
                )
            )""")
            args.append(username)
        if selected_date:
            where.append("""(id LIKE ? OR EXISTS (
                SELECT 1 FROM nursing_care n
                WHERE n.patient_id=patients.id AND date(n.care_dt)=?
            ) OR EXISTS (
                SELECT 1 FROM triage_records t
                WHERE t.patient_id=patients.id AND date(t.triage_dt)=?
            ) OR date(COALESCE(
                NULLIF(patients.created_dt,''),
                NULLIF(patients.updated_dt,'')
            ))=?)""")
            try:
                prefix = datetime.strptime(
                    selected_date, "%Y-%m-%d"
                ).strftime("%y%m%d") + "%"
            except ValueError:
                prefix = "__invalid_date__"
            args.extend([prefix, selected_date, selected_date, selected_date])
        if query:
            where.append(
                "(id LIKE ? OR name LIKE ? OR diagnosis LIKE ?)"
            )
            args.extend(["%" + query + "%"] * 3)
        sql = (
            "SELECT id, name, dob, gender, diagnosis, department "
            "FROM patients"
        )
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += " ORDER BY name COLLATE NOCASE,id"
        cursor.execute(sql, args)
        return self._build_patient_list_rows(cursor.fetchall())

    def search_patient_list_rows(self, query, current_user=None):
        return self.get_patient_list_rows(
            query=query, current_user=current_user
        )

    def generate_next_patient_id(self, for_date=None):
        """Generate unique 10-digit patient id: YYMMDD + 4-digit daily sequence."""
        if for_date is None:
            for_date = datetime.now()
        prefix = for_date.strftime("%y%m%d")
        cursor = self.conn.cursor()
        cursor.execute("SELECT id FROM patients WHERE id LIKE ? ORDER BY id DESC LIMIT 1", (f"{prefix}%",))
        row = cursor.fetchone()
        last_seq = 0
        if row and row[0]:
            try:
                last_seq = int(str(row[0])[-4:])
            except Exception:
                last_seq = 0
        next_seq = last_seq + 1
        if next_seq > 9999:
            raise ValueError("Daily patient sequence exceeded 9999")
        return f"{prefix}{next_seq:04d}"

    def upsert_patient(self, patient):
        cursor = self.conn.cursor()
        cursor.execute('''INSERT INTO patients (id, name, dob, gender, diagnosis)
                        VALUES (?, ?, ?, ?, ?)
                        ON CONFLICT(id) DO UPDATE SET
                            name=excluded.name,
                            dob=excluded.dob,
                            gender=CASE
                                WHEN excluded.gender IS NOT NULL AND TRIM(excluded.gender) <> '' THEN excluded.gender
                                ELSE patients.gender
                            END,
                            diagnosis=excluded.diagnosis''',
                    (patient.patient_id, patient.name, patient.dob, getattr(patient, 'gender', '') or '', patient.diagnosis))
        self.conn.commit()


