        if not int(row[0] or 0):
            return True
        role = str((current_user or {}).get("role", "") or "").lower()
        if role in ("admin", "instructor", "lecturer", "teacher"):
            return True
        return bool(self.get_exam_attempt(patient_id, current_user))

