    def save_triage_record(self, patient_id, triage_dt, nurse_code, nurse_name,
                           triage_data, source="Desktop", triage_id=None):
        patient = self.conn.execute(
            "SELECT department FROM patients WHERE id=?", (patient_id,)
        ).fetchone()
        if not patient:
            raise ValueError("Patient not found.")
        if not _is_emergency_department(patient[0]):
            raise ValueError(
                "Triage is available only for patients in the Emergency Department."
            )
        now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        handoff = (
            triage_data.get("handoff", {})
            if isinstance(triage_data, dict)
            and isinstance(triage_data.get("handoff"), dict) else {}
        )
        handoff_username = str(
            handoff.get("student_username", "") or ""
        ).strip()
        student = None
        if handoff_username:
            student = self.conn.execute(
                """SELECT username,nurse_code,full_name FROM users
                   WHERE username=? AND lower(role)='student'""",
                (handoff_username,),
            ).fetchone()
            if not student:
                raise ValueError("Select a valid nursing student for handoff.")
        payload = json.dumps(
            triage_data if isinstance(triage_data, dict) else {},
            ensure_ascii=False,
        )
        if triage_id:
            existing = self.conn.execute(
                "SELECT patient_id FROM triage_records WHERE triage_id=?",
                (int(triage_id),),
            ).fetchone()
            if not existing or str(existing[0]) != str(patient_id):
                raise ValueError("Triage record not found for this patient.")
            self.conn.execute(
                """UPDATE triage_records SET triage_dt=?,nurse_code=?,
                   nurse_name=?,triage_data=?,source=?,updated_dt=?
                   WHERE triage_id=?""",
                (
                    triage_dt, nurse_code, nurse_name, payload, source,
                    now_text, int(triage_id),
                ),
            )
            saved_id = int(triage_id)
        else:
            cursor = self.conn.execute(
                """INSERT INTO triage_records(
                   patient_id,triage_dt,nurse_code,nurse_name,triage_data,
                   source,created_dt,updated_dt
                   ) VALUES(?,?,?,?,?,?,?,?)""",
                (
                    patient_id, triage_dt, nurse_code, nurse_name, payload,
                    source, now_text, now_text,
                ),
            )
            saved_id = int(cursor.lastrowid or 0)
        if student:
            self.conn.execute("""INSERT INTO triage_handoffs(
                    triage_id,patient_id,student_username,student_code,
                    student_name,assigned_dt,assigned_by_username,
                    assigned_by_code,assigned_by_name,acknowledged_dt,
                    source,updated_dt
                ) VALUES(?,?,?,?,?,?,?,?,?,'',?,?)
                ON CONFLICT(triage_id) DO UPDATE SET
                    patient_id=excluded.patient_id,
                    student_code=excluded.student_code,
                    student_name=excluded.student_name,
                    assigned_by_username=excluded.assigned_by_username,
                    assigned_by_code=excluded.assigned_by_code,
                    assigned_by_name=excluded.assigned_by_name,
                    assigned_dt=CASE
                        WHEN triage_handoffs.student_username=excluded.student_username
                        THEN triage_handoffs.assigned_dt ELSE excluded.assigned_dt END,
                    acknowledged_dt=CASE
                        WHEN triage_handoffs.student_username=excluded.student_username
                        THEN triage_handoffs.acknowledged_dt ELSE '' END,
                    student_username=excluded.student_username,
                    source=excluded.source,updated_dt=excluded.updated_dt""", (
                saved_id, patient_id, student[0], student[1], student[2],
                str(handoff.get("assigned_dt", "") or now_text),
                str(
                    triage_data.get("entered_by_username", "")
                    if isinstance(triage_data, dict) else ""
                ),
                nurse_code, nurse_name, source, now_text,
            ))
            self.conn.execute(
                """DELETE FROM triage_handoff_acceptances
                   WHERE triage_id=? AND assigned_student_username<>?""",
                (saved_id, student[0]),
            )
        self.conn.commit()
        return saved_id

    def get_student_handoffs(self, student_username, only_new=True):
        sql = """SELECT h.triage_id,h.patient_id,h.student_username,
                    h.student_code,h.student_name,h.assigned_dt,
                    h.acknowledged_dt,p.name,p.dob,p.gender,p.diagnosis,
                    p.department,t.triage_dt,t.triage_data
                 FROM triage_handoffs h
                 JOIN patients p ON p.id=h.patient_id
                 JOIN triage_records t ON t.triage_id=h.triage_id
                 WHERE h.student_username=?"""
        args = [str(student_username or "")]
        if only_new:
            sql += " AND trim(COALESCE(h.acknowledged_dt,''))=''"
        sql += """ ORDER BY datetime(h.assigned_dt) DESC,h.triage_id DESC"""
        return self.conn.execute(sql, args).fetchall()

