    def has_handoff_coverage_acceptance(self, triage_id, username):
        return bool(self.conn.execute(
            """SELECT acceptance_id FROM triage_handoff_acceptances
               WHERE triage_id=? AND covering_username=?""",
            (int(triage_id), str(username or "")),
        ).fetchone())

    def accept_handoff_coverage(self, triage_id, covering_user,
                                source="Desktop"):
        handoff = self.conn.execute(
            """SELECT h.*,p.name AS patient_name
               FROM triage_handoffs h
               JOIN patients p ON p.id=h.patient_id
               WHERE h.triage_id=?""",
            (int(triage_id),),
        ).fetchone()
        if not handoff:
            raise ValueError("Patient handoff not found.")
        username = str((covering_user or {}).get("username", "") or "")
        if not username:
            raise ValueError("A logged-in nursing student is required.")
        if username == str(handoff["student_username"] or ""):
            self.acknowledge_triage_handoff(
                username, triage_id=int(triage_id)
            )
            return
        now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        covering_name = str(
            (covering_user or {}).get("full_name", "") or username
        )
        assigned_name = str(
            handoff["student_name"] or handoff["student_username"] or ""
        )
        message = (
            "%s agreed to care for patient %s and will notify the assigned "
            "nursing student %s."
            % (
                covering_name,
                handoff["patient_name"] or handoff["patient_id"],
                assigned_name,
            )
        )
        self.conn.execute(
            """INSERT INTO triage_handoff_acceptances(
                   triage_id,patient_id,assigned_student_username,
                   assigned_student_name,covering_username,covering_code,
                   covering_name,accepted_dt,message,source,
                   assigned_notified_dt
               ) VALUES(?,?,?,?,?,?,?,?,?,?,'')
               ON CONFLICT(triage_id,covering_username) DO UPDATE SET
                   covering_code=excluded.covering_code,
                   covering_name=excluded.covering_name,
                   accepted_dt=excluded.accepted_dt,
                   message=excluded.message,source=excluded.source,
                   assigned_notified_dt=''""",
            (
                int(triage_id), handoff["patient_id"],
                handoff["student_username"], assigned_name,
                username,
                str((covering_user or {}).get("nurse_code", "") or ""),
                covering_name, now_text, message, source,
            ),
        )
        self.conn.commit()

    def get_handoff_coverage_notices(self, assigned_username):
        return self.conn.execute(
            """SELECT a.*,p.name AS patient_name
               FROM triage_handoff_acceptances a
               JOIN patients p ON p.id=a.patient_id
               WHERE a.assigned_student_username=?
               ORDER BY datetime(a.accepted_dt) DESC,a.acceptance_id DESC""",
            (str(assigned_username or ""),),
        ).fetchall()

    def acknowledge_triage_handoff(self, student_username, triage_id=None,
                                   patient_id=None):
        where = ["student_username=?"]
        args = [str(student_username or "")]
        if triage_id is not None:
            where.append("triage_id=?")
            args.append(str(int(triage_id)))
        if patient_id is not None:
            where.append("patient_id=?")
            args.append(str(patient_id))
        now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.conn.execute(
            """UPDATE triage_handoffs SET acknowledged_dt=CASE
                   WHEN trim(COALESCE(acknowledged_dt,''))=''
                   THEN ? ELSE acknowledged_dt END,updated_dt=?
               WHERE """ + " AND ".join(where),
            [now_text, now_text] + args,
        )
        self.conn.commit()

