    def _on_exam_status_change(self, cat: str, idx: int):
        """idx=0: Chưa phát hiện bất thường -> chỉ hiện 'Trạng thái' và cho nó chiếm hết.
        idx=1: Bất thường -> hiện list + chi tiết + Thêm."""
        row = self.exam_rows[cat]
        is_abn = (idx == 1)

        row["abn"].setVisible(is_abn)
        row["detail"].setVisible(is_abn)
        row["add"].setVisible(is_abn)

        # Điều chỉnh stretch trong container để 'Trạng thái' đầy ô khi bình thường
        box_layout = row["box"].layout()
        if is_abn:
            # Khi bất thường: chia chỗ cho detail; trạng thái vẫn hiện nhưng không cần tràn hết
            box_layout.setStretch(0, 0)  # st
            box_layout.setStretch(2, 1)  # detail
        else:
            # Khi bình thường: chỉ còn 'st' -> tràn hết
            box_layout.setStretch(0, 1)  # st
            box_layout.setStretch(2, 0)  # detail

        # Nếu là 'Dị ứng': tô đỏ khi bất thường
        if cat == "Allergy":
            row["label"].setStyleSheet("color:#B00020; font-weight:600;" if is_abn else "")

    def _tune_combo(self, cb):
        """
        Giúp QComboBox đọc đủ chữ:
        - Popup rộng theo item dài nhất (không làm ô combo phình).
        - Tắt elide trong danh sách.
        - Gắn tooltip cho item đang chọn và cho từng item trong list.
        Gọi lại hàm này sau khi bạn đã addItems(...) vào combo.
        """
        # Dùng QListView làm view cho popup
        view = QListView()
        view.setTextElideMode(Qt.ElideNone)   # không '…' trong danh sách
        cb.setView(view)

        # Tính độ rộng item dài nhất
        fm = view.fontMetrics()
        widest = 0
        for i in range(cb.count()):
            text = cb.itemText(i)
            widest = max(widest, fm.horizontalAdvance(text))
            # Tooltip cho từng item trong danh sách
            cb.setItemData(i, text, Qt.ToolTipRole)

        # Đặt bề rộng tối thiểu cho popup (ô đóng vẫn giữ maxWidth bạn đã đặt)
        # +40 để chừa padding/scrollbar; kẹp trần 600px để không quá to
        popup_w = min(widest + 40, 600)
        cb.view().setMinimumWidth(popup_w)

        # Tooltip cho item đang chọn
        cb.setToolTip(cb.currentText())

        def _sync_tooltip(idx: int):
            cb.setToolTip(cb.itemText(idx))

        # Chỉ nối tín hiệu tooltip 1 lần, dùng overload [int] để chắc chắn
        if not hasattr(cb, "_tt_connected"):
            cb.currentIndexChanged[int].connect(_sync_tooltip)
            cb._tt_connected = True



    def _on_add_exam_abnormal(self, cat: str):
        """Thêm một dòng bất thường vào bảng tổng hợp."""
        row = self.exam_rows[cat]
        abn_text = row["abn"].currentText().strip() if row["abn"].isVisible() else ""
        detail   = row["detail"].text().strip() if row["detail"].isVisible() else ""

        if not abn_text and not detail:
            # Không có gì để thêm
            return

        r = self.tbl_exam_abn.rowCount()
        self.tbl_exam_abn.insertRow(r)
        self.tbl_exam_abn.setItem(r, 0, QTableWidgetItem(cat))
        self.tbl_exam_abn.setItem(r, 1, QTableWidgetItem(abn_text))
        self.tbl_exam_abn.setItem(r, 2, QTableWidgetItem(detail))

        # Nếu là 'Dị ứng' thì giữ nhãn đỏ (có bất thường)
        if cat == "Allergy":
            row["label"].setStyleSheet("color:#B00020; font-weight:600;")

        # Xóa nội dung chi tiết sau khi thêm để tránh trùng
        row["detail"].clear()

    def _save_exam_summary(self):
        """Thu thập dữ liệu bảng vào cấu trúc lưu tạm (có thể tích hợp Model DB sau)."""
        self.exam_summary = []
        for r in range(self.tbl_exam_abn.rowCount()):
            item = {
                "muc":      self.tbl_exam_abn.item(r, 0).text() if self.tbl_exam_abn.item(r, 0) else "",
                "bat_thuong": self.tbl_exam_abn.item(r, 1).text() if self.tbl_exam_abn.item(r, 1) else "",
                "chi_tiet": self.tbl_exam_abn.item(r, 2).text() if self.tbl_exam_abn.item(r, 2) else "",
            }
            self.exam_summary.append(item)
        # Nếu muốn, bạn có thể gọi self.model.save_exam(self.exam_summary)
        # hoặc phát signal ra ngoài controller.

    def _del_exam_selected(self):
        """Xóa dòng đang chọn trong bảng tổng hợp."""
        r = self.tbl_exam_abn.currentRow()
        if r >= 0:
            self.tbl_exam_abn.removeRow(r)

    def _update_allergy_highlight(self):
        """Tô đỏ trường Dị ứng nếu có 'CÓ' hoặc có nội dung chi tiết."""
        positive = (self.cb_diung.currentIndex() == 1) or bool(self.ed_diung.text().strip())
        if positive:
            # nền hồng nhạt, chữ đỏ đậm
            self.ed_diung.setStyleSheet("background-color:#FFE5E5; color:#B00020;")
            self.lbl_diung.setStyleSheet("color:#B00020; font-weight:600;")
        else:
            # quay về style mặc định (kế thừa từ theme chung)
            self.ed_diung.setStyleSheet("")
            self.lbl_diung.setStyleSheet("")

    def _init_structured_note_editor(self, editor, tags):
        """Create a single editor that always shows bold section letters (e.g., S/O/A/P) on separate lines."""
        from PyQt5.QtWidgets import QTextEdit
        from PyQt5.QtGui import QTextCursor, QTextCharFormat, QColor

        self._structured_note_busy = getattr(self, "_structured_note_busy", False)

        def render(sections=None):
            # sections: dict tag->text (may contain \n)
            if sections is None:
                sections = {t: "" for t in tags}

            # Build HTML: bold + gray prefix, normal black content
            lines = []
            for t in tags:
                content = (sections.get(t, "") or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                content = content.replace("\n", "<br>")
                lines.append(
                    f"<div style='margin:0; padding:0;'>"
                    f"<span style='color:{('#000' if (sections.get(t,'') or '').strip() else '#888')}; font-weight:700;'>{t}:</span> "
                    f"<span style='color:#000;'>{content}</span>"
                    f"</div>"
                )
            editor.blockSignals(True)
            editor.setHtml("\n".join(lines))
            editor.blockSignals(False)

        def parse_plain():
            # Parse from plain text into dict tag->text, allowing multi-line per section
            txt = editor.toPlainText()
            sections = {t: "" for t in tags}
            current = None
            buf = []
            for line in txt.splitlines():
                m = None
                for t in tags:
                    if re.match(rf"^\s*{re.escape(t)}\s*:\s*", line):
                        # flush previous
                        if current is not None:
                            sections[current] = "\n".join(buf).strip()
                        current = t
                        buf = [re.sub(rf"^\s*{re.escape(t)}\s*:\s*", "", line)]
                        m = True
                        break
                if m:
                    continue
                # continuation line
                if current is None:
                    continue
                buf.append(line)
            if current is not None:
                sections[current] = "\n".join(buf).strip()
            return sections

        def enforce():
            if getattr(self, "_structured_note_busy", False):
                return
            self._structured_note_busy = True
            try:
                pos = editor.textCursor().position()
                sections = parse_plain()
                render(sections)
                try:
                    cur = editor.textCursor()
                    txtlen = len(editor.toPlainText())
                    cur.setPosition(min(pos, txtlen))
                    editor.setTextCursor(cur)
                except Exception:
                    pass
            finally:
                self._structured_note_busy = False

        # First render empty template
        render({t: "" for t in tags})

        # Keep prefixes always visible & bold (re-render on change)
        editor.textChanged.connect(enforce)

        # Put cursor at the first section content
        cur = editor.textCursor()
        cur.movePosition(QTextCursor.Start)
        editor.setTextCursor(cur)


    def apply_logged_in_user(self, user_info: dict | None):
        if not user_info:
            return
        try:
            if hasattr(self, "ed_nurse_code"):
                self.ed_nurse_code.setText(str(user_info.get("nurse_code", "") or ""))
            if hasattr(self, "ed_nurse_name"):
                self.ed_nurse_name.setText(str(user_info.get("full_name", "") or ""))
        except Exception:
            pass

