        # Stable, independent timestamps for Process, SOAP and SBAR. These
        # controls stay in their own tab for the lifetime of the view.
        def add_section_time_box(section_key, title, target_layout):
            box = QGroupBox(title + " Documentation Time")
            grid = QGridLayout(box)
            date_edit = QLineEdit(datetime.now().strftime("%d/%m/%Y"))
            time_edit = ClockTimeEdit(datetime.now().strftime("%H:%M"))
            date_edit.setObjectName("ed_%s_date" % section_key)
            time_edit.setObjectName("ed_%s_time" % section_key)
            date_edit.setPlaceholderText("DD/MM/YYYY")
            time_edit.setPlaceholderText("HH:MM")
            # Nursing Process, SOAP and SBAR must not invent a monitoring
            # timepoint of their own: they document an observation that the
            # Nursing Care Time tab already recorded. Only Triage keeps its
            # own editable clock.
            if section_key in ("process", "soap", "sbar"):
                date_edit.setReadOnly(True)
                time_edit.setReadOnly(True)
                for locked in (date_edit, time_edit):
                    locked.setStyleSheet("background:#eef2f7;color:#31465e;")
                    locked.setToolTip(
                        "Tu dong theo Nursing Care Time - khong tao moc "
                        "thoi gian moi. Sua o tab Nursing Care Time."
                    )
            summary = QLabel("")
            summary.setWordWrap(True)
            summary.setStyleSheet("color:#536b86;")
            grid.addWidget(QLabel("Date"), 0, 0)
            grid.addWidget(date_edit, 0, 1)
            grid.addWidget(QLabel("Time"), 0, 2)
            grid.addWidget(time_edit, 0, 3)
            grid.addWidget(QLabel("Linked vital signs"), 1, 0)
            grid.addWidget(summary, 1, 1, 1, 3)
            if section_key == "process":
                source_box = QComboBox()
                source_box.addItem(
                    "Use Nursing Care vital signs", "current"
                )
                source_box.addItem(
                    "Use latest Triage vital signs", "triage"
                )
                # "Enter a new vital-sign observation" was removed: a new
                # observation would be a new monitoring timepoint, which must
                # be created in the Nursing Care Time tab instead.
                choose_button = QPushButton(
                    "Choose / edit linked vital signs"
                )
                grid.addWidget(QLabel("Vital-sign sample"), 2, 0)
                grid.addWidget(source_box, 2, 1, 1, 2)
                grid.addWidget(choose_button, 2, 3)
                self.cb_process_vital_source = source_box
                source_box.setObjectName("cb_process_vital_source")
                self._process_linked_vitals = {}
                choose_button.clicked.connect(
                    self._choose_process_vital_sample
                )
            setattr(self, "ed_%s_date" % section_key, date_edit)
            setattr(self, "ed_%s_time" % section_key, time_edit)
            setattr(self, "lbl_%s_vitals" % section_key, summary)
            target_layout.addWidget(box)

        add_section_time_box("process", "Nursing Process", self.proc_col1)
        add_section_time_box("triage", "Triage Nurse", self.triage)
        add_section_time_box("soap", "SOAP", self.soap)
