        def add_follow_up_box(field_key, field_label, object_name):
            follow_up_layout.addWidget(QLabel(field_label))
            catalog_key = FOLLOW_UP_CARE_CATALOGS.get(field_key, "")
            if catalog_key:
                picker_row = QHBoxLayout()
                picker_row.setContentsMargins(0, 0, 0, 0)
                picker = QComboBox()
                picker.setEditable(True)
                picker.setInsertPolicy(QComboBox.NoInsert)
                picker.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                picker.setObjectName("cb_%s_pick" % object_name)
                add_button = QPushButton("Add")
                picker_row.addWidget(picker, 1)
                picker_row.addWidget(add_button)
                follow_up_layout.addLayout(picker_row)
                self.follow_up_pickers[field_key] = (picker, catalog_key)
                add_button.clicked.connect(
                    partial(self._append_follow_up_choice, field_key)
                )
            editor = QPlainTextEdit()
            editor.setObjectName("pt_%s" % object_name)
            editor.setMaximumHeight(64)
            follow_up_layout.addWidget(editor)
            self.follow_up_editors[field_key] = editor

