        # 2.3 Chỉ số sinh tồn, sinh trắc
        grp_vitals = QGroupBox("Vital Signs and Biometrics")
        g = QGridLayout(grp_vitals)

        # Make all numeric inputs the same width
        NUM_W = 80

        def narrow(le: QLineEdit, w=NUM_W):
            le.setMaximumWidth(w)
            le.setMinimumWidth(w)
            le.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            return le

        r = 0
        self.v_pulse = QLineEdit(); self.v_pulse.setObjectName("v_pulse")
        g.addWidget(QLabel("Pulse (bpm)"), r, 0); g.addWidget(narrow(self.v_pulse), r, 1)

        self.v_bp_sys = QLineEdit(); self.v_bp_sys.setObjectName("v_bp_sys")
        self.v_bp_dia = QLineEdit(); self.v_bp_dia.setObjectName("v_bp_dia")
        bp_wrap = QWidget()
        bp_h = QHBoxLayout(bp_wrap); bp_h.setContentsMargins(0,0,0,0); bp_h.setSpacing(4)
        bp_h.addWidget(narrow(self.v_bp_sys))
