        bp_h.addStretch(1)
        g.addWidget(QLabel("BP Sys/Dia (mmHg)"), r, 2); g.addWidget(bp_wrap, r, 3); r += 1

        self.v_temp = QLineEdit(); self.v_temp.setObjectName("v_temp")
        g.addWidget(QLabel("Temperature (°C)"), r, 0); g.addWidget(narrow(self.v_temp), r, 1)

        self.v_rr = QLineEdit(); self.v_rr.setObjectName("v_rr")
        g.addWidget(QLabel("RR (breaths/min)"), r, 2); g.addWidget(narrow(self.v_rr), r, 3); r += 1

        self.v_spo2 = QLineEdit(); self.v_spo2.setObjectName("v_spo2")
        g.addWidget(QLabel("SpO2 (%)"), r, 0); g.addWidget(narrow(self.v_spo2), r, 1)

        self.v_height = QLineEdit(); self.v_height.setObjectName("v_height")
        g.addWidget(QLabel("Height (cm)"), r, 2); g.addWidget(narrow(self.v_height), r, 3); r += 1

        self.v_weight = QLineEdit(); self.v_weight.setObjectName("v_weight")
        g.addWidget(QLabel("Weight (kg)"), r, 0); g.addWidget(narrow(self.v_weight), r, 1)

        self.v_bmi = QLineEdit(); self.v_bmi.setObjectName("v_bmi")
        self.v_bmi.setReadOnly(True)
        self.v_bmi.setPlaceholderText("Auto")
        g.addWidget(QLabel("BMI"), r, 2); g.addWidget(narrow(self.v_bmi), r, 3); r += 1

        self.v_pain = QComboBox(); self.v_pain.setObjectName("v_pain")
        self.v_pain.addItems([""] + [str(i) for i in range(11)])
        self.v_pain.setMaximumWidth(NUM_W)
        self.v_pain.setMinimumWidth(NUM_W)
        g.addWidget(QLabel("Pain score (0–10)"), r, 0); g.addWidget(self.v_pain, r, 1); r += 1


        def _calc_bmi():
            try:
                h_txt = (self.v_height.text() or "").strip().replace(",", ".")
                w_txt = (self.v_weight.text() or "").strip().replace(",", ".")
                h_cm = float(h_txt) if h_txt else 0.0
                w_kg = float(w_txt) if w_txt else 0.0
                if h_cm <= 0 or w_kg <= 0:
                    self.v_bmi.setText("")
                    return
                h_m = h_cm / 100.0
                bmi = w_kg / (h_m * h_m)
                # keep a clean display (2 decimals)
                self.v_bmi.setText(f"{bmi:.2f}")
            except Exception:
                self.v_bmi.setText("")

        # Auto-calc BMI when height/weight changes (manual or autofill)
        self.v_height.textChanged.connect(_calc_bmi)
        self.v_weight.textChanged.connect(_calc_bmi)
        self.io_entries = []

