        # 2.4 Thăm khám điều dưỡng — trạng thái mặc định & mở rộng khi "Bất thường"
        grp_exam = QGroupBox("Nursing Assessment")
        E = QGridLayout(grp_exam)
        E.setHorizontalSpacing(6); E.setVerticalSpacing(4)

        # Danh mục bất thường (có thể điều chỉnh sau)
        abn_map = {
            "General Condition": ["Pale skin", "Jaundice", "Pale mucosa", "Drowsy", "Lethargic", "Edema"],
            "Mental Status": ["Anxiety", "Agitation", "Confusion"],
            "Pain": ["Chest pain", "Abdominal pain", "Headache", "Joint pain", "Other"],
            "Respiratory": ["Dyspnea", "Crackles", "Coarse crackles", "Cyanosis", "Excessive sputum"],
            "Cardiovascular": ["Tachycardia", "Hypertension", "Hypotension", "Peripheral edema", "CRT ≥2s"],
            "Gastrointestinal": ["Nausea", "Vomiting", "Abdominal pain", "Diarrhea", "Constipation"],
            "Nutrition": ["Poor intake", "Weight loss", "Low BMI"],
            "Personal Hygiene": ["Dependent for hygiene", "Poor hygiene"],
            "Sleep – Rest": ["Difficulty sleeping", "Poor sleep quality", "Daytime sleepiness"],
            "Mobility – Rehabilitation": ["Limited mobility", "Needs rehab support", "Fall risk"],
            "Health Education": ["Needs counseling", "Limited cooperation"],
            "Other Monitoring": ["Pressure injury risk", "Fall risk", "Malnutrition risk", "High NEWS"],
            "Allergy": ["Medication", "Food", "Environment", "Other"],
        }

        order = [
            "General Condition", "Mental Status", "Pain", "Respiratory", "Cardiovascular", "Gastrointestinal",
            "Nutrition", "Personal Hygiene", "Sleep – Rest",
            "Mobility – Rehabilitation", "Health Education", "Other Monitoring", "Allergy"
        ]

        self.exam_rows = {}
        row = 0

        for cat in order:
            # Cột 0: nhãn
            lbl = QLabel(cat)
            E.addWidget(lbl, row, 0)

            # Cột 1..5: một CONTAINER chứa các ô của hàng này
            box = QWidget()
            h = QHBoxLayout(box)
            h.setContentsMargins(0, 0, 0, 0)
            h.setSpacing(6)

            # Trạng thái (mặc định: Chưa phát hiện bất thường) — CHIẾM TOÀN BỘ BỀ RỘNG
            st = QComboBox()
            st.addItems(["No abnormalities detected", "Abnormal"])
            st.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)  # <-- quan trọng để 'đầy ô cột 2'
            st.setMinimumWidth(0)  # cho phép co giãn tự nhiên

            # Khi chọn "Bất thường" mới hiện 3 ô dưới:
            abn = QComboBox()
            abn.addItems(abn_map.get(cat, []))
            abn.setVisible(False)

            det = QLineEdit()
            det.setPlaceholderText("Specify description/location/severity...")
            det.setVisible(False)
            det.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

            btn_add = QPushButton("Add")
            btn_add.setVisible(False)

            # Sắp xếp trong container
            h.addWidget(st, 1)      # index 0: trạng thái (stretch = 1) -> mặc định chiếm hết
            h.addWidget(abn)        # index 1
            h.addWidget(det, 1)     # index 2: chi tiết (stretch = 1)
            h.addWidget(btn_add)    # index 3

            # Thêm container vào grid, chiếm từ cột 1 tới 5
            E.addWidget(box, row, 1, 1, 5)
            row += 1

            # Lưu để dùng trong handler
            self.exam_rows[cat] = {"label": lbl, "box": box, "state": st, "abn": abn, "detail": det, "add": btn_add}

            # Sự kiện
            st.currentIndexChanged[int].connect(partial(self._on_exam_status_change, cat))
            btn_add.clicked.connect(lambda _, c=cat: self._on_add_exam_abnormal(c))

        # Care Level Classification: ô cuối cùng của Nursing Assessment,
        # ngay sau Allergy. Giá trị dùng chung với Mobile Web qua
        # extras["care_level"] và hiển thị ở cột Care Level của danh sách
        # người bệnh.
        E.addWidget(QLabel("Care Level Classification"), row, 0)
        self.cb_cap = QComboBox()
        self.cb_cap.setObjectName("cb_cap")
        self.cb_cap.addItems(
            ["", "1A", "1B", "1C", "2A", "2B", "2C", "3A", "3B", "3C"]
        )
        self.cb_cap.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        E.addWidget(self.cb_cap, row, 1, 1, 5)
        row += 1

        # Cho container (cột 1) được giãn trong group, nhãn giữ nguyên
        E.setColumnStretch(0, 0)
        E.setColumnStretch(1, 1)
        for c in range(2, 6):
            E.setColumnStretch(c, 0)

        # Bảng tổng hợp + nút lưu/xóa (giữ như hiện tại của bạn)
        sum_box = QGroupBox("Recorded Abnormal Findings")
        sum_layout = QVBoxLayout(sum_box)
        self.tbl_exam_abn = QTableWidget(0, 3)
        self.tbl_exam_abn.setHorizontalHeaderLabels(["Category", "Abnormal", "Details"])
        self.tbl_exam_abn.horizontalHeader().setStretchLastSection(True)
        for i in range(3):
            self.tbl_exam_abn.horizontalHeader().setSectionResizeMode(i, self.tbl_exam_abn.horizontalHeader().Stretch)
