        def add_nonmed_order_block(
            category, title, combo_attribute, label_attribute,
            refresh_attribute, add_attribute
        ):
            block = QVBoxLayout()
            block.setSpacing(4)
            block.addWidget(QLabel(title))
            block_row = QHBoxLayout()
            combo = QComboBox()
            combo.setObjectName(combo_attribute)
            combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            combo.setMinimumContentsLength(28)
            block_row.addWidget(combo, 1)
            refresh_button = QPushButton("Refresh Orders")
            add_button = QPushButton("Add")
            block_row.addWidget(refresh_button)
            block_row.addWidget(add_button)
            block.addLayout(block_row)
            status_label = QLabel(
                "No current %s orders." % category.lower()
            )
            status_label.setWordWrap(True)
            status_label.setStyleSheet("color:#536b86;")
            block.addWidget(status_label)
            order_exec.addLayout(block)
            setattr(self, combo_attribute, combo)
            setattr(self, label_attribute, status_label)
            setattr(self, refresh_attribute, refresh_button)
            setattr(self, add_attribute, add_button)
            refresh_button.clicked.connect(
                self._refresh_orders_for_current_patient
            )
            def handle_add_nonmed_order(_checked=False):
                self._perform_selected_nonmed_order(
                    combo_attribute, category, title
                )

            add_button.clicked.connect(handle_add_nonmed_order)

