        # 4 equal lines (S/O/A/P) with light separators
        def _mk_line(ph: str):
            ed = QPlainTextEdit()
            ed.setPlaceholderText(ph)
            ed.setFixedHeight(52)
            ed.setStyleSheet("QPlainTextEdit { border: 1px solid #cccccc; background: #ffffff; padding: 6px; }")
            return ed

        def _mk_sep():
            sp = QFrame()
            sp.setFrameShape(QFrame.HLine)
            sp.setFrameShadow(QFrame.Sunken)
            sp.setStyleSheet("QFrame { color: #d0d0d0; }")
            return sp

        self.soap_fields = {
            "S": _mk_line("S (Subjective)"),
            "O": _mk_line("O (Objective)"),
            "A": _mk_line("A (Assessment)"),
            "P": _mk_line("P (Plan)"),
        }
        soap_v.addWidget(self.soap_fields["S"])
        soap_v.addWidget(_mk_sep())
        soap_v.addWidget(self.soap_fields["O"])
        soap_v.addWidget(_mk_sep())
        soap_v.addWidget(self.soap_fields["A"])
        soap_v.addWidget(_mk_sep())
        soap_v.addWidget(self.soap_fields["P"])

        # Keep compatibility for other functions that may still check te_soap
        self.te_soap = self.soap_fields["S"]  # backward-compatible reference (not used for parsing)

        self.soap.addWidget(self.grp_soap, 1)

