    def _update_triage_tab_visibility(self, *_args):
        if not hasattr(self, "nc_tabs") or not hasattr(self, "tab_triage"):
            return
        department = (
            self.cb_admin_department.currentText()
            if hasattr(self, "cb_admin_department") else ""
        )
        is_emergency = _is_emergency_department(department)
        visible = True
        index = self.nc_tabs.indexOf(self.tab_triage)
        if hasattr(self.nc_tabs.tabBar(), "setTabVisible"):
            if index >= 0:
                self.nc_tabs.tabBar().setTabVisible(index, visible)
        else:
            if visible and index < 0:
                self.nc_tabs.insertTab(
                    0, self.tab_triage,
                    self._ui_label("tab.triage", "Triage"),
                )
                index = 0
            elif not visible and index >= 0:
                self.nc_tabs.removeTab(index)
                index = -1
        if not visible and self.nc_tabs.currentWidget() is self.tab_triage:
            self.nc_tabs.setCurrentWidget(self.tab_monitor)
        if hasattr(self, "btn_new_triage"):
            self.btn_new_triage.setEnabled(is_emergency)
        if hasattr(self, "btn_save_triage"):
            self.btn_save_triage.setEnabled(is_emergency)
        if hasattr(self, "lbl_triage_department"):
            self.lbl_triage_department.setText(department or "Not assigned")
        if hasattr(self, "lbl_triage_access"):
            self.lbl_triage_access.setText(
                "Triage history is available for review. New or edited Triage "
                "records can be saved only while the patient is in the "
                "Emergency Department."
                if not is_emergency else
                "Emergency Department: Triage history can be reviewed and "
                "new or edited records can be saved."
            )


