    def update_patient_table(self, patients):
        """Nhận danh sách BN và hiển thị đầy đủ các cột có dữ liệu vào bảng NC."""
        self.tbl_patients.setRowCount(0)
        for row in patients:
            pid = str(row[0]) if len(row) > 0 and row[0] is not None else ""
            name = str(row[1]) if len(row) > 1 and row[1] is not None else ""
            gender = str(row[2]) if len(row) > 2 and row[2] is not None else ""
            dob = str(row[3]) if len(row) > 3 and row[3] is not None else ""
            care_level = str(row[4]) if len(row) > 4 and row[4] is not None else ""
            department = str(row[5]) if len(row) > 5 and row[5] is not None else ""
            r = self.tbl_patients.rowCount()
            self.tbl_patients.insertRow(r)
            self.tbl_patients.setItem(r, 0, QTableWidgetItem(pid))
            self.tbl_patients.setItem(r, 1, QTableWidgetItem(name))
            self.tbl_patients.setItem(r, 2, QTableWidgetItem(gender))
            self.tbl_patients.setItem(r, 3, QTableWidgetItem(dob))
            self.tbl_patients.setItem(r, 4, QTableWidgetItem(care_level or "-"))
            self.tbl_patients.setItem(r, 5, QTableWidgetItem(department))

    def _upsert_patient_in_list(self, info: dict, care_text: str):
        """Thêm/cập nhật dòng bệnh nhân trong self.tbl_patients theo Mã BN."""
        if not hasattr(self, "tbl_patients"):
            return

        pid = info.get("patient_id","")
        if not pid:
            return

        name   = info.get("name","")
        gender = info.get("gender","")
        dob    = info.get("dob","")
        # Care Level lấy từ ô Care Level Classification ở cuối trang
        # Nursing Assessment - dùng chung với cột Care Level của Mobile Web.
        care_level = care_text or ""
        department = info.get("department", "")

        # tìm nếu đã có pid -> cập nhật
        found_row = -1
        for r in range(self.tbl_patients.rowCount()):
            it = self.tbl_patients.item(r, 0)
            if it and it.text().strip() == pid:
                found_row = r
                break

        if found_row < 0:
            r = self.tbl_patients.rowCount()
            self.tbl_patients.insertRow(r)
        else:
            r = found_row

        def setitem(col, text):
            item = self.tbl_patients.item(r, col)
            if item is None:
                item = QTableWidgetItem()
                self.tbl_patients.setItem(r, col, item)
            item.setText(text or "")

        # Cột: 0=Mã BN, 1=Họ tên, 2=Giới, 3=NS, 4=Care Level, 5=Khoa
        setitem(0, pid)
        setitem(1, name)
        setitem(2, gender)
        setitem(3, dob)
        setitem(4, care_level or "-")
        setitem(5, department)

    def _get_admin_info(self) -> dict:
        return {
            "patient_id": (self.ed_admin_pid.text().strip() if hasattr(self, "ed_admin_pid") else ""),
            "name":       (self.ed_admin_name.text().strip() if hasattr(self, "ed_admin_name") else ""),
            "gender":     (self.cb_admin_gender.currentText().strip() if hasattr(self, "cb_admin_gender") else ""),
            "dob":        (self.ed_admin_dob.text().strip() if hasattr(self, "ed_admin_dob") else ""),
            "department": (
                self.cb_admin_department.currentText().strip()
                if hasattr(self, "cb_admin_department") else ""
            ),
        }


