    def _del_ct(self):
        r = self.tbl_ct.currentRow()
        if r >= 0:
            self.tbl_ct.removeRow(r)

    # -- NIC: "Đã thực hiện" checkbox + giờ thực hiện (mỗi lần một giờ
    # riêng) + số lần/ngày, tự đồng bộ 3 cột này với nhau. -----------
    def _on_ct_rows_inserted(self, _parent, first, last):
        for row in range(first, last + 1):
            self._ensure_ct_row_extra_columns(row)

    def _ensure_ct_row_extra_columns(self, row):
        if row < 0 or row >= self.tbl_ct.rowCount():
            return
        if self.tbl_ct.item(row, 2) is None:
            done_item = QTableWidgetItem()
            done_item.setFlags(
                Qt.ItemIsUserCheckable | Qt.ItemIsEnabled | Qt.ItemIsSelectable
            )
            done_item.setCheckState(Qt.Unchecked)
            self.tbl_ct.setItem(row, 2, done_item)
        if self.tbl_ct.item(row, 3) is None:
            count_item = QTableWidgetItem("0")
            count_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            self.tbl_ct.setItem(row, 3, count_item)
        if self.tbl_ct.item(row, 4) is None:
            self.tbl_ct.setItem(row, 4, QTableWidgetItem(""))

    @staticmethod
    def _parse_ct_times(text):
        times = []
        for raw in str(text or "").split(","):
            value = raw.strip()
            if not value:
                continue
            if re.fullmatch(r"\d{1,2}:\d{2}", value):
                hour, minute = value.split(":")
                value = "%02d:%02d" % (int(hour), int(minute))
            times.append(value)
        return times

    def _set_ct_times(self, row, times):
        self._ensure_ct_row_extra_columns(row)
        # Guard against itemChanged re-entrancy (setText/setCheckState
        # below each emit itemChanged); save/restore rather than force to
        # False so a caller that is itself inside the guard (e.g.
        # _on_ct_item_changed) is not accidentally un-guarded early.
        was_syncing = self._ct_sync_in_progress
        self._ct_sync_in_progress = True
        try:
            times_item = self.tbl_ct.item(row, 4)
            times_item.setText(", ".join(times))
            count_item = self.tbl_ct.item(row, 3)
            count_item.setText(str(len(times)))
            done_item = self.tbl_ct.item(row, 2)
            done_item.setCheckState(Qt.Checked if times else Qt.Unchecked)
        finally:
            self._ct_sync_in_progress = was_syncing

    def _on_ct_item_changed(self, item):
        if self._ct_sync_in_progress:
            return
        row, column = item.row(), item.column()
        if column not in (2, 4):
            return
        self._ct_sync_in_progress = True
        try:
            if column == 2:
                checked = item.checkState() == Qt.Checked
                times_item = self.tbl_ct.item(row, 4)
                times = self._parse_ct_times(
                    times_item.text() if times_item else ""
                )
                if checked and not times:
                    times = [datetime.now().strftime("%H:%M")]
                elif not checked:
                    times = []
                self._set_ct_times(row, times)
            elif column == 4:
                times = self._parse_ct_times(item.text())
                self._ensure_ct_row_extra_columns(row)
                count_item = self.tbl_ct.item(row, 3)
                count_item.setText(str(len(times)))
                done_item = self.tbl_ct.item(row, 2)
                done_item.setCheckState(Qt.Checked if times else Qt.Unchecked)
        finally:
            self._ct_sync_in_progress = False

    def _save_ct(self):
        """Thu thập các can thiệp vào thuộc tính (để lưu DB nếu cần)."""
        self.ct_list = []
        for r in range(self.tbl_ct.rowCount()):
            self._ensure_ct_row_extra_columns(r)
            loai = self.tbl_ct.item(r, 0).text() if self.tbl_ct.item(r, 0) else ""
            chitiet = self.tbl_ct.item(r, 1).text() if self.tbl_ct.item(r, 1) else ""
            done_item = self.tbl_ct.item(r, 2)
            times_item = self.tbl_ct.item(r, 4)
            times = self._parse_ct_times(
                times_item.text() if times_item else ""
            )
            completed = bool(
                times
                or (done_item is not None and done_item.checkState() == Qt.Checked)
            )
            self.ct_list.append({
                "loai": loai, "chi_tiet": chitiet,
                "type": loai, "details": chitiet,
                "completed": completed,
                "executions": [{"time": t} for t in times],
                "execution_count": len(times),
            })
        # Mirror the Procedure Implementation list into ct_list so the saved
        # record, the PDF and Mobile Web all show the same wording. The
        # authoritative rows are written to nursing_procedure_records by the
        # controller once the care_id exists.
        self.procedure_rows = self.collect_procedure_rows()
        procedure_text = format_nursing_procedure_text(self.procedure_rows)
        self.ct_list = [
            entry for entry in self.ct_list
            if entry.get("loai") != "Procedure Implementation"
        ]
        if procedure_text:
            self.ct_list.append({
                "loai": "Procedure Implementation",
                "chi_tiet": procedure_text,
                "type": "Procedure Implementation",
                "details": procedure_text,
                "completed": any(
                    row.get("performed_time") for row in self.procedure_rows
                ),
                "executions": [
                    {"time": row["performed_time"]}
                    for row in self.procedure_rows if row.get("performed_time")
                ],
                "execution_count": sum(
                    1 for row in self.procedure_rows
                    if row.get("performed_time")
                ),
            })
    def _on_patient_double_click(self, item):
        row = item.row()
        self.tbl_patients.selectRow(row)
        pid_item = self.tbl_patients.item(row, 0)
        if not pid_item: return
        pid = pid_item.text().strip()
        mw = self
        while mw is not None and not hasattr(mw, "controller"):
            mw = mw.parent()
        if mw is not None and hasattr(mw, "controller"):
            if not mw.controller.confirm_handoff_access(pid, self):
                return
            mw.controller.load_patient_everywhere(pid)
    def resizeEvent(self, e):
        super().resizeEvent(e)
        # trừ đi 3 khoảng spacing giữa 4 cột
        spacing = 8  # đúng bằng columns.setSpacing(8)
        total = self.width() - spacing * 3 - 2  # 2px dự phòng
        w = max(260, total // 4)  # 260: ngưỡng an toàn cho nội dung ngắn
        if getattr(self, "_last_nursing_column_width", None) == w:
            return
        self._last_nursing_column_width = w
        for wdt in (
            self.col1w, self.col2w, self.col3w, self.col4w,
            self.proc_col1w, self.proc_col2w, self.proc_col3w
        ):
            wdt.setMinimumWidth(0)      # cho phép thu nhỏ
            wdt.setMaximumWidth(w)      # không vượt quá 1/4


    def _parse_care_datetime(self):
        date_str = self.ed_care_date.text().strip() if hasattr(self, "ed_care_date") else ""
        time_str = self.ed_care_time.text().strip() if hasattr(self, "ed_care_time") else ""
        raw = f"{date_str} {time_str}".strip()
        for fmt in ("%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
            try:
                return datetime.strptime(raw, fmt)
            except Exception:
                pass
        return datetime.now()

    def _set_care_datetime(self, dt_obj):
        try:
            self.ed_care_date.setText(dt_obj.strftime("%d/%m/%Y"))
            self.ed_care_time.setText(dt_obj.strftime("%H:%M"))
        except Exception:
            pass

    def _sync_new_record_shared_time_from_fields(self):
        if not getattr(self, "_new_record_shared_timestamp", False):
            return
        raw = "%s %s" % (
            self.ed_care_date.text().strip(),
            self.ed_care_time.text().strip(),
        )
        parsed = None
        for fmt in (
            "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M",
            "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
        ):
            try:
                parsed = datetime.strptime(raw, fmt)
                break
            except ValueError:
                continue
        if parsed is not None:
            self._set_all_section_datetimes(parsed)

    def _parse_section_datetime(self, section_key, fallback=None):
        date_widget = getattr(self, "ed_%s_date" % section_key, None)
        time_widget = getattr(self, "ed_%s_time" % section_key, None)
        date_text = date_widget.text().strip() if date_widget is not None else ""
        time_text = time_widget.text().strip() if time_widget is not None else ""
        raw = (date_text + " " + time_text).strip()
        for fmt in ("%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M",
                    "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
            try:
                return datetime.strptime(raw, fmt)
            except ValueError:
                continue
        return fallback or self._parse_care_datetime()

    def _set_section_datetime(self, section_key, dt_obj):
        date_widget = getattr(self, "ed_%s_date" % section_key, None)
        time_widget = getattr(self, "ed_%s_time" % section_key, None)
        if date_widget is not None:
            date_widget.setText(dt_obj.strftime("%d/%m/%Y"))
        if time_widget is not None:
            time_widget.setText(dt_obj.strftime("%H:%M"))

    def _set_all_section_datetimes(self, dt_obj):
        for section_key in NURSING_SECTION_KEYS[1:]:
            self._set_section_datetime(section_key, dt_obj)

